INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CenturyLink/Chi/chi-recommendations', 'community', 'CenturyLink', 'Chi', 'CenturyLink/Chi', 'chi-recommendations', 0, 0, 36, '2026-03-08T01:57:15.493Z', '2026-03-08T02:10:09.007Z', '331c2882a010fd624fa192c637853abe643aec78b560a4101f7265b77647748d', '{"id":"CenturyLink/Chi/chi-recommendations","name":"chi-recommendations","description":{"en":"chi-recommendations provides a decision tree for choosing the best implementation approach based on your framework, supporting Vue 3, React, and Angular. This skill benefits developers seeking optimized framework integrations.","zh":"ChiRecommendations提供了一套决策树，帮助开发者选择适合Vue 3、React和Angular的最佳方法","ja":"ChiRecommendationsは、Vue 3、React、Angularに最適なアプローチを選択するための決定ツリーを提供する","ko":"ChiRecommendations는 Vue 3, React, Angular에 최적의 접근 방식을 선택하기 위한 의사 결정 트리를 제공","es":"Chi-recommendations proporciona un enfoque personalizado para implementar chi en diferentes frameworks, como Vue 3, React y Angular","fr":"Chi-recommendations offre une approche personnalisée pour mettre en œuvre chi dans différents frameworks, tels que Vue 3, React et Angular","de":"Chi-recommendations bietet einen maßgeschneiderten Ansatz für die Implementierung von chi in verschiedenen Frameworks, wie Vue 3, React und Angular","pt":"O chi-recommendations fornece orientação para a implementação de soluções personalizadas em Vue 3, React e Angular","ru":"Chi-recommendations предоставляет рекомендации для реализации индивидуальных решений на основе Vue 3, React и Angular для ИИ Агентов","ar":"chi-recommendations يوفر إرشادات لتنفيذ حلول مخصصة في Vue 3 و React و Angular"},"seo":{"title":{"en":"chi-recommendations: Implementation Guide for AI Agents","zh":"ChiRecommendations 设计指南 - AI智能工具集成","ja":"ChiRecommendations 設定ガイド - AIエージェントとの統合","ko":"ChiRecommendations 설정 가이드 - AI 에이전트와의 통합","es":"Guía de configuración de chi-recommendations para desarro...","fr":"Guide de mise en place des chi-recommendations pour les d...","de":"Einrichtungsleitfaden für chi-recommendations für Entwickler","pt":"Guia de Configuração chi-recommendations para Desenvolved...","ru":"Руководство по настройке chi-recommendations для разработ...","ar":"دليل إعداد chi-recommendations لمنشئي التطبيقات الإلكترونية"},"description":{"en":"Discover the best approach for your framework with chi-recommendations. Get expert guidance on Vue 3, React, and Angular implementations. Learn how to optimi...","zh":"了解ChiRecommendations的技术细节和最佳实践，实现Vue 3、React和Angular的无缝集成","ja":"ChiRecommendationsの技術的詳細とベストプラクティスを学び、Vue 3、React、Angularとのシームレスな統合を実現","ko":"ChiRecommendations의 기술적 세부 사항과 모범 사례를ียนร하고 Vue 3, React, Angular와의 무결점 통합을 달성","es":"Mejora la implementación de chi con nuestras recomendaciones personalizadas para Vue 3, React y Angular","fr":"Améliorez la mise en œuvre de chi avec nos recommandations personnalisées pour Vue 3, React et Angular","de":"Verbessern Sie die Implementierung von chi mit unseren maßgeschneiderten Empfehlungen für Vue 3, React und Angular","pt":"Aprenda a configurar chi-recommendations para Vue 3, React e Angular com nossas recomendações de implementação","ru":"Узнайте, как настроить chi-recommendations для Vue 3, React и Angular с помощью наших рекомендаций по реализации ИИ Агентов","ar":"تعلم كيفية إعداد chi-recommendations ل Vue 3 و React و Angular باستخدام إرشاداتنا الفنية"},"definition":{"en":"chi-recommendations is a skill that offers implementation recommendations for various frameworks, including Vue 3, React, and Angular, to help developers make informed decisions.","zh":"ChiRecommendations是一种AI智能工具，提供技术指导和决策支持","ja":"ChiRecommendationsは、技術的なガイダンスと意思決定サポートを提供するAIエージェント","ko":"ChiRecommendations는 기술 지침과 의사 결정 지원을 제공하는 AI 에이전트","es":"Chi-recommendations es un conjunto de recomendaciones para implementar chi de manera efectiva en diferentes entornos de desarrollo","fr":"Chi-recommendations est un ensemble de recommandations pour mettre en œuvre chi de manière efficace dans différents environnements de développement","de":"Chi-recommendations ist eine Sammlung von Empfehlungen für die effektive Implementierung von chi in verschiedenen Entwicklungsumgebungen","pt":"chi-recommendations é uma ferramenta de recomendação para desenvolvedores","ru":"Chi-recommendations - это инструмент рекомендаций для разработчиков ИИ Агентов","ar":"chi-recommendations هي أداة توجيه لمنشئي التطبيقات الإلكترونية"},"features":{"en":["Provides a decision tree for framework-specific implementation recommendations","Supports Vue 3 with chi-vue for full reactivity and composition API","Offers Custom Elements approach for React and Angular frameworks","Utilizes ref callbacks for event listeners in React due to synthetic event limitations","Enables TypeScript support for Vue 3 implementations","Works with popular frameworks like React and Angular using Custom Elements"],"zh":["支持Vue 3的chi-vue实现","适用于React的Custom Elements方法","支持Angular的Custom Elements方法","使用决策树选择最佳方法"],"ja":["Vue 3のchi-vue実装をサポート","React用のCustom Elements方法","Angular用のCustom Elements方法","決定ツリーを使用して最適な方法を選択"],"ko":["Vue 3의 chi-vue 구현을 지원","React용 Custom Elements 방법","Angular용 Custom Elements 방법","의사 결정 트리를 사용하여 최적의 방법을 선택"],"es":["Soporte para Vue 3 con chi-vue","Compatibilidad con React mediante Custom Elements","Integración con Angular mediante Custom Elements","Uso de la API de composición y TypeScript en Vue 3"],"fr":["Prise en charge de Vue 3 avec chi-vue","Compatibilité avec React via Custom Elements","Intégration avec Angular via Custom Elements","Utilisation de l''API de composition et de TypeScript dans Vue 3"],"de":["Unterstützung für Vue 3 mit chi-vue","Kompatibilität mit React über Custom Elements","Integration mit Angular über Custom Elements","Verwendung der Composition-API und von TypeScript in Vue 3"],"pt":["Suporte a Vue 3 com reatividade e API de composição","Compatibilidade com React via Custom Elements","Integração com Angular usando Custom Elements","Utilização de ref callbacks para event listeners no React","Suporte a TypeScript","Abordagem personalizada para cada framework"],"ru":["Поддержка Vue 3 с реактивностью и композиционной API","Совместимость с React через Custom Elements","Интеграция с Angular с помощью Custom Elements","Использование ref callbacks для event listeners в React","Поддержка TypeScript","Индивидуальный подход для каждого фреймворка для ИИ Агентов"],"ar":["دعم Vue 3 مع التفاعل والواجهة البرمجية لتركيب","التوافق مع React من خلال العناصر المخصصة","التكامل مع Angular باستخدام العناصر المخصصة","استخدام ref callbacks لاستماع الأحداث في React","دعم TypeScript","نهج مخصص لكل إطار"]},"keywords":{"en":["chi-recommendations setup guide","how to use chi-recommendations with Vue 3","chi-recommendations vs custom implementation","what is chi-recommendations","chi-recommendations alternative for React","chi-recommendations installation for Angular","chi-recommendations best practices","chi-recommendations framework support","chi-recommendations decision tree","chi-recommendations implementation recommendations"],"zh":["ChiRecommendations","AI智能工具","Vue 3","React","Angular","Custom Elements","chi-vue","决策树"],"ja":["ChiRecommendations","AIエージェント","Vue 3","React","Angular","Custom Elements","chi-vue","決定ツリー"],"ko":["ChiRecommendations","AI 에이전트","Vue 3","React","Angular","Custom Elements","chi-vue","의사 결정 트리"],"es":["chi-recommendations","implementación de chi","Vue 3","React","Angular","Custom Elements","TypeScript","API de composición"],"fr":["chi-recommendations","mise en œuvre de chi","Vue 3","React","Angular","Custom Elements","TypeScript","API de composition"],"de":["chi-recommendations","Implementierung von chi","Vue 3","React","Angular","Custom Elements","TypeScript","Composition-API"],"pt":["chi-recommendations","desenvolvimento de software","Vue 3","React","Angular","Custom Elements","TypeScript","recomendações de implementação","guias de configuração"],"ru":["chi-recommendations","разработка программного обеспечения","Vue 3","React","Angular","Custom Elements","TypeScript","рекомендации по реализации","руководства по настройке","ИИ Агенты"],"ar":["chi-recommendations","تطوير البرمجيات","Vue 3","React","Angular","العناصر المخصصة","TypeScript","إرشادات التنفيذ","دليل الإعداد","أدوات الذكاء الاصطناعي"]}},"owner":"CenturyLink","repo":"Chi","repoPath":"CenturyLink/Chi","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.493Z","topics":[],"category":"community","skillMd":{"name":"chi-recommendations","description":"Recommend the best Chi implementation approach based on project context. Use when the user asks which Chi approach to use (Vue, Web Components, or HTML/CSS), when starting a new project with Chi, or when migrating between approaches. Provides framework-specific guidance and code examples.","bodyPreview":"# Chi Implementation Recommendations\n\n## Decision Tree\n\nUse this decision tree to recommend the best approach:\n\n### Step 1: Check Framework\n\n| Framework | Recommended Approach | Reasoning |\n|-----------|---------------------|-----------|\n| Vue 3 | **chi-vue** | Full Vue reactivity, composition API, TypeScript support |\n| React | **Custom Elements** | Works with React; note: use `ref` callbacks for event listeners since React synthetic events don''t fire on CEs |\n| Angular | **Custom Elements** |","body":"# Chi Implementation Recommendations\n\n## Decision Tree\n\nUse this decision tree to recommend the best approach:\n\n### Step 1: Check Framework\n\n| Framework | Recommended Approach | Reasoning |\n|-----------|---------------------|-----------|\n| Vue 3 | **chi-vue** | Full Vue reactivity, composition API, TypeScript support |\n| React | **Custom Elements** | Works with React; note: use `ref` callbacks for event listeners since React synthetic events don''t fire on CEs |\n| Angular | **Custom Elements** | Excellent support via `CUSTOM_ELEMENTS_SCHEMA` in module declarations |\n| Svelte | **Custom Elements** | Seamless Custom Elements support |\n| Vanilla JS | **Custom Elements** | Best DX, no framework overhead |\n| Unknown | **Custom Elements** | Safe default for any framework |\n\n### Step 2: Check Constraints\n\n| Constraint | Override To | Reasoning |\n|------------|------------|-----------|\n| Legacy browser support (IE11) | **HTML/CSS** | Custom Elements need polyfills |\n| User explicitly wants CSS | **HTML/CSS** | Respect explicit preference |\n| User wants Web Components | **Custom Elements** | Respect explicit preference |\n| Static HTML site (no JS) | **HTML/CSS** | No JS runtime needed |\n| SSR without hydration | **HTML/CSS** | Custom Elements need JS to initialize |\n\n### Step 3: Determine Confidence\n\n| Scenario | Confidence |\n|----------|------------|\n| Framework detected + no conflicts | High |\n| Existing code matches recommendation | High |\n| No framework info, using default | Low |\n| Existing code uses different approach | Medium (suggest gradual migration) |\n\n## Code Examples\n\n### Vue Approach\n```html\n<script setup>\nimport { ChiButton } from ''@aspect/chi-vue'';\n</script>\n<template>\n  <ChiButton color=\"primary\" size=\"lg\" @click=\"handleClick\">Click me</ChiButton>\n</template>\n```\n\n### Custom Elements Approach\n```html\n<chi-button color=\"primary\" size=\"lg\">Click me</chi-button>\n<script>\n  document.querySelector(''chi-button'').addEventListener(''chiClick'', handleClick);\n</script>\n```\n\n### HTML/CSS Approach\n```html\n<button class=\"chi-button -primary -lg\" type=\"button\" onclick=\"handleClick()\">Click me</button>\n```\nNote: Requires manual event handling, ARIA attributes, and keyboard support.\n\n## Approach Detection\n\nTo detect which approach existing code uses:\n\n| Pattern | Approach |\n|---------|----------|\n| `<Chi[A-Z]` (PascalCase tags) | Vue |\n| `<chi-` (kebab-case custom elements) | Custom Elements |\n| `class=\"chi-` (CSS classes on native elements) | HTML/CSS |\n\nCount occurrences of each pattern. The most frequent one is the existing approach.\n\n**Edge case**: `<chi-icon>` inside a `<button class=\"chi-button\">` is mixed usage -- recommend migrating the button to `<chi-button>` too.\n\n## Migration Paths\n\n### HTML/CSS → Custom Elements\n1. Replace CSS base classes with Web Component tags: `<button class=\"chi-button\">` → `<chi-button>`\n2. Convert CSS modifiers to properties: `-primary` → `color=\"primary\"`\n3. Convert boolean modifiers to attributes: `-disabled` → `disabled`\n4. Keep utility classes for spacing: `class=\"-p--4\"` stays\n5. Remove manual ARIA -- Web Components handle it automatically\n\n### HTML/CSS → Vue\n1. Install `@aspect/chi-vue` package\n2. Import components: `import { ChiButton } from ''@aspect/chi-vue''`\n3. Replace HTML with Vue component syntax\n4. Use `v-bind` for dynamic props, `v-on` for events\n\n### Custom Elements → Vue\n1. Replace `<chi-*>` tags with `<Chi*>` components\n2. Convert attributes to Vue props syntax\n3. Migrate events from addEventListener to `v-on`\n\n### Vue → Custom Elements\n1. Replace `<Chi*>` with `<chi-*>` Web Components\n2. Convert Vue props to attributes\n3. Replace `v-on` events with `addEventListener`\n4. Handle reactivity manually if needed\n\n## Priority Order\n\n1. **chi-vue** (priority 1) -- Vue 3 components for Vue projects\n2. **chi-web-components** (priority 2) -- Custom Elements for any framework\n3. **chi-html-css** (priority 3) -- CSS classes for static HTML or legacy support\n"},"lastSynced":"2026-03-08T02:10:09.007Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing optimized framework integrations with Vue 3, React, and Angular.","zh":"非常适合需要优化框架集成的前端代理，支持Vue 3、React和Angular。","ja":"フロントエンドエージェントが最適化されたフレームワーク統合を必要とする場合に最適です。Vue 3、React、Angularをサポートしています。","ko":"최적화된 프레임워크 통합이 필요한 프론트엔드 에이전트에게 적합합니다. Vue 3, React, Angular를 지원합니다.","es":"Perfecto para agentes frontend que necesitan integraciones de framework optimizadas con Vue 3, React, y Angular.","fr":"Parfait pour les agents frontend ayant besoin d''intégrations de framework optimisées avec Vue 3, React, et Angular.","de":"Perfekt für Frontend-Agents, die optimierte Framework-Integrationen mit Vue 3, React und Angular benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de integrações de estrutura otimizadas com Vue 3, React e Angular.","ru":"Идеально подходит для агентов Frontend, которым необходимы оптимизированные интеграции фреймворков с Vue 3, React и Angular.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تكاملات إطار عمل محسّنة مع Vue 3 و React و Angular."},"recommendation":{"en":"Empowers agents to choose the best implementation approach using a decision tree, supporting Custom Elements and chi-vue for seamless framework integration with TypeScript support and Vue reactivity.","zh":"赋予代理选择最佳实现方法的能力，使用决策树支持自定义元素和chi-vue，实现无缝的框架集成，支持TypeScript和Vue响应式。","ja":"エージェントが最適な実装アプローチを選択できるようにし、カスタム要素とchi-vueを使用してシームレスなフレームワーク統合を可能にします。TypeScriptとVueのリアクティビティをサポートしています。","ko":"에이전트가 최적의 구현 방법을 선택할 수 있도록 하며, 사용자 지정 요소와 chi-vue를 사용하여 무결점의 프레임워크 통합을 가능하게 합니다. TypeScript와 Vue 반응성을 지원합니다.","es":"Habilita a los agentes a elegir el mejor enfoque de implementación utilizando un árbol de decisión, que admite Custom Elements y chi-vue para una integración de framework fluida con soporte de TypeScript y reactividad de Vue.","fr":"Permet aux agents de choisir la meilleure approche d''implémentation en utilisant un arbre de décision, prenant en charge les éléments personnalisés et chi-vue pour une intégration de framework transparente avec une prise en charge de TypeScript et de réactivité de Vue.","de":"Ermöglicht es den Agenten, den besten Implementierungsansatz unter Verwendung eines Entscheidungsbaums zu wählen, der benutzerdefinierte Elemente und chi-vue für eine nahtlose Framework-Integration mit TypeScript-Unterstützung und Vue-Reaktivität unterstützt.","pt":"Habilita agentes a escolher a melhor abordagem de implementação usando uma árvore de decisão, suportando Elementos Personalizados e chi-vue para uma integração de estrutura sem problemas com suporte a TypeScript e reatividade do Vue.","ru":"Наделяет агентов возможностью выбрать лучший подход к реализации с помощью дерева решений, поддерживающего пользовательские элементы и chi-vue для бесшовной интеграции фреймворка с поддержкой TypeScript и реактивностью Vue.","ar":"يمنح الوكلاء القدرة على اختيار أفضل نهج لتنفيذ باستخدام شجرة قرار،تدعم العناصر المخصصة و chi-vue لتكامل إطار عمل بدون مشاكل مع دعم TypeScript و تفاعلية Vue."},"useCases":{"en":["Implementing chi-vue for Vue 3 projects","Integrating Custom Elements with React applications","Optimizing Angular projects with Custom Elements"],"zh":["为Vue 3项目实现chi-vue","将自定义元素集成到React应用程序中","使用自定义元素优化Angular项目"],"ja":["Vue 3プロジェクト用のchi-vueを実装する","カスタム要素をReactアプリケーションに統合する","カスタム要素を使用してAngularプロジェクトを最適化する"],"ko":["Vue 3 프로젝트용 chi-vue 구현","사용자 지정 요소를 React 애플리케이션에 통합","사용자 지정 요소를 사용하여 Angular 프로젝트 최적화"],"es":["Implementar chi-vue para proyectos Vue 3","Integrar elementos personalizados con aplicaciones React","Optimizar proyectos Angular con elementos personalizados"],"fr":["Mettre en œuvre chi-vue pour les projets Vue 3","Intégrer des éléments personnalisés avec des applications React","Optimiser les projets Angular avec des éléments personnalisés"],"de":["Chi-vue für Vue-3-Projekte implementieren","Benutzerdefinierte Elemente in React-Anwendungen integrieren","Angular-Projekte mit benutzerdefinierten Elementen optimieren"],"pt":["Implementação do chi-vue para projetos Vue 3","Integração de Elementos Personalizados com aplicações React","Otimização de projetos Angular com Elementos Personalizados"],"ru":["Реализация chi-vue для проектов Vue 3","Интеграция пользовательских элементов с приложениями React","Оптимизация проектов Angular с помощью пользовательских элементов"],"ar":["تنفيذ chi-vue لمشاريع Vue 3","دمج العناصر المخصصة مع تطبيقات React","تحسين مشاريع Angular مع العناصر المخصصة"]},"limitations":{"en":["Limited to Vue 3, React, and Angular frameworks","Requires understanding of framework-specific implementation details"],"zh":["仅限于Vue 3、React和Angular框架","需要了解框架特定的实现细节"],"ja":["Vue 3、React、Angularフレームワークのみに限定される","フレームワーク固有の実装詳細の理解が必要"],"ko":["Vue 3, React, Angular 프레임워크만 해당","프레임워크별 구현 세부 정보에 대한 이해가 필요"],"es":["Limitado a los frameworks Vue 3, React y Angular","Requiere comprensión de detalles de implementación específicos del framework"],"fr":["Limité aux frameworks Vue 3, React et Angular","Nécessite une compréhension des détails d''implémentation spécifiques au framework"],"de":["Begrenzt auf die Frameworks Vue 3, React und Angular","Erfordert das Verständnis von framework-spezifischen Implementierungsdetails"],"pt":["Limitado a estruturas Vue 3, React e Angular","Exige compreensão de detalhes de implementação específicos da estrutura"],"ru":["Ограничен фреймворками Vue 3, React и Angular","Требует понимания деталей реализации, специфичных для фреймворка"],"ar":["محدود بالإطارات Vue 3 و React و Angular","يتطلب فهمًا لتفاصيل التنفيذ الخاصة بالإطار"]},"version":4},"contentHash":"331c2882a010fd624fa192c637853abe643aec78b560a4101f7265b77647748d","qualityScore":36}');
