INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Asheng008/unifiles-mcp/code-quality-check', 'code-quality-check', 'Asheng008', 'unifiles-mcp', 'community', 'code-quality-check Asheng008 unifiles-mcp community The code-quality-check skill automates Python code quality assurance by executing Black for formatting, Ruff for linting and auto-fixing, and Mypy for static type checking. It is designed for developers and teams who want to enforce consistent code standards in their projects. 代码质量检查工具通过运行Black、Ruff和Mypy等工具，确保代码符合项目规范 コード品質チェックツールは、Black、Ruff、Mypyなどのツールを実行してコードをプロジェクト規約に準拠させます 코드 품질检查 도구는 Black, Ruff, Mypy 등의 도구를 실행하여 코드를 프로젝트 규약에 준수하도록 합니다 El skill de código de alta calidad permite ejecutar herramientas de verificación de código como Black, Ruff y Mypy para asegurar la calidad del código Le skill de code de haute qualité permet d''exécuter des outils de vérification de code tels que Black, Ruff et Mypy pour assurer la qualité du code Das Skill zur Code-Qualitätsprüfung ermöglicht die Ausführung von Code-Überprüfungstools wie Black, Ruff und Mypy, um die Code-Qualität zu gewährleisten O agente de verificação de qualidade de código executa ferramentas como Black, Ruff e Mypy para garantir a conformidade do código com os padrões do projeto ИИ Агент для проверки кодовой качества запускает инструменты seperti Black, Ruff и Mypy, чтобы обеспечить соответствие кода стандартам проекта يعمل عامل الذكاء الاصطناعي للتحقق من جودة الكود على تشغيل أدوات مثل Black و Ruff و Mypy لضمان مطابقة الكود لمعايير المشروع code-quality-check setup guide how to use code-quality-check code-quality-check vs pre-commit automate Python code formatting Ruff linter auto-fix Mypy type checking Black formatter AI agent Python code quality automation code-quality-check alternative install code-quality-check skill 代码质量检查工具 代码格式化 代码检查 代码自动修复 Mypy类型检查 Black格式化 Ruff检查 代码开发工具 AI代码检查 代码质量保证 Executes Black code formatting on `src/` and `tests/` directories Runs Ruff linting with the `--fix` flag for automatic corrections Performs static type checking using Mypy on the `src/unifiles_mcp/` package Supports a full sequential workflow (Black -> Ruff -> Mypy) or individual tool execution Allows for a Black dry-run using the `--check` flag to verify formatting without changes Configures UTF-8 console encoding and activates a Python virtual environment (.venv) code-quality-check is an AI Agent skill that automates Python code quality checks. It executes a sequence of tools including the Black code formatter, the Ruff linter with auto-fix capabilities, and the Mypy static type checker on specified source and test directories.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Solrak97/cursor_workflow/git-setup', 'community', 'Solrak97', 'cursor_workflow', 'Solrak97/cursor_workflow', 'git-setup', 0, 0, 36, '2026-03-08T01:57:15.495Z', '2026-03-08T02:10:12.772Z', 'c6b232667e5ce5ccbb44311d9a2ccf646b5ff99267932bf1eff9e97045e8d826', '{"id":"Solrak97/cursor_workflow/git-setup","name":"git-setup","description":{"en":"The git-setup skill helps developers configure git by setting up their identity and making commits. It benefits developers who need to manage their git accounts and commit history.","zh":"git-setup是用于配置Git账户和提交的技术，包括设置用户名和邮箱","ja":"Git Setupは、Gitアカウントの設定とコミットを行う技術であり、ユーザー名とメールアドレスの設定が含まれる","ko":"Git Setup는 Git 계정 설정과 커밋을 수행하는 기술로, 사용자 이름과 이메일 설정이 포함","es":"El setup de Git es crucial para los desarrolladores. Configura tu identidad y comienza a realizar commits.","fr":"Le paramétrage de Git est essentiel pour les développeurs. Configurez votre identité et commencez à réaliser des commits.","de":"Die Einrichtung von Git ist für Entwickler von entscheidender Bedeutung. Konfigurieren Sie Ihre Identität und beginnen Sie damit, Commits durchzuführen.","pt":"O git-setup é um skill que ajuda a configurar o Git e fazer commits. Ele verifica se a identidade do usuário está configurada e, se não, executa o fluxo de configuração","ru":"Git-setup - это навык, который помогает настроить Git и совершать коммиты. Он проверяет,是否 настроена личность пользователя, и, если нет, выполняет поток настройки с помощью ИИ Агентов","ar":"_git-setup هو مهارة تساعد في إعداد Git وعمليات الإيداع. يقوم بتأكيد ما إذا كانت هوية المستخدم لديه تم إعدادها، وإذا لم يكن، ينفذ تدفق الإعداد للآلات الذكية"},"seo":{"title":{"en":"git-setup: Setup Guide for AI Agents","zh":"git-setup配置指南","ja":"Git Setupベストプラクティス - AIエージェント","ko":"Git Setup 가이드 - AI Tools","es":"Configuración de Git: Guía de configuración para desarrol...","fr":"Paramétrage de Git : Meilleures pratiques pour les dévelo...","de":"Git-Setup: Einrichtungsleitfaden für Entwickler","pt":"Configuração do Git: Guia de Configuração","ru":"Настройка Git: Руководство по настройке ИИ Агентов","ar":"إعداد Git: دليل الإعداد للآلات الذكية"},"description":{"en":"Learn how to configure git with our step-by-step setup guide. Get started with git-setup and master git configuration, commits, and account setup.","zh":"了解git-setup的配置流程和技术细节，实现Git账户设置和提交","ja":"Git Setupの設定方法とベストプラクティスを学習し、AIエージェントを活用してGitコミットを効率化","ko":"Git Setup의 설정 방법과 기술 세부 사항을 익히고 AI Tools를 사용하여 Git 커밋을 최적화","es":"Aprende a configurar Git con nuestra guía paso a paso. Configura tu cuenta y comienza a realizar commits de manera efectiva con nuestros consejos para desarr...","fr":"Découvrez comment paramétrer Git avec notre guide étape par étape. Configurez votre compte et commencez à réaliser des commits de manière efficace avec nos c...","de":"Erfahren Sie, wie Sie Git mit unserem Schritt-für-Schritt-Leitfaden einrichten. Konfigurieren Sie Ihr Konto und beginnen Sie damit, Commits effektiv durchzuf...","pt":"Aprenda a configurar o Git com nosso guia passo a passo. Configure sua identidade e faça commits com facilidade","ru":"Узнайте, как настроить Git с нашей пошаговой инструкцией. Настройте свою личность и совершайте коммиты с легкостью с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Git مع دليلنا الخطوة بخطوة. configure هويتك و قم بعمليات الإيداع بسهولة مع الآلات الذكية"},"definition":{"en":"git-setup is a skill that enables developers to configure their git account, set up their identity, and make commits using commands like git config and git commit.","zh":"git-setup是一种用于配置Git账户和提交的技术","ja":"Git Setupは、Gitアカウントの設定とコミットを行う技術","ko":"Git Setup는 Git 계정 설정과 커밋을 수행하는 기술","es":"El setup de Git se refiere al proceso de configuración de la identidad del usuario y la cuenta para realizar commits.","fr":"Le paramétrage de Git fait référence au processus de configuration de l''identité de l''utilisateur et du compte pour réaliser des commits.","de":"Die Einrichtung von Git bezeichnet den Prozess der Konfiguration der Benutzeridentität und des Kontos für die Durchführung von Commits.","pt":"O git-setup é um skill de configuração do Git que ajuda a configurar a identidade do usuário e fazer commits","ru":"Git-setup - это навык настройки Git, который помогает настроить личность пользователя и совершать коммиты с помощью ИИ Агентов","ar":"git-setup هو مهارة إعداد Git تساعد في إعداد هوية المستخدم وعمليات الإيداع للآلات الذكية"},"features":{"en":["Sets up git identity using git config user.name and git config user.email","Configures git account settings using one-time account setup flow","Checks if identity is set before first commit using git config commands","Runs setup flow if identity is empty, using git config [--global] user.name and user.email","Supports commit flow after identity is set, using git commit commands"],"zh":["设置用户名和邮箱","配置Git账户","实现Git提交","支持一键设置","兼容多种Git版本","提供技术支持"],"ja":["ユーザー名とメールアドレスの設定","Gitアカウントの設定","Gitコミットの実装","ワンクリック設定","複数のGitバージョンのサポート","テクニカルサポート"],"ko":["사용자 이름과 이메일 설정","Git 계정 설정","Git 커밋 thực装","원클릭 설정","다양한 Git 버전 지원","기술 지원"],"es":["Configuración de la identidad del usuario con `git config user.name`","Configuración de la dirección de correo electrónico con `git config user.email`","Flujo de configuración de la cuenta de un solo uso","Verificación de la identidad antes del primer commit","Uso de `git config [--global]` para configurar la identidad globalmente"],"fr":["Configuration de l''identité de l''utilisateur avec `git config user.name`","Configuration de l''adresse e-mail avec `git config user.email`","Flux de configuration du compte à usage unique","Vérification de l''identité avant le premier commit","Utilisation de `git config [--global]` pour configurer l''identité de manière globale"],"de":["Konfiguration der Benutzeridentität mit `git config user.name`","Konfiguration der E-Mail-Adresse mit `git config user.email`","Einrichtungsfluss für die Einmal-Kontokonfiguration","Überprüfung der Identität vor dem ersten Commit","Verwendung von `git config [--global]` zur globalen Konfiguration der Identität"],"pt":["Configuração da identidade do usuário com `git config user.name`","Configuração do e-mail do usuário com `git config user.email`","Verificação da identidade do usuário antes do primeiro commit","Execução do fluxo de configuração se a identidade não estiver configurada","Suporte a commits com `git config`"],"ru":["Настройка личности пользователя с помощью `git config user.name`","Настройка электронной почты пользователя с помощью `git config user.email`","Проверка личности пользователя перед первым коммитом с помощью ИИ Агентов","Выполнение потока настройки, если личность не настроена","Поддержка коммитов с помощью `git config`"],"ar":["إعداد هوية المستخدم مع `git config user.name`","إعداد البريد الإلكتروني للمستخدم مع `git config user.email`","التأكد من هوية المستخدم قبل 第一 commit للآلات الذكية","تنفيذ تدفق الإعداد إذا لم يتم إعداد الهوية","دعم عمليات الإيداع مع `git config`"]},"keywords":{"en":["how to use git-setup","git-setup setup guide","git configuration best practices","git account setup tutorial","git-setup vs git config","git-setup install guide","what is git-setup","git-setup alternative tools","git-setup for developers"],"zh":["git-setup","Git配置","Git账户设置","Git提交","AI工具","git config","git commit","git setup流程"],"ja":["Git Setup","Git設定","Gitアカウント設定","Gitコミット","AIエージェント","git config","git commit","Git Setupベストプラクティス"],"ko":["Git Setup","Git 설정","Git 계정 설정","Git 커밋","AI Tools","git config","git commit","Git Setup 가이드"],"es":["configuración de git","setup de git","git para desarrolladores","configuración de la identidad de git","commits en git","git config user.name","git config user.email"],"fr":["paramétrage de git","configuration de git","git pour les développeurs","configuration de l''identité de git","commits dans git","git config user.name","git config user.email"],"de":["git einrichten","git setup","git für entwickler","konfiguration der git-identität","commits in git","git config user.name","git config user.email"],"pt":["configuração do git","git setup","identidade do usuário","commits","git config","configuração da identidade","primeiro commit"],"ru":["настройка git","git setup","личность пользователя","коммиты","git config","настройка личности","первый коммит","ИИ Агенты"],"ar":["إعداد git","git setup","هوية المستخدم","عمليات الإيداع","git config","إعداد الهوية","الأول commit","الآلات الذكية"]}},"owner":"Solrak97","repo":"cursor_workflow","repoPath":"Solrak97/cursor_workflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.495Z","topics":[],"category":"community","skillMd":{"name":"git-setup","description":"One-time git account setup (user.name, user.email) and commit workflow. Use when the user asks to set up git, configure git identity, or when git user.name/user.email appear unset. After setup, use Git MCP tools or the commit script for commits with messages.","bodyPreview":"# Git Setup & Commits\n\n## When to run\n\n- User says \"set up my git\", \"configure git\", \"git account\", or similar\n- Before first commit: check if identity is set (`git config user.name` / `git config user.email`); if empty, run the setup flow\n- User asks how to commit or wants to make a commit (use commit flow below after identity is set)\n\n## One-time account setup flow\n\nAsk the user (one question at a time if needed):\n\n1. **Name for commits:** `git config [--global] user.name \"Your Name\"`\n2. **Ema","body":"# Git Setup & Commits\n\n## When to run\n\n- User says \"set up my git\", \"configure git\", \"git account\", or similar\n- Before first commit: check if identity is set (`git config user.name` / `git config user.email`); if empty, run the setup flow\n- User asks how to commit or wants to make a commit (use commit flow below after identity is set)\n\n## One-time account setup flow\n\nAsk the user (one question at a time if needed):\n\n1. **Name for commits:** `git config [--global] user.name \"Your Name\"`\n2. **Email for commits:** `git config [--global] user.email \"you@example.com\"`\n3. **Scope:** \"For this repo only, or for all repos on this machine?\"  \n   - This repo only: omit `--global`  \n   - All repos: use `--global`\n\nThen run:\n\n```bash\ngit config [--global] user.name \"Their Name\"\ngit config [--global] user.email \"their@email.com\"\n```\n\nConfirm with: `git config user.name` and `git config user.email` (or with `--global` if they chose global).\n\n## Making commits (after setup)\n\nUse **one** of these:\n\n### Option A: Git MCP (preferred when available)\n\n- **git_status**: Check for changes\n- **git_diff**: Review changes\n- **git_commit**: Create commit with message (stages all by default)\n  - Parameters: `message` (required), `stage_all` (default true)\n\nUse the `git_commit` tool with a clear, conventional message (e.g. `feat: add login form`, `fix: resolve null in parser`).\n\n### Option B: Commit script (when MCP not used)\n\nRun the skill''s script from the **project repository root** (not inside the submodule):\n\n```bash\nbash .cursor/cursor_workflow/.cursor/skills/git-setup/scripts/commit.sh \"your commit message here\"\n```\n\nOr if skills were copied to project `.cursor/skills/`:\n\n```bash\nbash .cursor/skills/git-setup/scripts/commit.sh \"your commit message here\"\n```\n\nThe script stages all changes and creates a single commit with the given message.\n\n## Commit message guidelines\n\n- Use conventional style when possible: `feat:`, `fix:`, `docs:`, `refactor:`, `test:`\n- One line, imperative: \"Add login\" not \"Added login\"\n- Reference task/ticket if applicable (e.g. \"feat: add login (task #12)\")\n\n## Summary\n\n1. **Once:** Run account setup flow → set `user.name` and `user.email` (local or global).\n2. **Commits:** Use Git MCP `git_commit` with a message, or run `scripts/commit.sh \"message\"` from repo root.\n"},"lastSynced":"2026-03-08T02:10:12.772Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined git configuration and commit management.","zh":"非常适合需要简化git配置和提交管理的开发代理。","ja":"開発エージェントがストリームライン化されたgitの設定とコミット管理を必要とする場合に最適です。","ko":"git 구성 및 커밋 관리를 간소화해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una configuración de git simplificada y una gestión de commits.","fr":"Parfait pour les agents de développement ayant besoin d''une configuration git simplifiée et d''une gestion de commits.","de":"Perfekt für Entwicklungsmittel, die eine vereinfachte git-Konfiguration und eine Commit-Verwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de configuração de git simplificada e gerenciamento de commits.","ru":"Идеально подходит для агентов разработки, которым необходима упрощенная настройка git и управление коммитами.","ar":"مثالي لعميل التطوير الذي يحتاج إلى تكوين git مبسط وإدارة الإلتزامات."},"recommendation":{"en":"Empowers agents to configure git identities using `git config` commands, set up commit histories, and manage git accounts efficiently, leveraging protocols like git config and file formats such as commit logs.","zh":"使代理能够使用`git config`命令配置git身份，设置提交历史，并利用诸如git config和提交日志等协议高效地管理git账户。","ja":"エージェントが`git config`コマンドを使用してgit ID を構成し、コミット履歴を設定し、git configやコミットログなどのプロトコルを利用してgitアカウントを効率的に管理できるようにします。","ko":"에이전트가 `git config` 명령을 사용하여 git ID를 구성하고 커밋 기록을 설정하며 git config 및 커밋 로그 등의 프로토콜을 활용하여 git 계정을 효율적으로 관리하도록 합니다.","es":"Habilita a los agentes a configurar identidades de git mediante comandos `git config`, configurar historiales de commits y gestionar cuentas de git de manera eficiente, utilizando protocolos como git config y formatos de archivo como registros de commit.","fr":"Permet aux agents de configurer des identités git à l''aide de commandes `git config`, de configurer des historiques de commit et de gérer des comptes git de manière efficace, en exploitant des protocoles tels que git config et des formats de fichier tels que les journaux de commit.","de":"Ermöglicht es den Agenten, git-Identitäten mithilfe von `git config`-Befehlen zu konfigurieren, Commit-Verlaufsprotokolle einzurichten und git-Konten effizient zu verwalten, indem Protokolle wie git config und Dateiformate wie Commit-Protokolle genutzt werden.","pt":"Habilita os agentes a configurar identidades git usando comandos `git config`, configurar históricos de commits e gerenciar contas git de forma eficiente, aproveitando protocolos como git config e formatos de arquivo como logs de commits.","ru":"Наделяет агентов возможностью настраивать идентификаторы git с помощью команд `git config`, устанавливать истории коммитов и эффективно управлять учетными записями git, используя протоколы seperti git config и форматы файлов, такие как журналы коммитов.","ar":"تمكّن الوكلاء من تكوين هويات git باستخدام أوامر `git config`، وضبط سجلات الإلتزامات وإدارة حسابات git بفعالية، مستفيدة من بروتوكولات مثل git config وتنسيقات الملفات مثل سجلات الإلتزامات."},"useCases":{"en":["Configuring git identities for new projects","Managing commit histories for collaborative development","Automating initial git setup for developers"],"zh":["为新项目配置git身份","管理协作开发的提交历史","为开发人员自动执行初始git设置"],"ja":["新しいプロジェクトのgit IDの構成","共同開発のコミット履歴の管理","開発者のための初期git設定の自動化"],"ko":["새 프로젝트를 위한 git ID 구성","협동 개발을 위한 커밋 기록 관리","개발자 위한 초기 git 설정 자동화"],"es":["Configuración de identidades de git para nuevos proyectos","Gestión de historiales de commits para el desarrollo colaborativo","Automatización de la configuración inicial de git para desarrolladores"],"fr":["Configuration des identités git pour les nouveaux projets","Gestion des historiques de commit pour le développement collaboratif","Automatisation de la configuration initiale de git pour les développeurs"],"de":["Konfiguration von git-Identitäten für neue Projekte","Verwaltung von Commit-Verlaufsprotokollen für die Zusammenarbeit bei der Entwicklung","Automatisierung der initialen git-Konfiguration für Entwickler"],"pt":["Configurando identidades git para novos projetos","Gerenciando históricos de commits para desenvolvimento colaborativo","Automatizando a configuração inicial do git para desenvolvedores"],"ru":["Настройка идентификаторов git для новых проектов","Управление историей коммитов для совместной разработки","Автоматизация первоначальной настройки git для разработчиков"],"ar":["تكوين هويات git لمشاريع جديدة","إدارة سجلات الإلتزامات لتطوير تعاوني","تأتميم إعدادات git الأولية للمطورين"]},"limitations":{"en":["Requires git installation and access","Limited to git-based version control systems"],"zh":["需要git安装和访问","仅限于基于git的版本控制系统"],"ja":["gitのインストールとアクセスが必要","gitベースのバージョン管理システムに限定される"],"ko":["git 설치 및 접근이 필요","git 기반 버전 관리 시스템에만 제한"],"es":["Requiere la instalación y el acceso a git","Limitado a sistemas de control de versiones basados en git"],"fr":["Nécessite l''installation et l''accès à git","Limité aux systèmes de contrôle de version basés sur git"],"de":["Benötigt die Installation und den Zugriff auf git","Begrenzt auf git-basierte Versionskontrollsysteme"],"pt":["Exige instalação do git e acesso","Limitado a sistemas de controle de versão baseados em git"],"ru":["Требуется установка git и доступ","Ограничен для систем контроля версий на основе git"],"ar":["يتطلب تثبيت git والوصول","محدود بنظم تحكم بالنسخ المبنية على git"]},"version":4},"contentHash":"c6b232667e5ce5ccbb44311d9a2ccf646b5ff99267932bf1eff9e97045e8d826","qualityScore":36}');
