INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Solrak97/cursor_workflow/git-setup', 'git-setup', 'Solrak97', 'cursor_workflow', 'community', 'git-setup Solrak97 cursor_workflow community The git-setup skill helps developers configure git by setting up their identity and making commits. It benefits developers who need to manage their git accounts and commit history. git-setup是用于配置Git账户和提交的技术，包括设置用户名和邮箱 Git Setupは、Gitアカウントの設定とコミットを行う技術であり、ユーザー名とメールアドレスの設定が含まれる Git Setup는 Git 계정 설정과 커밋을 수행하는 기술로, 사용자 이름과 이메일 설정이 포함 El setup de Git es crucial para los desarrolladores. Configura tu identidad y comienza a realizar commits. Le paramétrage de Git est essentiel pour les développeurs. Configurez votre identité et commencez à réaliser des commits. Die Einrichtung von Git ist für Entwickler von entscheidender Bedeutung. Konfigurieren Sie Ihre Identität und beginnen Sie damit, Commits durchzuführen. O git-setup é um skill que ajuda a configurar o Git e fazer commits. Ele verifica se a identidade do usuário está configurada e, se não, executa o fluxo de configuração Git-setup - это навык, который помогает настроить Git и совершать коммиты. Он проверяет,是否 настроена личность пользователя, и, если нет, выполняет поток настройки с помощью ИИ Агентов _git-setup هو مهارة تساعد في إعداد Git وعمليات الإيداع. يقوم بتأكيد ما إذا كانت هوية المستخدم لديه تم إعدادها، وإذا لم يكن، ينفذ تدفق الإعداد للآلات الذكية how to use git-setup git-setup setup guide git configuration best practices git account setup tutorial git-setup vs git config git-setup install guide what is git-setup git-setup alternative tools git-setup for developers git-setup Git配置 Git账户设置 Git提交 AI工具 git config git commit git setup流程 Sets up git identity using git config user.name and git config user.email Configures git account settings using one-time account setup flow Checks if identity is set before first commit using git config commands Runs setup flow if identity is empty, using git config [--global] user.name and user.email Supports commit flow after identity is set, using git commit commands git-setup is a skill that enables developers to configure their git account, set up their identity, and make commits using commands like git config and git commit.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sayujks0071/probable-fiesta/risk-management', 'community', 'sayujks0071', 'probable-fiesta', 'sayujks0071/probable-fiesta', 'risk-management', 0, 0, 36, '2026-03-08T01:57:15.496Z', '2026-03-08T02:10:13.923Z', '675d7c7b864fbfff73a923ced43dbc2bd40a7997bce5cf9fe66767469103334b', '{"id":"sayujks0071/probable-fiesta/risk-management","name":"risk-management","description":{"en":"The risk-management skill helps AI agents manage trade risks by setting per-trade risk limits and monitoring portfolio heat, benefiting developers and traders alike.","zh":"风险管理是交易中的关键组成部分，涉及风险限额、仓位规模和时间退出策略","ja":"リスク管理はトレーディングの重要な要素であり、リスク限度、ポジションサイズ、時間ベースの退出戦略を含む","ko":"리스크 관리는 거래의 중요한 부분으로 리스크 한계, 포지션 크기, 시간 기반 종료 전략을 포함","es":"La gestión de riesgos es crucial para los agentes de IA. Configure límites de riesgo personalizados y estrategias de salida basadas en el tiempo para minimizar las pérdidas","fr":"La gestion des risques est essentielle pour les outils d''IA. Paramétrez des limites de risque personnalisées et des stratégies de sortie basées sur le temps pour minimiser les pertes","de":"Das Risikomanagement ist für KI-Agents entscheidend. Richten Sie benutzerdefinierte Risikolimits und zeitbasierte Ausstiegstrategien ein, um Verluste zu minimieren","pt":"O gerenciamento de risco é uma habilidade crucial para ferramentas de inteligência artificial, permitindo limites de risco personalizáveis e estratégias de saída baseadas no tempo","ru":"Управление рисками является важнейшим навыком для ИИ Агентов, позволяющим устанавливать индивидуальные лимиты риска и временные стратегии выхода","ar":"إدارة المخاطر هي مهارة حيوية لأدوات الذكاء الاصطناعي، مما يسمح بحدود المخاطر القابلة للتعديل واستراتيجيات الخروج المستندة إلى الوقت"},"seo":{"title":{"en":"Risk-Management: Setup Guide for AI Agents","zh":"风险管理 Setup Guide - AIエージェント","ja":"リスク管理 Best Practices - AIエージェント","ko":"리스크 관리 Setup Guide - AI 툴","es":"Guía de Configuración de Gestión de Riesgos para Agentes ...","fr":"Paramétrer la Gestion des Risques pour les Outils d''IA","de":"Risikomanagement-Setup für KI-Agents","pt":"Guia de Configuração de Gerenciamento de Risco para Ferra...","ru":"Настройка управления рисками для ИИ Агентов: Лучшие практики","ar":"دليل إعداد إدارة المخاطر لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to implement risk-management in your AI agent with our expert setup guide and minimize losses with per-trade risk limits and daily loss limits","zh":"了解风险管理的核心原则，包括风险限额、仓位规模和时间退出策略，优化您的交易策略","ja":"リスク管理の基本原則を学び、リスク限度、ポジションサイズ、時間ベースの退出戦略を最適化する","ko":"리스크 관리의 핵심 원칙을 배우고 리스크 한계, 포지션 크기, 시간 기반 종료 전략을 최적화 하세요","es":"Aprende a configurar la gestión de riesgos para agentes de IA con límites de riesgo personalizados y estrategias de salida basadas en el tiempo","fr":"Découvrez comment paramétrer la gestion des risques pour les outils d''IA avec des limites de risque personnalisées et des stratégies de sortie basées sur le ...","de":"Erfahren Sie, wie Sie das Risikomanagement für KI-Agents mit benutzerdefinierten Risikolimits und zeitbasierten Ausstiegstrategien einrichten","pt":"Aprenda a configurar o gerenciamento de risco para ferramentas de inteligência artificial com limites de risco personalizáveis e estratégias de saída baseada...","ru":"Узнайте, как настроить управление рисками для ИИ Агентов с индивидуальными лимитами риска и временными стратегиями выхода","ar":"تعلم كيفية إعداد إدارة المخاطر لأدوات الذكاء الاصطناعي مع حدود المخاطر القابلة للتعديل واستراتيجيات الخروج المستندة إلى الوقت"},"definition":{"en":"Risk-management is a set of principles and rules that help AI agents limit potential losses by setting risk limits, monitoring portfolio exposure, and triggering automatic position flattening","zh":"风险管理是指使用风险限额、仓位规模和时间退出策略来控制和管理交易风险的过程","ja":"リスク管理とは、リスク限度、ポジションサイズ、時間ベースの退出戦略を使用してトレーディングリスクを制御するプロセス","ko":"리스크 관리는 리스크 한계, 포지션 크기, 시간 기반 종료 전략을 사용하여 거래 리스크를 제어하고 관리하는 과정","es":"La gestión de riesgos es el proceso de identificar y mitigar los riesgos asociados con los agentes de IA","fr":"La gestion des risques est le processus d''identification et d''atténuation des risques associés aux outils d''IA","de":"Das Risikomanagement ist der Prozess der Identifizierung und Minderung der Risiken, die mit KI-Agents verbunden sind","pt":"O gerenciamento de risco é a capacidade de controlar e mitigar riscos financeiros em operações de inteligência artificial","ru":"Управление рисками - это способность контролировать и смягчать финансовые риски в операциях ИИ Агентов","ar":"إدارة المخاطر هي القدرة على التحكم والتخفيف من المخاطر المالية في عمليات الذكاء الاصطناعي"},"features":{"en":["Sets per-trade risk limits between 0.5-2.0% of capital","Monitors aggregate exposure across all positions with portfolio heat","Triggers automatic position flattening with daily loss limit of -2.5% of capital","Automatically squares off positions at 15:25 IST to prevent overnight risk","Supports time-based exits to minimize potential losses"],"zh":["支持每笔交易风险限额（默认0.5-2.0%）","支持最大仓位规模（2.0%）","支持每日损失限额（-2.5%）","支持时间退出策略（EOD auto square-off）","支持风险基于的仓位规模","支持多种技术指标"],"ja":["トレードごとのリスク限度（デフォルト0.5-2.0%）をサポート","最大ポジションサイズ（2.0%）をサポート","毎日損失限度（-2.5%）をサポート","時間ベースの退出戦略（EOD auto square-off）をサポート","リスクベースのポジションサイズをサポート","多種のテクニカル指標をサポート"],"ko":["거래별 리스크 한계（기본 0.5-2.0%）을 지원","최대 포지션 크기（2.0%）을 지원","일일 손실 한계（-2.5%）을 지원","시간 기반 종료 전략（EOD auto square-off）을 지원","리스크 기반의 포지션 크기를 지원","다양한 기술적 지표를 지원"],"es":["Límites de riesgo personalizados por operación","Límites de riesgo de cartera para controlar la exposición","Límites de pérdida diaria para evitar pérdidas excesivas","Estrategias de salida basadas en el tiempo para minimizar el riesgo","Monitoreo de la exposición agregada en todas las posiciones","Parametrización de la posición para minimizar el riesgo"],"fr":["Limites de risque personnalisés par opération","Limites de risque de portefeuille pour contrôler l''exposition","Limites de perte journalière pour éviter les pertes excessives","Stratégies de sortie basées sur le temps pour minimiser le risque","Suivi de l''exposition agrégée dans toutes les positions","Paramétrage de la position pour minimiser le risque"],"de":["Benutzerdefinierte Risikolimits pro Trade","Risikolimits für das Portfolio zur Kontrolle der Exposition","Tägliche Verlustlimits zur Vermeidung exzessiver Verluste","Zeitbasierte Ausstiegstrategien zur Minimierung des Risikos","Überwachung der aggregierten Exposition in allen Positionen","Parametrierung der Position zur Minimierung des Risikos"],"pt":["Limites de risco personalizáveis (0,5-2,0% do capital por negociação)","Estratégias de saída baseadas no tempo (EOD auto square-off: 15:25 IST)","Monitoramento de exposição agregada em todas as posições","Limite de perda diário (-2,5% do capital)","Posicionamento baseado em risco"],"ru":["Индивидуальные лимиты риска (0,5-2,0% капитала за торговлю)","Временные стратегии выхода (EOD auto square-off: 15:25 IST)","Мониторинг агрегированной экспозиции во всех позициях","Дневной лимит потерь (-2,5% капитала)","Позиционирование на основе риска"],"ar":["حدود المخاطر القابلة للتعديل (0.5-2.0٪ من رأس المال لكل صفقة)","استراتيجيات الخروج المستندة إلى الوقت (EOD auto square-off: 15:25 IST)","مراقبة التعرّض المجمّع في جميع المواقف","حد الخسارة اليومي (-2.5٪ من رأس المال)","التحديد المستند إلى المخاطر"]},"keywords":{"en":["how to use risk-management in AI agents","what is risk-management in trading","risk-management alternative for AI agents","risk-management vs portfolio optimization","risk-management setup guide for developers","installing risk-management in AI agents","risk-management best practices for traders"],"zh":["风险管理","AIエージェント","交易策略","风险限额","仓位规模","时间退出策略","Python","React","CLI"],"ja":["リスク管理","AIエージェント","トレーディング戦略","リスク限度","ポジションサイズ","時間ベースの退出戦略","Python","React","CLI"],"ko":["리스크 관리","AI 툴","거래 전략","리스크 한계","포지션 크기","시간 기반 종료 전략","Python","React","CLI"],"es":["gestión de riesgos para agentes de IA","límites de riesgo personalizados","estrategias de salida basadas en el tiempo","monitoreo de exposición","parametrización de la posición","agentes de IA y gestión de riesgos","herramientas de IA para la gestión de riesgos","configuración de la gestión de riesgos para agentes de IA"],"fr":["gestion des risques pour les outils d''IA","limites de risque personnalisés","stratégies de sortie basées sur le temps","suivi de l''exposition","paramétrage de la position","outils d''IA et gestion des risques","outils d''IA pour la gestion des risques","paramétrage de la gestion des risques pour les outils d''IA"],"de":["Risikomanagement für KI-Agents","benutzerdefinierte Risikolimits","zeitbasierte Ausstiegstrategien","Überwachung der Exposition","Parametrierung der Position","KI-Agents und Risikomanagement","KI-Tools für das Risikomanagement","Einrichtung des Risikomanagements für KI-Agents"],"pt":["gerenciamento de risco","ferramentas de inteligência artificial","limites de risco","estratégias de saída","monitoramento de exposição","limite de perda diário","posicionamento baseado em risco"],"ru":["управление рисками","ИИ Агенты","индивидуальные лимиты риска","временные стратегии выхода","мониторинг агрегированной экспозиции","дневной лимит потерь","позиционирование на основе риска"],"ar":["إدارة المخاطر","أدوات الذكاء الاصطناعي","حدود المخاطر القابلة للتعديل","استراتيجيات الخروج المستندة إلى الوقت","مراقبة التعرّض المجمّع","حد الخسارة اليومي","التحديد المستند إلى المخاطر"]}},"owner":"sayujks0071","repo":"probable-fiesta","repoPath":"sayujks0071/probable-fiesta","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.496Z","topics":[],"category":"community","skillMd":{"name":"risk-management","description":"Implement and review risk controls, position sizing, portfolio heat limits, stop losses, and risk monitoring. Use when implementing risk management, reviewing risk controls, calculating position sizes, or analyzing portfolio risk exposure.","bodyPreview":"# Risk Management\n\n## Core Principles\n\n### Risk Limits\n\n**Per-Trade Risk:**\n- Default: 0.5-2.0% of capital per trade\n- Maximum: 2.5% per trade (hard limit)\n\n**Portfolio Heat:**\n- Maximum: 2.0% of capital at risk simultaneously\n- Monitors aggregate exposure across all positions\n\n**Daily Loss Limit:**\n- Hard stop: -2.5% of capital\n- Triggers automatic position flattening\n\n**Time-Based Exits:**\n- EOD auto square-off: 15:25 IST\n- Prevents overnight risk\n\n## Position Sizing\n\n### Risk-Based Position S","body":"# Risk Management\n\n## Core Principles\n\n### Risk Limits\n\n**Per-Trade Risk:**\n- Default: 0.5-2.0% of capital per trade\n- Maximum: 2.5% per trade (hard limit)\n\n**Portfolio Heat:**\n- Maximum: 2.0% of capital at risk simultaneously\n- Monitors aggregate exposure across all positions\n\n**Daily Loss Limit:**\n- Hard stop: -2.5% of capital\n- Triggers automatic position flattening\n\n**Time-Based Exits:**\n- EOD auto square-off: 15:25 IST\n- Prevents overnight risk\n\n## Position Sizing\n\n### Risk-Based Position Sizing\n\n```python\ndef calculate_position_size(entry_price, stop_loss_price, account_size, risk_pct=0.02):\n    \"\"\"\n    Calculate position size based on risk per trade.\n    \n    Args:\n        entry_price: Entry price\n        stop_loss_price: Stop loss price\n        account_size: Total account size\n        risk_pct: Risk percentage per trade (default 2%)\n    \n    Returns:\n        Quantity to trade\n    \"\"\"\n    risk_amount = account_size * risk_pct\n    risk_per_unit = abs(entry_price - stop_loss_price)\n    \n    if risk_per_unit == 0:\n        return 0\n    \n    quantity = int(risk_amount / risk_per_unit)\n    return max(quantity, 1)  # Minimum 1 unit\n```\n\n### ATR-Based Position Sizing\n\n```python\ndef calculate_atr_position_size(entry_price, atr, account_size, risk_pct=0.02, atr_multiplier=2.0):\n    \"\"\"\n    Calculate position size using ATR-based stop loss.\n    \n    Args:\n        entry_price: Entry price\n        atr: Average True Range\n        account_size: Total account size\n        risk_pct: Risk percentage per trade\n        atr_multiplier: ATR multiplier for stop loss (default 2.0)\n    \n    Returns:\n        Quantity to trade\n    \"\"\"\n    stop_loss_price = entry_price - (atr * atr_multiplier)\n    return calculate_position_size(entry_price, stop_loss_price, account_size, risk_pct)\n```\n\n### Options Position Sizing\n\n```python\ndef calculate_options_position_size(option_ltp, lot_size, account_size, risk_pct=0.02, sl_pct=0.20):\n    \"\"\"\n    Calculate options position size.\n    \n    Args:\n        option_ltp: Option last traded price\n        lot_size: Lot size (e.g., 50 for NIFTY)\n        account_size: Total account size\n        risk_pct: Risk percentage per trade\n        sl_pct: Stop loss percentage (default 20% for options)\n    \n    Returns:\n        Number of lots\n    \"\"\"\n    risk_amount = account_size * risk_pct\n    risk_per_lot = option_ltp * lot_size * sl_pct\n    \n    if risk_per_lot == 0:\n        return 0\n    \n    lots = int(risk_amount / risk_per_lot)\n    return max(lots, 1)  # Minimum 1 lot\n```\n\n## Portfolio Heat Management\n\n### Heat Calculation\n\n```python\nclass PortfolioRiskManager:\n    def __init__(self, account_size, max_heat=0.02):\n        self.account_size = account_size\n        self.max_heat = max_heat  # 2% max portfolio heat\n        self.positions = []\n    \n    def calculate_position_risk(self, position):\n        \"\"\"Calculate risk for a single position\"\"\"\n        if position[''side''] == ''LONG'':\n            risk = abs(position[''entry_price''] - position[''stop_loss'']) * position[''quantity'']\n        else:  # SHORT\n            risk = abs(position[''stop_loss''] - position[''entry_price'']) * position[''quantity'']\n        \n        return risk\n    \n    def calculate_portfolio_heat(self):\n        \"\"\"Calculate total portfolio heat\"\"\"\n        total_risk = sum(self.calculate_position_risk(pos) for pos in self.positions)\n        heat_pct = total_risk / self.account_size\n        return heat_pct\n    \n    def can_add_position(self, new_position_risk):\n        \"\"\"Check if new position can be added\"\"\"\n        current_heat = self.calculate_portfolio_heat()\n        new_heat = (current_heat * self.account_size + new_position_risk) / self.account_size\n        \n        return new_heat <= self.max_heat\n```\n\n### Heat Monitoring\n\n```python\ndef check_portfolio_heat(positions, account_size, max_heat=0.02):\n    \"\"\"\n    Check if portfolio heat is within limits.\n    \n    Returns:\n        (is_ok, current_heat, max_heat)\n    \"\"\"\n    total_risk = sum(\n        abs(pos[''entry_price''] - pos[''stop_loss'']) * pos[''quantity'']\n        for pos in positions\n    )\n    \n    current_heat = total_risk / account_size\n    \n    if current_heat > max_heat:\n        logger.warning(f\"[REJECTED] Portfolio heat limit: {current_heat:.2%} > {max_heat:.2%}\")\n        return False, current_heat, max_heat\n    \n    return True, current_heat, max_heat\n```\n\n## Stop Loss Management\n\n### Fixed Percentage Stop Loss\n\n```python\ndef calculate_stop_loss(entry_price, side, stop_loss_pct=1.5):\n    \"\"\"\n    Calculate stop loss price.\n    \n    Args:\n        entry_price: Entry price\n        side: ''BUY'' (long) or ''SELL'' (short)\n        stop_loss_pct: Stop loss percentage\n    \n    Returns:\n        Stop loss price\n    \"\"\"\n    if side == ''BUY'':\n        return entry_price * (1 - stop_loss_pct / 100)\n    else:  # SELL (short)\n        return entry_price * (1 + stop_loss_pct / 100)\n```\n\n### ATR-Based Stop Loss\n\n```python\ndef calculate_atr_stop_loss(entry_price, atr, side, atr_multiplier=2.0):\n    \"\"\"\n    Calculate ATR-based stop loss.\n    \n    Args:\n        entry_price: Entry price\n        atr: Average True Range\n        side: ''BUY'' (long) or ''SELL'' (short)\n        atr_multiplier: ATR multiplier (default 2.0)\n    \n    Returns:\n        Stop loss price\n    \"\"\"\n    stop_distance = atr * atr_multiplier\n    \n    if side == ''BUY'':\n        return entry_price - stop_distance\n    else:  # SELL (short)\n        return entry_price + stop_distance\n```\n\n### Trailing Stop Loss\n\n```python\nclass TrailingStop:\n    def __init__(self, initial_stop, trailing_pct=0.5):\n        self.initial_stop = initial_stop\n        self.trailing_pct = trailing_pct\n        self.current_stop = initial_stop\n        self.highest_price = initial_stop  # For long positions\n    \n    def update(self, current_price, side=''BUY''):\n        \"\"\"Update trailing stop based on current price\"\"\"\n        if side == ''BUY'':\n            if current_price > self.highest_price:\n                self.highest_price = current_price\n                self.current_stop = current_price * (1 - self.trailing_pct / 100)\n        else:  # SELL (short)\n            if current_price < self.lowest_price:\n                self.lowest_price = current_price\n                self.current_stop = current_price * (1 + self.trailing_pct / 100)\n        \n        return self.current_stop\n    \n    def is_stopped_out(self, current_price, side=''BUY''):\n        \"\"\"Check if stop loss is hit\"\"\"\n        if side == ''BUY'':\n            return current_price <= self.current_stop\n        else:  # SELL (short)\n            return current_price >= self.current_stop\n```\n\n## Take Profit Management\n\n### Fixed Take Profit\n\n```python\ndef calculate_take_profit(entry_price, side, take_profit_pct=3.0):\n    \"\"\"\n    Calculate take profit price.\n    \n    Args:\n        entry_price: Entry price\n        side: ''BUY'' (long) or ''SELL'' (short)\n        take_profit_pct: Take profit percentage\n    \n    Returns:\n        Take profit price\n    \"\"\"\n    if side == ''BUY'':\n        return entry_price * (1 + take_profit_pct / 100)\n    else:  # SELL (short)\n        return entry_price * (1 - take_profit_pct / 100)\n```\n\n### Staged Take Profit\n\n```python\nclass StagedTakeProfit:\n    def __init__(self, entry_price, side, tp_levels=[0.5, 1.0, 1.5]):\n        \"\"\"\n        Staged take profit with multiple levels.\n        \n        Args:\n            entry_price: Entry price\n            side: ''BUY'' (long) or ''SELL'' (short)\n            tp_levels: List of take profit percentages\n        \"\"\"\n        self.entry_price = entry_price\n        self.side = side\n        self.tp_levels = sorted(tp_levels)\n        self.levels_hit = []\n    \n    def calculate_tp_prices(self):\n        \"\"\"Calculate take profit prices for all levels\"\"\"\n        tp_prices = []\n        for level in self.tp_levels:\n            if self.side == ''BUY'':\n                tp_price = self.entry_price * (1 + level / 100)\n            else:  # SELL (short)\n                tp_price = self.entry_price * (1 - level / 100)\n            tp_prices.append(tp_price)\n        return tp_prices\n    \n    def check_tp_levels(self, current_price):\n        \"\"\"Check which take profit levels are hit\"\"\"\n        tp_prices = self.calculate_tp_prices()\n        hit_levels = []\n        \n        for i, tp_price in enumerate(tp_prices):\n            if i in self.levels_hit:\n                continue\n            \n            if self.side == ''BUY'' and current_price >= tp_price:\n                hit_levels.append(i)\n            elif self.side == ''SELL'' and current_price <= tp_price:\n                hit_levels.append(i)\n        \n        self.levels_hit.extend(hit_levels)\n        return hit_levels\n```\n\n## Daily Loss Limits\n\n### Daily Loss Tracking\n\n```python\nclass DailyLossTracker:\n    def __init__(self, account_size, daily_loss_limit=-0.025):\n        self.account_size = account_size\n        self.daily_loss_limit = daily_loss_limit  # -2.5%\n        self.starting_balance = account_size\n        self.current_balance = account_size\n        self.trades_today = []\n    \n    def update_balance(self, new_balance):\n        \"\"\"Update current balance\"\"\"\n        self.current_balance = new_balance\n    \n    def add_trade(self, trade_pnl):\n        \"\"\"Add trade PnL\"\"\"\n        self.trades_today.append(trade_pnl)\n        self.current_balance += trade_pnl\n    \n    def check_daily_loss(self):\n        \"\"\"Check if daily loss limit is exceeded\"\"\"\n        daily_pnl = self.current_balance - self.starting_balance\n        daily_pnl_pct = daily_pnl / self.starting_balance\n        \n        if daily_pnl_pct <= self.daily_loss_limit:\n            logger.error(f\"[RISK] Daily loss limit hit: {daily_pnl_pct:.2%}\")\n            return True\n        \n        return False\n    \n    def reset_daily(self):\n        \"\"\"Reset for new trading day\"\"\"\n        self.starting_balance = self.current_balance\n        self.trades_today = []\n```\n\n## Risk Monitoring\n\n### Real-Time Risk Check\n\n```python\ndef check_signal_risk(signal, portfolio_manager, account_size):\n    \"\"\"\n    Comprehensive risk check before entering trade.\n    \n    Returns:\n        (is_approved, rejection_reason)\n    \"\"\"\n    # 1. Per-trade risk check\n    position_risk = calculate_position_risk(signal)\n    risk_pct = position_risk / account_size\n    \n    if risk_pct > 0.025:  # 2.5% max per trade\n        return False, \"Per-trade risk limit exceeded\"\n    \n    # 2. Portfolio heat check\n    can_add, current_heat, max_heat = check_portfolio_heat(\n        portfolio_manager.positions,\n        account_size\n    )\n    \n    if not can_add:\n        return False, f\"Portfolio heat limit: {current_heat:.2%} > {max_heat:.2%}\"\n    \n    # 3. Daily loss check\n    if portfolio_manager.daily_loss_tracker.check_daily_loss():\n        return False, \"Daily loss limit exceeded\"\n    \n    # 4. Position limit check\n    if len(portfolio_manager.positions) >= MAX_POSITIONS:\n        return False, \"Maximum position limit reached\"\n    \n    return True, None\n```\n\n## Risk Reporting\n\n### Risk Metrics Report\n\n```python\ndef generate_risk_report(portfolio_manager, account_size):\n    \"\"\"Generate comprehensive risk report\"\"\"\n    report = {\n        ''account_size'': account_size,\n        ''current_balance'': portfolio_manager.current_balance,\n        ''portfolio_heat'': portfolio_manager.calculate_portfolio_heat(),\n        ''max_heat_limit'': 0.02,\n        ''daily_pnl'': portfolio_manager.daily_loss_tracker.current_balance - portfolio_manager.daily_loss_tracker.starting_balance,\n        ''daily_loss_limit'': account_size * -0.025,\n        ''positions'': len(portfolio_manager.positions),\n        ''max_positions'': MAX_POSITIONS,\n        ''total_exposure'': sum(pos[''quantity''] * pos[''entry_price''] for pos in portfolio_manager.positions)\n    }\n    \n    return report\n```\n\n## Best Practices\n\n1. **Always use stop losses** - Never enter a trade without a defined stop loss\n2. **Respect portfolio heat** - Monitor aggregate risk across all positions\n3. **Scale position sizes** - Reduce size during drawdowns, increase during winning streaks\n4. **Time-based exits** - Always exit before market close (15:25 IST)\n5. **Daily loss limits** - Hard stop at -2.5% to prevent catastrophic losses\n6. **Regular monitoring** - Check risk metrics throughout the trading day\n7. **Document exceptions** - Log any risk limit overrides with justification\n\n## Additional Resources\n\n- AITRAPP risk module: `AITRAPP/AITRAPP/packages/core/risk.py`\n- Trading utils: `openalgo/strategies/utils/trading_utils.py`\n- Risk documentation: `AITRAPP/AITRAPP/SECURITY.md`\n"},"lastSynced":"2026-03-08T02:10:13.923Z","agentAnalysis":{"suitability":{"en":"Perfect for Trading Agents needing advanced risk management capabilities with per-trade risk limits and portfolio heat monitoring.","zh":"非常适合需要高级风险管理能力的交易代理，包括每笔交易风险限制和投资组合热度监控。","ja":"高度なリスク管理機能を必要とするトレーディングエージェントに適しています。取引ごとのリスク限度とポートフォリオの熱度監視などを提供します。","ko":"고급 리스크 관리 기능이 필요한 트레이딩 에이전트에게 적합합니다. 거래별 리스크 제한 및 포트폴리오의 열기 모니터링 등을 제공합니다.","es":"Perfecto para Agentes de Trading que necesitan capacidades de gestión de riesgos avanzadas con límites de riesgo por operación y monitoreo de calor de cartera.","fr":"Parfait pour les Agents de Trading qui nécessitent des capacités de gestion de risques avancées avec des limites de risque par transaction et un suivi de la chaleur du portefeuille.","de":"Perfekt für Trading-Agenten, die erweiterte Risikomanagementfunktionen mit Risikolimits pro Trade und Überwachung der Portfoliohitze benötigen.","pt":"Perfeito para Agentes de Negociação que necessitam de capacidades avançadas de gerenciamento de riscos com limites de risco por negociação e monitoramento de calor de carteira.","ru":"Идеально для торговых агентов, которым необходимы продвинутые возможности управления рисками с лимитами риска на сделку и мониторингом портфельного тепла.","ar":" مثالي للوكلاء التجاريين الذين يحتاجون إلى إمكانيات إدارة المخاطر المتقدمة مع حدود المخاطر لكل сделة ومراقبة حرارة المحفظة."},"recommendation":{"en":"Empowers agents to manage trade risks by setting default and maximum per-trade risk limits of 0.5-2.0% and 2.5% of capital respectively, while monitoring portfolio heat and enforcing daily loss limits using protocols like automatic position flattening.","zh":"赋予代理管理交易风险的能力，通过设置默认和最大每笔交易风险限度（分别为资本的0.5-2.0%和2.5%），同时监控投资组合热度，并使用自动平仓等协议强制执行每日损失限度。","ja":"エージェントが取引リスクを管理する機能を提供します。デフォルトおよび最大の取引ごとのリスク限度（それぞれ資本の0.5-2.0%および2.5%）を設定し、ポートフォリオの熱度を監視し、自動ポジションフラットニングなどのプロトコルを使用して毎日の損失限度を強制的に実施します。","ko":"에이전트가 거래 리スク를 관리할 수 있는 기능을 제공합니다. 기본 및 최대 거래별 리스크 제한（각각 자본의 0.5-2.0% 및 2.5%）을 설정하며, 포트폴리오의 열기를 모니터링하고 자동 포지션 평단화 등의 프로토콜을 사용하여 일일 손실 제한을 강제로実施합니다.","es":"Habilita a los agentes a gestionar los riesgos comerciales estableciendo límites de riesgo por defecto y máximo por operación del 0,5-2,0% y 2,5% del capital, respectivamente, mientras se monitorea la temperatura de la cartera y se aplican límites de pérdida diaria utilizando protocolos como la aplanación automática de posiciones.","fr":"Permet aux agents de gérer les risques commerciaux en définissant des limites de risque par défaut et maximales par transaction de 0,5-2,0% et 2,5% du capital, respectivement, tout en surveillant la chaleur du portefeuille et en appliquant des limites de perte journalière à l''aide de protocoles tels que l''aplanissement automatique des positions.","de":"Ermächtigt die Agenten, Handelsrisiken durch Festlegung von Standard- und Maximal-Risikolimits pro Trade von 0,5-2,0% und 2,5% des Kapitals zu managen, während sie die Portfoliohitze überwachen und tägliche Verlustlimits mit Protokollen wie automatischer Positionsglättung durchsetzen.","pt":"Habilita os agentes a gerenciar riscos de negociação definindo limites de risco padrão e máximo por negociação de 0,5-2,0% e 2,5% do capital, respectivamente, enquanto monitora o calor da carteira e impõe limites de perda diários usando protocolos como achatamento automático de posições.","ru":"Наделяет агентов возможностью управлять торговыми рисками, устанавливая стандартные и максимальные лимиты риска на сделку в размере 0,5-2,0% и 2,5% капитала соответственно, а также отслеживает портфельное тепло и обеспечивает соблюдение дневных лимитов убытков с помощью протоколов, таких как автоматическое выравнивание позиций.","ar":"يمنح الوكلاء إمكانية إدارة مخاطر التداول عن طريق تعيين حدود المخاطر الافتراضية والقصوى لكل сделة من 0.5-2.0٪ و 2.5٪ من رأس المال على التوالي، مع مراقبة حرارة المحفظة وفرض حدود الخسارة اليومية باستخدام بروتوكولات مثل تقليل الأوضاع التلقائي."},"useCases":{"en":["Automating daily loss limit enforcement with a hard stop at -2.5% of capital","Monitoring aggregate exposure across all positions to prevent excessive portfolio heat","Implementing time-based exits with EOD auto square-off to prevent overnight risk"],"zh":["使用硬性停止機制在-2.5%的资本损失时自动执行每日损失限度强制执行","监控所有头寸的聚合暴露以防止过度的投资组合热度","实施基于时间的退出策略，使用EOD自动平仓功能防止过夜风险"],"ja":["資本の-2.5%の損失時に自動ポジションフラットニングを使用して毎日の損失限度を強制的に実施する","全ポジションの集約暴露を監視して過度のポートフォリオの熱度を防ぐ","EOD自動スクエアオフ機能を使用して夜間リスクを防ぐタイムベースの退出戦略を実施する"],"ko":["자본의 -2.5% 손실 시 자동 포지션 평단화를 사용하여 일일 손실 제한을 강제로実施하는 것","모든 포지션의 집계暴露를 모니터링하여過度の 포트폴리오의 열기를防ぐ","EOD 자동 평단화 기능을 사용하여 밤새 리スク를防ぐ 시간 기반의退出 전략을 구현하는 것"],"es":["Automatizar la aplicación de límites de pérdida diaria con una parada dura en -2,5% del capital","Monitorear la exposición agregada en todas las posiciones para prevenir un exceso de calor de cartera","Implementar salidas basadas en el tiempo con EOD auto cuadrado para prevenir el riesgo nocturno"],"fr":["Automatiser l''application de la limite de perte journalière avec un arrêt dur à -2,5% du capital","Surveiller l''exposition agrégée sur toutes les positions pour prévenir un excès de chaleur du portefeuille","Mettre en œuvre des sorties basées sur le temps avec EOD auto carré pour prévenir le risque nocturne"],"de":["Automatisieren der Durchsetzung des täglichen Verlustlimits mit einem harten Stopp bei -2,5% des Kapitals","Überwachen der aggregierten Exposition über alle Positionen, um ein Übermaß an Portfoliohitze zu verhindern","Implementieren von zeitbasierten Ausstiegen mit EOD-Auto-Quadrieren, um das Übernachtrisiko zu verhindern"],"pt":["Automatizar a aplicação do limite de perda diário com uma parada rígida em -2,5% do capital","Monitorar a exposição agregada em todas as posições para prevenir o superaquecimento excessivo da carteira","Implementar saídas baseadas no tempo com EOD auto square-off para prevenir o risco noturno"],"ru":["Автоматизировать применение дневного лимита убытков с жесткой остановкой на уровне -2,5% капитала","Отслеживать совокупную экспозицию по всем позициям для предотвращения чрезмерного нагрева портфеля","Реализовать временные выходы с EOD авто-сквэр-офф для предотвращения ночного риска"],"ar":["تأتمتة تطبيق حد الخسارة اليومي مع остановة صلبة عند -2.5٪ من رأس المال","مراقبة التعرض الإجمالي لجميع المواقف لمنع حرارة المحفظة الزائدة","تنفيذ الخروج المستندة إلى الوقت مع EOD تقليل الأوضاع التلقائي لمنع المخاطر الليلية"]},"limitations":{"en":["Requires capital allocation for effective risk management","Maximum per-trade risk limit capped at 2.5% of capital","Daily loss limit triggers automatic position flattening"],"zh":["需要为有效的风险管理分配资本","每笔交易的最大风险限度被限制在资本的2.5%以内","每日损失限度触发自动平仓"],"ja":["有効なリスク管理のために資本を割り当てる必要がある","取引ごとの最大リスク限度は資本の2.5%以内に制限されている","毎日の損失限度が自動ポジションフラットニングをトリガーする"],"ko":["유효한 리스크 관리를 위해서 자본을 할당해야 한다","거래별 최대 리스크 제한은 자본의 2.5% 이내로 제한된다","일일 손실 제한이 자동 포지션 평단화를 트리거한다"],"es":["Requiere asignación de capital para una gestión de riesgos efectiva","Límite de riesgo máximo por operación limitado al 2,5% del capital","El límite de pérdida diaria activa la aplanación automática de posiciones"],"fr":["Nécessite une allocation de capital pour une gestion de risques efficace","Limite de risque maximal par transaction limitée à 2,5% du capital","La limite de perte journalière déclenche l''aplanissement automatique des positions"],"de":["Benötigt Kapitalzuweisung für eine effektive Risikomanagement","Maximales Risikolimit pro Trade auf 2,5% des Kapitals begrenzt","Das tägliche Verlustlimit löst die automatische Positionsglättung aus"],"pt":["Exige alocação de capital para gerenciamento de risco eficaz","Limite de risco por negociação máximo limitado a 2,5% do capital","Limite de perda diário dispara achatamento automático de posições"],"ru":["Требует распределения капитала для эффективного управления рисками","Максимальный лимит риска на сделку ограничен 2,5% капитала","Дневной лимит убытков запускает автоматическое выравнивание позиций"],"ar":["يتطلب تخصيص رأس المال لإدارة المخاطر الفعالة","الحد الأقصى للمخاطر لكل сделة مقيد ب 2.5٪ من رأس المال","حد الخسارة اليومي يطلق تقليل الأوضاع التلقائي"]},"version":4},"contentHash":"675d7c7b864fbfff73a923ced43dbc2bd40a7997bce5cf9fe66767469103334b","qualityScore":36}');
