INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StuartF303/vandaemon/kicad', 'kicad', 'StuartF303', 'vandaemon', 'community', 'kicad StuartF303 vandaemon community KiCad skill designs PCB schematics and layouts for VanDaemon hardware projects, primarily the ESP32-based 8-channel LED dimmer, following automotive-grade design practices. KiCad 是一个用于设计 PCB 架构和布局的工具，主要用于 ESP32 基础的 8 通道 LED 调光器项目 KiCad は、主に ESP32 ベースの 8 チャンネル LED ディマー プロジェクトで使用される、PCB スキーマとレイアウトを設計するツールです KiCad는 ESP32 기반의 8채널 LED 디머 프로젝트에서 주로 사용되는 PCB 스키마와 레이아웃을 설계하는 도구입니다 KiCad es una herramienta de diseño de PCB y esquemas para proyectos de hardware de VanDaemon, incluyendo el dimmer de LED de 8 canales basado en ESP32 KiCad est un outil de conception de PCB et de schémas pour les projets de matériel VanDaemon, y compris le gradateur de LED 8 canaux basé sur ESP32 KiCad ist ein Tool für die Entwicklung von PCB- und Schaltplänen für VanDaemon-Hardware-Projekte, einschließlich des 8-Kanal-LED-Dimmers auf Basis von ESP32 O KiCad é uma ferramenta de design de PCB e layout para projetos de VanDaemon, incluindo hardware de iluminação. Siga nosso guia para configurar o KiCad KiCad - это инструмент для разработки схем и макетов плат для проектов VanDaemon, включая оборудование освещения. Следуйте нашему руководству для настройки KiCad KiCad هو أداة لتصميم لوحات الدوائر المطبوعة وتخطيطها لمشاريع VanDaemon، بما في ذلك عتاد الإضاءة. اتبع دليلنا لإعداد KiCad how to use kicad kicad setup guide kicad vs eagle kicad install what is kicad kicad alternative kicad modbus integration kicad pcb design kicad s-expression format kicad automotive grade design KiCad 设计 ModBus 中央露营车控制系统 ESP32 基础的 8 通道 LED 调光器 S 表达式格式 汽车级设计实践 电子电路设计工具 Designs PCB schematics and layouts using S-expression format Supports ESP32-based 8-channel LED dimmer hardware projects Follows automotive-grade design practices for reliability Utilizes ModBus protocol for communication Generates files in KiCad 7+ compatible format Locates project files using bash commands like find hw/LEDDimmer -name "*.kicad_*" -type f KiCad is a central camper van control system for ModBus in C#, used for designing and developing reliable vehicle environments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jeronartest/wcibasketball/devvit-skill-setup', 'community', 'jeronartest', 'wcibasketball', 'jeronartest/wcibasketball', 'devvit-skill-setup', 0, 0, 36, '2026-03-08T01:57:15.502Z', '2026-03-08T02:10:19.047Z', 'c6799b06748521e644b1cdf9ba2e6d056f93c3ac7bf4a4918f9b02fd1bc7f49d', '{"id":"jeronartest/wcibasketball/devvit-skill-setup","name":"devvit-skill-setup","description":{"en":"devvit-skill-setup prepares a code repository for devvit skills by ensuring devvit-docs skill is added and configuring rules for working with Devvit. It benefits developers by streamlining the setup process.","zh":"Devvit Skill Setup 是一个基本的设置，用于使代码仓库准备好使用 Devvit 技能。它包括添加 devvit-docs Skill 和配置规则文件","ja":"Devvit Skill Setup は、コードリポジトリを Devvit スキルの使用に準備するための基本的な設定です","ko":"Devvit Skill Setup은 코드 저장소를 Devvit 기능을 사용할 수 있도록 준비하는 기본 설정입니다","es":"devvit-skill-setup configura tu repositorio de código para usar habilidades de Devvit. Asegúrate de que esté listo para su uso.","fr":"devvit-skill-setup configure votre référentiel de code pour utiliser les compétences de Devvit. Assurez-vous qu''il est prêt à l''emploi.","de":"devvit-skill-setup konfiguriert Ihr Code-Repository für die Verwendung von Devvit-Fähigkeiten. Stellen Sie sicher, dass es für die Verwendung bereit ist.","pt":"O Devvit Skill Setup é uma habilidade que configura um repositório de código para usar habilidades Devvit, garantindo a configuração correta do Redis.","ru":"Devvit Skill Setup — это навык, который настраивает кодовый репозиторий для использования навыков Devvit, обеспечивая правильную настройку Redis.","ar":"مهارة Devvit Skill Setup هي مهارة تكوين مستودع الشفرة لاستخدام مهارات Devvit، وتضمن الإعداد الصحيح للريديس."},"seo":{"title":{"en":"devvit-skill-setup: Setup Guide for AI Agents","zh":"Devvit Skill Setup 指南：代码仓库准备","ja":"Devvit Skill Setup ガイド：コードリポジトリの準備","ko":"Devvit Skill Setup 가이드: 코드 저장소 준비","es":"Configuración de devvit-skill-setup: Guía de configuració...","fr":"Configuration de devvit-skill-setup : Guide de mise en ro...","de":"Einrichtung von devvit-skill-setup: Setup-Anleitung für E...","pt":"Configuração do Devvit Skill Setup: Guia de Instalação","ru":"Настройка Devvit Skill Setup: Руководство по установке","ar":"إعداد مهارة Devvit Skill Setup: دليل الإعداد"},"description":{"en":"Get started with devvit-skill-setup and configure your code repository for seamless devvit skills integration - learn how to set up and troubleshoot","zh":"Devvit Skill Setup 是一个基本的设置，用于使代码仓库准备好使用 Devvit 技能，包括添加 devvit-docs Skill 和配置规则文件","ja":"Devvit Skill Setup は、コードリポジトリを Devvit スキルの使用に準備するための基本的な設定です。devvit-docs スキルの追加や規則ファイルの設定が含まれます","ko":"Devvit Skill Setup은 코드 저장소를 Devvit 기능을 사용할 수 있도록 준비하는 기본 설정입니다. devvit-docs 기능 추가 및 규칙 파일 설정이 포함됩니다","es":"Aprende a configurar devvit-skill-setup para tu repositorio de código. Descubre cómo preparar tu proyecto para usar habilidades de Devvit con nuestra guía pa...","fr":"Découvrez comment configurer devvit-skill-setup pour votre référentiel de code. Apprenez à préparer votre projet pour utiliser les compétences de Devvit avec...","de":"Erfahren Sie, wie Sie devvit-skill-setup für Ihr Code-Repository einrichten. Entdecken Sie, wie Sie Ihr Projekt für die Verwendung von Devvit-Fähigkeiten mit...","pt":"Aprenda a configurar o Devvit Skill Setup para preparar um repositório de código para usar habilidades Devvit. Veja como garantir a configuração correta do R...","ru":"Узнайте, как настроить Devvit Skill Setup, чтобы подготовить кодовый репозиторий для использования навыков Devvit. Проверьте правильность настройки Redis.","ar":"تعلم كيفية إعداد مهارة Devvit Skill Setup لتحضير مستودع الشفرة لاستخدام مهارات Devvit. انظر كيفية ضمان الإعداد الصحيح للريديس."},"definition":{"en":"devvit-skill-setup is a skill that performs basic setup tasks to make a code repository ready for devvit skills, including adding devvit-docs and configuring rules","zh":"Devvit Skill Setup 是一个用于设置代码仓库以使用 Devvit 技能的过程","ja":"Devvit Skill Setup は、コードリポジトリを Devvit スキルの使用に準備するためのプロセスです","ko":"Devvit Skill Setup은 코드 저장소를 Devvit 기능을 사용할 수 있도록 설정하는 프로세스입니다","es":"devvit-skill-setup es una habilidad que configura un repositorio de código para su uso con Devvit, incluyendo la configuración de archivos de instrucciones y comprobación de la documentación.","fr":"devvit-skill-setup est une compétence qui configure un référentiel de code pour son utilisation avec Devvit, y compris la configuration des fichiers d''instructions et la vérification de la documentation.","de":"devvit-skill-setup ist eine Fähigkeit, die ein Code-Repository für die Verwendung mit Devvit konfiguriert, einschließlich der Konfiguration von Anweisungsdateien und der Überprüfung der Dokumentation.","pt":"O que é Devvit Skill Setup? É uma habilidade que prepara um repositório de código para usar habilidades Devvit.","ru":"Что такое Devvit Skill Setup? Это навык, который готовит кодовый репозиторий для использования навыков Devvit.","ar":"ما هي مهارة Devvit Skill Setup؟ هي مهارة تحضير مستودع الشفرة لاستخدام مهارات Devvit."},"features":{"en":["Ensures devvit-docs skill is added to the repository","Calls devvit-docs with ''how does redis work'' to verify configuration","Checks for common instruction files like AGENTS.md and CLAUDE.md","Inserts rules for working with Devvit into the repository","Presents errors to the user if configuration fails"],"zh":["添加 devvit-docs Skill","配置规则文件","检查代码仓库根目录中的常见指令文件","确保 Devvit Skill 正确配置"],"ja":["devvit-docs スキルの追加","規則ファイルの設定","コードリポジトリのルートディレクトリにある共通の指示ファイルの確認","Devvit スキルの正しい設定の確認"],"ko":["devvit-docs 기능 추가","규칙 파일 설정","코드 저장소 루트 디렉토리에서 일반적인 지침 파일 확인","Devvit 기능의 올바른 설정 확인"],"es":["Configuración de archivos de instrucciones como AGENTS.md y CLAUDE.md","Comprobación de la configuración de la documentación con devvit-docs","Inserción de bloques de configuración para trabajar con Devvit","Verificación de errores y presentación al usuario","Preparación del repositorio para el uso de habilidades de Devvit"],"fr":["Configuration des fichiers d''instructions tels que AGENTS.md et CLAUDE.md","Vérification de la configuration de la documentation avec devvit-docs","Insertion de blocs de configuration pour travailler avec Devvit","Vérification des erreurs et présentation à l''utilisateur","Préparation du référentiel pour l''utilisation des compétences de Devvit"],"de":["Konfiguration von Anweisungsdateien wie AGENTS.md und CLAUDE.md","Überprüfung der Dokumentationskonfiguration mit devvit-docs","Einfügung von Konfigurationsblöcken zur Arbeit mit Devvit","Überprüfung von Fehlern und Darstellung für den Benutzer","Vorbereitung des Repositories für die Verwendung von Devvit-Fähigkeiten"],"pt":["Verifica se o arquivo de regras adiciona um bloco sobre trabalhar com Devvit","Chama o `devvit-docs` com \"como funciona o Redis\" para garantir a configuração correta","Verifica a presença de arquivos de instruções comuns no repositório raiz","Insere um bloco de configuração para trabalhar com Devvit","Trabalha com a habilidade `devvit-docs` para garantir a configuração correta","Suporta a configuração do Redis para uso com habilidades Devvit"],"ru":["Проверяет, добавляет ли файл правил блок о работе с Devvit","Вызывает `devvit-docs` с \"как работает Redis\", чтобы обеспечить правильную настройку","Проверяет наличие общих файлов инструкций в корне репозитория","Вставляет блок настройки для работы с Devvit","Работает с навыком `devvit-docs`, чтобы обеспечить правильную настройку","Поддерживает настройку Redis для использования с навыками Devvit"],"ar":["يتحقق من وجود ملف القواعد لإضافة كتلة حول العمل مع Devvit","يستدعي `devvit-docs` مع \"كيف يعمل Redis\" لضمان الإعداد الصحيح","يتحقق من وجود ملفات الإرشادات الشائعة في الجذر المستودع","يضيف كتلة إعداد للعمل مع Devvit","يعمل مع مهارة `devvit-docs` لضمان الإعداد الصحيح","يدعم إعداد Redis لاستخدامه مع مهارات Devvit"]},"keywords":{"en":["how to use devvit-skill-setup","devvit-skill-setup setup guide","devvit-skill-setup alternative","devvit-skill-setup vs devvit-docs","devvit-skill-setup install","what is devvit-skill-setup","devvit-skill-setup configuration","devvit-skill-setup troubleshooting"],"zh":["Devvit Skill Setup","代码仓库设置","devvit-docs Skill","规则文件配置","AI工具","代码仓库管理"],"ja":["Devvit Skill Setup","コードリポジトリ設定","devvit-docs スキル","規則ファイル設定","AIエージェント","コードリポジトリ管理"],"ko":["Devvit Skill Setup","코드 저장소 설정","devvit-docs 기능","규칙 파일 설정","AI 도구","코드 저장소 관리"],"es":["devvit-skill-setup","configuración de Devvit","habilidades de Devvit","referencia de código","AGENTS.md","CLAUDE.md","devvit-docs","errores de configuración","preparación del repositorio"],"fr":["devvit-skill-setup","configuration de Devvit","compétences de Devvit","référentiel de code","AGENTS.md","CLAUDE.md","devvit-docs","erreurs de configuration","préparation du référentiel"],"de":["devvit-skill-setup","Konfiguration von Devvit","Fähigkeiten von Devvit","Code-Repository","AGENTS.md","CLAUDE.md","devvit-docs","Konfigurationsfehler","Vorbereitung des Repositories"],"pt":["devvit skill setup","configuração de repositório de código","habilidades Devvit","Redis","devvit-docs","configuração de habilidades","repositório de código","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["devvit skill setup","настройка кодового репозитория","навыки Devvit","Redis","devvit-docs","настройка навыков","кодовый репозиторий","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["إعداد مهارة Devvit Skill Setup","إعداد مستودع الشفرة","مهارات Devvit","Redis","devvit-docs","إعداد مهارات","مستودع الشفرة","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"jeronartest","repo":"wcibasketball","repoPath":"jeronartest/wcibasketball","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.502Z","topics":[],"category":"community","skillMd":{"name":"devvit-skill-setup","description":"Configure a repos agent instruction files (AGENTS.md, CLAUDE.md, etc.) to auto-apply Devvit skill guidance. Trigger phrases: \\configure skills\\, \\setup skills\\, \\add devvit docs rule\\.","bodyPreview":"# Devvit Skill Setup\n\nDoes basic setup to make a code repository ready to use devvit skills.\n\n1. Ensure the devvit-docs skill is added. If not, skip. If it is, call `devvit-docs` with \"how does redis work\" to make sure things are configured correctly. If there is an error, present it to the user.\n\n2. Ensure the rules file adds a block about working with Devvit\n\nPlease do the following:\n\n- Check the repo root for common instruction files (`AGENTS.md`, `CLAUDE.md`, etc.).\n- Insert the following sk","body":"# Devvit Skill Setup\n\nDoes basic setup to make a code repository ready to use devvit skills.\n\n1. Ensure the devvit-docs skill is added. If not, skip. If it is, call `devvit-docs` with \"how does redis work\" to make sure things are configured correctly. If there is an error, present it to the user.\n\n2. Ensure the rules file adds a block about working with Devvit\n\nPlease do the following:\n\n- Check the repo root for common instruction files (`AGENTS.md`, `CLAUDE.md`, etc.).\n- Insert the following skill a close to the top of the rules file\n\n```md\nAlways use the devvit-docs skill when I need library/API documentation about anything related to devvit including: documentation, code generation, setup or configuration steps without me having to explicitly ask. This includes capabilities that devvit offers like Redis, Reddit API, Media, and more as Devvit has special rules and documentation.\n```\n\n- If no instruction file exists, create `AGENTS.md` with the block above.\n- Add success or failure to summary of skill call result\n\n3. Present Results to User\n\nTell the user the changes you made.\n\n## Troubleshooting\n\n- **Permission errors**: Verify the repo is writable.\n- **Wrong location**: Ensure the repo root is being edited.\n- **No changes**: The rule block already exists; no update needed.\n- **Missing skill**:  Ask the user to run `npx add-skill reddit/devvit-skills` to add the missing skill if they want to utilize that feature.\n"},"lastSynced":"2026-03-08T02:10:19.047Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents requiring streamlined Devvit skill integration and configuration.","zh":"非常适合需要简化Devvit技能集成和配置的开发代理。","ja":"Devvitスキルの統合と設定を簡素化する必要がある開発エージェントに最適です。","ko":"Devvit 스킬 통합 및 구성이 간소화된 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que requieren una integración y configuración de habilidades de Devvit optimizadas.","fr":"Parfait pour les agents de développement nécessitant une intégration et une configuration de compétences Devvit rationalisées.","de":"Perfekt für Entwicklungsmittel, die eine optimierte Devvit-Fähigkeitsintegration und -konfiguration erfordern.","pt":"Perfeito para Agentes de Desenvolvimento que exigem integração e configuração de habilidades Devvit otimizadas.","ru":"Идеально подходит для агентов разработки, требующих оптимизированной интеграции и конфигурации навыков Devvit.","ar":"مثالي لعمليات تطوير الوكلاء التي تتطلب دمجًا ومواصفات مهارات Devvit مبسطة."},"recommendation":{"en":"Empowers agents to automate Devvit skill setup by ensuring devvit-docs skill integration and configuring rules for working with Devvit, utilizing files like AGENTS.md and protocols for Redis.","zh":"使代理能够自动设置Devvit技能，通过确保devvit-docs技能集成并为使用Devvit配置规则，使用诸如AGENTS.md和Redis协议的文件。","ja":"エージェントがDevvitスキルの設定を自動化できるようにし、devvit-docsスキルの統合を保証し、Devvitの使用を規定するルールを設定します。AGENTS.mdやRedisプロトコルなどのファイルが使用されます。","ko":"에이전트가 Devvit 스킬 설정을 자동화할 수 있도록 하며, devvit-docs 스킬 통합을 보장하고 Devvit를 사용하기 위한 규칙을 구성합니다. AGENTS.md 및 Redis 프로토콜과 같은 파일을 사용합니다.","es":"Permite a los agentes automatizar la configuración de habilidades de Devvit asegurando la integración de la habilidad devvit-docs y configurando reglas para trabajar con Devvit, utilizando archivos como AGENTS.md y protocolos para Redis.","fr":"Permet aux agents d''automatiser la configuration des compétences Devvit en assurant l''intégration de la compétence devvit-docs et en configurant des règles pour travailler avec Devvit, en utilisant des fichiers comme AGENTS.md et des protocoles pour Redis.","de":"Ermöglicht es Agenten, die Devvit-Fähigkeitskonfiguration zu automatisieren, indem sie die devvit-docs-Fähigkeitsintegration sicherstellen und Regeln für die Arbeit mit Devvit konfigurieren, unter Verwendung von Dateien wie AGENTS.md und Protokollen für Redis.","pt":"Habilita os agentes a automatizar a configuração da habilidade Devvit garantindo a integração da habilidade devvit-docs e configurando regras para trabalhar com Devvit, utilizando arquivos como AGENTS.md e protocolos para Redis.","ru":"Наделяет агентов возможностью автоматизировать настройку навыка Devvit, обеспечивая интеграцию навыка devvit-docs и настройку правил для работы с Devvit, используя файлы, такие как AGENTS.md, и протоколы для Redis.","ar":"يتمكّن الوكلاء من توفير автоматиّة لإعداد مهارة Devvit من خلال ضمان دمج مهارة devvit-docs وتفصيل القواعد للعمل مع Devvit، باستخدام ملفات مثل AGENTS.md وبروتوكولات للوصول إلى Redis."},"useCases":{"en":["Configuring Devvit skills for seamless integration","Debugging Devvit setup issues with Redis","Streamlining repository setup for Devvit compatibility"],"zh":["为无缝集成配置Devvit技能","使用Redis调试Devvit设置问题","简化存储库设置以实现Devvit兼容性"],"ja":["シームレスな統合のためのDevvitスキルの設定","Redisを使用したDevvit設定の問題のデバッグ","Devvitの互換性のためのリポジトリ設定の簡素化"],"ko":["무결점 통합을 위한 Devvit 스킬 구성","Redis를 사용한 Devvit 설정 문제 디버깅","Devvit 호환성을 위한 저장소 설정 간소화"],"es":["Configuración de habilidades de Devvit para una integración sin problemas","Depuración de problemas de configuración de Devvit con Redis","Optimización de la configuración del repositorio para la compatibilidad con Devvit"],"fr":["Configuration des compétences Devvit pour une intégration transparente","Débogage des problèmes de configuration Devvit avec Redis","Optimisation de la configuration 