INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('twentyhq/twenty/syncable-entity-testing', 'syncable-entity-testing', 'twentyhq', 'twenty', 'community', 'syncable-entity-testing twentyhq twenty community The syncable-entity-testing skill enables developers to build a modern alternative to Salesforce, powered by the community, by creating comprehensive test suites for syncable entities. This skill benefits developers working on integration testing for community-driven projects. Syncable Entity 测试是一个用于构建现代替代Salesforce的社区驱动项目，需要创建全面测试套件 Syncable Entityテストは、Salesforceの代替としてのモダンなコミュニティ駆動プロジェクトを構築するために必要な、包括的なテストスイートを作成することを目的としています Syncable Entity 테스트는 Salesforce의 현대적인 대체로서의 커뮤니티 주도 프로젝트를 구축하기 위해 필요한 포괄적인 테스트 스위트를 생성하는 것을 목표로 합니다 El testing de entidades sincronizables es crucial para asegurar la integridad de los datos. Nuestro enfoque cubre escenarios de falla y éxito. Le testing d''entités synchronisables est essentiel pour assurer l''intégrité des données. Notre approche couvre les scénarios d''échec et de succès. Das Testing von synchronisierbaren Entitäten ist entscheidend, um die Datenintegrität zu gewährleisten. Unser Ansatz behandelt Fehler- und Erfolgsszenarien. O teste de entidades sincronizáveis é uma etapa crucial para garantir a integração perfeita de uma alternativa moderna ao Salesforce. Тестирование синхронизируемых сущностей является важным шагом для обеспечения идеальной интеграции современной альтернативы Salesforce. اختبار الكيانات المتزامنة هو خطوة حاسمة لضمان التكامل المثالي للبديل الحديث لمنصة Salesforce. how to use syncable-entity-testing syncable-entity-testing setup guide what is syncable-entity-testing syncable-entity-testing alternative to Salesforce syncable-entity-testing vs traditional testing methods syncable-entity-testing install and configuration integration testing for syncable entities comprehensive test suite development input transpilation exception handling Syncable Entity 测试 AIエージェント测试 Salesforce 替代 社区驱动项目 集成测试 验证场景 输入转换异常 Creates comprehensive test suites covering all validation scenarios Covers input transpilation exceptions for robust error handling Supports testing of successful use cases, including CRUD operations Enforces mandatory integration testing for all syncable entities Includes quick start guide for rapid test suite development Covers edge cases for thorough testing of syncable entities syncable-entity-testing is a skill that facilitates the creation of comprehensive test suites for syncable entities, covering validation scenarios, input transpilation exceptions, and successful use cases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('judacas/LLM-Automated-Inventory-Management/run-linting', 'community', 'judacas', 'LLM-Automated-Inventory-Management', 'judacas/LLM-Automated-Inventory-Management', 'run-linting', 0, 0, 36, '2026-03-08T01:57:15.507Z', '2026-03-08T02:10:22.900Z', '5fa8ffd7fc4bc6c5550ea4e12ecc5ffa0b747066123992e711897ccdf096605a', '{"id":"judacas/LLM-Automated-Inventory-Management/run-linting","name":"run-linting","description":{"en":"The run-linting skill provides a workflow for computer engineers to identify and fix errors using ReadLints and Ruff CLI. It benefits developers working with Microsoft and USF.","zh":"Run Linting工具使用ReadLints和Ruff CLI进行代码检查和错误诊断","ja":"Run Lintingは、ReadLintsとRuff CLIを使用してコードをチェックし、エラーを診断します","ko":"런트링 코드 검사 도구는 ReadLints와 Ruff CLI를 사용하여 코드를 검사하고 오류를 진단합니다","es":"Run-linting es una herramienta que utiliza ReadLints para identificar errores en el código y proporciona una lista completa de diagnósticos de linter y LSP","fr":"Run-linting est un outil qui utilise ReadLints pour identifier les erreurs dans le code et fournit une liste complète de diagnostics de linter et LSP","de":"Run-linting ist ein Tool, das ReadLints verwendet, um Fehler im Code zu identifizieren und eine vollständige Liste von Linter- und LSP-Diagnosen bereitstellt","pt":"O Run-Linting é uma ferramenta que ajuda a identificar erros de linting e LSP diagnostics em projetos de desenvolvimento. Use-o para obter uma lista completa de erros antes de corrigi-los","ru":"Run-Linting - это инструмент, который помогает выявить ошибки linting и LSP diagnostics в проектах разработки. Используйте его, чтобы получить полный список ошибок перед их исправлением","ar":"Run-Linting هو أداة تساعد في تحديد أخطاء Linting و LSP diagnostics في مشاريع التطوير. استخدمه للحصول على قائمة كاملة بالأخطاء قبل تصحيحها"},"seo":{"title":{"en":"run-linting: Linting and Diagnostics Setup Guide | AI Age...","zh":"运行linting代码检查工具Setup Guide","ja":"AIエージェントのRun Lintingベストプラクティス","ko":"런트링 코드 검사 도구 설정 가이드","es":"Guía de configuración de run-linting para herramientas de AI","fr":"Configurer run-linting pour les outils d''IA","de":"Einrichtungsleitfaden für run-linting in AI-Tools","pt":"Guia de Configuração do Run-Linting: Melhores Práticas pa...","ru":"Настройка Run-Linting: Руководство по использованию ИИ Аг...","ar":"دليل تشغيل Run-Linting: إرشادات أفضل للمطورين باستخدام أد..."},"description":{"en":"Discover how to use run-linting for comprehensive linting and diagnostics. Get a complete list of errors with ReadLints and Ruff CLI. Learn more and set up now!","zh":"了解如何使用Run Linting工具进行代码检查和错误诊断，提高代码质量","ja":"AIエージェントのRun Linting機能を使用してコードをチェックし、エラーを診断します","ko":"런트링 코드 검사 도구를 사용하여 코드를 검사하고 오류를 진단하는 방법을 알아보세요","es":"Aprende a utilizar run-linting para identificar y corregir errores en tu proyecto con herramientas de AI como Ruff y Pyright","fr":"Découvrez comment utiliser run-linting pour identifier et corriger les erreurs dans votre projet avec des outils d''IA tels que Ruff et Pyright","de":"Erfahren Sie, wie Sie run-linting verwenden, um Fehler in Ihrem Projekt mit AI-Tools wie Ruff und Pyright zu identifizieren und zu beheben","pt":"Aprenda a configurar o Run-Linting para obter uma lista completa de erros de linting e LSP diagnostics antes de corrigi-los","ru":"Узнайте, как настроить Run-Linting, чтобы получить полный список ошибок linting и LSP diagnostics перед их исправлением с помощью ИИ Агентов","ar":"تعرف على كيفية تشغيل Run-Linting للحصول على قائمة كاملة بالأخطاءLinting و LSP diagnostics قبل تصحيحها باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"run-linting is a skill that utilizes ReadLints and Ruff CLI to return LSP/linter diagnostics and report errors for comprehensive code review.","zh":"Run Linting是一种代码检查工具，使用ReadLints和Ruff CLI进行错误诊断","ja":"Run Lintingは、コードをチェックし、エラーを診断するAIエージェントの機能です","ko":"런트링 코드 검사 도구는 코드를 검사하고 오류를 진단하는 도구입니다","es":"Run-linting es una función que ejecuta herramientas de linter y LSP para identificar errores en el código","fr":"Run-linting est une fonction qui exécute des outils de linter et LSP pour identifier les erreurs dans le code","de":"Run-linting ist eine Funktion, die Linter- und LSP-Tools ausführt, um Fehler im Code zu identifizieren","pt":"Run-Linting é uma ferramenta que executa linting e LSP diagnostics em projetos de desenvolvimento","ru":"Run-Linting - это инструмент, который выполняет linting и LSP diagnostics в проектах разработки","ar":"Run-Linting هو أداة تنفذ Linting و LSP diagnostics في مشاريع التطوير"},"features":{"en":["Returns current workspace’s LSP/linter diagnostics using ReadLints","Utilizes Ruff CLI for separate project-wide linting checks","Supports uv run ruff check --fix command for automated fixes","Provides a complete list of linter and LSP diagnostics for error identification","Works with Ruff as the main linter for consistent error reporting","Integrates with IDE for real-time diagnostics and error reporting"],"zh":["使用ReadLints工具进行代码检查","支持Ruff CLI进行代码错误诊断","提供代码错误列表","支持IDE和CLI两种模式","提高代码质量和可维护性"],"ja":["ReadLintsを使用したコードチェック","Ruff CLIを使用したコードエラー診断","コードエラーリストの提供","IDEとCLIの両方をサポート","コード品質とメンテナンス性の向上"],"ko":["ReadLints를 사용한 코드 검사","Ruff CLI를 사용한 코드 오류 진단","코드 오류 목록 제공","IDE와 CLI 두 가지 모드를 지원","코드 품질과 유지 보수성 향상"],"es":["Utiliza ReadLints para identificar errores en el código","Proporciona una lista completa de diagnósticos de linter y LSP","Integra con Ruff y Pyright para una verificación exhaustiva","Permite la ejecución de comandos CLI como ''uv run ruff check --fix''","Identifica errores en el código antes de su implementación"],"fr":["Utilise ReadLints pour identifier les erreurs dans le code","Fournit une liste complète de diagnostics de linter et LSP","Intègre avec Ruff et Pyright pour une vérification exhaustive","Permet l''exécution de commandes CLI comme ''uv run ruff check --fix''","Identifie les erreurs dans le code avant leur mise en œuvre"],"de":["Verwendet ReadLints, um Fehler im Code zu identifizieren","Bietet eine vollständige Liste von Linter- und LSP-Diagnosen","Integriert mit Ruff und Pyright für eine umfassende Überprüfung","Ermöglicht die Ausführung von CLI-Befehlen wie ''uv run ruff check --fix''","Identifiziert Fehler im Code vor ihrer Implementierung"],"pt":["Executa linting e LSP diagnostics em projetos de desenvolvimento","Retorna uma lista completa de erros de linting e LSP diagnostics","Utiliza o Ruff CLI para verificar erros em todo o projeto","Integra-se com editores de código para mostrar erros em tempo real","Suporta a utilização de ferramentas de linting como Ruff e Pyright"],"ru":["Выполняет linting и LSP diagnostics в проектах разработки","Возвращает полный список ошибок linting и LSP diagnostics","Использует Ruff CLI для проверки ошибок во всем проекте","Интегрируется с редакторами кода для показа ошибок в режиме реального времени","Поддерживает использование инструментов linting, таких как Ruff и Pyright"],"ar":["تنفذ Linting و LSP diagnostics في مشاريع التطوير","ترجع قائمة كاملة بالأخطاء Linting و LSP diagnostics","تستخدم Ruff CLI للتحقق من الأخطاء في المشروع كله","تتكامل مع محررات الكود لإظهار الأخطاء في الوقت الفعلي","تدعم استخدام أدوات Linting مثل Ruff و Pyright"]},"keywords":{"en":["how to use run-linting","run-linting setup guide","what is run-linting","run-linting vs Ruff","run-linting alternative to Pyright","run-linting install for Microsoft","run-linting for USF developers","run-linting and LSP diagnostics","run-linting with ReadLints and Ruff CLI"],"zh":["代码检查工具","Run Linting","ReadLints","Ruff CLI","代码错误诊断","代码质量","AI代码检查","代码检查最佳实践"],"ja":["AIエージェント","Run Linting","ReadLints","Ruff CLI","コードチェック","コードエラー診断","コード品質","AIコードチェック"],"ko":["코드 검사 도구","런트링","ReadLints","Ruff CLI","코드 오류 진단","코드 품질","AI 코드 검사","코드 검사 설정 가이드"],"es":["run-linting","herramientas de AI","Ruff","Pyright","ReadLints","LSP","linter","CLI","identificación de errores","corrección de código"],"fr":["run-linting","outils d''IA","Ruff","Pyright","ReadLints","LSP","linter","CLI","identification d''erreurs","correction de code"],"de":["run-linting","AI-Tools","Ruff","Pyright","ReadLints","LSP","Linter","CLI","Fehleridentifizierung","Codekorrektur"],"pt":["run-linting","linting","LSP diagnostics","Ruff CLI","Pyright","desenvolvimento de software","ferramentas de desenvolvimento","erros de linting","correção de erros"],"ru":["run-linting","linting","LSP diagnostics","Ruff CLI","Pyright","разработка программного обеспечения","инструменты разработки","ошибки linting","исправление ошибок","ИИ Агенты"],"ar":["run-linting","Linting","LSP diagnostics","Ruff CLI","Pyright","تطوير البرمجيات","أدوات التطوير","أخطاء Linting","تصحيح الأخطاء","أدوات الذكاء الاصطناعي"]}},"owner":"judacas","repo":"LLM-Automated-Inventory-Management","repoPath":"judacas/LLM-Automated-Inventory-Management","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.507Z","topics":[],"category":"community","skillMd":{"name":"run-linting","description":"Runs linting and LSP diagnostics to list all errors and warnings in the workspace. Use when fixing linter errors, checking code quality, or when the linter-fixer subagent or user asks to see all lint/LSP issues.","bodyPreview":"# Run Linting and See All Errors\r\n\r\nUse this workflow to get a complete list of linter and LSP diagnostics before fixing them.\r\n\r\n**ReadLints** is a tool the agent has: it returns the current workspace’s LSP/linter diagnostics (what the editor shows — e.g. Ruff, Pyright). **Ruff CLI** (`uv run ruff check --fix`) is a separate run over the whole project. They often report the same issues when Ruff is the main linter, but aren’t identical: the IDE may be stale or include other sources; Ruff CLI is","body":"# Run Linting and See All Errors\r\n\r\nUse this workflow to get a complete list of linter and LSP diagnostics before fixing them.\r\n\r\n**ReadLints** is a tool the agent has: it returns the current workspace’s LSP/linter diagnostics (what the editor shows — e.g. Ruff, Pyright). **Ruff CLI** (`uv run ruff check --fix`) is a separate run over the whole project. They often report the same issues when Ruff is the main linter, but aren’t identical: the IDE may be stale or include other sources; Ruff CLI is the canonical full-project pass. Use both for full coverage.\r\n\r\n## 1. Run Ruff on the entire project (required)\r\n\r\nAlways run:\r\n\r\n```bash\r\nuv run ruff check --fix\r\n```\r\n\r\nThis runs Ruff over the whole project. Capture the output and treat it as the authoritative list of Ruff issues.\r\n\r\n## 2. Read LSP/linter diagnostics (optional extra)\r\n\r\nUse the **ReadLints** tool to get IDE diagnostics — same or overlapping with Ruff in many setups, but can include other LSP sources (e.g. Pyright) or reflect unsaved state.\r\n\r\n- **Paths**: Pass the path(s) you care about, or omit for the whole workspace.\r\n- Interpret each diagnostic: file, line, severity, message, and optional source.\r\n\r\nCombine with the Ruff output: merge by file/line, dedupe when they refer to the same issue.\r\n\r\n## 3. Consolidate and prioritize\r\n\r\n- Treat **errors** as must-fix; **warnings** as should-fix when feasible.\r\n- Group by file so fixes can be applied in one pass per file.\r\n- Note any diagnostics that need broader context so they can be delegated instead of auto-fixed.\r\n\r\n## Summary\r\n\r\n1. **Always** run `uv run ruff check --fix` on the entire project.\r\n2. Optionally call **ReadLints** for IDE diagnostics and merge with Ruff output.\r\n3. List all issues by file and severity; flag any that need human or main-agent context.\r\n"},"lastSynced":"2026-03-08T02:10:22.900Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced linting and error detection capabilities using ReadLints and Ruff CLI.","zh":"适用于需要高级linting和错误检测功能的代码审查代理，使用ReadLints和Ruff CLI。","ja":"ReadLintsとRuff CLIを使用する高度なlintingおよびエラーディテクション機能を必要とするコードレビュー代理に最適です。","ko":"ReadLints와 Ruff CLI를 사용하는 고급 linting 및 오류 감지 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan capacidades avanzadas de linting y detección de errores utilizando ReadLints y Ruff CLI.","fr":"Parfait pour les agents de révision de code nécessitant des capacités de linting et de détection d''erreurs avancées utilisant ReadLints et Ruff CLI.","de":"Perfekt für Code-Review-Agents, die erweiterte Linting- und Fehlernachweismöglichkeiten mit ReadLints und Ruff CLI benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de capacidades avançadas de linting e detecção de erros usando ReadLints e Ruff CLI.","ru":"Идеально подходит для агентов кодового обзора, которым необходимы расширенные возможности проверки кода и обнаружения ошибок с помощью ReadLints и Ruff CLI.","ar":"مثالي لعمليات المراجعة البرمجية التي تحتاج إلى إمكانيات متقدمة لتحليل الشفرة واكتشاف الأخطاء باستخدام ReadLints و Ruff CLI."},"recommendation":{"en":"Empowers agents to identify and fix errors in codebases using LSP diagnostics and Ruff CLI checks, providing a comprehensive list of linting and diagnostics issues to improve code quality and reliability.","zh":"赋予代理识别和修复代码库中的错误的能力，使用LSP诊断和Ruff CLI检查，提供一个全面性的linting和诊断问题列表，以提高代码质量和可靠性。","ja":"LSPの診断とRuff CLIのチェックを使用して、コードベース内のエラーを特定して修正するエージェントを可能にし、コードの品質と信頼性を向上させるための包括的なlintingと診断の問題の一覧を提供します。","ko":"LSP 진단 및 Ruff CLI 검사를 사용하여 코드베이스 내의 오류를 식별하고 수정하는 에이전트를 가능하게 하며, 코드 품질 및 신뢰성을 향상시키기 위한 포괄적인 linting 및 진단 문제 목록을 제공합니다.","es":"Habilita a los agentes a identificar y corregir errores en bases de código utilizando diagnósticos LSP y comprobaciones de Ruff CLI, proporcionando una lista completa de problemas de linting y diagnósticos para mejorar la calidad y confiabilidad del código.","fr":"Permet aux agents d''identifier et de corriger les erreurs dans les bases de code en utilisant les diagnostics LSP et les vérifications Ruff CLI, fournissant une liste complète des problèmes de linting et de diagnostics pour améliorer la qualité et la fiabilité du code.","de":"Ermächtigt Agenten, Fehler in Codebasen zu identifizieren und zu beheben, indem sie LSP-Diagnose und Ruff-CLI-Prüfungen verwenden, und bietet eine umfassende Liste von Linting- und Diagnoseproblemen, um die Codequalität und -zuverlässigkeit zu verbessern.","pt":"Habilita os agentes a identificar e corrigir erros em codebases usando diagnósticos LSP e verificações Ruff CLI, fornecendo uma lista abrangente de problemas de linting e diagnósticos para melhorar a qualidade e confiabilidade do código.","ru":"Наделяет агентов возможностью выявлять и исправлять ошибки в кодовых базах с помощью диагностических средств LSP и проверок Ruff CLI, обеспечивая всесторонний список проблем, связанных с проверкой кода и диагностикой, для улучшения качества и надежности кода.","ar":"تمكّن الوكلاء من تحديد وتصحيح الأخطاء في قواعد البيانات البرمجية باستخدام تشخيصات LSP وعمليات فحص Ruff CLI، وتقديم قائمة شاملة من مشاكل التحليل والتشخيص لتحسين جودة وموثوقية الشفرة."},"useCases":{"en":["Debugging code errors with ReadLints","Running Ruff CLI checks for project-wide linting","Identifying stale or inconsistent linting issues between IDE and Ruff CLI"],"zh":["使用ReadLints进行代码错误调试","运行Ruff CLI检查以进行项目范围的linting","在IDE和Ruff CLI之间识别过时或不一致的linting问题"],"ja":["ReadLintsを使用したコードエラーデバッグ","プロジェクト全体のlintingのためのRuff CLIチェックの実行","IDEとRuff CLIの間で古くなった、または一貫性のないlinting問題の特定"],"ko":["ReadLints를 사용한 코드 오류 디버깅","프로젝트 전체의 linting을 위한 Ruff CLI 검사 실행","IDE 및 Ruff CLI 간에 오래된 또는 일관되지 않은 linting 문제 식별"],"es":["Depuración de errores de código con ReadLints","Ejecución de comprobaciones de Ruff CLI para linting a nivel de proyecto","Identificación de problemas de linting estancados o inconsistentes entre IDE y Ruff CLI"],"fr":["Débogage des erreurs de code avec ReadLints","Exécution des vérifications Ruff CLI pour le linting au niveau du projet","Identification des problèmes de linting obsolètes ou incohérents entre l''IDE et Ruff CLI"],"de":["Fehlerbehebung in Code mit ReadLints","Ausführung von Ruff-CLI-Prüfungen für das Linting auf Projektebene","Identifizierung veralteter oder inkonsistenter Linting-Probleme zwischen IDE und Ruff CLI"],"pt":["Depuração de erros de código com ReadLints","Execução de verificações Ruff CLI para linting em todo o projeto","Identificação de problemas de linting obsoletos ou inconsistentes entre IDE e Ruff CLI"],"ru":["Отладка кодовых ошибок с помощью ReadLints","Запуск проверок Ruff CLI для проектного linting","Выявление устаревших или несоответствующих проблем проверки кода между IDE и Ruff CLI"],"ar":["تصحيح أخطاء الشفرة باستخدام ReadLints","تشغيل عمليات فحص Ruff CLI للتحليل البرمجي على مستوى المشروع","تحديد قضايا التحليل البرمجي القديمة أو غير المتسقة بين بيئة التطوير و Ruff CLI"]},"limitations":{"en":["Requires ReadLints and Ruff CLI tools","Limited to projects using compatible LSP and linter configurations"],"zh":["需要ReadLints和Ruff CLI工具","仅限于使用兼容的LSP和linter配置的项目"],"ja":["ReadLintsとRuff CLIツールが必要","互換性のあるLSPとlinterの構成を使用するプロジェクトに限定"],"ko":["ReadLints 및 Ruff CLI 도구가 필요","호환되는 LSP 및 linter 구성만 사용하는 프로젝트로 제한"],"es":["Requiere las herramientas ReadLints y Ruff CLI","Limitado a proyectos que utilizan configuraciones de LSP y linter compatibles"],"fr":["Nécessite les outils ReadLints et Ruff CLI","Limité aux projets utilisant des configurations LSP et linter compatibles"],"de":["Benötigt die Tools ReadLints und Ruff CLI","Begrenzt auf Projekte, die kompatible LSP- und Linter-Konfigurationen verwenden"],"pt":["Exige ferramentas ReadLints e Ruff CLI","Limitado a projetos que utilizam configurações LSP e linter compatíveis"],"ru":["Требует инструментов ReadLints и Ruff CLI","Ограничен проектами, использующими совместимые конфигурации LSP и линтер"],"ar":["يتطلب أدوات ReadLints و Ruff CLI","محدود بمشاريع تستخدم إعدادات LSP ومتوافقة مع لينتر"]},"version":4},"contentHash":"5fa8ffd7fc4bc6c5550ea4e12ecc5ffa0b747066123992e711897ccdf096605a","qualityScore":36}');
