INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('judacas/LLM-Automated-Inventory-Management/run-linting', 'run-linting', 'judacas', 'LLM-Automated-Inventory-Management', 'community', 'run-linting judacas LLM-Automated-Inventory-Management community The run-linting skill provides a workflow for computer engineers to identify and fix errors using ReadLints and Ruff CLI. It benefits developers working with Microsoft and USF. Run Linting工具使用ReadLints和Ruff CLI进行代码检查和错误诊断 Run Lintingは、ReadLintsとRuff CLIを使用してコードをチェックし、エラーを診断します 런트링 코드 검사 도구는 ReadLints와 Ruff CLI를 사용하여 코드를 검사하고 오류를 진단합니다 Run-linting es una herramienta que utiliza ReadLints para identificar errores en el código y proporciona una lista completa de diagnósticos de linter y LSP Run-linting est un outil qui utilise ReadLints pour identifier les erreurs dans le code et fournit une liste complète de diagnostics de linter et LSP Run-linting ist ein Tool, das ReadLints verwendet, um Fehler im Code zu identifizieren und eine vollständige Liste von Linter- und LSP-Diagnosen bereitstellt O Run-Linting é uma ferramenta que ajuda a identificar erros de linting e LSP diagnostics em projetos de desenvolvimento. Use-o para obter uma lista completa de erros antes de corrigi-los Run-Linting - это инструмент, который помогает выявить ошибки linting и LSP diagnostics в проектах разработки. Используйте его, чтобы получить полный список ошибок перед их исправлением Run-Linting هو أداة تساعد في تحديد أخطاء Linting و LSP diagnostics في مشاريع التطوير. استخدمه للحصول على قائمة كاملة بالأخطاء قبل تصحيحها how to use run-linting run-linting setup guide what is run-linting run-linting vs Ruff run-linting alternative to Pyright run-linting install for Microsoft run-linting for USF developers run-linting and LSP diagnostics run-linting with ReadLints and Ruff CLI 代码检查工具 Run Linting ReadLints Ruff CLI 代码错误诊断 代码质量 AI代码检查 代码检查最佳实践 Returns current workspace’s LSP/linter diagnostics using ReadLints Utilizes Ruff CLI for separate project-wide linting checks Supports uv run ruff check --fix command for automated fixes Provides a complete list of linter and LSP diagnostics for error identification Works with Ruff as the main linter for consistent error reporting Integrates with IDE for real-time diagnostics and error reporting run-linting is a skill that utilizes ReadLints and Ruff CLI to return LSP/linter diagnostics and report errors for comprehensive code review.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ozahirnyi/movie_finder/connect-to-lightsail-instance', 'community', 'ozahirnyi', 'movie_finder', 'ozahirnyi/movie_finder', 'connect-to-lightsail-instance', 0, 0, 36, '2026-03-08T01:57:15.510Z', '2026-03-08T02:10:25.157Z', 'df71d903e6f2f59a6c5273a1b717ecc4802f8f800cd62ee4c6a1e83041388d73', '{"id":"ozahirnyi/movie_finder/connect-to-lightsail-instance","name":"connect-to-lightsail-instance","description":{"en":"The connect-to-lightsail-instance skill enables developers to establish a secure SSH connection to their Lightsail instance, facilitating efficient server management and deployment. It benefits developers working with Lightsail instances.","zh":"本指南介绍如何连接到 Lightsail 实例，包括使用 SSH 命令和管理密钥文件","ja":"このガイドでは、Lightsail インスタンスに接続する方法を紹介します。SSH コマンドや鍵ファイルの管理について","ko":"본 가이드는 Lightsail 인스턴스에 연결하는 방법을介绍합니다. SSH 명령어와 키 파일 관리에 대해","es":"Conecta tu instancia de Lightsail con facilidad. Nuestra guía te muestra cómo configurar tu entorno de desarrollo.","fr":"Connectez votre instance Lightsail avec facilité. Notre guide vous montre comment configurer votre environnement de développement.","de":"Verbinden Sie Ihre Lightsail-Instanz mit Leichtigkeit. Unsere Anleitung zeigt Ihnen, wie Sie Ihre Entwicklungsumgebung konfigurieren.","pt":"Conecte-se ao Lightsail com facilidade. Aprenda a configurar a chave SSH e acessar sua instância para gerenciar seus recursos.","ru":"Подключайтесь к Lightsail и управляйте своими ресурсами. Настройте ключ SSH и получите доступ к вашему экземпляру.","ar":"اتصل بلайтسيل بسهولة. تعلم كيفية設定 مفتاح SSH والوصول إلى مثيلك لإدارة الموارد الخاصة بك."},"seo":{"title":{"en":"connect-to-lightsail-instance: SSH Connection Setup Guide...","zh":"Lightsail 实例连接设置指南","ja":"Lightsail インスタンス接続設定ガイド","ko":"Lightsail 인스턴스 연결 설정 가이드","es":"Conectar a Lightsail: Guía de configuración para desarrol...","fr":"Se connecter à Lightsail : Guide de configuration pour le...","de":"Verbindung zu Lightsail herstellen: Einrichtungsanleitung...","pt":"Conectar ao Lightsail: Guia de Configuração","ru":"ИИ Агенты: Подключение к Lightsail - Руководство","ar":"التوصيل بلайтسيل: إرشادات الإعداد"},"description":{"en":"Discover how to securely connect to your Lightsail instance using SSH, and explore the benefits of streamlined server management - get started now!","zh":"了解如何连接到 Lightsail 实例，包括 SSH 命令和密钥文件管理","ja":"Lightsail インスタンスに接続する方法を学びます。SSH コマンドや鍵ファイルの管理について","ko":"Lightsail 인스턴스에 연결하는 방법을 알아보세요. SSH 명령어와 키 파일 관리에 대해","es":"Aprende a conectar tu instancia de Lightsail con nuestra guía paso a paso para desarrolladores. Configura tu entorno de desarrollo con facilidad.","fr":"Découvrez comment vous connecter à votre instance Lightsail avec notre guide étape par étape pour les développeurs. Configurez votre environnement de dévelop...","de":"Erfahren Sie, wie Sie Ihre Lightsail-Instanz mit unserer Schritt-für-Schritt-Anleitung für Entwickler verbinden. Konfigurieren Sie Ihre Entwicklungsumgebung ...","pt":"Aprenda a conectar ao Lightsail com nosso guia passo a passo. Descubra como configurar a chave SSH e acessar sua instância.","ru":"Подключайтесь к Lightsail с помощью нашего пошагового руководства. Узнайте, как настроить ключ SSH и получить доступ к вашему экземпляру.","ar":"تعرف على كيفية الاتصال بلайтسيل بخطوات بسيطة. اكتشف كيفية設定 مفتاح SSH والوصول إلى مثيلك."},"definition":{"en":"connect-to-lightsail-instance is a skill that facilitates secure SSH connections to Amazon Lightsail instances using keys like LightsailDefaultKey-eu-central-1.pem.","zh":"Lightsail 实例连接是指使用 SSH 协议连接到 Amazon Lightsail 实例的过程","ja":"Lightsail インスタンス接続とは、Amazon Lightsail インスタンスに SSH プロトコルで接続するプロセスです","ko":"Lightsail 인스턴스 연결은 Amazon Lightsail 인스턴스에 SSH 프로토콜을 사용하여 연결하는 프로세스입니다","es":"Conectar a Lightsail es un proceso que permite a los desarrolladores acceder a sus instancias en la nube de AWS.","fr":"Se connecter à Lightsail est un processus qui permet aux développeurs d''accéder à leurs instances dans le cloud d''AWS.","de":"Die Verbindung zu Lightsail ist ein Prozess, der es Entwicklern ermöglicht, auf ihre Instanzen in der AWS-Cloud zuzugreifen.","pt":"Conectar ao Lightsail é um processo de configuração que permite acessar e gerenciar recursos na nuvem.","ru":"Подключение к Lightsail - это процесс настройки, который позволяет получить доступ и управлять ресурсами в облаке.","ar":"التوصيل بلайтسيل هو عملية إعداد تسمح بالوصول وإدارة الموارد في السحابة."},"features":{"en":["Establishes secure SSH connections to Lightsail instances using LightsailDefaultKey-eu-central-1.pem","Supports interactive SSH sessions for direct server access","Utilizes ec2-user for secure authentication","Manages connections via key files stored in the project root or workspace","Enables updating of instance IP addresses for seamless connection maintenance","Executes commands for interactive shell access"],"zh":["使用 SSH 命令连接到 Lightsail 实例","管理 LightsailDefaultKey-eu-central-1.pem 密钥文件","配置 Host 和 User 参数","支持 Git Bash 和 Windows 平台"],"ja":["SSH コマンドを使用して Lightsail インスタンスに接続","LightsailDefaultKey-eu-central-1.pem 鍵ファイルを管理","Host と User パラメータを設定","Git Bash と Windows プラットフォームをサポート"],"ko":["SSH 명령어를 사용하여 Lightsail 인스턴스에 연결","LightsailDefaultKey-eu-central-1.pem 키 파일을 관리","Host와 User 파라미터를 설정","Git Bash와 Windows 플랫폼을 지원"],"es":["Conexión SSH interactiva","Uso de la clave LightsailDefaultKey-eu-central-1.pem","Acceso como usuario ec2-user","Conexión a la instancia con la dirección IP 3.75.113.52","Compatibilidad con Git Bash y entornos de desarrollo Windows"],"fr":["Connexion SSH interactive","Utilisation de la clé LightsailDefaultKey-eu-central-1.pem","Accès en tant qu''utilisateur ec2-user","Connexion à l''instance avec l''adresse IP 3.75.113.52","Compatibilité avec Git Bash et les environnements de développement Windows"],"de":["Interaktive SSH-Verbindung","Verwendung des Schlüssels LightsailDefaultKey-eu-central-1.pem","Zugriff als Benutzer ec2-user","Verbindung zur Instanz mit der IP-Adresse 3.75.113.52","Kompatibilität mit Git Bash und Windows-Entwicklungsumgebungen"],"pt":["Configuração da chave SSH","Acesso à instância do Lightsail","Gerenciamento de recursos na nuvem","Utilização do comando SSH interativo","Definição do usuário e do host","Specifying o caminho da chave no workspace"],"ru":["Настройка ключа SSH","Доступ к экземпляру Lightsail","Управление ресурсами в облаке","Использование интерактивного команды SSH","Определение пользователя и хоста","Указание пути к ключу в workspace"],"ar":["إعداد مفتاح SSH","الوصول إلى مثيل لايتسيل","إدارة الموارد في السحابة","استخدام الأمر SSH التفاعلي","تحديد المستخدم والاستضافة","تحديد مسار المفتاح في workspace"]},"keywords":{"en":["how to use connect-to-lightsail-instance","connect-to-lightsail-instance setup guide","Lightsail instance SSH connection","connect-to-lightsail-instance alternative","connect-to-lightsail-instance vs AWS CLI","connect-to-lightsail-instance install","what is connect-to-lightsail-instance","connect-to-lightsail-instance tutorial"," Lightsail instance management"],"zh":["Lightsail 实例连接","SSH 命令","LightsailDefaultKey-eu-central-1.pem","Amazon Lightsail","云计算","服务器管理"],"ja":["Lightsail インスタンス接続","SSH コマンド","LightsailDefaultKey-eu-central-1.pem","Amazon Lightsail","クラウドコンピューティング","サーバー管理"],"ko":["Lightsail 인스턴스 연결","SSH 명령어","LightsailDefaultKey-eu-central-1.pem","Amazon Lightsail","클라우드 컴퓨팅","서버 관리"],"es":["conectar a lightsail","guía de configuración lightsail","desarrollo en la nube","aws lightsail","ssh lightsail","clave lightsail","ec2-user lightsail","git bash lightsail"],"fr":["se connecter à lightsail","guide de configuration lightsail","développement dans le cloud","aws lightsail","ssh lightsail","clé lightsail","ec2-user lightsail","git bash lightsail"],"de":["verbindung zu lightsail herstellen","einrichtungsanleitung lightsail","entwicklung in der cloud","aws lightsail","ssh lightsail","schlüssel lightsail","ec2-user lightsail","git bash lightsail"],"pt":["conectar ao lightsail","configurar chave ssh","acessar instância lightsail","gerenciar recursos nuvem","comando ssh interativo","lightsail instance","chave ssh lightsail","acesso lightsail"],"ru":["подключение к lightsail","настройка ключа ssh","доступ к экземпляру lightsail","управление ресурсами облако","интерактивная команда ssh","lightsail экземпляр","ключ ssh lightsail","доступ lightsail"],"ar":["التوصيل بلайтسيل","إعداد مفتاح ssh","الوصول إلى مثيل لايتسيل","إدارة الموارد السحابية","الأمر ssh التفاعلي","مثيل لايتسيل","مفتاح ssh لايتسيل","الوصول لايتسيل"]}},"owner":"ozahirnyi","repo":"movie_finder","repoPath":"ozahirnyi/movie_finder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.510Z","topics":[],"category":"community","skillMd":{"name":"connect-to-lightsail-instance","description":"How to SSH to the Movie Finder Lightsail instance. Use when the user asks to connect to the instance, check deploy logs, or run commands on the production server.","bodyPreview":"# Connect to Lightsail instance\n\n## Connection details\n\n| What   | Value |\n|--------|--------|\n| **Key** | `LightsailDefaultKey-eu-central-1.pem` (in project root; may be gitignored) |\n| **User** | `ec2-user` |\n| **Host** | `3.75.113.52` (update if instance IP changed) |\n\nKey path in workspace: `o:\\projects\\movie_finder\\LightsailDefaultKey-eu-central-1.pem` (Windows) or `o:/projects/movie_finder/LightsailDefaultKey-eu-central-1.pem` (Git Bash).\n\n## Commands\n\n**Interactive SSH (open a shell on th","body":"# Connect to Lightsail instance\n\n## Connection details\n\n| What   | Value |\n|--------|--------|\n| **Key** | `LightsailDefaultKey-eu-central-1.pem` (in project root; may be gitignored) |\n| **User** | `ec2-user` |\n| **Host** | `3.75.113.52` (update if instance IP changed) |\n\nKey path in workspace: `o:\\projects\\movie_finder\\LightsailDefaultKey-eu-central-1.pem` (Windows) or `o:/projects/movie_finder/LightsailDefaultKey-eu-central-1.pem` (Git Bash).\n\n## Commands\n\n**Interactive SSH (open a shell on the instance):**\n```bash\nssh -i \"o:\\projects\\movie_finder\\LightsailDefaultKey-eu-central-1.pem\" -o StrictHostKeyChecking=accept-new ec2-user@3.75.113.52\n```\n\n**Run a single command on the instance (no interactive shell):**\n```bash\nssh -i \"o:\\projects\\movie_finder\\LightsailDefaultKey-eu-central-1.pem\" -o StrictHostKeyChecking=accept-new ec2-user@3.75.113.52 \"COMMAND_HERE\"\n```\n\n**Examples:**\n- **Backend only (512 MB: Grafana off)** — app on 8000, nginx on host uses 80/443 and proxies to 8000:  \n  `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml up -d\"`  \n  Without nginx (app directly on 80):  \n  `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml -f docker-compose.lightsail-direct.yml up -d\"`\n- Start backend + Grafana (when instance has ≥1 GB RAM):  \n  `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml -f docker-compose.monitoring.yml up -d\"`\n- **Stop monitoring** (free RAM) — запускай **першим після ребуту**, щоб Grafana не піднялась:  \n  `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml -f docker-compose.monitoring.yml down 2>/dev/null; docker-compose -f docker-compose.lightsail.yml up -d\"`\n- CodeDeploy agent log (last 250 lines):  \n  `\"sudo tail -250 /var/log/aws/codedeploy-agent/codedeploy-agent.log\"`\n- Docker containers (backend only):  \n  `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml ps\"`\n- **Error logs (for debugging)** — logs are kept by Docker until rotation; recent errors are still there. Agent can run this when you report an error:  \n  `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml logs --tail=300 web 2>&1 | grep -iE ''error|exception|traceback|500|failed''\"`  \n  Full last 200 lines:  \n  `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml logs --tail=200 web\"`\n\n## Script\n\nTo fetch deploy logs without typing the full SSH command:\n```bash\n./scripts/deploy/fetch-deploy-logs.sh \"o:/projects/movie_finder/LightsailDefaultKey-eu-central-1.pem\" 3.75.113.52\n```\n\n## Manual deploy (use while CI is broken)\n\n**Deploy via CI is currently not working. Always update production yourself** after pushing changes that should go to prod.\n\n**On 512 MB instance run backend only (no Grafana).** Grafana eats RAM, so **always stop it first**, then do pull/rebuild.\n\n**Order of operations (important):**\n\n0. **Спочатку вимкнути Grafana** (звільнити пам’ять), потім уже pull/build:\n   `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml -f docker-compose.monitoring.yml down 2>/dev/null; docker-compose -f docker-compose.lightsail.yml up -d\"`\n   (Якщо моніторинг не був запущений — підніме backend на 8000; nginx на 80/443.)\n1. **Pull latest code:**\n   `\"cd /home/ec2-user/movie_finder && git fetch origin main && git reset --hard origin/main\"`\n2. **Rebuild app image (if code changed):**\n   `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml build web\"`\n   (Uses cache: only changed layers rebuild. Use `build --no-cache web` only when dependencies or Dockerfile changed.)\n3. **Migrations + static (if needed):**\n   `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml run --rm web poetry run python manage.py migrate --noinput && docker-compose -f docker-compose.lightsail.yml run --rm web poetry run python manage.py collectstatic --noinput\"`\n4. **Restart backend only** (app on 8000, nginx на 80):\n   `\"cd /home/ec2-user/movie_finder && docker-compose -f docker-compose.lightsail.yml up -d\"`\n\n**Після ребуту інстансу:** спочатку крок 0 (щоб Grafana/observability не піднімались і не забивали пам’ять), потім 1–4. Не запускай `docker-compose.monitoring.yml` на 512 MB — інстанс зависає.\n\n**Логи:** при роботі тільки `docker-compose.lightsail.yml` (web + db) усі stdout/stderr контейнера `web` пишуться в Docker (драйвер json-file). Перегляд: `docker-compose -f docker-compose.lightsail.yml logs --tail=200 web` або з grep по error (див. Error logs вище). Ротація логів за замовчуванням — логи зберігаються, поки не перезапустиш контейнер або не спрацює ротація.\n\nIf you upgrade to ≥1 GB RAM and want Grafana again, use `-f docker-compose.monitoring.yml` in step 4 and start with both compose files.\n\n## Error logs when something breaks\n\nWhen you report an error (e.g. 500, crash), the agent can try to SSH and run the **Error logs** command above to fetch recent error/exception lines from the `web` container. Docker keeps container stdout/stderr in a log file (json-file driver) until it’s rotated or the container is removed, so **recent errors usually stay available** for at least the last restarts / last tens of MB of logs. They don’t disappear instantly; only when the log is rotated or the container is recreated and the old log is discarded.\n\n## Notes\n\n- If the instance IP changes (e.g. after rebuild), update the host in this skill and in `TROUBLESHOOTING_CODEDEPLOY.md`.\n- The key file is in `.gitignore` (`*.pem`); it must exist locally in the project or another path you pass to `ssh -i`.\n"},"lastSynced":"2026-03-08T02:10:25.157Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Management Agents needing secure SSH connections to Lightsail instances.","zh":"非常适合需要安全SSH连接到Lightsail实例的Cloud Management Agents。","ja":"Lightsailインスタンスへの安全なSSH接続を必要とするCloud Management Agentsに最適です。","ko":"Lightsail 인스턴스에 안전한 SSH 연결이 필요한 Cloud Management Agents에 적합합니다.","es":"Perfecto para agentes de gestión en la nube que necesitan conexiones SSH seguras a instancias de Lightsail.","fr":"Parfait pour les agents de gestion cloud nécessitant des connexions SSH sécurisées aux instances Lightsail.","de":"Perfekt für Cloud-Management-Agents, die sichere SSH-Verbindungen zu Lightsail-Instanzen benötigen.","pt":"Perfeito para agentes de gerenciamento de nuvem que precisam de conexões SSH seguras para instâncias do Lightsail.","ru":"Идеально подходит для агентов управления облаком, которым необходимы безопасные подключения SSH к экземплярам Lightsail.","ar":"مثالي لعمليات إدارة السحابة التي تحتاج إلى اتصالات SSH آمنة مع مثيلات Lightsail."},"recommendation":{"en":"Empowers agents to establish secure SSH connections to Lightsail instances using keys like LightsailDefaultKey-eu-central-1.pem, facilitating efficient server management and deployment over protocols like SSH.","zh":"赋予代理建立安全的SSH连接到Lightsail实例的能力，使用诸如LightsailDefaultKey-eu-central-1.pem的密钥，方便高效的服务器管理和部署，通过协议如SSH。","ja":"Lightsailインスタンスへの安全なSSH接続を確立するためにエージェントをEmpowerし、LightsailDefaultKey-eu-central-1.pemなどのキーを使用して、SSHなどのプロトコルを使用した効率的なサーバー管理とデプロイを容易にします。","ko":"에이전트가 Lightsail 인스턴스에 안전한 SSH 연결을 설정할 수 있도록 하여, LightsailDefaultKey-eu-central-1.pem 같은 키를 사용하여 SSH 같은 프로토콜을 통해 효율적인 서버 관리와 배포를 용이하게 합니다.","es":"Habilita a los agentes a establecer conexiones SSH seguras a instancias de Lightsail utilizando claves como LightsailDefaultKey-eu-central-1.pem, lo que facilita una gestión y implementación de servidores eficientes a través de protocolos como SSH.","fr":"Permet aux agents d''établir des connexions SSH sécurisées aux instances Lightsail à l''aide de clés comme LightsailDefaultKey-eu-central-1.pem, facilitant ainsi une gestion et un déploiement de serveurs efficaces via des protocoles comme SSH.","de":"Ermächtigt Agenten, sichere SSH-Verbindungen zu Lightsail-Instanzen mit Schlüsseln wie LightsailDefaultKey-eu-central-1.pem herzustellen, was eine effiziente Serververwaltung und -bereitstellung über Protokolle wie SSH erleichtert.","pt":"Permite que os agentes estabeleçam conexões SSH seguras para instâncias do Lightsail usando chaves como LightsailDefaultKey-eu-central-1.pem, facilitando o gerenciamento eficiente de servidores e implantação sobre protocolos como SSH.","ru":"Позволяет агентам устанавливать безопасные подключения SSH к экземплярам Lightsail с помощью ключей, таких как LightsailDefaultKey-eu-central-1.pem, что облегчает эффективное управление серверами и развертывание по протоколам, таким как SSH.","ar":"تمكن العميل من إنشاء اتصالات SSH آمنة مع مثيلات Lightsail باستخدام مفاتيح مثل LightsailDefaultKey-eu-central-1.pem، مما يسهل إدارة الخواديم وتوزيعها عبر بروتوكولات مثل SSH."},"useCases":{"en":["Automating server deployments to Lightsail instances","Debugging applications running on Lightsail instances via SSH","Managing server configurations on Lightsail instances"],"zh":["将服务器部署自动化到Lightsail实例","通过SSH调试在Lightsail实例上运行的应用程序","在Lightsail实例上管理服务器配置"],"ja":["Lightsailインスタンスへのサーバー展開の自動化","SSHを介してLightsailインスタンスで実行されているアプリケーションのデバッグ","Lightsailインスタンスでのサーバー構成の管理"],"ko":["Lightsail 인스턴스에 서버 배포 자동화","SSH를 통해 Lightsail 인스턴스에서 실행되는 애플리케이션 디버깅","Lightsail 인스턴스에서 서버 구성 관리"],"es":["Automatizar despliegues de servidores en instancias de Lightsail","Depurar aplicaciones que se ejecutan en instancias de Lightsail a través de SSH","Administrar configuraciones de servidor en instancias de Lightsail"],"fr":["Automatiser les déploiements de serveurs sur des instances Lightsail","Déboguer des applications s''exécutant sur des instances Lightsail via SSH","Gérer les configurations de serveur sur des instances Lightsail"],"de":["Automatisieren von Serverbereitstellungen auf Lightsail-Instanzen","Debuggen von Anwendungen, die auf Lightsail-Instanzen über SSH ausgeführt werden","Verwalten von Serverkonfigurationen auf Lightsail-Instanzen"],"pt":["Automatizar implantações de servidores para instâncias do Lightsail","Depurar aplicações em execução em instâncias do Lightsail via SSH","Gerenciar configurações de servidores em instâncias do Lightsail"],"ru":["Автоматизация развертывания серверов на экземпляры Lightsail","Отладка приложений, работающих на экземплярах Lightsail по SSH","Управление конфигурациями серверов на экземплярах Lightsail"],"ar":["تأتمة نشر الخواديم على مثيلات Lightsail","تصحيح الأعطال للتطبيقات التي تعمل على مثيلات Lightsail عبر SSH","إدارة تكوين الخواديم على مثيلات Lightsail"]},"limitations":{"en":["Requires Lightsail instance IP and credentials","Needs access to the private key file (e.g., LightsailDefaultKey-eu-central-1.pem)","Limited to Lightsail instances"],"zh":["需要Lightsail实例IP和凭证","需要访问私钥文件（例如LightsailDefaultKey-eu-central-1.pem）","仅限Lightsail实例"],"ja":["LightsailインスタンスのIPと資格情報が必要","プライベートキーファイル（例：LightsailDefaultKey-eu-central-1.pem）へのアクセスが必要","Lightsailインスタンスのみに限定"],"ko":["Lightsail 인스턴스 IP와 자격 증명이 필요","개인 키 파일(LightsailDefaultKey-eu-central-1.pem 등) 액세스가 필요","Lightsail 인스턴스에만 제한"],"es":["Requiere la dirección IP de la instancia de Lightsail y las credenciales","Necesita acceso al archivo de clave privada (por ejemplo, LightsailDefaultKey-eu-central-1.pem)","Limitado a instancias de Lightsail"],"fr":["Nécessite l''adresse IP de l''instance Lightsail et les informations d''identification","Nécessite l''accès au fichier de clé privée (par exemple, LightsailDefaultKey-eu-central-1.pem)","Limité aux instances Lightsail"],"de":["Benötigt die IP-Adresse der Lightsail-Instanz und die Anmeldedaten","Benötigt den Zugriff auf die private Schlüsseldatei (z. B. LightsailDefaultKey-eu-central-1.pem)","Begrenzt auf Lightsail-Instanzen"],"pt":["Requer o endereço IP da instância do Lightsail e credenciais","Precisa de acesso ao arquivo de chave privada (por exemplo, LightsailDefaultKey-eu-central-1.pem)","Limitado a instâncias do Lightsail"],"ru":["Требует IP-адреса экземпляра Lightsail и учетных данных","Требует доступа к файлу приватного ключа (например, LightsailDefaultKey-eu-central-1.pem)","Ограничен экземплярами Lightsail"],"ar":["يتطلب عنوان IP لمثيل Lightsail والاعتمادات","يحتاج إلى الوصول إلى ملف المفتاح الخاص (على سبيل المثال LightsailDefaultKey-eu-central-1.pem)","محدود لمثيلات Lightsail"]},"version":4},"contentHash":"df71d903e6f2f59a6c5273a1b717ecc4802f8f800cd62ee4c6a1e83041388d73","qualityScore":36}');
