INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ozahirnyi/movie_finder/connect-to-lightsail-instance', 'connect-to-lightsail-instance', 'ozahirnyi', 'movie_finder', 'community', 'connect-to-lightsail-instance ozahirnyi movie_finder community The connect-to-lightsail-instance skill enables developers to establish a secure SSH connection to their Lightsail instance, facilitating efficient server management and deployment. It benefits developers working with Lightsail instances. 本指南介绍如何连接到 Lightsail 实例，包括使用 SSH 命令和管理密钥文件 このガイドでは、Lightsail インスタンスに接続する方法を紹介します。SSH コマンドや鍵ファイルの管理について 본 가이드는 Lightsail 인스턴스에 연결하는 방법을介绍합니다. SSH 명령어와 키 파일 관리에 대해 Conecta tu instancia de Lightsail con facilidad. Nuestra guía te muestra cómo configurar tu entorno de desarrollo. Connectez votre instance Lightsail avec facilité. Notre guide vous montre comment configurer votre environnement de développement. Verbinden Sie Ihre Lightsail-Instanz mit Leichtigkeit. Unsere Anleitung zeigt Ihnen, wie Sie Ihre Entwicklungsumgebung konfigurieren. Conecte-se ao Lightsail com facilidade. Aprenda a configurar a chave SSH e acessar sua instância para gerenciar seus recursos. Подключайтесь к Lightsail и управляйте своими ресурсами. Настройте ключ SSH и получите доступ к вашему экземпляру. اتصل بلайтسيل بسهولة. تعلم كيفية設定 مفتاح SSH والوصول إلى مثيلك لإدارة الموارد الخاصة بك. how to use connect-to-lightsail-instance connect-to-lightsail-instance setup guide Lightsail instance SSH connection connect-to-lightsail-instance alternative connect-to-lightsail-instance vs AWS CLI connect-to-lightsail-instance install what is connect-to-lightsail-instance connect-to-lightsail-instance tutorial Lightsail instance management Lightsail 实例连接 SSH 命令 LightsailDefaultKey-eu-central-1.pem Amazon Lightsail 云计算 服务器管理 Establishes secure SSH connections to Lightsail instances using LightsailDefaultKey-eu-central-1.pem Supports interactive SSH sessions for direct server access Utilizes ec2-user for secure authentication Manages connections via key files stored in the project root or workspace Enables updating of instance IP addresses for seamless connection maintenance Executes commands for interactive shell access connect-to-lightsail-instance is a skill that facilitates secure SSH connections to Amazon Lightsail instances using keys like LightsailDefaultKey-eu-central-1.pem.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nicoowr/chinese-flashcards/design-proposals', 'community', 'Nicoowr', 'chinese-flashcards', 'Nicoowr/chinese-flashcards', 'design-proposals', 0, 0, 36, '2026-03-08T01:57:15.511Z', '2026-03-08T02:10:27.547Z', '6663b8fa55a7e703f623c289ebca5a526c19750551a6db488fa1ec4bfe38c0a0', '{"id":"Nicoowr/chinese-flashcards/design-proposals","name":"design-proposals","description":{"en":"The design-proposals skill generates HTML mockups for UX direction exploration, benefiting developers and designers. It streamlines the design process with a two-phase workflow.","zh":"设计提案技能允许您生成2-3个独立的HTML模拟，以比较UX方向并实施最佳设计。该技能包括两个阶段：HTML模拟探索和真实组件实施","ja":"デザイン提案スキルは、UX方向を比較して最適な設計を実現するために、2-3つの独立したHTMLモックアップを生成することを可能にします。このスキルには、HTMLモックアップの探索と実際のコンポーネントの実装の2つの段階が含まれています","ko":"디자인 제안 기능을 사용하면 UX 방향을 비교하여 최선의 디자인을 구현할 수 있는 2-3개의 독립적인 HTML 모의를 생성할 수 있습니다. 이 기능은 HTML 모의 탐색 및 실제 구성 요소 구현의 두 단계로 구성됩니다","es":"El skill de propuestas de diseño genera 2-3 maquetas de HTML independientes para comparar direcciones de UX","fr":"Le skill de propositions de conception génère 2-3 maquettes HTML indépendantes pour comparer les directions UX","de":"Das Designvorschläge-Skill erstellt 2-3 unabhängige HTML-Mockups, um UX-Richtungen zu vergleichen","pt":"O skill de propostas de design gera mockups HTML para comparar direções de UX. Utilize Ferramentas de IA para explorar e implementar designs.","ru":"Навык генерации пропозов дизайна создает HTML-мокапы для сравнения направлений UX. Используйте ИИ Агенты для изучения и реализации дизайна.","ar":"مهارة مقترحات التصميم генери نماذج HTML لمقارنة اتجاهات UX. استخدم أدوات الذكاء الاصطناعي لاستكشاف وتنفيذ التصاميم."},"seo":{"title":{"en":"Design-Proposals: HTML Mockup Generation Guide | AI Agent...","zh":"设计提案设置指南 - 生成HTML模拟","ja":"デザイン提案のベストプラクティス - AIエージェントを使用したHTMLモックアップ","ko":"디자인 제안 가이드 - HTML 모의 구현","es":"Guía de configuración de propuestas de diseño con HTML","fr":"Guide de mise en place de propositions de conception avec...","de":"Einrichtungsleitfaden für Designvorschläge mit HTML","pt":"Guia de Configuração de Propostas de Design com Ferrament...","ru":"Настройка ИИ Агентов для Генерации Пропозов Дизайна","ar":"دليل إعداد مقترحات التصميم باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Explore UX directions with 2-3 standalone HTML mockups. Learn how to implement design-proposals and visualize project design language with our expert guide.","zh":"了解如何使用设计提案技能生成2-3个独立的HTML模拟，比较UX方向并实施最佳设计","ja":"AIエージェントを使用してデザイン提案を実施する方法を学び、UX方向を比較して最適な設計を実現する","ko":"디자인 제안 기능을 사용하여 HTML 모의를 생성하고 UX 방향을 비교하여 최선의 디자인을 구현하는 방법","es":"Aprende a generar propuestas de diseño con HTML para comparar direcciones de UX antes de implementarlas","fr":"Découvrez comment générer des propositions de conception avec HTML pour comparer les directions UX avant de les mettre en œuvre","de":"Erfahren Sie, wie Sie Designvorschläge mit HTML erstellen, um UX-Richtungen vor der Implementierung zu vergleichen","pt":"Aprenda a criar mockups HTML para explorar direções de UX antes de implementar com componentes reais utilizando Ferramentas de IA","ru":"Откройте для себя, как создавать HTML-мокапы для изучения направлений UX до реализации с помощью ИИ Агентов","ar":"تعلم كيفية إنشاء نماذج HTML لاستكشاف اتجاهات UX قبل التنفيذ باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"Design-proposals is a skill that generates 2-3 standalone HTML mockups for visually comparing UX directions before implementation.","zh":"设计提案是一种技能，用于生成HTML模拟以比较UX方向","ja":"デザイン提案は、UX方向を比較するためにHTMLモックアップを生成するスキルです","ko":"디자인 제안은 UX 방향을 비교하기 위한 HTML 모의를 생성하는 기능입니다","es":"Un designvorschlag es una representación visual de una dirección de UX creada con HTML","fr":"Une proposition de conception est une représentation visuelle d''une direction UX créée avec HTML","de":"Ein Designvorschlag ist eine visuelle Darstellung einer UX-Richtung, die mit HTML erstellt wird","pt":"Propostas de design são soluções de design geradas por Ferramentas de IA para explorar direções de UX","ru":"Пропозы дизайна - это решения дизайна, сгенерированные ИИ Агентами для изучения направлений UX","ar":"مقترحات التصميم هي حلول التصميم التي تم إنشاؤها بواسطة أدوات الذكاء الاصطناعي لاستكشاف اتجاهات UX"},"features":{"en":["Generates 2-3 standalone HTML mockups for UX direction exploration","Checks for project design system reference in .design-proposals/design-system.md","Supports two-phase workflow: exploration via HTML mockups and implementation with real components","Allows for visual comparison of UX directions before committing to one","Streamlines design process with HTML mockup generation"],"zh":["生成2-3个独立的HTML模拟","比较UX方向","实施真实组件","项目设计系统参考","HTML模拟探索"],"ja":["2-3つの独立したHTMLモックアップを生成","UX方向を比較","実際のコンポーネントを実装","プロジェクトデザインシステム参考","HTMLモックアップの探索"],"ko":["2-3개의 독립적인 HTML 모의 생성","UX 방향 비교","실제 구성 요소 구현","프로젝트 디자인 시스템 참조","HTML 모의 탐색"],"es":["Generación de 2-3 maquetas de HTML independientes","Exploración de direcciones de UX mediante mockups de HTML","Implementación de la dirección elegida con componentes reales","Revisión de la documentación del sistema de diseño del proyecto","Uso de la referencia del sistema de diseño del proyecto"],"fr":["Génération de 2-3 maquettes HTML indépendantes","Exploration de directions UX via des mockups HTML","Mise en œuvre de la direction choisie avec des composants réels","Vérification de la documentation du système de conception du projet","Utilisation de la référence du système de conception du projet"],"de":["Erstellung von 2-3 unabhängigen HTML-Mockups","Erkundung von UX-Richtungen mittels HTML-Mockups","Implementierung der gewählten Richtung mit echten Komponenten","Überprüfung der Dokumentation des Designsystems des Projekts","Verwendung der Referenz des Designsystems des Projekts"],"pt":["Geração de 2-3 mockups HTML autônomos","Exploração de direções de UX antes da implementação","Utilização de projetos de design system reference","Criação de mockups com base em .design-proposals/design-system.md","Implementação com componentes reais após escolha da direção"],"ru":["Генерация 2-3 автономных HTML-мокапов","Изучение направлений UX до реализации","Использование проектов дизайн систем референса","Создание мокапов на основе .design-proposals/design-system.md","Реализация с помощью реальных компонентов после выбора направления"],"ar":["إنشاء 2-3 نموذج HTML مستقل","استكشاف اتجاهات UX قبل التنفيذ","استخدام مشاريع نظام التصميم المرجعي","إنشاء نماذج بناءً على .design-proposals/design-system.md","التنفيذ باستخدام مكونات حقيقية بعد اختيار الاتجاه"]},"keywords":{"en":["how to use design-proposals","design-proposals tutorial","what is design-proposals","design-proposals alternative","design-proposals vs Adobe XD","design-proposals setup guide","design-proposals install","HTML mockup generation","UX direction exploration"],"zh":["设计提案","HTML模拟","UX方向","项目设计系统","AI工具","设计系统参考","HTML模拟探索","真实组件实施"],"ja":["デザイン提案","HTMLモックアップ","UX方向","プロジェクトデザインシステム","AIエージェント","デザインシステム参考","HTMLモックアップの探索","実際のコンポーネントの実装"],"ko":["디자인 제안","HTML 모의","UX 방향","프로젝트 디자인 시스템","AI 도구","디자인 시스템 참조","HTML 모의 탐색","실제 구성 요소 구현"],"es":["propuestas de diseño","maquetas de HTML","direcciones de UX","sistema de diseño","implementación de componentes","diseño de interfaz de usuario","desarrollo web","herramientas de diseño"],"fr":["propositions de conception","maquettes HTML","directions UX","système de conception","mise en œuvre de composants","conception d''interface utilisateur","développement web","outils de conception"],"de":["Designvorschläge","HTML-Mockups","UX-Richtungen","Designsystem","Implementierung von Komponenten","Benutzeroberflächendesign","Webentwicklung","DesignTools"],"pt":["Ferramentas de IA para design","Propostas de design","Mockups HTML","UX design","Design system reference","Desenvolvimento de interfaces","Ferramentas de desenvolvimento"],"ru":["ИИ Агенты для дизайна","Пропозы дизайна","HTML-мокапы","UX-дизайн","Дизайн систем референса","Разработка интерфейсов","Инструменты разработки"],"ar":["أدوات الذكاء الاصطناعي للتصميم","مقترحات التصميم","نماذج HTML","تصميم UX","نظام التصميم المرجعي","تطوير الواجهات","أدوات التطوير"]}},"owner":"Nicoowr","repo":"chinese-flashcards","repoPath":"Nicoowr/chinese-flashcards","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.511Z","topics":[],"category":"community","skillMd":{"name":"design-proposals","description":"Generate and present multiple visual UX/UI design proposals as interactive HTML mockups. Use when the user asks to propose, explore, or compare designs, layouts, or UX ideas for a feature — or when a feature request could benefit from visual exploration before implementation.","bodyPreview":"# Design Proposals\n\nGenerate 2–3 standalone HTML mockups so the user can visually compare UX directions before committing to one. This is a two-phase workflow: first explore via HTML mockups, then implement the chosen direction with real components.\n\n## Phase 1 — HTML Mockups (exploration)\n\n### Step 1: Understand the project''s design language\n\nBefore creating any mockup, check if a **project design system reference** exists:\n\n1. Look for `.design-proposals/design-system.md` in the project root.","body":"# Design Proposals\n\nGenerate 2–3 standalone HTML mockups so the user can visually compare UX directions before committing to one. This is a two-phase workflow: first explore via HTML mockups, then implement the chosen direction with real components.\n\n## Phase 1 — HTML Mockups (exploration)\n\n### Step 1: Understand the project''s design language\n\nBefore creating any mockup, check if a **project design system reference** exists:\n\n1. Look for `.design-proposals/design-system.md` in the project root.\n2. **If it exists**, read it — it contains the project''s colors, fonts, CSS utilities, layout patterns, and example markup ready to reuse in mockups. Skip discovery and go to Step 2.\n3. **If it doesn''t exist**, discover the design language manually:\n   - Find the global CSS file (e.g., `globals.css`, `index.css`, `tailwind.config.*`) — extract colors, fonts, border radii, and any custom utilities.\n   - Scan 1–2 existing page/layout files to understand overall structure (navigation, spacing, dark/light mode).\n   - Note the component library in use (shadcn, Radix, MUI, Chakra, plain HTML…).\n   - **Then offer to create the reference file** for future sessions (see \"Creating a design system reference\" below).\n\n### Step 2: Create the mockups\n\n1. Create a `.design-proposals/` directory at the project root (add it to `.gitignore` if not already present, along with `.screenshots/`).\n2. For each proposal, create a self-contained HTML file:\n   - Name files descriptively: `option-a-<short-label>.html`, `option-b-<short-label>.html`, etc.\n   - Use **Tailwind CDN** (`<script src=\"https://cdn.tailwindcss.com\"></script>`) for utility classes.\n   - Import the same font the project uses (e.g., Google Fonts link).\n   - Replicate the project''s color palette and visual style via inline `<style>` — match dark/light mode, glass effects, gradients, border styles, etc.\n   - Each file must be fully self-contained (no external dependencies beyond CDN links).\n   - Add a **colored annotation banner** fixed at the top of each page, briefly describing the design direction (use a distinct color per option so they''re easy to tell apart).\n   - Populate with realistic placeholder content relevant to the feature.\n\n### Step 3: Present the mockups\n\n1. Start a local HTTP server in `.design-proposals/`:\n   ```\n   python3 -m http.server 8899\n   ```\n   Run it in the background (block_until_ms: 0, full_network permission).\n2. Open each mockup in the Cursor built-in browser at `http://localhost:8899/<filename>.html`.\n3. Resize the browser to **1440×900** before taking screenshots.\n4. Take a screenshot of each option.\n5. After all screenshots, provide a structured comparison:\n   - For each option: a short description, **best for**, and **trade-off**.\n   - Ask the user which direction they prefer, or if they want to mix elements.\n\n### Iteration\n\nWhen the user requests tweaks to a specific option, edit that HTML file in place and reload the browser. Do not recreate the file from scratch.\n\n## Phase 2 — Real implementation (after the user picks a direction)\n\nOnce a direction is chosen:\n\n1. Create a temporary design route or page in the project (e.g., `src/app/(design)/...` or equivalent for the framework in use).\n2. Implement the chosen design using the project''s **actual** components, styles, and data types.\n3. Let the user validate on the dev server.\n4. When approved, move the implementation to its final location and clean up design artifacts.\n\n## Creating a design system reference\n\nWhen a project doesn''t have a `design-system.md` yet, offer to create one after the first design session. The file captures everything needed to replicate the project''s visual style in standalone HTML mockups.\n\nStore it at `.design-proposals/design-system.md` (already gitignored alongside the mockups).\n\nThe reference should include:\n- **Theme**: dark/light mode, background colors (HSL values)\n- **Color palette**: primary, secondary, muted, accent, destructive — with exact HSL values from the CSS\n- **Typography**: font family, Google Fonts import URL, key sizes\n- **Border & radius**: radius values, border colors\n- **Custom utilities**: any project-specific CSS like glass effects, gradients, shadows — copy the exact CSS\n- **Layout patterns**: typical page structure (e.g., \"3-column: filters | main card | sidebar\")\n- **Component library**: which library is used, key components (Button, Card, etc.)\n- **HTML boilerplate**: a ready-to-copy `<head>` block with all CDN links, font imports, and `<style>` block so new mockups can be started instantly\n\nKeep the reference concise (under 150 lines). It''s a cheat sheet, not full documentation.\n\n## Rules\n\n- **Never** use the image generation tool for design proposals — it produces hallucinated UI elements and doesn''t match the project''s design system.\n- Always propose **2–3 options**, not just one. The value is in comparison.\n- Each option should represent a **fundamentally different UX approach** (e.g., side panel vs. full page vs. drawer), not just color or spacing variations.\n- Keep mockups focused on layout, information hierarchy, and interaction flow — pixel-perfect polish is not the goal at this stage.\n- Use an opaque (not glass/transparent) background on the drawer/panel containers if the page background is dark — semi-transparent glass is invisible against matching dark backgrounds in standalone mockups.\n"},"lastSynced":"2026-03-08T02:10:27.547Z","agentAnalysis":{"suitability":{"en":"Perfect for UX-focused AI Agents needing streamlined design process integration with HTML mockup generation.","zh":"适用于需要将流线型设计过程与 HTML 模拟生成集成的 UX 集中 AI Agents。","ja":"UX に焦点を当てた AI エージェントがストリームライン化された設計プロセスと HTML モックアップ生成の統合を必要とする場合に最適です。","ko":"UX 에 중점을 둔 AI 에이전트가 스트림 라인화된 디자인 프로세스와 HTML 모의 생성 통합을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de IA centrados en UX que necesitan una integración de proceso de diseño simplificado con generación de bocetos HTML.","fr":"Parfait pour les agents IA axés sur l''UX nécessitant une intégration de processus de conception simplifiée avec génération de maquettes HTML.","de":"Perfekt für UX-fokussierte KI-Agents, die eine vereinfachte Designprozessintegration mit HTML-Mockup-Generierung benötigen.","pt":"Perfeito para Agentes de IA focados em UX que necessitam de integração de processo de design simplificado com geração de mockup em HTML.","ru":"Идеально подходит для агентов ИИ, ориентированных на UX, которым необходим упрощенный процесс дизайна с генерацией макетов HTML.","ar":"مثالي للوكلاء الذكيين الذين يركزون على UX وهم بحاجة إلى دمج عملية التصميم المبسطة مع توليد النماذج المصغرة HTML."},"recommendation":{"en":"Empowers agents to generate standalone HTML mockups for UX direction exploration, utilizing a two-phase workflow that streamlines the design process with real components, and referencing project design systems via .design-proposals/design-system.md files.","zh":"赋予代理生成独立的 HTML 模拟以探索 UX 方向，采用两阶段工作流来简化设计过程，并通过 .design-proposals/design-system.md 文件引用项目设计系统。","ja":"UX 方向の探索のために独立した HTML モックアップを生成するエージェントを可能にし、設計プロセスを簡素化する 2 つの段階のワークフローを使用し、.design-proposals/design-system.md ファイルを介してプロジェクトの設計システムを参照します。","ko":"UX 방향 탐색을 위한 독립형 HTML 모의 생성을 에이전트에게 가능하게 하며, 디자인 프로세스를 단순화하는 2단계 워크플로를 사용하고, .design-proposals/design-system.md 파일을 통해 프로젝트 디자인 시스템을 참조합니다.","es":"Habilita a los agentes a generar maquetas HTML autónomas para explorar la dirección de UX, utilizando un flujo de trabajo de dos fases que simplifica el proceso de diseño con componentes reales y hace referencia a los sistemas de diseño del proyecto a través de archivos .design-proposals/design-system.md.","fr":"Permet aux agents de générer des maquettes HTML autonomes pour explorer la direction de l''UX, en utilisant un flux de travail en deux phases qui simplifie le processus de conception avec des composants réels et référence les systèmes de conception du projet via des fichiers .design-proposals/design-system.md.","de":"Ermöglicht es Agenten, eigenständige HTML-Mockups für die Erforschung der UX-Richtung zu generieren, indem ein zweiphasiger Arbeitsablauf verwendet wird, der den Designprozess mit echten Komponenten vereinfacht und auf die Designsprachen des Projekts über Dateien .design-proposals/design-system.md verweist.","pt":"Habilita os agentes a gerar mockups HTML autônomos para exploração de direção de UX, utilizando um fluxo de trabalho de duas fases que simplifica o processo de design com componentes reais e faz referência a sistemas de design de projeto via arquivos .design-proposals/design-system.md.","ru":"Наделяет агентов возможностью генерировать самостоятельные макеты HTML для изучения направления UX, используя двухфазный рабочий процесс, который упрощает процесс дизайна с реальными компонентами и ссылается на системы дизайна проекта через файлы .design-proposals/design-system.md.","ar":"يمنح الوكلاء القدرة على توليد نماذج مصغرة HTML مستقلة لاستكشاف اتجاه UX، باستخدام تدفق عمل على مرحلتين يبسط عملية التصميم مع المكونات الفعلية ويشير إلى أنظمة التصميم للمشروع من خلال ملفات .design-proposals/design-system.md."},"useCases":{"en":["Generating HTML mockups for UX direction comparison","Implementing chosen design directions with real components","Exploring project design languages via design system references"],"zh":["生成 HTML 模拟以比较 UX 方向","使用真实组件实现所选设计方向","通过设计系统引用探索项目设计语言"],"ja":["UX 方向の比較のための HTML モックアップの生成","実際のコンポーネントを使用して選択した設計方向を実装する","設計システムの参照を介してプロジェクトの設計言語を探索する"],"ko":["UX 방향 비교를 위한 HTML 모의 생성","실제 구성 요소를 사용하여 선택한 디자인 방향을 구현하는 것","디자인 시스템 참조를 통해 프로젝트 디자인 언어 탐색"],"es":["Generar maquetas HTML para comparar direcciones de UX","Implementar direcciones de diseño elegidas con componentes reales","Explorar lenguajes de diseño del proyecto a través de referencias del sistema de diseño"],"fr":["Générer des maquettes HTML pour comparer les directions de l''UX","Mettre en œuvre les directions de conception choisies avec des composants réels","Explorer les langages de conception du projet via des références au système de conception"],"de":["Generieren von HTML-Mockups zum Vergleich von UX-Richtungen","Implementieren von gewählten Designrichtungen mit echten Komponenten","Erforschung von Designsprachen des Projekts über Designsprachenreferenzen"],"pt":["Gerar mockups HTML para comparação de direção de UX","Implementar direções de design escolhidas com componentes reais","Explorar linguagens de design de projeto via referências de sistema de design"],"ru":["Генерировать макеты HTML для сравнения направления UX","Реализовывать выбранные направления дизайна с реальными компонентами","Изучать языки дизайна проекта через ссылки на систему дизайна"],"ar":["توليد نماذج مصغرة HTML لمقارنة اتجاه UX","تنفيذ اتجاهات التصميم المختارة مع المكونات الفعلية","استكشاف لغات التصميم للمشروع من خلال مرجع نظام التصميم"]},"limitations":{"en":["Requires project design system reference file (.design-proposals/design-system.md)","Limited to two-phase workflow"],"zh":["需要项目设计系统引用文件 (.design-proposals/design-system.md)","仅限两阶段工作流"],"ja":["プロジェクトの設計システム参照ファイル (.design-proposals/design-system.md) が必要","2 段階のワークフローに限定される"],"ko":["프로젝트 디자인 시스템 참조 파일 (.design-proposals/design-system.md) 필요","2단계 워크플로우로 제한됨"],"es":["Requiere un archivo de referencia del sistema de diseño del proyecto (.design-proposals/design-system.md)","Limitado a un flujo de trabajo de dos fases"],"fr":["Nécessite un fichier de référence du système de conception du projet (.design-proposals/design-system.md)","Limité à un flux de travail en deux phases"],"de":["Benötigt eine Referenzdatei des Designsprachensystems des Projekts (.design-proposals/design-system.md)","Begrenzt auf einen zweiphasigen Arbeitsablauf"],"pt":["Exige arquivo de referência de sistema de design do projeto (.design-proposals/design-system.md)","Limitado a fluxo de trabalho de duas fases"],"ru":["Требует файла ссылки на систему дизайна проекта (.design-proposals/design-system.md)","Ограничен двухфазным рабочим процессом"],"ar":["يتطلب ملف مرجع نظام التصميم للمشروع (.design-proposals/design-system.md)","محدود بتدفق العمل على مرحلتين"]},"version":4},"contentHash":"6663b8fa55a7e703f623c289ebca5a526c19750551a6db488fa1ec4bfe38c0a0","qualityScore":36}');
