INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nicoowr/chinese-flashcards/design-proposals', 'design-proposals', 'Nicoowr', 'chinese-flashcards', 'community', 'design-proposals Nicoowr chinese-flashcards community The design-proposals skill generates HTML mockups for UX direction exploration, benefiting developers and designers. It streamlines the design process with a two-phase workflow. 设计提案技能允许您生成2-3个独立的HTML模拟，以比较UX方向并实施最佳设计。该技能包括两个阶段：HTML模拟探索和真实组件实施 デザイン提案スキルは、UX方向を比較して最適な設計を実現するために、2-3つの独立したHTMLモックアップを生成することを可能にします。このスキルには、HTMLモックアップの探索と実際のコンポーネントの実装の2つの段階が含まれています 디자인 제안 기능을 사용하면 UX 방향을 비교하여 최선의 디자인을 구현할 수 있는 2-3개의 독립적인 HTML 모의를 생성할 수 있습니다. 이 기능은 HTML 모의 탐색 및 실제 구성 요소 구현의 두 단계로 구성됩니다 El skill de propuestas de diseño genera 2-3 maquetas de HTML independientes para comparar direcciones de UX Le skill de propositions de conception génère 2-3 maquettes HTML indépendantes pour comparer les directions UX Das Designvorschläge-Skill erstellt 2-3 unabhängige HTML-Mockups, um UX-Richtungen zu vergleichen O skill de propostas de design gera mockups HTML para comparar direções de UX. Utilize Ferramentas de IA para explorar e implementar designs. Навык генерации пропозов дизайна создает HTML-мокапы для сравнения направлений UX. Используйте ИИ Агенты для изучения и реализации дизайна. مهارة مقترحات التصميم генери نماذج HTML لمقارنة اتجاهات UX. استخدم أدوات الذكاء الاصطناعي لاستكشاف وتنفيذ التصاميم. how to use design-proposals design-proposals tutorial what is design-proposals design-proposals alternative design-proposals vs Adobe XD design-proposals setup guide design-proposals install HTML mockup generation UX direction exploration 设计提案 HTML模拟 UX方向 项目设计系统 AI工具 设计系统参考 HTML模拟探索 真实组件实施 Generates 2-3 standalone HTML mockups for UX direction exploration Checks for project design system reference in .design-proposals/design-system.md Supports two-phase workflow: exploration via HTML mockups and implementation with real components Allows for visual comparison of UX directions before committing to one Streamlines design process with HTML mockup generation Design-proposals is a skill that generates 2-3 standalone HTML mockups for visually comparing UX directions before implementation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('smkun/32Gamers/designing-onboarding-paths', 'community', 'smkun', '32Gamers', 'smkun/32Gamers', 'designing-onboarding-paths', 0, 0, 36, '2026-03-08T01:57:15.512Z', '2026-03-08T02:10:28.019Z', 'ce967a2f5058afc0606cfde40968aa0269282d1814e9913df19f12a0c43d7e89', '{"id":"smkun/32Gamers/designing-onboarding-paths","name":"designing-onboarding-paths","description":{"en":"The designing-onboarding-paths skill enables developers to create intuitive onboarding flows for the 32Gamers cyberpunk portal using vanilla JavaScript and Firebase Auth. It benefits developers seeking to enhance user engagement.","zh":"设计入门路径技能，用于创建个性化的第一运行体验，使用vanilla JavaScript和Firebase Auth","ja":"入門パスの設計スキルは、vanilla JavaScriptとFirebase Authを使ってカスタマイズされた初回実行体験を作成します","ko":"디자인 온보딩 경로 스킬을 사용하여 개인화된 첫 실행 경험을 만들 수 있습니다. Vanilla JavaScript와 Firebase Auth를 사용합니다","es":"Diseña rutas de incorporación personalizadas con JavaScript y Firebase. Detecta la primera visita y muestra modals de bienvenida para mejorar la experiencia del usuario","fr":"Concevez des parcours d''intégration personnalisés avec JavaScript et Firebase. Détection de la première visite et affichage de modals de bienvenue pour améliorer l''expérience utilisateur","de":"Erstellen Sie benutzerdefinierte Onboarding-Pfade mit JavaScript und Firebase. Verwenden Sie die Erstdetektion und zeigen Sie Willkommensmodals an, um die Benutzererfahrung zu verbessern","pt":"Desenvolva caminhos de integração eficazes com JavaScript e Firebase Auth para melhorar a experiência do usuário.","ru":"Разработайте эффективные пути интеграции с помощью JavaScript и Firebase Auth для улучшения пользовательского опыта.","ar":"قم بإنشاء مسارات التكامل الفعالة باستخدام JavaScript و Firebase Auth لتحسين تجربة المستخدم."},"seo":{"title":{"en":"Designing-Onboarding-Paths: Setup Guide for AI Agents","zh":"设计入门路径Setup Guide - AIエージェント工具","ja":"入門パスの設計 Best Practices - AIエージェント","ko":"온보딩 경로 설계 Setup Guide - AI 에이전트","es":"Guía de configuración de rutas de incorporación con JavaS...","fr":"Guide de configuration des parcours d''intégration avec Ja...","de":"Einrichtungsleitfaden für Onboarding-Pfade mit JavaScript...","pt":"Guia de Configuração de Caminhos de Integração com Ferram...","ru":"ИИ Агенты: Настройка Путей Интеграции для 32Gamers","ar":"إعداد مسارات التكامل مع أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock seamless user experiences with designing-onboarding-paths! Learn how to implement first-run experiences, checklists, and guided UI with vanilla JavaSc...","zh":"了解如何使用设计入门路径技能，通过vanilla JavaScript和Firebase Auth创建个性化的第一运行体验","ja":"入門パスの設計スキルを使って、vanilla JavaScriptとFirebase Authでカスタマイズされた初回実行体験を作成する方法を学びます","ko":"디자인 온보딩 경로 스킬을 사용하여 Vanilla JavaScript와 Firebase Auth로 개인화된 첫 실행 경험을 만드는 방법을 알아보세요","es":"Aprende a diseñar rutas de incorporación efectivas con JavaScript y Firebase. Descubre cómo detectar la primera visita y mostrar modales de bienvenida","fr":"Découvrez comment concevoir des parcours d''intégration efficaces avec JavaScript et Firebase. Apprenez à détecter la première visite et à afficher des modaux...","de":"Erfahren Sie, wie Sie effektive Onboarding-Pfade mit JavaScript und Firebase erstellen. Lernen Sie, die erste Besuchsdetektion und die Anzeige von Willkommen...","pt":"Aprenda a projetar caminhos de integração personalizados com JavaScript e Firebase Auth para melhorar a experiência do usuário.","ru":"Откройте для себя, как создать индивидуальные пути интеграции с помощью JavaScript и Firebase Auth для улучшения пользовательского опыта.","ar":"تعرف على كيفية تصميم مسارات التكامل المخصصة باستخدام JavaScript و Firebase Auth لتحسين تجربة المستخدم."},"definition":{"en":"Designing-onboarding-paths is a skill that covers the creation of first-run experiences, checklists, and guided UI for web applications, utilizing technologies like vanilla JavaSc