INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('smkun/32Gamers/designing-onboarding-paths', 'designing-onboarding-paths', 'smkun', '32Gamers', 'community', 'designing-onboarding-paths smkun 32Gamers community The designing-onboarding-paths skill enables developers to create intuitive onboarding flows for the 32Gamers cyberpunk portal using vanilla JavaScript and Firebase Auth. It benefits developers seeking to enhance user engagement. 设计入门路径技能，用于创建个性化的第一运行体验，使用vanilla JavaScript和Firebase Auth 入門パスの設計スキルは、vanilla JavaScriptとFirebase Authを使ってカスタマイズされた初回実行体験を作成します 디자인 온보딩 경로 스킬을 사용하여 개인화된 첫 실행 경험을 만들 수 있습니다. Vanilla JavaScript와 Firebase Auth를 사용합니다 Diseña rutas de incorporación personalizadas con JavaScript y Firebase. Detecta la primera visita y muestra modals de bienvenida para mejorar la experiencia del usuario Concevez des parcours d''intégration personnalisés avec JavaScript et Firebase. Détection de la première visite et affichage de modals de bienvenue pour améliorer l''expérience utilisateur Erstellen Sie benutzerdefinierte Onboarding-Pfade mit JavaScript und Firebase. Verwenden Sie die Erstdetektion und zeigen Sie Willkommensmodals an, um die Benutzererfahrung zu verbessern Desenvolva caminhos de integração eficazes com JavaScript e Firebase Auth para melhorar a experiência do usuário. Разработайте эффективные пути интеграции с помощью JavaScript и Firebase Auth для улучшения пользовательского опыта. قم بإنشاء مسارات التكامل الفعالة باستخدام JavaScript و Firebase Auth لتحسين تجربة المستخدم. designing-onboarding-paths setup guide how to use designing-onboarding-paths designing-onboarding-paths alternative designing-onboarding-paths vs custom onboarding vanilla JavaScript onboarding examples Firebase Auth user state detection designing-onboarding-paths install 32Gamers cyberpunk portal integration guided UI implementation first-run experience best practices 设计入门路径 AIエージェント工具 vanilla JavaScript Firebase Auth 第一运行体验 个性化欢迎模态窗口 本地存储访问 首次访问检测 Detects first-time visits using localStorage Implements welcome modals for new users Utilizes Firebase Auth for user state detection Integrates with the 32Gamers cyberpunk portal Employs vanilla JavaScript for seamless execution Includes a Quick Start guide for easy setup Designing-onboarding-paths is a skill that covers the creation of first-run experiences, checklists, and guided UI for web applications, utilizing technologies like vanilla JavaScript and Firebase Auth.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('congwa/embedease-ai/image-compress', 'community', 'congwa', 'embedease-ai', 'congwa/embedease-ai', 'image-compress', 0, 0, 36, '2026-03-08T01:57:15.520Z', '2026-03-08T02:10:42.919Z', 'a82a3ca886de046173759b2652884690cc4c48a7ba2b7eab38c2aa7376cddef1', '{"id":"congwa/embedease-ai/image-compress","name":"image-compress","description":{"en":"The image-compress skill optimizes images in README files, ensuring they are under 100KB, and recommends formats like avif, webp, and png for better compression","zh":"image-compress是一款优化图片压缩的工具，帮助开发者减少图片大小，提高网页加载速度。它支持多种图片格式，包括avif、webp、png、jpg等。","ja":"image-compressは画像圧縮を最適化するツールで、開発者が画像のサイズを削減し、Webページの読み込み時間を短縮するのに役立ちます。avif、webp、png、jpgなどの複数の画像形式をサポートしています。","ko":"image-compress는 이미지 압축을 최적화하는 도구로 개발자가 이미지 크기를 줄이고 웹 페이지 로딩 속도를 향상시킬 수 있도록 도와줍니다. avif, webp, png, jpg等 여러 이미지 형식을 지원합니다.","es":"Image-compress es una herramienta para optimizar imágenes, que comprime archivos de imagen para mejorar la velocidad de carga de sitios web","fr":"Image-compress est un outil pour optimiser les images, qui comprime les fichiers d''image pour améliorer la vitesse de chargement des sites web","de":"Image-compress ist ein Tool zur Bildoptimierung, das Bilddateien komprimiert, um die Ladezeit von Websites zu verbessern","pt":"O image-compress é uma ferramenta que ajuda a otimizar imagens, reduzindo tamanhos de arquivos e melhorando a velocidade de carga","ru":"image-compress - это инструмент, который помогает оптимизировать изображения, уменьшая размер файлов и повышая скорость загрузки для ИИ Агентов","ar":"image-compress هو أداة تساعد في ضغط الصور، لتقليل حجم الملفات وتحسين سرعة التحميل للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"image-compress: Image Optimization Setup Guide | AI Agent...","zh":"image-compress Setup Guide：优化图片压缩","ja":"image-compress設定ガイド：画像圧縮の最適化","ko":"image-compress 설정 가이드: 이미지 압축 최적화","es":"Guía de configuración de image-compress para optimizar im...","fr":"Guide de mise en place de image-compress pour compresser ...","de":"Einrichtungsleitfaden für image-compress zur Bildoptimierung","pt":"Guia de Configuração do image-compress: Otimização de Ima...","ru":"Настройка image-compress: Сжатие Изображений для ИИ Агентов","ar":"دليل إعداد image-compress: ضغط الصور للوكلاء الذكاء الاصط..."},"description":{"en":"Discover how to compress images with image-compress, learn the best practices for optimizing README images, and get started with our easy-to-follow setup guide","zh":"学习使用image-compress优化图片压缩，减少图片大小，提高网页加载速度。了解压缩规则、推荐格式和检查命令。","ja":"image-compressを使用して画像を圧縮し、サイズを削減し、Webページの読み込み時間を短縮する方法を学びます。圧縮ルール、推奨フォーマット、チェックコマンドについて詳しく。","ko":"image-compress를 사용하여 이미지 압축을 최적화하고 이미지 크기를 줄이며 웹 페이지 로딩 속도를 향상시키는 방법에 대해 알아보세요. 압축 규칙, 추천 형식 및 확인 명령에 대해 자세히 알아보세요.","es":"Aprende a utilizar image-compress para reducir el tamaño de las imágenes y mejorar la velocidad de carga de tu sitio web","fr":"Découvrez comment utiliser image-compress pour compresser les images et améliorer la vitesse de chargement de votre site web","de":"Erfahren Sie, wie Sie image-compress verwenden können, um die Bildgröße zu reduzieren und die Ladezeit Ihrer Website zu verbessern","pt":"Aprenda a configurar o image-compress para otimizar imagens em seus projetos, reduzindo tamanhos de arquivos e melhorando a velocidade de carga","ru":"Узнайте, как настроить image-compress для сжатия изображений в ваших проектах, уменьшая размер файлов и повышая скорость загрузки для ИИ Агентов","ar":"تعلم كيفية إعداد image-compress لضغط الصور في مشاريعك، لتقليل حجم الملفات وتحسين سرعة التحميل للوكلاء الذكاء الاصطناعي"},"definition":{"en":"image-compress is a skill that automatically optimizes images in README files to reduce their size, prioritizing formats like avif and webp for better compression","zh":"image-compress是一款用于优化图片压缩的AI工具，帮助开发者提高网页加载速度。","ja":"image-compressは画像圧縮を最適化するAIツールで、開発者がWebページの読み込み時間を短縮するのに役立ちます。","ko":"image-compress는 이미지 압축을 최적화하는 AI 도구로 개발자가 웹 페이지 로딩 속도를 향상시킬 수 있도록 도와줍니다.","es":"Image-compress es una herramienta de optimización de imágenes que reduce el tamaño de los archivos de imagen","fr":"Image-compress est un outil d''optimisation d''images qui réduit la taille des fichiers d''image","de":"Image-compress ist ein Tool zur Bildoptimierung, das die Größe von Bilddateien reduziert","pt":"O que é image-compress? É uma ferramenta de otimização de imagens que ajuda a reduzir tamanhos de arquivos","ru":"Что такое image-compress? Это инструмент для сжатия изображений, который помогает уменьшить размер файлов для ИИ Агентов","ar":"ما هو image-compress؟ هو أداة لضغط الصور تساعد في تقليل حجم الملفات للوكلاء الذكاء الاصطناعي"},"features":{"en":["Scans README.md files for images exceeding 100KB","Supports compression using macOS''s built-in sips tool","Prioritizes image formats like avif, webp, png, and jpg for optimal compression","Uses the find command to identify large images in docs/ and images/ directories","Compresses images to reduce size while maintaining quality"],"zh":["支持多种图片格式，包括avif、webp、png、jpg等","自动检查图片大小，超过100KB的图片必须压缩","推荐格式优先级：avif > webp > png > jpg","支持macOS内置sips工具进行图片压缩","提供检查命令，方便开发者检查图片大小"],"ja":["複数の画像形式をサポート：avif、webp、png、jpgなど","画像サイズを自動的にチェックし、100KBを超える画像を圧縮","推奨フォーマットの優先順位：avif > webp > png > jpg","macOS内蔵のsipsツールを使用した画像圧縮をサポート","チェックコマンドを提供し、開発者が画像サイズを簡単にチェックできる"],"ko":["여러 이미지 형식 지원: avif, webp, png, jpg 등","이미지 크기 자동 체크, 100KB 이상의 이미지 압축","추천 형식 우선 순위: avif > webp > png > jpg","macOS 내장 sips 도구를 사용한 이미지 압축 지원","확인 명령 제공, 개발자가 이미지 크기 쉽게 확인할 수 있도록"],"es":["Comprime imágenes para reducir su tamaño","Soporta formatos de imagen como avif, webp, png y jpg","Permite establecer un tamaño máximo de 100KB para las imágenes","Incluye una herramienta de comando para buscar imágenes grandes","Soporta la compresión de imágenes en macOS con sips"],"fr":["Comprime les images pour réduire leur taille","Prend en charge les formats d''image tels que avif, webp, png et jpg","Permet de définir une taille maximale de 100KB pour les images","Inclut un outil de commande pour rechercher les images de grande taille","Prend en charge la compression d''images sur macOS avec sips"],"de":["Komprimiert Bilder, um ihre Größe zu reduzieren","Unterstützt Bildformate wie avif, webp, png und jpg","Ermöglicht die Festlegung einer maximalen Größe von 100KB für Bilder","Enthält ein Kommandozeilen-Tool zum Suchen nach großen Bildern","Unterstützt die Bildkomprimierung auf macOS mit sips"],"pt":["Verificação de imagens com tamanhos acima de 100KB","Suporte a formatos de imagem como avif, webp, png e jpg","Uso de comandos como find e sips para compressão de imagens","Otimização de imagens para melhorar a velocidade de carga","Suporte a plataformas como macOS para compressão de imagens"],"ru":["Проверка изображений с размерами более 100КБ","Поддержка форматов изображений как avif, webp, png и jpg для ИИ Агентов","Использование команд как find и sips для сжатия изображений","Оптимизация изображений для повышения скорости загрузки","Поддержка платформ как macOS для сжатия изображений"],"ar":["فحص الصور بأحجام أكبر من 100KB","دعم صيغ الصور مثل avif و webp و png و jpg للوكلاء الذكاء الاصطناعي","استخدام أوامر مثل find و sips لضغط الصور","تحسين الصور لتحسين سرعة التحميل","دعم منصات مثل macOS لضغط الصور"]},"keywords":{"en":["how to use image-compress","image-compress setup guide","image compression techniques","avif vs webp image format","optimizing README images","image-compress alternative tools","installing image-compress","image-compress best practices","compressing images with sips"],"zh":["image-compress","图片压缩","网页加载速度","avif","webp","png","jpg","macOS","sips","AI工具"],"ja":["image-compress","画像圧縮","Webページの読み込み時間","avif","webp","png","jpg","macOS","sips","AIツール"],"ko":["image-compress","이미지 압축","웹 페이지 로딩 속도","avif","webp","png","jpg","macOS","sips","AI 도구"],"es":["image-compress","optimización de imágenes","compresión de imágenes","reducción de tamaño de imágenes","herramientas de optimización de sitios web","mejora de la velocidad de carga de sitios web"],"fr":["image-compress","optimisation d''images","compression d''images","réduction de taille d''images","outils d''optimisation de sites web","amélioration de la vitesse de chargement de sites web"],"de":["image-compress","Bildoptimierung","Bildkomprimierung","Größenreduzierung von Bildern","Tools zur Optimierung von Websites","Verbesserung der Ladezeit von Websites"],"pt":["image-compress","otimização de imagens","redução de tamanhos de arquivos","velocidade de carga","ferramentas de desenvolvimento","macOS","avif","webp","png","jpg"],"ru":["image-compress","сжатие изображений","уменьшение размера файлов","скорость загрузки","инструменты для разработки","ИИ Агенты","macOS","avif","webp","png","jpg"],"ar":["image-compress","ضغط الصور","تقليل حجم الملفات","سرعة التحميل","أدوات التطوير","الوكلاء الذكاء الاصطناعي","macOS","avif","webp","png","jpg"]}},"owner":"congwa","repo":"embedease-ai","repoPath":"congwa/embedease-ai","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.520Z","topics":[],"category":"community","skillMd":{"name":"image-compress","description":"图片压缩检查规则。当添加或修改 README 引用的图片时自动触发。检查图片是否超过 100KB，超出则压缩。推荐使用 avif/webp 格式。触发场景：添加新图片到仓库、更新 README 中的截图、发版前检查。","bodyPreview":"# Image Compress\n\nREADME 引用的图片不得超过 **100KB**。\n\n## 检查规则\n\n1. 扫描 README.md 中所有 `![](path)` 引用的图片文件\n2. 检查每个文件大小，超过 100KB 的必须压缩\n3. 推荐格式优先级：**avif > webp > png > jpg**\n\n## 检查命令\n\n```bash\n# 查找 docs/ 和 images/ 下超过 100KB 的图片\nfind docs/ images/ -type f \\( -name \"*.png\" -o -name \"*.jpg\" -o -name \"*.jpeg\" -o -name \"*.webp\" -o -name \"*.avif\" -o -name \"*.gif\" \\) -size +100k\n```\n\n## 压缩方式\n\n### macOS 内置 sips（png/jpg）\n\n```bash\n# 缩小尺寸（保持宽度 1200px 以内）\nsips --resampleWidth 1200 image.png\n\n# 转为 jpg 并降低质量\nsips -s forma","body":"# Image Compress\n\nREADME 引用的图片不得超过 **100KB**。\n\n## 检查规则\n\n1. 扫描 README.md 中所有 `![](path)` 引用的图片文件\n2. 检查每个文件大小，超过 100KB 的必须压缩\n3. 推荐格式优先级：**avif > webp > png > jpg**\n\n## 检查命令\n\n```bash\n# 查找 docs/ 和 images/ 下超过 100KB 的图片\nfind docs/ images/ -type f \\( -name \"*.png\" -o -name \"*.jpg\" -o -name \"*.jpeg\" -o -name \"*.webp\" -o -name \"*.avif\" -o -name \"*.gif\" \\) -size +100k\n```\n\n## 压缩方式\n\n### macOS 内置 sips（png/jpg）\n\n```bash\n# 缩小尺寸（保持宽度 1200px 以内）\nsips --resampleWidth 1200 image.png\n\n# 转为 jpg 并降低质量\nsips -s format jpeg -s formatOptions 80 image.png --out image.jpg\n```\n\n### ffmpeg（推荐，支持 avif/webp）\n\n```bash\n# png → avif（推荐，体积最小）\nffmpeg -i input.png -c:v libaom-av1 -crf 30 -still-picture 1 output.avif\n\n# png → webp\nffmpeg -i input.png -quality 80 output.webp\n\n# 批量转换\nfor f in docs/screenshots/*.png; do\n  ffmpeg -i \"$f\" -c:v libaom-av1 -crf 30 -still-picture 1 \"${f%.png}.avif\"\ndone\n```\n\n### 使用 scripts/check_compress.sh\n\n```bash\nbash .windsurf/skills/image-compress/scripts/check_compress.sh\n```\n\n## 压缩后\n\n1. 更新 README.md 中的图片路径（扩展名可能变化）\n2. 删除旧的大图片文件\n3. 确认所有图片 < 100KB\n"},"lastSynced":"2026-03-08T02:10:42.919Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing optimized image compression for web applications.","zh":"非常适合需要为 Web 应用程序优化图像压缩的开发代理。","ja":"Web アプリケーション向けの最適化された画像圧縮が必要な開発エージェントに最適です。","ko":"웹 애플리케이션을 위한 최적화된 이미지 압축이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan compresión de imagen optimizada para aplicaciones web.","fr":"Parfait pour les agents de développement ayant besoin d''une compression d''image optimisée pour les applications web.","de":"Perfekt für Entwicklungssagenten, die eine optimierte Bildkomprimierung für Webanwendungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de compressão de imagem otimizada para aplicações web.","ru":"Идеально подходит для агентов разработки, которым необходима оптимизированная сжатие изображений для веб-приложений.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى ضغط صورة محسّن لتقديم التطبيقات على الويب."},"recommendation":{"en":"Empowers agents to compress images to under 100KB, utilizing formats like avif, webp, and png for better compression, ensuring faster webpage loading times and improved user experience.","zh":"赋予代理压缩图像到 100KB 以下的能力，利用如 avif、webp 和 png 等格式实现更好的压缩，从而确保网页加载速度更快、用户体验更好。","ja":"エージェントに、avif、webp、png などのフォーマットを使用して 100KB 未満に画像を圧縮する能力を提供し、Web ページの読み込み時間を短縮し、ユーザー エクスペリエンスを向上させます。","ko":"에이전트에게 avif, webp, png 등의 형식을 사용하여 100KB 이하로 이미지 압축할 수 있는 능력을 부여하여 웹 페이지 로딩 속도를 빠르게 하고 사용자 경험을 개선합니다.","es":"Habilita a los agentes a comprimir imágenes a menos de 100KB, utilizando formatos como avif, webp y png para una mejor compresión, lo que garantiza tiempos de carga de página web más rápidos y una mejor experiencia del usuario.","fr":"Permet aux agents de compresser les images à moins de 100 Ko, en utilisant des formats tels que avif, webp et png pour une meilleure compression, garantissant ainsi des temps de chargement de page web plus rapides et une expérience utilisateur améliorée.","de":"Ermächtigt die Agenten, Bilder auf weniger als 100KB zu komprimieren, wobei Formate wie avif, webp und png für eine bessere Komprimierung verwendet werden, was zu schnelleren Ladezeiten von Webseiten und einer verbesserten Benutzererfahrung führt.","pt":"Habilita os agentes a comprimir imagens para menos de 100KB, utilizando formatos como avif, webp e png para uma melhor compressão, garantindo tempos de carregamento de página mais rápidos e uma experiência do usuário aprimorada.","ru":"Наделяет агентов возможностью сжимать изображения до менее 100КБ, используя форматы seperti avif, webp и png для лучшей сжатия, обеспечивая более быструю загрузку страниц и улучшенный пользовательский опыт.","ar":"يمنح الوكلاء القدرة على ضغط الصور إلى أقل من 100 كيلو بايت، باستخدام تنسيقات مثل avif و webp و png للحصول على ضغط أفضل، مما يضمن أوقات تحميل صفحة أسرع وتجربة مستخدم محسّنة."},"useCases":{"en":["Compressing images in README files for GitHub repositories","Converting images to optimized formats like avif and webp","Automating image size checks and compression for web development projects"],"zh":["压缩 GitHub 存储库的 README 文件中的图像","将图像转换为 avif 和 webp 等优化格式","自动执行 Web 开发项目的图像大小检查和压缩"],"ja":["GitHub リポジトリの README ファイル内の画像を圧縮する","avif や webp などの最適化された形式に画像を変換する","Web 開発プロジェクトの画像サイズのチェックと圧縮を自動化する"],"ko":["GitHub 저장소의 README 파일 내 이미지 압축","avif 및 webp 등의 최적화된 형식으로 이미지 변환","웹 개발 프로젝트의 이미지 크기 확인 및 압축 자동화"],"es":["Comprimir imágenes en archivos README para repositorios de GitHub","Convertir imágenes a formatos optimizados como avif y webp","Automatizar comprobaciones de tamaño de imagen y compresión para proyectos de desarrollo web"],"fr":["Compresser les images dans les fichiers README pour les référentiels GitHub","Convertir les images en formats optimisés tels que avif et webp","Automatiser les vérifications de taille d''image et la compression pour les projets de développement web"],"de":["Bilder in README-Dateien für GitHub-Repositorys komprimieren","Bilder in optimierte Formate wie avif und webp konvertieren","Bildgrößenprüfungen und -komprimierung für Webentwicklungsprojekte automatisieren"],"pt":["Comprimir imagens em arquivos README para repositórios GitHub","Converter imagens para formatos otimizados como avif e webp","Automatizar verificações de tamanho de imagem e compressão para projetos de desenvolvimento web"],"ru":["Сжатие изображений в файлах README для репозиториев GitHub","Преобразование изображений в оптимизированные форматы, такие как avif и webp","Автоматизация проверок размера изображения и сжатия для проектов веб-разработки"],"ar":["ضغط الصور في ملفات README لمخازن GitHub","تحويل الصور إلى تنسيقات محسنة مثل avif و webp","تأتميم فحص حجم الصورة والضغط لل مشاريع تطوير الويب"]},"limitations":{"en":["Limited to compressing images under 100KB","Requires access to image files in the file system","macOS specific commands for image compression using sips"],"zh":["仅限压缩 100KB 以下的图像","需要访问文件系统中的图像文件","使用 sips 的 macOS 特定命令进行图像压缩"],"ja":["100KB 未満の画像のみを圧縮する","ファイル システム内の画像ファイルへのアクセスが必要","sips を使用した macOS 特有の画像圧縮コマンド"],"ko":["100KB 이하의 이미지만 압축","파일 시스템 내 이미지 파일에 접근해야 함","sips를 사용한 macOS 전용 이미지 압축 명령어"],"es":["Limitado a la compresión de imágenes de menos de 100KB","Requiere acceso a archivos de imagen en el sistema de archivos","Comandos específicos de macOS para la compresión de imágenes utilizando sips"],"fr":["Limité à la compression d''images de moins de 100 Ko","Nécessite un accès aux fichiers image dans le système de fichiers","Commandes spécifiques à macOS pour la compression d''images en utilisant sips"],"de":["Begrenzt auf die Komprimierung von Bildern unter 100KB","Benötigt Zugriff auf Bilddateien im Dateisystem","macOS-spezifische Befehle zur Bildkomprimierung mit sips"],"pt":["Limitado à compressão de imagens com menos de 100KB","Requer acesso a arquivos de imagem no sistema de arquivos","Comandos específicos do macOS para compressão de imagem usando sips"],"ru":["Ограничен сжатием изображений менее 100КБ","Требует доступа к файлам изображений в файловой системе","Специфические команды macOS для сжатия изображений с помощью sips"],"ar":["محدود بضغط الصور بأقل من 100 كيلو بايت","يتطلب الوصول إلى ملفات الصور في نظام الملفات","أوامر محددة ل macos لضغط الصور باستخدام sips"]},"version":4},"contentHash":"a82a3ca886de046173759b2652884690cc4c48a7ba2b7eab38c2aa7376cddef1","qualityScore":36}');
