INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('congwa/embedease-ai/image-compress', 'image-compress', 'congwa', 'embedease-ai', 'community', 'image-compress congwa embedease-ai community The image-compress skill optimizes images in README files, ensuring they are under 100KB, and recommends formats like avif, webp, and png for better compression image-compress是一款优化图片压缩的工具，帮助开发者减少图片大小，提高网页加载速度。它支持多种图片格式，包括avif、webp、png、jpg等。 image-compressは画像圧縮を最適化するツールで、開発者が画像のサイズを削減し、Webページの読み込み時間を短縮するのに役立ちます。avif、webp、png、jpgなどの複数の画像形式をサポートしています。 image-compress는 이미지 압축을 최적화하는 도구로 개발자가 이미지 크기를 줄이고 웹 페이지 로딩 속도를 향상시킬 수 있도록 도와줍니다. avif, webp, png, jpg等 여러 이미지 형식을 지원합니다. Image-compress es una herramienta para optimizar imágenes, que comprime archivos de imagen para mejorar la velocidad de carga de sitios web Image-compress est un outil pour optimiser les images, qui comprime les fichiers d''image pour améliorer la vitesse de chargement des sites web Image-compress ist ein Tool zur Bildoptimierung, das Bilddateien komprimiert, um die Ladezeit von Websites zu verbessern O image-compress é uma ferramenta que ajuda a otimizar imagens, reduzindo tamanhos de arquivos e melhorando a velocidade de carga image-compress - это инструмент, который помогает оптимизировать изображения, уменьшая размер файлов и повышая скорость загрузки для ИИ Агентов image-compress هو أداة تساعد في ضغط الصور، لتقليل حجم الملفات وتحسين سرعة التحميل للوكلاء الذكاء الاصطناعي how to use image-compress image-compress setup guide image compression techniques avif vs webp image format optimizing README images image-compress alternative tools installing image-compress image-compress best practices compressing images with sips image-compress 图片压缩 网页加载速度 avif webp png jpg macOS sips AI工具 Scans README.md files for images exceeding 100KB Supports compression using macOS''s built-in sips tool Prioritizes image formats like avif, webp, png, and jpg for optimal compression Uses the find command to identify large images in docs/ and images/ directories Compresses images to reduce size while maintaining quality image-compress is a skill that automatically optimizes images in README files to reduce their size, prioritizing formats like avif and webp for better compression');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HNULS-LabHub/HNULS-KnowledgeDatabase/SurrealDB 深度研判与实战指南', 'community', 'HNULS-LabHub', 'HNULS-KnowledgeDatabase', 'HNULS-LabHub/HNULS-KnowledgeDatabase', 'SurrealDB 深度研判与实战指南', 0, 0, 36, '2026-03-08T01:57:15.543Z', '2026-03-08T02:11:18.277Z', '2afa61f5b032f5265397c0ea8578f2f7e103954eb52b2bbcb857ebfd15d93bd1', '{"id":"HNULS-LabHub/HNULS-KnowledgeDatabase/SurrealDB 深度研判与实战指南","name":"SurrealDB 深度研判与实战指南","description":{"en":"SurrealDB 深度研判与实战指南 provides expert guidance for AI agents, offering professional and responsible advice on SurrealDB-related topics. It helps users understand and optimize their SurrealQL queries and schema designs.","zh":"SurrealDB 深度研判与实战指南提供专业的设置和最佳实践，帮助开发者优化数据库性能","ja":"SurrealDB 深度分析と実戦ガイドは、AIエージェントによる設定とベストプラクティスを提供し、開発者がデータベースのパフォーマンスを最適化できるようにする","ko":"SurrealDB 심층 분석 및 실전 가이드는 전문가가 제공하는 설정 및 최적화 방법을 제공하여 개발자가 데이터베이스 성능을 최적화할 수 있도록 합니다","es":"SurrealDB es una base de datos que requiere una configuración y un uso precisos. Nuestra guía ofrece consejos y mejores prácticas para desarrolladores","fr":"SurrealDB est une base de données qui nécessite une configuration et une utilisation précises. Notre guide propose des conseils et des meilleures pratiques pour les développeurs","de":"SurrealDB ist eine Datenbank, die eine präzise Konfiguration und Verwendung erfordert. Unser Leitfaden bietet Tipps und beste Praktiken für Entwickler","pt":"O SurrealDB é uma ferramenta poderosa para desenvolvedores. Nossa guia oferece dicas e melhores práticas para configurar e otimizar o SurrealDB.","ru":"SurrealDB - это мощный инструмент для разработчиков. Наше руководство предлагает советы и лучшие практики для настройки и оптимизации SurrealDB для ИИ Агентов","ar":"SurrealDB هو أداة قوية لمنشئي الأدوات الذكية. دليلنا يقدم نصائح وأفضل الممارسات لتحسين وتشغيل SurrealDB"},"seo":{"title":{"en":"SurrealDB 深度研判与实战指南: Expert Guidance for AI Agents | AI A...","zh":"SurrealDB 深度研判与实战指南 - 专业设置和最佳实践","ja":"SurrealDB 深度研判与実戦ガイド - AIエージェントによる設定とベストプラクティス","ko":"SurrealDB 심층 분석 및 실전 가이드 - 전문가가 제공하는 설정 및 최적화","es":"Guía de configuración de SurrealDB para desarrolladores","fr":"Guide de mise en route de SurrealDB pour les développeurs","de":"Einrichtungsleitfaden für SurrealDB-Entwickler","pt":"Guia de Configuração SurrealDB - Melhores Práticas para D...","ru":"Руководство SurrealDB - Лучшие практики для разработчиков...","ar":"دليل إعداد SurrealDB - أفضل الممارسات لمنشئي الأدوات الذكية"},"description":{"en":"Unlock the full potential of SurrealDB with expert guidance and practical tips. Learn how to optimize your SurrealQL queries and schema designs with our in-d...","zh":"了解SurrealDB的专业设置和最佳实践，通过深度研判和实战指南，优化您的数据库性能","ja":"SurrealDBの設定とベストプラクティスを学び、AIエージェントによる深度分析と実戦ガイドでデータベースのパフォーマンスを最適化する","ko":"SurrealDB의 전문가가 제공하는 설정 및 최적화 방법을 알아보세요. 심층 분석 및 실전 가이드로 데이터베이스 성능을 최적화합니다","es":"Aprende a dominar SurrealDB con nuestra guía de mejores prácticas y consejos para desarrolladores","fr":"Maîtrisez SurrealDB avec notre guide de meilleures pratiques et de conseils pour les développeurs","de":"Meistern Sie SurrealDB mit unserem Leitfaden für beste Praktiken und Tipps für Entwickler","pt":"Aprenda a configurar e otimizar o SurrealDB com nossa guia de melhores práticas para desenvolvedores, incluindo dicas para escrever SurrealQL eficaz","ru":"Узнайте, как настроить и оптимизировать SurrealDB с нашей помощью, включая советы по написанию эффективного SurrealQL для ИИ Агентов","ar":"تعلم كيفية إعداد وتحسين SurrealDB باستخدام دليل أفضل الممارسات لدينا، بما في ذلك نصائح لكتابة SurrealQL فعال"},"definition":{"en":"SurrealDB 深度研判与实战指南 is a comprehensive guide for SurrealDB experts and users, providing professional advice and practical tips on SurrealDB-related topics.","zh":"SurrealDB 深度研判与实战指南是一种专业的数据库设置和优化指南","ja":"SurrealDB 深度分析と実戦ガイドは、AIエージェントによるデータベースの設定と最適化方法を提供するツールです","ko":"SurrealDB 심층 분석 및 실전 가이드는 데이터베이스의 설정과 최적화를 위한 전문가 가이드입니다","es":"SurrealDB es una base de datos que ofrece una guía de configuración y uso para desarrolladores","fr":"SurrealDB est une base de données qui propose un guide de configuration et d''utilisation pour les développeurs","de":"SurrealDB ist eine Datenbank, die einen Konfigurations- und Bedienungsleitfaden für Entwickler bietet","pt":"O SurrealDB é uma ferramenta de banco de dados que permite aos desenvolvedores criar aplicações escaláveis e eficientes","ru":"SurrealDB - это инструмент базы данных, который позволяет разработчикам создавать масштабируемые и эффективные приложения для ИИ Агентов","ar":"SurrealDB هو أداة قاعدة بيانات تمكن منشئي الأدوات الذكية من إنشاء تطبيقات قابلة للتوسيع والفعالة"},"features":{"en":["Provides professional auditing and guidance on SurrealQL queries and schema designs","Utilizes mcp_deepwiki_ask_question for deepwiki queries and confirmation","Offers expert advice on optimizing SurrealQL syntax and data model design","Includes core behavior guidelines for user interaction and query optimization","Supports users in understanding and correcting errors in their SurrealQL queries and schema designs"],"zh":["专业的SurrealDB设置和最佳实践","深度分析和实战指南","优化数据库性能","使用mcp_deepwiki_ask_question查询确认","专业审视SurrealQL语法和数据模型设计"],"ja":["AIエージェントによるSurrealDBの設定とベストプラクティス","深度分析と実戦ガイド","データベースのパフォーマンスを最適化","mcp_deepwiki_ask_questionを使用した検証","SurrealQLの文法とデータモデル設計のプロフェッショナルなレビュー"],"ko":["전문가가 제공하는 SurrealDB 설정 및 최적화","심층 분석 및 실전 가이드","데이터베이스 성능을 최적화","mcp_deepwiki_ask_question를 사용한 확인","SurrealQL의 문법과 데이터 모델 설계의 전문가 리뷰"],"es":["Análisis de requisitos de los usuarios de SurrealDB","Revisión profesional de la sintaxis SurrealQL","Diseño de esquemas de datos precisos","Uso de la función mcp_deepwiki_ask_question para confirmar la información","Corrección de errores y sugerencias de mejores prácticas"],"fr":["Analyse des besoins des utilisateurs de SurrealDB","Révision professionnelle de la syntaxe SurrealQL","Conception de schémas de données précis","Utilisation de la fonction mcp_deepwiki_ask_question pour confirmer les informations","Correction des erreurs et suggestions de meilleures pratiques"],"de":["Analyse der Anforderungen der SurrealDB-Benutzer","Professionelle Überprüfung der SurrealQL-Syntax","Präzise Datenbankschema-Design","Verwendung der Funktion mcp_deepwiki_ask_question zur Bestätigung von Informationen","Fehlerkorrektur und Vorschläge für beste Praktiken"],"pt":["Suporte a SurrealQL para consultas eficazes","Análise de esquemas de dados para otimização","Integração com mcp_deepwiki_ask_question para respostas precisas","Auditoria de código para prevenir erros","Otimização de desempenho para aplicações escaláveis"],"ru":["Поддержка SurrealQL для эффективных запросов","Анализ схем данных для оптимизации","Интеграция с mcp_deepwiki_ask_question для точных ответов","Аудит кода для предотвращения ошибок","Оптимизация производительности для масштабируемых приложений"],"ar":["دعم SurrealQL للاستفسارات الفعالة","تحليل مخططات البيانات لتحسين الأداء","التكامل مع mcp_deepwiki_ask_question للاجابات الدقيقة","مراجعة الشفرة لمنع الأخطاء","تحسين الأداء لتطبيقات قابلة للتوسيع"]},"keywords":{"en":["SurrealDB 深度研判与实战指南 setup guide","how to use SurrealDB 深度研判与实战指南","SurrealDB 深度研判与实战指南 vs other databases","SurrealDB 深度研判与实战指南 expert guidance","SurrealDB 深度研判与实战指南 optimization tips","what is SurrealDB 深度研判与实战指南"],"zh":["SurrealDB","数据库设置","最佳实践","深度分析","实战指南","mcp_deepwiki_ask_question","SurrealQL","数据模型设计"],"ja":["SurrealDB","データベースの設定","ベストプラクティス","深度分析","実戦ガイド","mcp_deepwiki_ask_question","SurrealQL","データモデル設計","AIエージェント"],"ko":["SurrealDB","데이터베이스 설정","최적화","심층 분석","실전 가이드","mcp_deepwiki_ask_question","SurrealQL","데이터 모델 설계","AI 에이전트"],"es":["SurrealDB","desarrollo de bases de datos","configuración de SurrealDB","mejores prácticas de SurrealDB","SurrealQL","diseño de esquemas de datos","mcp_deepwiki_ask_question","desarrollo de aplicaciones con SurrealDB"],"fr":["SurrealDB","développement de bases de données","configuration de SurrealDB","meilleures pratiques de SurrealDB","SurrealQL","conception de schémas de données","mcp_deepwiki_ask_question","développement d''applications avec SurrealDB"],"de":["SurrealDB","Datenbankentwicklung","SurrealDB-Konfiguration","beste Praktiken für SurrealDB","SurrealQL","Datenbankschema-Design","mcp_deepwiki_ask_question","Entwicklung von Anwendungen mit SurrealDB"],"pt":["SurrealDB","SurrealQL","desenvolvimento de aplicações","otimização de banco de dados","melhores práticas para desenvolvedores","configuração SurrealDB","consultas eficazes","análise de esquemas de dados"],"ru":["SurrealDB","SurrealQL","разработка приложений","оптимизация базы данных","лучшие практики для разработчиков","настройка SurrealDB","эффективные запросы","анализ схем данных"],"ar":["SurrealDB","SurrealQL","تنمية التطبيقات","تحسين قاعدة البيانات","أفضل الممارسات لمنشئي الأدوات الذكية","إعداد SurrealDB","استفسارات فعالة","تحليل مخططات البيانات"]}},"owner":"HNULS-LabHub","repo":"HNULS-KnowledgeDatabase","repoPath":"HNULS-LabHub/HNULS-KnowledgeDatabase","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.543Z","topics":[],"category":"community","skillMd":{"name":"SurrealDB 深度研判与实战指南","description":"当涉及以下场景时激活此技能：(1) 编写、审查、调试任何 SurrealQL 查询或 Schema 定义；(2) 讨论数据存储方案并使用 SurrealDB 时的状态机设计、数据流转、Schema 规划；(3) 操作本项目的 QueryService、surrealdb-query.ts、跨库查询、IPC 数据库调用；(4) 用户提到 Record ID、RELATE、图遍历、DEFINE EVENT/FIELD/TABLE、事务、MERGE/CONTENT/PATCH 等 SurrealDB 关键词；(5) 规划业务模型需要落地到 SurrealDB 的表结构、索引、权限设计。","bodyPreview":"# SurrealDB 深度研判与实战指南 — 概要入口\n\n## 你是谁\n\n你是 SurrealDB 领域的专家顾问。当用户涉及 SurrealDB 相关话题时，你必须以专业、严谨、负责的态度提供指导。\n\n## 核心行为准则（必须遵守）\n\n### 1. 主动质疑用户 — 不被带偏\n\n用户不是 SurrealDB 专家，也不是计算机科班出身。用户描述的需求、给出的 SurrealQL 写法、提出的 Schema 设计，**大概率存在错误或不精确之处**。\n\n你必须：\n- 先理解用户的**真实意图**（而非字面表述）\n- 对用户给出的 SurrealQL 语法、数据模型设计进行**专业审视**\n- 发现问题时**明确指出**并给出正确方案，而不是顺着用户的错误往下走\n- 用通俗语言解释为什么用户的方案有问题，以及正确做法的好处\n\n### 2. 强制查询 deepwiki — 禁止猜测\n\n本 skill 的内容是有限的。遇到以下情况，**必须**使用 `mcp_deepwiki_ask_question`（repo: `surrealdb/surrealdb`）查询确认：\n\n- 不确定某个","body":"# SurrealDB 深度研判与实战指南 — 概要入口\n\n## 你是谁\n\n你是 SurrealDB 领域的专家顾问。当用户涉及 SurrealDB 相关话题时，你必须以专业、严谨、负责的态度提供指导。\n\n## 核心行为准则（必须遵守）\n\n### 1. 主动质疑用户 — 不被带偏\n\n用户不是 SurrealDB 专家，也不是计算机科班出身。用户描述的需求、给出的 SurrealQL 写法、提出的 Schema 设计，**大概率存在错误或不精确之处**。\n\n你必须：\n- 先理解用户的**真实意图**（而非字面表述）\n- 对用户给出的 SurrealQL 语法、数据模型设计进行**专业审视**\n- 发现问题时**明确指出**并给出正确方案，而不是顺着用户的错误往下走\n- 用通俗语言解释为什么用户的方案有问题，以及正确做法的好处\n\n### 2. 强制查询 deepwiki — 禁止猜测\n\n本 skill 的内容是有限的。遇到以下情况，**必须**使用 `mcp_deepwiki_ask_question`（repo: `surrealdb/surrealdb`）查询确认：\n\n- 不确定某个 SurrealQL 语法是否存在或其确切行为\n- 不确定某个函数（如 `time::now()`、`array::distinct()`）的参数和返回值\n- 用户提出的用法你没有在 skill 模块中找到明确说明\n- 涉及 SurrealDB 版本差异、新特性、废弃特性\n- 涉及性能特性、索引行为、存储引擎细节\n\n**禁止**：\n- \"我觉得应该是...\"、\"大概是...\"、\"按照 SQL 的经验...\"\n- 用 SQL 思维推测 SurrealQL 行为（它们有本质差异）\n- 假定用户了解 SurrealQL 和 SQL 的区别\n\n### 3. 精准捕获需求 — 反思用户设计\n\n用户可能：\n- 用错术语（把\"关联\"说成\"JOIN\"，把\"边\"说成\"关系表\"）\n- 用 SQL 思维描述需求（想用 JOIN 但其实应该用图遍历）\n- 过度设计或设计不足\n- 不了解 SurrealDB 的独特能力（图模型、DEFINE EVENT、COMPUTED 字段等）\n\n你必须：\n- 翻译用户的意图为 SurrealDB 最佳实践\n- 主动建议更适合 SurrealDB 范式的方案\n- 解释 SurrealDB 特有能力如何简化用户的需求\n\n### 4. SurrealQL ≠ SQL — 范式转移\n\n每次写 SurrealQL 之前，提醒自己：\n- Record ID 是 `table:key` 格式的指针，不是自增整数\n- 关联数据用 `->` 图遍历，不是 JOIN\n- `NONE` ≠ `NULL`，行为完全不同\n- `MERGE` 不等于 `UPDATE SET`，数组会被整体替换\n- 事务用 `CANCEL` 不是 `ROLLBACK`\n- `CONTENT` 会**覆盖整个文档**，不是部分更新\n\n---\n\n## 模块索引\n\n本 skill 由以下子模块组成，根据场景按需阅读：\n\n| 模块文件 | 内容 | 何时阅读 |\n|----------|------|----------|\n| `modules/surrealql-syntax.md` | Record ID、类型系统、参数化查询、Cast 语法 | 编写任何 SurrealQL 查询时 |\n| `modules/data-operations.md` | SET/MERGE/CONTENT/PATCH 差异、+=/-= 陷阱、NONE vs NULL | 做数据创建/更新操作时 |\n| `modules/schema-and-statemachine.md` | DEFINE FIELD/EVENT/ASSERT、COMPUTED、FSM 设计 | 设计 Schema 或状态流转时 |\n| `modules/transaction-and-errors.md` | BEGIN/COMMIT/CANCEL、THROW、错误类型 | 涉及事务或错误处理时 |\n| `modules/graph-and-relations.md` | RELATE、箭头遍历、边属性、FETCH 策略 | 涉及关联数据或图查询时 |\n| `modules/architecture-integration.md` | Sidecar vs WASM、WebSocket、连接生命周期、Live Query | 讨论架构或连接管理时 |\n| `modules/project-conventions.md` | 单例注入、QueryService、并发安全、日志规范 | 编写本项目后端代码时 |\n\n**使用方式**：根据当前对话场景，读取对应模块获取详细指导。多个场景重叠时读取多个模块。\n\n---\n\n## 兜底规则\n\n当模块内容不足以回答用户问题时，**必须**执行以下操作：\n\n```\nmcp_deepwiki_ask_question(\n  repoName: \"surrealdb/surrealdb\",\n  question: \"<你的具体问题>\"\n)\n```\n\n查询后将结果整合到回答中，并标注信息来源。绝不凭记忆或推测回答 SurrealDB 相关的技术细节。\n"},"lastSynced":"2026-03-08T02:11:18.277Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing expert guidance on SurrealDB-related topics, such as optimizing SurrealQL queries and schema designs.","zh":"非常适合需要专家指导的 AI Agent，以便优化 SurrealQL 查询和 schema 设计等 SurrealDB 相关主题。","ja":"SurrealDB 関連のトピック、たとえば SurrealQL クエリとスキーマ設計の最適化についての専門家の指導が必要な AI エージェントに最適です。","ko":"SurrealQL 쿼리 및 스키마 디자인 최적화 등 SurrealDB 관련 주제에 대한 전문가 지침이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA que necesitan orientación experta sobre temas relacionados con SurrealDB, como la optimización de consultas SurrealQL y diseños de esquema.","fr":"Parfait pour les agents IA qui ont besoin de conseils d''experts sur les sujets liés à SurrealDB, tels que l''optimisation des requêtes SurrealQL et les conceptions de schéma.","de":"Perfekt für KI-Agents, die Expertenratgeber zu SurrealDB-bezogenen Themen benötigen, wie z. B. die Optimierung von SurrealQL-Abfragen und Schemadesigns.","pt":"Perfeito para agentes de IA que precisam de orientação especializada em tópicos relacionados ao SurrealDB, como otimização de consultas SurrealQL e designs de esquema.","ru":"Идеально подходит для агентов ИИ, которым требуется экспертное руководство по темам, связанным с SurrealDB, таким как оптимизация запросов SurrealQL и проектирование схем.","ar":"مثالي لعميل الذكاء الاصطناعي الذين يحتاجون إلى إرشادات خبيرة في مواضيع متعلقة بـ SurrealDB، مثل تحسين استفسارات SurrealQL وتصاميم مخططات البيانات."},"recommendation":{"en":"Empowers agents to provide professional and responsible advice on SurrealDB, utilizing deepwiki queries to ensure accuracy and validity, while leveraging SurrealQL and schema design expertise to optimize user queries.","zh":"赋予代理提供专业和负责的建议关于 SurrealDB，利用 deepwiki 查询以确保准确性和有效性，同时利用 SurrealQL 和 schema 设计专业知识以优化用户查询。","ja":"SurrealDB に関する専門家のアドバイスを提供するためにエージェントをエンパワーメントし、deepwiki クエリを使用して正確性と有効性を確保し、SurrealQL とスキーマ設計の専門知識を活用してユーザーのクエリを最適化します。","ko":"에이전트가 SurrealDB에 대한 전문가의 조언을 제공할 수 있도록 권장하며, deepwiki 쿼리를 사용하여 정확성과 유효성을 보장하고, SurrealQL 및 스키마 설계 전문 지식을 활용하여 사용자 쿼리를 최적화합니다.","es":"Habilita a los agentes a brindar asesoramiento profesional y responsable sobre SurrealDB, utilizando consultas deepwiki para garantizar la precisión y la validez, y aprovechando la experiencia en SurrealQL y diseño de esquema para optimizar las consultas de los usuarios.","fr":"Permet aux agents de fournir des conseils professionnels et responsables sur SurrealDB, en utilisant des requêtes deepwiki pour assurer l''exactitude et la validité, tout en exploitant l''expertise en SurrealQL et conception de schéma pour optimiser les requêtes des utilisateurs.","de":"Ermöglicht es den Agents, professionelle und verantwortungsvolle Beratung zu SurrealDB zu bieten, indem sie Deepwiki-Anfragen nutzen, um Genauigkeit und Gültigkeit sicherzustellen, und SurrealQL- und Schemadesign-Expertise nutzen, um Benutzeranfragen zu optimieren.","pt":"Habilita os agentes a fornecer conselhos profissionais e responsáveis sobre o SurrealDB, utilizando consultas deepwiki para garantir a precisão e a validade, enquanto aproveita a especialização em SurrealQL e design de esquema para otimizar as consultas dos usuários.","ru":"Наделяет агентов возможностью предоставлять профессиональные и ответственные советы по SurrealDB, используя запросы deepwiki для обеспечения точности и достоверности, а также используя экспертизу в области SurrealQL и проектирования схем для оптимизации запросов пользователей.","ar":"تمكّن الوكلاء من تقديم نصائح مهنية ومسؤولة حول SurrealDB، مستخدمين استفسارات deepwiki لضمان الدقة وسلامة البيانات، في حين استغلال الخبرة في SurrealQL وتصميم مخططات البيانات لتحسين استفسارات المستخدمين."},"useCases":{"en":["Debugging inefficient SurrealQL queries","Validating schema designs for optimal performance","Providing expert guidance on SurrealDB best practices"],"zh":["调试低效的 SurrealQL 查询","验证 schema 设计以获得最佳性能","提供 SurrealDB 最佳实践的专家指导"],"ja":["非効率的な SurrealQL クエリのデバッグ","最適なパフォーマンスのためのスキーマ設計の検証","SurrealDB ベストプラクティスの専門家の指導の提供"],"ko":["비효율적인 SurrealQL 쿼리의 디버깅","최적의 성능을 위한 스키마 디자인의 확인","SurrealDB 최선의 관행에 대한 전문가의 지침 제공"],"es":["Depuración de consultas SurrealQL ineficientes","Validación de diseños de esquema para un rendimiento óptimo","Brindar orientación experta sobre las mejores prácticas de SurrealDB"],"fr":["Débogage de requêtes SurrealQL inefficaces","Validation de conceptions de schéma pour une performance optimale","Fournir des conseils d''experts sur les meilleures pratiques de SurrealDB"],"de":["Debugging ineffizienter SurrealQL-Abfragen","Validierung von Schemadesigns für optimale Leistung","Bereitstellung von Expertenratgebern zu SurrealDB-Best-Practices"],"pt":["Depuração de consultas SurrealQL ineficientes","Validação de designs de esquema para desempenho ótimo","Fornecimento de orientação especializada em práticas recomendadas do SurrealDB"],"ru":["Отладка неэффективных запросов SurrealQL","Проверка проектов схем для оптимальной производительности","Предоставление экспертных рекомендаций по лучшим практикам SurrealDB"],"ar":["تصحيح استفسارات SurrealQL غير الفعالة","تحقق من تصميم مخططات البيانات من أجل الأداء الأمثل","تقديم إرشادات خبيرة في أفضل الممارسات ل SurrealDB"]},"limitations":{"en":["Requires access to deepwiki for confirmation on uncertain topics","Limited to SurrealDB-specific knowledge and expertise"],"zh":["需要访问 deepwiki 以确认不确定的主题","仅限 SurrealDB 特定的知识和专业知识"],"ja":["不確実なトピックの確認のために deepwiki へのアクセスが必要","SurrealDB に特有の知識と専門知識に限定される"],"ko":["불확실한 주제를 확인하기 위해 deepwiki에 액세스해야 함","SurrealDB에 특정한 지식과 전문 지식으로 제한됨"],"es":["Requiere acceso a deepwiki para confirmar temas inciertos","Limitado a conocimientos y experiencia específicos de SurrealDB"],"fr":["Nécessite un accès à deepwiki pour confirmer les sujets incertains","Limité à des connaissances et une expertise spécifiques à SurrealDB"],"de":["Benötigt Zugriff auf Deepwiki, um unsichere Themen zu bestätigen","Begrenzt auf SurrealDB-spezifisches Wissen und Expertise"],"pt":["Requer acesso ao deepwiki para confirmação em tópicos incertos","Limitado ao conhecimento e especialização específicos do SurrealDB"],"ru":["Требует доступа к deepwiki для подтверждения неопределенных тем","Ограничен знаниями и экспертизой, специфичными для SurrealDB"],"ar":["يتطلب الوصول إلى deepwiki للتأكيد على المواضيع غير المؤكدة","محدود بالمعرفة والخبرة المحدودة المتعلقة بـ SurrealDB"]},"version":4},"contentHash":"2afa61f5b032f5265397c0ea8578f2f7e103954eb52b2bbcb857ebfd15d93bd1","qualityScore":36}');
