INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HNULS-LabHub/HNULS-KnowledgeDatabase/SurrealDB 深度研判与实战指南', 'SurrealDB 深度研判与实战指南', 'HNULS-LabHub', 'HNULS-KnowledgeDatabase', 'community', 'SurrealDB 深度研判与实战指南 HNULS-LabHub HNULS-KnowledgeDatabase community SurrealDB 深度研判与实战指南 provides expert guidance for AI agents, offering professional and responsible advice on SurrealDB-related topics. It helps users understand and optimize their SurrealQL queries and schema designs. SurrealDB 深度研判与实战指南提供专业的设置和最佳实践，帮助开发者优化数据库性能 SurrealDB 深度分析と実戦ガイドは、AIエージェントによる設定とベストプラクティスを提供し、開発者がデータベースのパフォーマンスを最適化できるようにする SurrealDB 심층 분석 및 실전 가이드는 전문가가 제공하는 설정 및 최적화 방법을 제공하여 개발자가 데이터베이스 성능을 최적화할 수 있도록 합니다 SurrealDB es una base de datos que requiere una configuración y un uso precisos. Nuestra guía ofrece consejos y mejores prácticas para desarrolladores SurrealDB est une base de données qui nécessite une configuration et une utilisation précises. Notre guide propose des conseils et des meilleures pratiques pour les développeurs SurrealDB ist eine Datenbank, die eine präzise Konfiguration und Verwendung erfordert. Unser Leitfaden bietet Tipps und beste Praktiken für Entwickler O SurrealDB é uma ferramenta poderosa para desenvolvedores. Nossa guia oferece dicas e melhores práticas para configurar e otimizar o SurrealDB. SurrealDB - это мощный инструмент для разработчиков. Наше руководство предлагает советы и лучшие практики для настройки и оптимизации SurrealDB для ИИ Агентов SurrealDB هو أداة قوية لمنشئي الأدوات الذكية. دليلنا يقدم نصائح وأفضل الممارسات لتحسين وتشغيل SurrealDB SurrealDB 深度研判与实战指南 setup guide how to use SurrealDB 深度研判与实战指南 SurrealDB 深度研判与实战指南 vs other databases SurrealDB 深度研判与实战指南 expert guidance SurrealDB 深度研判与实战指南 optimization tips what is SurrealDB 深度研判与实战指南 SurrealDB 数据库设置 最佳实践 深度分析 实战指南 mcp_deepwiki_ask_question SurrealQL 数据模型设计 Provides professional auditing and guidance on SurrealQL queries and schema designs Utilizes mcp_deepwiki_ask_question for deepwiki queries and confirmation Offers expert advice on optimizing SurrealQL syntax and data model design Includes core behavior guidelines for user interaction and query optimization Supports users in understanding and correcting errors in their SurrealQL queries and schema designs SurrealDB 深度研判与实战指南 is a comprehensive guide for SurrealDB experts and users, providing professional advice and practical tips on SurrealDB-related topics.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EnzeD/r3f-skills/r3f-textures', 'community', 'EnzeD', 'r3f-skills', 'EnzeD/r3f-skills', 'r3f-textures', 0, 0, 36, '2026-03-08T01:57:15.550Z', '2026-03-08T02:11:26.076Z', 'd0bf95a2cc6e2752a0cb6c86fc7fc3cd602b859c1235b4b10e319c04e5c724fb', '{"id":"EnzeD/r3f-skills/r3f-textures","name":"r3f-textures","description":{"en":"r3f-textures is a skill for creating 3D textures with React Three Fiber. It benefits developers who want to add realistic textures to their 3D models.","zh":"r3f-textures 是一个用于 React Three Fiber 的纹理库，提供 useTexture Hook 和 meshStandardMaterial。","ja":"r3f-textures は、React Three Fiber 用のテクスチャライブラリで、useTexture Hook と meshStandardMaterial を提供します。","ko":"r3f-textures는 React Three Fiber용 텍스쳐 라이브러리로서 useTexture Hook과 meshStandardMaterial을 제공합니다.","es":"r3f-textures es una herramienta para agregar texturas a objetos 3D en React Three Fiber, utilizando el hook useTexture de Drei","fr":"r3f-textures est un outil pour ajouter des textures à des objets 3D dans React Three Fiber, en utilisant le hook useTexture de Drei","de":"r3f-Textures ist ein Werkzeug zum Hinzufügen von Texturen zu 3D-Objekten in React Three Fiber, unter Verwendung des useTexture-Hooks von Drei","pt":"O hook useTexture do Drei permite adicionar texturas a objetos 3D em React Three Fiber. Confira nosso exemplo de código!","ru":"Хук useTexture из Drei позволяет добавлять текстуры к 3D-объектам в React Three Fiber. Посмотрите наш пример кода!","ar":"يسمح hook useTexture من Drei بإضافة النسيج إلى كائنات 3D في React Three Fiber. انظر إلى مثال кодنا!"},"seo":{"title":{"en":"r3f-textures: React Three Fiber Textures Setup Guide | AI...","zh":"r3f-textures 设置指南：React Three Fiber 纹理教程","ja":"r3f-textures セットアップガイド：React Three Fiber テクスチャのベストプラクティス","ko":"r3f-textures 설정 가이드: React Three Fiber 텍스쳐 사용법","es":"Guía de configuración de r3f-textures para desarrolladores","fr":"Guide de démarrage rapide pour r3f-textures","de":"r3f-Textures Einrichtungsleitfaden für Entwickler","pt":"r3f-textures: Guia de Configuração de Texturas em React T...","ru":"r3f-textures: Руководство по настройке текстур в React Th...","ar":"r3f-textures: دليل إعداد النسيج في React Three Fiber باست..."},"description":{"en":"Unlock the power of React Three Fiber textures with our expert guide. Learn how to use the useTexture hook and create stunning 3D visuals. Get started now!","zh":"了解如何使用 r3f-textures 实现 React Three Fiber 纹理，包括 useTexture Hook 和 meshStandardMaterial。","ja":"r3f-textures を使用して React Three Fiber テクスチャを実装する方法を学びましょう。useTexture Hook と meshStandardMaterial を含みます。","ko":"r3f-textures를 사용하여 React Three Fiber 텍스쳐를 구현하는 방법을 알아보세요. useTexture Hook과 meshStandardMaterial을 포함합니다.","es":"Aprende a utilizar r3f-textures con React Three Fiber y el hook useTexture de Drei para agregar texturas a tus objetos 3D","fr":"Découvrez comment utiliser r3f-textures avec React Three Fiber et le hook useTexture de Drei pour ajouter des textures à vos objets 3D","de":"Erfahren Sie, wie Sie r3f-Textures mit React Three Fiber und dem useTexture-Hook von Drei verwenden, um Texturen zu Ihren 3D-Objekten hinzuzufügen","pt":"Aprenda a usar o hook useTexture do Drei para adicionar texturas a seus objetos 3D em React Three Fiber. Confira nosso guia passo a passo!","ru":"Узнайте, как использовать хук useTexture из Drei, чтобы добавить текстуры к вашим 3D-объектам в React Three Fiber. Читайте нашу пошаговую инструкцию с помощь...","ar":"تعلم كيفية استخدام hook useTexture من Drei لإضافة النسيج إلى كائنات 3D الخاصة بك في React Three Fiber. استكشف دليلنا خطوة بخطوة باستخدام أدوات الذكاء الاصطناعي!"},"definition":{"en":"r3f-textures is a React Three Fiber skill that enables developers to create and manage 3D textures using the useTexture hook from @react-three/drei","zh":"r3f-textures 是一个用于 React Three Fiber 的纹理库，用于实现 3D 物体的纹理渲染。","ja":"r3f-textures は、React Three Fiber 用のテクスチャライブラリで、3D オブジェクトのテクスチャレンダリングを実現します。","ko":"r3f-textures는 React Three Fiber용 텍스쳐 라이브러리로서 3D 객체의 텍스쳐 렌더링을 구현하는 데 사용됩니다.","es":"r3f-textures es una función que permite agregar texturas a objetos 3D en aplicaciones web","fr":"r3f-textures est une fonction qui permet d''ajouter des textures à des objets 3D dans des applications web","de":"r3f-Textures ist eine Funktion, die das Hinzufügen von Texturen zu 3D-Objekten in Webanwendungen ermöglicht","pt":"r3f-textures é um recurso de React Three Fiber que permite adicionar texturas a objetos 3D usando o hook useTexture do Drei","ru":"r3f-textures — это функция React Three Fiber, которая позволяет добавлять текстуры к 3D-объектам с помощью хука useTexture из Drei","ar":"r3f-textures هو ميزة من React Three Fiber التي تمكن من إضافة النسيج إلى كائنات 3D باستخدام hook useTexture من Drei"},"features":{"en":["Imports textures using the useTexture hook from @react-three/drei","Supports rendering 3D models with textures using meshStandardMaterial","Uses the Canvas component from @react-three/fiber for rendering","Enables creation of textured boxes using the boxGeometry component","Utilizes ambientLight for scene illumination","Leverages the @react-three/fiber and @react-three/drei libraries for 3D rendering"],"zh":["useTexture Hook","meshStandardMaterial","支持 React Three Fiber","实现 3D 物体的纹理渲染","提供简单易用的 API"],"ja":["useTexture Hook","meshStandardMaterial","React Three Fiber をサポート","3D オブジェクトのテクスチャレンダリングを実現","シンプルで使いやすい API を提供"],"ko":["useTexture Hook","meshStandardMaterial","React Three Fiber를 지원","3D 객체의 텍스쳐 렌더링을 구현","간단하고 사용하기 쉬운 API를 제공"],"es":["Uso del hook useTexture de Drei","Compatibilidad con React Three Fiber","Carga de texturas desde una URL","Aplicación de texturas a objetos 3D","Personalización de materiales y texturas"],"fr":["Utilisation du hook useTexture de Drei","Compatibilité avec React Three Fiber","Chargement de textures à partir d''une URL","Application de textures à des objets 3D","Personnalisation de matériaux et de textures"],"de":["Verwendung des useTexture-Hooks von Drei","Kompatibilität mit React Three Fiber","Laden von Texturen von einer URL","Anwendung von Texturen auf 3D-Objekte","Anpassung von Materialien und Texturen"],"pt":["Uso do hook useTexture do Drei para adicionar texturas","Suporte a objetos 3D em React Three Fiber","Integração com a biblioteca @react-three/fiber","Exemplo de código para texto de madeira","Compatibilidade com meshStandardMaterial","Suporte a ambientLight"],"ru":["Использование хука useTexture из Drei для добавления текстур","Поддержка 3D-объектов в React Three Fiber","Интеграция с библиотекой @react-three/fiber","Пример кода для текстуры дерева","Совместимость с meshStandardMaterial","Поддержка ambientLight"],"ar":["استخدام hook useTexture من Drei لإضافة النسيج","دعم كائنات 3D في React Three Fiber","التكامل مع المكتبة @react-three/fiber","مثال رمز للنسيج الخشبي","التوافق مع meshStandardMaterial","دعم ambientLight"]},"keywords":{"en":["how to use r3f-textures","r3f-textures setup guide","react three fiber textures","useTexture hook","3D texture rendering","r3f-textures vs react-three-fiber","r3f-textures install","react three fiber tutorial","3D modeling with r3f-textures"],"zh":["r3f-textures","React Three Fiber","纹理渲染","3D 渲染","useTexture Hook","meshStandardMaterial","AIエージェント","JavaScript 库"],"ja":["r3f-textures","React Three Fiber","テクスチャレンダリング","3D レンダリング","useTexture Hook","meshStandardMaterial","AIエージェント","JavaScript ライブラリ"],"ko":["r3f-textures","React Three Fiber","텍스쳐 렌더링","3D 렌더링","useTexture Hook","meshStandardMaterial","AI 툴","JavaScript 라이브러리"],"es":["r3f-textures","React Three Fiber","useTexture","Drei","texturas 3D","desarrollo web","aplicaciones web","herramientas de desarrollo"],"fr":["r3f-textures","React Three Fiber","useTexture","Drei","textures 3D","développement web","applications web","outils de développement"],"de":["r3f-Textures","React Three Fiber","useTexture","Drei","3D-Texturen","Webentwicklung","Webanwendungen","Entwicklungstools"],"pt":["r3f-textures","React Three Fiber","useTexture","Drei","texturas 3D","objetos 3D","meshStandardMaterial","ambientLight","desenvolvimento de jogos","realidade virtual"],"ru":["r3f-textures","React Three Fiber","useTexture","Drei","3D-текстуры","3D-объекты","meshStandardMaterial","ambientLight","разработка игр","виртуальная реальность","ИИ Агенты"],"ar":["r3f-textures","React Three Fiber","useTexture","Drei","نسيج 3D","كائنات 3D","meshStandardMaterial","ambientLight","تطوير الألعاب","الواقع الافتراضي","أدوات الذكاء الاصطناعي"]}},"owner":"EnzeD","repo":"r3f-skills","repoPath":"EnzeD/r3f-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.550Z","topics":[],"category":"community","skillMd":{"name":"r3f-textures","description":"React Three Fiber textures - useTexture, texture loading, environment maps, texture configuration. Use when loading images, working with PBR texture sets, cubemaps, HDR environments, or optimizing texture usage.","bodyPreview":"# React Three Fiber Textures\n\n## Quick Start\n\n```tsx\nimport { Canvas } from ''@react-three/fiber''\nimport { useTexture } from ''@react-three/drei''\n\nfunction TexturedBox() {\n  const texture = useTexture(''/textures/wood.jpg'')\n\n  return (\n    <mesh>\n      <boxGeometry />\n      <meshStandardMaterial map={texture} />\n    </mesh>\n  )\n}\n\nexport default function App() {\n  return (\n    <Canvas>\n      <ambientLight />\n      <TexturedBox />\n    </Canvas>\n  )\n}\n```\n\n## useTexture Hook (Drei)\n\nThe recommended w","body":"# React Three Fiber Textures\n\n## Quick Start\n\n```tsx\nimport { Canvas } from ''@react-three/fiber''\nimport { useTexture } from ''@react-three/drei''\n\nfunction TexturedBox() {\n  const texture = useTexture(''/textures/wood.jpg'')\n\n  return (\n    <mesh>\n      <boxGeometry />\n      <meshStandardMaterial map={texture} />\n    </mesh>\n  )\n}\n\nexport default function App() {\n  return (\n    <Canvas>\n      <ambientLight />\n      <TexturedBox />\n    </Canvas>\n  )\n}\n```\n\n## useTexture Hook (Drei)\n\nThe recommended way to load textures in R3F.\n\n### Single Texture\n\n```tsx\nimport { useTexture } from ''@react-three/drei''\n\nfunction SingleTexture() {\n  const texture = useTexture(''/textures/color.jpg'')\n\n  return (\n    <mesh>\n      <planeGeometry args={[5, 5]} />\n      <meshBasicMaterial map={texture} />\n    </mesh>\n  )\n}\n```\n\n### Multiple Textures (Array)\n\n```tsx\nfunction MultipleTextures() {\n  const [colorMap, normalMap, roughnessMap] = useTexture([\n    ''/textures/color.jpg'',\n    ''/textures/normal.jpg'',\n    ''/textures/roughness.jpg'',\n  ])\n\n  return (\n    <mesh>\n      <sphereGeometry args={[1, 64, 64]} />\n      <meshStandardMaterial\n        map={colorMap}\n        normalMap={normalMap}\n        roughnessMap={roughnessMap}\n      />\n    </mesh>\n  )\n}\n```\n\n### Named Object (Recommended for PBR)\n\n```tsx\nfunction PBRTextures() {\n  // Named object automatically spreads to material\n  const textures = useTexture({\n    map: ''/textures/color.jpg'',\n    normalMap: ''/textures/normal.jpg'',\n    roughnessMap: ''/textures/roughness.jpg'',\n    metalnessMap: ''/textures/metalness.jpg'',\n    aoMap: ''/textures/ao.jpg'',\n    displacementMap: ''/textures/displacement.jpg'',\n  })\n\n  return (\n    <mesh>\n      <sphereGeometry args={[1, 64, 64]} />\n      <meshStandardMaterial\n        {...textures}\n        displacementScale={0.1}\n      />\n    </mesh>\n  )\n}\n```\n\n### With Texture Configuration\n\n```tsx\nimport { useTexture } from ''@react-three/drei''\nimport * as THREE from ''three''\n\nfunction ConfiguredTextures() {\n  const textures = useTexture({\n    map: ''/textures/color.jpg'',\n    normalMap: ''/textures/normal.jpg'',\n  }, (textures) => {\n    // Configure textures after loading\n    Object.values(textures).forEach(texture => {\n      texture.wrapS = texture.wrapT = THREE.RepeatWrapping\n      texture.repeat.set(4, 4)\n    })\n  })\n\n  return (\n    <mesh>\n      <planeGeometry args={[10, 10]} />\n      <meshStandardMaterial {...textures} />\n    </mesh>\n  )\n}\n```\n\n### Preloading\n\n```tsx\nimport { useTexture } from ''@react-three/drei''\n\n// Preload at module level\nuseTexture.preload(''/textures/hero.jpg'')\nuseTexture.preload([''/tex1.jpg'', ''/tex2.jpg''])\n\nfunction Component() {\n  // Will be instant if preloaded\n  const texture = useTexture(''/textures/hero.jpg'')\n}\n```\n\n## useLoader (Core R3F)\n\nFor more control over loading.\n\n```tsx\nimport { useLoader } from ''@react-three/fiber''\nimport { TextureLoader } from ''three''\n\nfunction WithUseLoader() {\n  const texture = useLoader(TextureLoader, ''/textures/color.jpg'')\n\n  // Multiple textures\n  const [color, normal] = useLoader(TextureLoader, [\n    ''/textures/color.jpg'',\n    ''/textures/normal.jpg'',\n  ])\n\n  return (\n    <mesh>\n      <boxGeometry />\n      <meshStandardMaterial map={color} normalMap={normal} />\n    </mesh>\n  )\n}\n\n// Preload\nuseLoader.preload(TextureLoader, ''/textures/color.jpg'')\n```\n\n## Texture Configuration\n\n### Wrapping Modes\n\n```tsx\nimport * as THREE from ''three''\n\nfunction ConfigureWrapping() {\n  const texture = useTexture(''/textures/tile.jpg'', (tex) => {\n    // Wrapping\n    tex.wrapS = THREE.RepeatWrapping      // Horizontal: ClampToEdgeWrapping, RepeatWrapping, MirroredRepeatWrapping\n    tex.wrapT = THREE.RepeatWrapping      // Vertical\n\n    // Repeat\n    tex.repeat.set(4, 4)                  // Tile 4x4\n\n    // Offset\n    tex.offset.set(0.5, 0.5)              // Shift UV\n\n    // Rotation\n    tex.rotation = Math.PI / 4            // Rotate 45 degrees\n    tex.center.set(0.5, 0.5)              // Rotation pivot\n  })\n\n  return (\n    <mesh>\n      <planeGeometry args={[10, 10]} />\n      <meshStandardMaterial map={texture} />\n    </mesh>\n  )\n}\n```\n\n### Filtering\n\n```tsx\nfunction ConfigureFiltering() {\n  const texture = useTexture(''/textures/color.jpg'', (tex) => {\n    // Minification (texture larger than screen pixels)\n    tex.minFilter = THREE.LinearMipmapLinearFilter  // Smooth with mipmaps (default)\n    tex.minFilter = THREE.NearestFilter             // Pixelated\n    tex.minFilter = THREE.LinearFilter              // Smooth, no mipmaps\n\n    // Magnification (texture smaller than screen pixels)\n    tex.magFilter = THREE.LinearFilter   // Smooth (default)\n    tex.magFilter = THREE.NearestFilter  // Pixelated (retro style)\n\n    // Anisotropic filtering (sharper at angles)\n    tex.anisotropy = 16  // Usually renderer.capabilities.getMaxAnisotropy()\n\n    // Generate mipmaps\n    tex.generateMipmaps = true  // Default\n  })\n}\n```\n\n### Color Space\n\nImportant for accurate colors.\n\n```tsx\nfunction ConfigureColorSpace() {\n  const [colorMap, normalMap, roughnessMap] = useTexture([\n    ''/textures/color.jpg'',\n    ''/textures/normal.jpg'',\n    ''/textures/roughness.jpg'',\n  ], (textures) => {\n    // Color/albedo textures should use sRGB\n    textures[0].colorSpace = THREE.SRGBColorSpace\n\n    // Data textures (normal, roughness, metalness, ao) use Linear\n    // This is the default, so usually no action needed\n    // textures[1].colorSpace = THREE.LinearSRGBColorSpace\n    // textures[2].colorSpace = THREE.LinearSRGBColorSpace\n  })\n}\n```\n\n## Environment Maps\n\n### useEnvironment Hook\n\n```tsx\nimport { useEnvironment, Environment } from ''@react-three/drei''\n\n// Use as texture\nfunction EnvMappedSphere() {\n  const envMap = useEnvironment({ preset: ''sunset'' })\n\n  return (\n    <mesh>\n      <sphereGeometry args={[1, 64, 64]} />\n      <meshStandardMaterial\n        metalness={1}\n        roughness={0}\n        envMap={envMap}\n      />\n    </mesh>\n  )\n}\n\n// Or use Environment component for scene-wide\nfunction Scene() {\n  return (\n    <>\n      <Environment preset=\"sunset\" background />\n      <Mesh />\n    </>\n  )\n}\n```\n\n### HDR Environment\n\n```tsx\nimport { useEnvironment } from ''@react-three/drei''\n\nfunction HDREnvironment() {\n  const envMap = useEnvironment({ files: ''/hdri/studio.hdr'' })\n\n  return (\n    <mesh>\n      <sphereGeometry args={[1, 64, 64]} />\n      <meshStandardMaterial\n        metalness={1}\n        roughness={0}\n        envMap={envMap}\n        envMapIntensity={1}\n      />\n    </mesh>\n  )\n}\n```\n\n### Cube Map\n\n```tsx\nimport { useCubeTexture } from ''@react-three/drei''\n\nfunction CubeMapTexture() {\n  const envMap = useCubeTexture(\n    [''px.jpg'', ''nx.jpg'', ''py.jpg'', ''ny.jpg'', ''pz.jpg'', ''nz.jpg''],\n    { path: ''/textures/cube/'' }\n  )\n\n  return (\n    <mesh>\n      <sphereGeometry args={[1, 64, 64]} />\n      <meshStandardMaterial envMap={envMap} metalness={1} roughness={0} />\n    </mesh>\n  )\n}\n```\n\n## Video Textures\n\n```tsx\nimport { useVideoTexture } from ''@react-three/drei''\n\nfunction VideoPlane() {\n  const texture = useVideoTexture(''/videos/sample.mp4'', {\n    start: true,\n    loop: true,\n    muted: true,\n  })\n\n  return (\n    <mesh>\n      <planeGeometry args={[16, 9].map(x => x * 0.5)} />\n      <meshBasicMaterial map={texture} toneMapped={false} />\n    </mesh>\n  )\n}\n```\n\n## Canvas Textures\n\n```tsx\nimport { useRef, useEffect } from ''react''\nimport { useFrame } from ''@react-three/fiber''\nimport * as THREE from ''three''\n\nfunction CanvasTexture() {\n  const meshRef = useRef()\n  const textureRef = useRef()\n\n  useEffect(() => {\n    const canvas = document.createElement(''canvas'')\n    canvas.width = 256\n    canvas.height = 256\n    const ctx = canvas.getContext(''2d'')\n\n    // Draw on canvas\n    ctx.fillStyle = ''red''\n    ctx.fillRect(0, 0, 256, 256)\n    ctx.fillStyle = ''white''\n    ctx.font = ''48px Arial''\n    ctx.fillText(''Hello'', 50, 150)\n\n    textureRef.current = new THREE.CanvasTexture(canvas)\n  }, [])\n\n  // Update texture dynamically\n  useFrame(({ clock }) => {\n    if (textureRef.current) {\n      const canvas = textureRef.current.image\n      const ctx = canvas.getContext(''2d'')\n      ctx.fillStyle = `hsl(${clock.elapsedTime * 50}, 100%, 50%)`\n      ctx.fillRect(0, 0, 256, 256)\n      textureRef.current.needsUpdate = true\n    }\n  })\n\n  return (\n    <mesh ref={meshRef}>\n      <planeGeometry args={[2, 2]} />\n      <meshBasicMaterial map={textureRef.current} />\n    </mesh>\n  )\n}\n```\n\n## Data Textures\n\n```tsx\nimport { useMemo } from ''react''\nimport * as THREE from ''three''\n\nfunction NoiseTexture() {\n  const texture = useMemo(() => {\n    const size = 256\n    const data = new Uint8Array(size * size * 4)\n\n    for (let i = 0; i < size * size; i++) {\n      const value = Math.random() * 255\n      data[i * 4] = value\n      data[i * 4 + 1] = value\n      data[i * 4 + 2] = value\n      data[i * 4 + 3] = 255\n    }\n\n    const texture = new THREE.DataTexture(data, size, size)\n    texture.needsUpdate = true\n    return texture\n  }, [])\n\n  return (\n    <mesh>\n      <planeGeometry args={[2, 2]} />\n      <meshBasicMaterial map={texture} />\n    </mesh>\n  )\n}\n```\n\n## Render Targets\n\nRender to texture.\n\n```tsx\nimport { useFBO } from ''@react-three/drei''\nimport { useFrame } from ''@react-three/fiber''\nimport { useRef } from ''react''\n\nfunction RenderToTexture() {\n  const fbo = useFBO(512, 512)\n  const meshRef = useRef()\n  const otherSceneRef = useRef()\n\n  useFrame(({ gl, camera }) => {\n    // Render other scene to FBO\n    gl.setRenderTarget(fbo)\n    gl.render(otherSceneRef.current, camera)\n    gl.setRenderTarget(null)\n  })\n\n  return (\n    <>\n      {/* Scene to render to texture */}\n      <group ref={otherSceneRef}>\n        <mesh position={[0, 0, -5]}>\n          <sphereGeometry args={[1, 32, 32]} />\n          <meshStandardMaterial color=\"red\" />\n        </mesh>\n      </group>\n\n      {/* Display the texture */}\n      <mesh ref={meshRef}>\n        <planeGeometry args={[4, 4]} />\n        <meshBasicMaterial map={fbo.texture} />\n      </mesh>\n    </>\n  )\n}\n```\n\n## Texture Atlas / Sprite Sheet\n\n```tsx\nimport { useTexture } from ''@react-three/drei''\nimport { useState } from ''react''\nimport { useFrame } from ''@react-three/fiber''\nimport * as THREE from ''three''\n\nfunction SpriteAnimation() {\n  const texture = useTexture(''/textures/spritesheet.png'')\n  const [frame, setFrame] = useState(0)\n\n  // Configure texture\n  texture.wrapS = texture.wrapT = THREE.ClampToEdgeWrapping\n  texture.repeat.set(1/4, 1/4)  // 4x4 sprite sheet\n\n  useFrame(({ clock }) => {\n    const newFrame = Math.floor(clock.elapsedTime * 10) % 16\n    if (newFrame !== frame) {\n      setFrame(newFrame)\n      const col = newFrame % 4\n      const row = Math.floor(newFrame / 4)\n      texture.offset.set(col / 4, 1 - (row + 1) / 4)\n    }\n  })\n\n  return (\n    <mesh>\n      <planeGeometry args={[1, 1]} />\n      <meshBasicMaterial map={texture} transparent />\n    </mesh>\n  )\n}\n```\n\n## Material Texture Maps Reference\n\n```tsx\n<meshStandardMaterial\n  // Base color (sRGB)\n  map={colorTexture}\n\n  // Surface detail (Linear)\n  normalMap={normalTexture}\n  normalScale={[1, 1]}\n\n  // Roughness (Linear, grayscale)\n  roughnessMap={roughnessTexture}\n  roughness={1}  // Multiplier\n\n  // Metalness (Linear, grayscale)\n  metalnessMap={metalnessTexture}\n  metalness={1}  // Multiplier\n\n  // Ambient Occlusion (Linear, requires uv2)\n  aoMap={aoTexture}\n  aoMapIntensity={1}\n\n  // Self-illumination (sRGB)\n  emissiveMap={emissiveTexture}\n  emissive=\"#ffffff\"\n  emissiveIntensity={1}\n\n  // Vertex displacement (Linear)\n  displacementMap={displacementTexture}\n  displacementScale={0.1}\n  displacementBias={0}\n\n  // Alpha (Linear)\n  alphaMap={alphaTexture}\n  transparent={true}\n\n  // Environment reflection\n  envMap={envTexture}\n  envMapIntensity={1}\n\n  // Lightmap (requires uv2)\n  lightMap={lightmapTexture}\n  lightMapIntensity={1}\n/>\n```\n\n## Second UV Channel (for AO/Lightmaps)\n\n```tsx\nimport { useEffect, useRef } from ''react''\n\nfunction MeshWithUV2() {\n  const meshRef = useRef()\n\n  useEffect(() => {\n    // Copy uv to uv2 for aoMap/lightMap\n    const geometry = meshRef.current.geometry\n    geometry.setAttribute(''uv2'', geometry.attributes.uv)\n  }, [])\n\n  return (\n    <mesh ref={meshRef}>\n      <boxGeometry />\n      <meshStandardMaterial\n        aoMap={aoTexture}\n        aoMapIntensity={1}\n      />\n    </mesh>\n  )\n}\n```\n\n## Suspense Loading\n\n```tsx\nimport { Suspense } from ''react''\nimport { useTexture } from ''@react-three/drei''\n\nfunction TexturedMesh() {\n  const texture = useTexture(''/textures/large.jpg'')\n  return (\n    <mesh>\n      <boxGeometry />\n      <meshStandardMaterial map={texture} />\n    </mesh>\n  )\n}\n\nfunction Fallback() {\n  return (\n    <mesh>\n      <boxGeometry />\n      <meshBasicMaterial color=\"gray\" wireframe />\n    </mesh>\n  )\n}\n\nfunction Scene() {\n  return (\n    <Suspense fallback={<Fallback />}>\n      <TexturedMesh />\n    </Suspense>\n  )\n}\n```\n\n## Performance Tips\n\n1. **Use power-of-2 dimensions**: 256, 512, 1024, 2048\n2. **Compress textures**: Use KTX2/Basis for web\n3. **Enable mipmaps**: For distant objects\n4. **Limit texture size**: 2048 usually sufficient\n5. **Reuse textures**: Same texture = better batching\n6. **Preload important textures**: Avoid pop-in\n\n```tsx\n// Preload critical textures\nuseTexture.preload(''/textures/hero.jpg'')\n\n// Check texture memory\nuseFrame(({ gl }) => {\n  console.log(''Textures:'', gl.info.memory.textures)\n})\n\n// Dispose unused textures (R3F usually handles this)\ntexture.dispose()\n```\n\n## See Also\n\n- `r3f-materials` - Applying textures to materials\n- `r3f-loaders` - Asset loading patterns\n- `r3f-shaders` - Custom texture sampling\n"},"lastSynced":"2026-03-08T02:11:26.076Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced 3D texture rendering capabilities with React Three Fiber","zh":"适合需要高级 3D 纹理渲染能力的前端代理，特别是使用 React Three Fiber","ja":"React Three Fiber を使用するフロントエンドエージェントが高度な 3D テクスチャレンダリング機能を必要とする場合に最適","ko":"React Three Fiber를 사용하는 프론트엔드 에이전트가 고급 3D 텍스처 렌더링 기능을 필요로 할 경우에 적합","es":"Perfecto para agentes Frontend que necesitan capacidades avanzadas de renderizado de texturas 3D con React Three Fiber","fr":"Parfait pour les agents Frontend nécessitant des capacités de rendu de textures 3D avancées avec React Three Fiber","de":"Perfekt für Frontend-Agents, die erweiterte 3D-Textur-Renderfunktionen mit React Three Fiber benötigen","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de renderização de texturas 3D com React Three Fiber","ru":"Идеально подходит для фронтенд-агентов, которым необходимы расширенные возможности рендеринга 3D-текстур с помощью React Three Fiber","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى قدرات متقدمة لتصيير النسيج ثلاثي الأبعاد مع React Three Fiber"},"recommendation":{"en":"Empowers agents to create realistic textures for 3D models using the useTexture hook from @react-three/drei, supporting various image formats like .jpg","zh":"赋予代理创建使用 @react-three/drei 中的 useTexture hook 的 3D 模型的真实纹理的能力，支持多种图像格式，如 .jpg","ja":"@react-three/drei の useTexture hook を使用して 3D モデルにリアルなテクスチャを作成するエージェントの能力を提供します。.jpg などのさまざまな画像形式をサポート","ko":"에이전트가 @react-three/drei의 useTexture hook를 사용하여 3D 모델에 대한 실제 텍스처를 만들 수 있는 능력을 제공합니다. .jpg와 같은 다양한 이미지 형식을 지원","es":"Habilita a los agentes a crear texturas realistas para modelos 3D utilizando el hook useTexture de @react-three/drei, que admite varios formatos de imagen como .jpg","fr":"Permet aux agents de créer des textures réalistes pour les modèles 3D en utilisant le hook useTexture de @react-three/drei, qui prend en charge divers formats d''image tels que .jpg","de":"Ermächtigt die Agenten, realistische Texturen für 3D-Modelle mit dem useTexture-Hook von @react-three/drei zu erstellen, der verschiedene Bildformate wie .jpg unterstützt","pt":"Habilita os agentes a criar texturas realistas para modelos 3D usando o hook useTexture do @react-three/drei, suportando vários formatos de imagem como .jpg","ru":"Наделяет агентов возможностью создавать реалистичные текстуры для 3D-моделей с помощью хука useTexture из @react-three/drei, поддерживая различные форматы изображений, такие как .jpg","ar":"يمكّن الوكلاء من إنشاء نسيج واقعي لطرازات ثلاثية الأبعاد باستخدام hook useTexture من @react-three/drei ، ودعم تنسيقات الصورة المختلفة مثل .jpg"},"useCases":{"en":["Rendering 3D scenes with custom textures","Creating immersive experiences with ambientLight and meshStandardMaterial","Optimizing 3D model performance with efficient texture loading"],"zh":["使用自定义纹理渲染 3D 场景","使用 ambientLight 和 meshStandardMaterial 创建身临其境的体验","使用高效的纹理加载优化 3D 模型性能"],"ja":["カスタムテクスチャを使用した 3D シーンのレンダリング","ambientLight と meshStandardMaterial を使用した臨場感のある体験の作成","効率的なテクスチャのロードを使用した 3D モデルのパフォーマンスの最適化"],"ko":["사용자 지정 텍스처를 사용한 3D 장면 렌더링","ambientLight와 meshStandardMaterial를 사용한 몰입감 있는 경험 생성","효율적인 텍스처 로딩을 사용한 3D 모델 성능 최적화"],"es":["Renderizado de escenas 3D con texturas personalizadas","Creación de experiencias inmersivas con ambientLight y meshStandardMaterial","Optimización del rendimiento de los modelos 3D con una carga de texturas eficiente"],"fr":["Rendu de scènes 3D avec des textures personnalisées","Création d''expériences immersives avec ambientLight et meshStandardMaterial","Optimisation des performances des modèles 3D avec un chargement de textures efficace"],"de":["Rendering von 3D-Szenen mit benutzerdefinierten Texturen","Erstellung von immersiven Erfahrungen mit ambientLight und meshStandardMaterial","Optimierung der Leistung von 3D-Modellen mit effizienter Texturenladung"],"pt":["Renderização de cenas 3D com texturas personalizadas","Criação de experiências imersivas com ambientLight e meshStandardMaterial","Otimização do desempenho do modelo 3D com carregamento eficiente de texturas"],"ru":["Рендеринг 3D-сцен с пользовательскими текстурами","Создание иммерсивных trải nghiệm с помощью ambientLight и meshStandardMaterial","Оптимизация производительности 3D-моделей за счет эффективной загрузки текстур"],"ar":["تصيير مشاهد ثلاثية الأبعاد ذات نسيج مخصص","إنشاء تجارب غامرة باستخدام ambientLight و meshStandardMaterial","تحسين أداء نموذج ثلاثي الأبعاد بفضل تحميل النسيج الفعال"]},"limitations":{"en":["Requires React Three Fiber and @react-three/drei libraries","Limited to 3D texture rendering only"],"zh":["需要 React Three Fiber 和 @react-three/drei 库","仅限 3D 纹理渲染"],"ja":["React Three Fiber と @react-three/drei ライブラリが必要","3D テクスチャレンダリングのみに限定"],"ko":["React Three Fiber와 @react-three/drei 라이브러리가 필요","3D 텍스처 렌더링만 가능"],"es":["Requiere las bibliotecas React Three Fiber y @react-three/drei","Limitado solo al renderizado de texturas 3D"],"fr":["Nécessite les bibliothèques React Three Fiber et @react-three/drei","Limité au seul rendu de textures 3D"],"de":["Benötigt die Bibliotheken React Three Fiber und @react-three/drei","Begrenzt auf das alleinige Rendering von 3D-Texturen"],"pt":["Requer as bibliotecas React Three Fiber e @react-three/drei","Limitado apenas à renderização de texturas 3D"],"ru":["Требует библиотек React Three Fiber и @react-three/drei","Ограничен только рендерингом 3D-текстур"],"ar":["يتطلب مكتبات React Three Fiber و @react-three/drei","محدود بتصيير النسيج ثلاثي الأبعاد فقط"]},"version":4},"contentHash":"d0bf95a2cc6e2752a0cb6c86fc7fc3cd602b859c1235b4b10e319c04e5c724fb","qualityScore":36}');
