INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EnzeD/r3f-skills/r3f-textures', 'r3f-textures', 'EnzeD', 'r3f-skills', 'community', 'r3f-textures EnzeD r3f-skills community r3f-textures is a skill for creating 3D textures with React Three Fiber. It benefits developers who want to add realistic textures to their 3D models. r3f-textures 是一个用于 React Three Fiber 的纹理库，提供 useTexture Hook 和 meshStandardMaterial。 r3f-textures は、React Three Fiber 用のテクスチャライブラリで、useTexture Hook と meshStandardMaterial を提供します。 r3f-textures는 React Three Fiber용 텍스쳐 라이브러리로서 useTexture Hook과 meshStandardMaterial을 제공합니다. r3f-textures es una herramienta para agregar texturas a objetos 3D en React Three Fiber, utilizando el hook useTexture de Drei r3f-textures est un outil pour ajouter des textures à des objets 3D dans React Three Fiber, en utilisant le hook useTexture de Drei r3f-Textures ist ein Werkzeug zum Hinzufügen von Texturen zu 3D-Objekten in React Three Fiber, unter Verwendung des useTexture-Hooks von Drei O hook useTexture do Drei permite adicionar texturas a objetos 3D em React Three Fiber. Confira nosso exemplo de código! Хук useTexture из Drei позволяет добавлять текстуры к 3D-объектам в React Three Fiber. Посмотрите наш пример кода! يسمح hook useTexture من Drei بإضافة النسيج إلى كائنات 3D في React Three Fiber. انظر إلى مثال кодنا! how to use r3f-textures r3f-textures setup guide react three fiber textures useTexture hook 3D texture rendering r3f-textures vs react-three-fiber r3f-textures install react three fiber tutorial 3D modeling with r3f-textures r3f-textures React Three Fiber 纹理渲染 3D 渲染 useTexture Hook meshStandardMaterial AIエージェント JavaScript 库 Imports textures using the useTexture hook from @react-three/drei Supports rendering 3D models with textures using meshStandardMaterial Uses the Canvas component from @react-three/fiber for rendering Enables creation of textured boxes using the boxGeometry component Utilizes ambientLight for scene illumination Leverages the @react-three/fiber and @react-three/drei libraries for 3D rendering r3f-textures is a React Three Fiber skill that enables developers to create and manage 3D textures using the useTexture hook from @react-three/drei');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Duit-Foundation/duit_go/duit-maintainer', 'community', 'Duit-Foundation', 'duit_go', 'Duit-Foundation/duit_go', 'duit-maintainer', 0, 0, 36, '2026-03-08T01:57:15.553Z', '2026-03-08T02:11:32.885Z', '4f45f85c80ccaf6e1aef72d967985a9612d49b7ee5395138b29f1ae6412324a9', '{"id":"Duit-Foundation/duit_go/duit-maintainer","name":"duit-maintainer","description":{"en":"The duit-maintainer skill provides a Golang DSL for the Duit Framework, enabling developers to create custom Flutter widgets. It benefits developers working with Flutter and Duit.","zh":"Duit Maintainer 是一个 Golang DSL，为 Duit 框架提供驱动 UI Tookit。它允许开发者快速实现新的 Flutter 小部件","ja":"Duit Maintainer は、Duit フレームワーク向けの駆動 UI Tookit を提供する Golang DSL です。開発者が新しい Flutter ウィジェットを迅速に実装できるようにします","ko":"Duit Maintainer는 Duit 프레임워크용 드라이브 UI 툴킷을 제공하는 Golang DSL입니다. 개발자가 새로운 Flutter 위젯을 빠르게 구현할 수 있도록 합니다","es":"Duit Maintainer es un DSL de Golang para el framework Duit, que permite crear herramientas de UI personalizadas para Flutter","fr":"Duit Maintainer est un DSL Golang pour le framework Duit, permettant de créer des outils d''interface utilisateur personnalisés pour Flutter","de":"Duit Maintainer ist ein Golang-DSL für das Duit-Framework, mit dem benutzerdefinierte UI-Tools für Flutter erstellt werden können","pt":"O Duit Maintainer é um DSL em Golang para o framework Duit, permitindo a criação de widgets personalizados para Flutter","ru":"Duit Maintainer - это DSL на Golang для фреймворка Duit, позволяющий создавать кастомные виджеты для Flutter","ar":"Duit Maintainer هو لغة تشغيلية في Golang لإطار Duit، مما يسمح بإنشاء أدوات تحكم مخصصة لFlutter"},"seo":{"title":{"en":"duit-maintainer: Golang DSL Setup Guide for Duit Framewor...","zh":"Duit Maintainer 快速入门指南","ja":"Duit Maintainer のセットアップガイド - Flutter 向けの UI Tookit","ko":"Duit Maintainer 설정 가이드 - Flutter용 드라이브 UI 툴킷","es":"Guía de configuración de Duit Maintainer para Flutter","fr":"Configurer Duit Maintainer pour Flutter - Meilleures prat...","de":"Duit Maintainer Einrichtung für Flutter - Technischer Lei...","pt":"Guia de Configuração do Duit Maintainer para Desenvolvedores","ru":"Настройка Duit Maintainer: Руководство для Разработчиков ...","ar":"دليل إعداد Duit Maintainer للبرمجة مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement new Flutter widgets with duit-maintainer. Learn the workflow and get started with the Golang DSL for Duit Framework today!","zh":"了解如何使用 Duit Maintainer 实现新的 Flutter 小部件，包括创建属性结构、添加小部件类型和运行代码生成","ja":"Duit Maintainer を使用して新しい Flutter ウィジェットを実装する方法について説明します。属性構造の作成、ウィジェット タイプの追加、コード生成の実行など","ko":"Duit Maintainer를 사용하여 새로운 Flutter 위젯을 구현하는 방법에 대해 설명합니다. 속성 구조 생성, 위젯 유형 추가, 코드 생성 실행 등","es":"Aprende a implementar Duit Maintainer para Flutter con nuestro tutorial paso a paso y mejora tu desarrollo de UI","fr":"Découvrez comment configurer Duit Maintainer pour Flutter et améliorer vos compétences en développement d''interface utilisateur","de":"Erfahren Sie, wie Sie Duit Maintainer für Flutter einrichten und Ihre Fähigkeiten im Bereich UI-Entwicklung verbessern","pt":"Aprenda a configurar o Duit Maintainer, um DSL em Golang para o framework Duit, e crie widgets personalizados para Flutter","ru":"Узнайте, как настроить Duit Maintainer, DSL на Golang для фреймворка Duit, и создавайте кастомные виджеты для Flutter с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Duit Maintainer، وهو لغة تشغيلية في Golang لإطار Duit، وقم بإنشاء أدوات تحكم مخصصة لFlutter مع أدوات الذكاء الاصطناعي"},"definition":{"en":"duit-maintainer is a Golang DSL for the Duit Framework, used for creating and managing Flutter widgets","zh":"Duit Maintainer 是一个用于实现新的 Flutter 小部件的 Golang DSL","ja":"Duit Maintainer は、新しい Flutter ウィジェットを実装するための Golang DSL です","ko":"Duit Maintainer는 새로운 Flutter 위젯을 구현하기 위한 Golang DSL입니다","es":"Duit Maintainer es un conjunto de herramientas para desarrolladores que permite crear y personalizar UI para aplicaciones Flutter","fr":"Duit Maintainer est un ensemble d''outils pour les développeurs qui permet de créer et de personnaliser les interfaces utilisateur pour les applications Flutter","de":"Duit Maintainer ist eine Sammlung von Tools für Entwickler, mit denen UI-Komponenten für Flutter-Anwendungen erstellt und angepasst werden können","pt":"Duit Maintainer é uma ferramenta de DSL em Golang para o framework Duit","ru":"Duit Maintainer - это инструмент DSL на Golang для фреймворка Duit","ar":"Duit Maintainer هو أداة لغة تشغيلية في Golang لإطار Duit"},"features":{"en":["Creates attributes structure in pkg/duit_attributes/","Adds widget type to pkg/duit_core/element_type.go","Generates code using the make gogen command","Supports writing tests in pkg/duit_widget/","Implements widget functions in pkg/duit_widget/"],"zh":["创建属性结构","添加小部件类型","运行代码生成","支持 Flutter 小部件实现","使用 Golang DSL"],"ja":["属性構造の作成","ウィジェット タイプの追加","コード生成の実行","Flutter ウィジェットの実装をサポート","Golang DSL を使用"],"ko":["속성 구조 생성","위젯 유형 추가","코드 생성 실행","Flutter 위젯 구현 지원","Golang DSL 사용"],"es":["Creación de estructuras de atributos personalizadas en pkg/duit_attributes/","Adición de tipos de widgets en pkg/duit_core/element_type.go","Implementación de funciones de widget en pkg/duit_widget/","Generación de código con make gogen","Creación de pruebas unitarias para widgets personalizados"],"fr":["Création de structures d''attributs personnalisées dans pkg/duit_attributes/","Ajout de types de widgets dans pkg/duit_core/element_type.go","Implémentation de fonctions de widget dans pkg/duit_widget/","Génération de code avec make gogen","Création de tests unitaires pour les widgets personnalisés"],"de":["Erstellung von benutzerdefinierten Attributstrukturen in pkg/duit_attributes/","Hinzufügen von Widget-Typen in pkg/duit_core/element_type.go","Implementierung von Widget-Funktionen in pkg/duit_widget/","Codegenerierung mit make gogen","Erstellung von Einheitstests für benutzerdefinierte Widgets"],"pt":["Criação de atributos de estrutura em pkg/duit_attributes/","Adição de tipo de widget em pkg/duit_core/element_type.go","Adição de função de widget em pkg/duit_widget/","Geração de código com make gogen","Escrita de testes personalizados"],"ru":["Создание структуры атрибутов в pkg/duit_attributes/","Добавление типа виджета в pkg/duit_core/element_type.go","Добавление функции виджета в pkg/duit_widget/","Генерация кода с помощью make gogen","Написание кастомных тестов"],"ar":["إنشاء هيكل السمة في pkg/duit_attributes/","إضافة نوع أداة التحكم في pkg/duit_core/element_type.go","إضافة دالة أداة التحكم في pkg/duit_widget/","إنشاء رمز البرنامج باستخدام make gogen","كتابة الاختبارات المخصصة"]},"keywords":{"en":["how to use duit-maintainer","duit-maintainer setup guide","duit-maintainer alternative","Golang DSL for Duit Framework","Flutter widget implementation","what is duit-maintainer","duit-maintainer vs Flutter","duit-maintainer install","Duit Framework tutorial"],"zh":["Duit Maintainer","Golang DSL","Flutter 小部件","驱动 UI Tookit","Duit 框架","代码生成","属性结构","小部件类型"],"ja":["Duit Maintainer","Golang DSL","Flutter ウィジェット","駆動 UI Tookit","Duit フレームワーク","コード生成","属性構造","ウィジェット タイプ"],"ko":["Duit Maintainer","Golang DSL","Flutter 위젯","드라이브 UI 툴킷","Duit 프레임워크","코드 생성","속성 구조","위젯 유형"],"es":["Duit Maintainer","Flutter","Golang","DSL","UI personalizada","desarrollo de aplicaciones móviles","herramientas de desarrollo","framework Duit","widgets personalizados"],"fr":["Duit Maintainer","Flutter","Golang","DSL","interface utilisateur personnalisée","développement d''applications mobiles","outils de développement","framework Duit","widgets personnalisés"],"de":["Duit Maintainer","Flutter","Golang","DSL","benutzerdefinierte UI","Mobile-App-Entwicklung","Entwicklungstools","Duit-Framework","benutzerdefinierte Widgets"],"pt":["Duit Maintainer","Golang","Duit Framework","Flutter","DSL","Desenvolvimento de widgets","Configuração do Duit Maintainer","Criação de atributos de estrutura","Geração de código"],"ru":["Duit Maintainer","Golang","Duit Framework","Flutter","DSL","Разработка виджетов","Настройка Duit Maintainer","Создание структуры атрибутов","Генерация кода","ИИ Агенты"],"ar":["Duit Maintainer","Golang","Duit Framework","Flutter","DSL","برمجة أدوات التحكم","إعداد Duit Maintainer","إنشاء هيكل السمة","إنشاء رمز البرنامج","أدوات الذكاء الاصطناعي"]}},"owner":"Duit-Foundation","repo":"duit_go","repoPath":"Duit-Foundation/duit_go","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.553Z","topics":[],"category":"community","skillMd":{"name":"duit-maintainer","description":"Implements new Flutter widgets following Duit project patterns, conducts code reviews, writes tests, and enforces coding conventions. Use when implementing new widget functionality, reviewing Flutter widget code, or maintaining the Duit library.","bodyPreview":"# Duit Maintainer\n\n## Quick Start\n\nWhen implementing a new Flutter widget for the Duit library, follow this workflow:\n\n1. Create attributes structure in `pkg/duit_attributes/`\n2. Add widget type to `pkg/duit_core/element_type.go`\n3. Add widget function in `pkg/duit_widget/`\n4. Run code generation: `make gogen`\n5. Write tests if required\n\n## Widget Implementation Workflow\n\n### Step 1: Create Attributes Structure\n\nCreate a new file in `pkg/duit_attributes/` named `{widget_name}_attributes.go`:\n\n``","body":"# Duit Maintainer\n\n## Quick Start\n\nWhen implementing a new Flutter widget for the Duit library, follow this workflow:\n\n1. Create attributes structure in `pkg/duit_attributes/`\n2. Add widget type to `pkg/duit_core/element_type.go`\n3. Add widget function in `pkg/duit_widget/`\n4. Run code generation: `make gogen`\n5. Write tests if required\n\n## Widget Implementation Workflow\n\n### Step 1: Create Attributes Structure\n\nCreate a new file in `pkg/duit_attributes/` named `{widget_name}_attributes.go`:\n\n```go\npackage duit_attributes\n\nimport (\n    \"errors\"\n    \"github.com/Duit-Foundation/duit_go/v4/pkg/duit_utils\"\n)\n\n// WidgetNameAttributes defines attributes for WidgetName widget.\n// See: https://api.flutter.dev/flutter/widgets/WidgetName-class.html\ntype WidgetNameAttributes struct {\n    *ValueReferenceHolder `gen:\"wrap\"`\n    *ThemeConsumer        `gen:\"wrap\"`\n    Property1             duit_utils.Tristate[bool] `json:\"property1,omitempty\"`\n    Property2             string                     `json:\"property2,omitempty\"`\n}\n\n// NewWidgetNameAttributes creates a new WidgetNameAttributes instance.\nfunc NewWidgetNameAttributes() *WidgetNameAttributes {\n    return &WidgetNameAttributes{}\n}\n\n// SetProperty1 sets the property1 and returns WidgetNameAttributes for method chaining.\nfunc (r *WidgetNameAttributes) SetProperty1(property1 bool) *WidgetNameAttributes {\n    r.Property1 = duit_utils.BoolValue(property1)\n    return r\n}\n\n// SetProperty2 sets the property2 and returns WidgetNameAttributes for method chaining.\nfunc (r *WidgetNameAttributes) SetProperty2(property2 string) *WidgetNameAttributes {\n    r.Property2 = property2\n    return r\n}\n\n//bindgen:exclude\nfunc (r *WidgetNameAttributes) Validate() error {\n    if err := r.ValueReferenceHolder.Validate(); err != nil {\n        return err\n    }\n\n    if err := r.ThemeConsumer.Validate(); err != nil {\n        return err\n    }\n\n    if r.Property1 == nil {\n        return errors.New(\"property1 is required\")\n    }\n\n    return nil\n}\n```\n\n**Rules:**\n\n- Use `*ValueReferenceHolder` with `gen:\"wrap\"` tag\n- Use `*ThemeConsumer` with `gen:\"wrap\"` tag\n- Use `duit_utils.Tristate[T]` for optional boolean properties\n- Add `json:\"propertyName,omitempty\"` tag for all fields\n- Method receiver must be named `r`\n- Add `//bindgen:exclude` comment to `Validate()` method\n- Documentation must be in English\n\n### Step 2: Add Widget Type\n\nAdd a constant to `pkg/duit_core/element_type.go`:\n\n```go\nconst (\n    // ... existing types\n    WidgetName DuitElementType = \"WidgetName\"\n)\n```\n\nFollow naming convention: Use PascalCase with no spaces or underscores.\n\n### Step 3: Add Widget Function\n\nCreate a new file in `pkg/duit_widget/` named `{widget_name}.go`:\n\n```go\npackage duit_widget\n\nimport (\n    \"github.com/Duit-Foundation/duit_go/v4/pkg/duit_attributes\"\n    \"github.com/Duit-Foundation/duit_go/v4/pkg/duit_core\"\n)\n\n/*\nExample:\n    WidgetName(\n        duit_attributes.NewWidgetNameAttributes().\n            SetProperty1(true).\n            SetProperty2(\"value\"),\n        \"id\",\n        false,\n        nil,\n    )\n*/\nfunc WidgetName(attributes *duit_attributes.WidgetNameAttributes, id string, controlled bool, child *duit_core.DuitElementModel) *duit_core.DuitElementModel {\n    checkAttributes(attributes)\n    return new(duit_core.DuitElementModel).CreateElement(duit_core.WidgetName, id, \"\", attributes, nil, controlled, 1, nil, child)\n}\n```\n\n**Function signature patterns:**\n\n- **Single child**: `func WidgetName(attributes *Attrs, id string, controlled bool, child *DuitElementModel) *DuitElementModel`\n- **Multiple children**: `func WidgetName(attributes *Attrs, id string, controlled bool, children []*DuitElementModel) *DuitElementModel`\n- **Optional child**: `func WidgetName(attributes *Attrs, id string, child *DuitElementModel) *DuitElementModel`\n\n**CreateElement parameters:**\n\n1. Widget type constant\n2. ID string\n3. Tag string (empty for most widgets)\n4. Attributes\n5. Commands (nil for most widgets)\n6. Controlled boolean\n7. Children count (use 2 for widgets with optional child like Visibility)\n8. Nil (reserved)\n9. Children (variadic)\n\n**Rules:**\n\n- Always call `checkAttributes(attributes)` to validate\n- Use `new(DuitElementModel).CreateElement(...)`\n- Add example usage in comment\n\n### Step 4: Run Code Generation\n\n```bash\nmake gogen\n```\n\nThis generates embedded struct delegates and other boilerplate code.\n\n### Step 5: Write Tests\n\nOnly write tests when explicitly required. When required, create `{widget_name}_attributes_test.go` in `pkg/duit_attributes/`:\n\n```go\npackage duit_attributes_test\n\nimport (\n    \"testing\"\n\n    \"github.com/Duit-Foundation/duit_go/v4/pkg/duit_attributes\"\n)\n\nfunc TestWidgetNameAttributes_Validate_ValidAttributes(t *testing.T) {\n    attrs := &duit_attributes.WidgetNameAttributes{\n        Property1: duit_utils.BoolValue(true),\n    }\n\n    err := attrs.Validate()\n    if err != nil {\n        t.Fatal(\"expected no error for valid attributes, got:\", err)\n    }\n}\n\nfunc TestWidgetNameAttributes_Validate_MissingRequiredProperty(t *testing.T) {\n    attrs := &duit_attributes.WidgetNameAttributes{\n        Property1: nil, // missing required property\n    }\n\n    err := attrs.Validate()\n    if err == nil {\n        t.Fatal(\"expected error for missing required property\")\n    }\n}\n\nfunc TestWidgetNameAttributes_SetProperty1(t *testing.T) {\n    attrs := duit_attributes.NewWidgetNameAttributes()\n    property1 := true\n\n    result := attrs.SetProperty1(property1)\n\n    if *attrs.Property1 != property1 {\n        t.Fatalf(\"expected Property1 to be %v, got: %v\", property1, attrs.Property1)\n    }\n\n    if result != attrs {\n        t.Fatal(\"expected SetProperty1 to return same instance for method chaining\")\n    }\n}\n```\n\n**Testing rules:**\n\n- Test filename: `{target_file}_test.go`\n- Only test properties explicitly used in structure''s methods\n- Always test `Tristate[T]` properties for JSON serialization\n- Never check error text, only check if error exists\n- Never cover embedded fields or embedded structs\n- Test setter methods return same instance for chaining\n\n## Code Review Checklist\n\nWhen reviewing widget implementations, check:\n\n- [ ] Receiver name is `r` for all structure methods\n- [ ] Documentation is in English\n- [ ] Method chaining returns same instance (`return r`)\n- [ ] Required properties validated in `Validate()` method\n- [ ] `Validate()` has `//bindgen:exclude` comment\n- [ ] `checkAttributes()` called in widget function\n- [ ] Widget type follows naming convention (PascalCase)\n- [ ] Attributes use appropriate types (`Tristate[T]` for optionals)\n- [ ] JSON tags use `omitempty` suffix\n- [ ] Example usage comment present in widget file\n- [ ] Nil checks for potentially nil receivers before method calls\n\n## Coding Conventions\n\n### Style Rules\n\nFrom `pkg/.cursor/rules/style.mdc`:\n\n1. Method receiver name must always be \"r\"\n2. Documentation must be in English\n3. Explicit nil checks for potentially nil receivers\n\n### Testing Rules\n\nFrom `pkg/.cursor/rules/testing.mdc`:\n\n1. Never cover embedded fields or embedded structs with tests\n2. Always add tests for `Tristate[T]` properties (JSON serialization)\n3. Test filename: `{target_file}_test.go`\n4. Only test properties explicitly used in structure''s methods\n5. Never check error text, only check if error exists\n\n### Flutter Documentation Reference\n\nAlways reference official Flutter documentation in attributes structure:\n\n```go\n// See: https://api.flutter.dev/flutter/widgets/WidgetName-class.html\n```\n\n## Common Patterns\n\n### Required Properties\n\n```go\nif r.RequiredProperty == nil {\n    return errors.New(\"requiredProperty is required\")\n}\n```\n\n### Optional Properties (Tristate)\n\n```go\ntype WidgetAttributes struct {\n    OptionalProperty duit_utils.Tristate[bool] `json:\"optionalProperty,omitempty\"`\n}\n\n// SetOptionalProperty sets the optional property.\nfunc (r *WidgetAttributes) SetOptionalProperty(optional bool) *WidgetAttributes {\n    r.OptionalProperty = duit_utils.BoolValue(optional)\n    return r\n}\n```\n\n### String Properties\n\n```go\ntype WidgetAttributes struct {\n    TextProperty string `json:\"textProperty,omitempty\"`\n}\n\n// SetTextProperty sets the text property.\nfunc (r *WidgetAttributes) SetTextProperty(text string) *WidgetAttributes {\n    r.TextProperty = text\n    return r\n}\n```\n\n### Nil-Safe Method Calls\n\n```go\nfunc SomeFunction(widget *DuitElementModel) {\n    if widget == nil {\n        return\n    }\n    widget.SomeMethod()\n}\n```\n\n## Makefile Commands\n\n```bash\n# Generate code\nmake gogen\n\n# Run tests\nmake test\n\n# Run vet\nmake vet\n```\n\nAlways run `make gogen` after adding new widgets.\n\n## Troubleshooting\n\n### Code generation fails\n\n- Check that `gen:\"wrap\"` tags are present for embedded structs\n- Verify attribute struct has no syntax errors\n- Ensure all referenced types are imported\n\n### Tests fail\n\n- Check that required properties are set in test\n- Verify Tristate properties are tested for JSON serialization\n- Ensure error checks don''t compare error text\n\n### Widget not recognized\n\n- Verify type is added to `element_type.go`\n- Check type name matches exactly in widget function\n- Run `make gogen` to regenerate delegates\n"},"lastSynced":"2026-03-08T02:11:32.885Z","agentAnalysis":{"suitability":{"en":"Perfect for Flutter Development Agents needing custom widget creation capabilities with the Duit Framework and Golang DSL.","zh":"适用于需要使用Duit Framework和Golang DSL进行自定义小部件创建的Flutter开发代理。","ja":"Duit FrameworkとGolang DSLを使用してカスタムウィジェットを作成する必要があるFlutter開発エージェントに適しています。","ko":"Duit Framework와 Golang DSL을 사용하여 사용자 지정 위젯을 생성해야 하는 Flutter 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Flutter que necesitan capacidades de creación de widgets personalizados con el marco Duit y el lenguaje de definición de software Golang.","fr":"Parfait pour les agents de développement Flutter qui ont besoin de capacités de création de widgets personnalisés avec le framework Duit et le DSL Golang.","de":"Perfekt für Flutter-Entwicklungsagenten, die benutzerdefinierte Widget-Erstellungsfunktionen mit dem Duit-Framework und dem Golang-DSL benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Flutter que precisam de capacidades de criação de widgets personalizados com o Framework Duit e a linguagem Golang DSL.","ru":"Идеально подходит для агентов разработки Flutter, которым необходимы возможности создания пользовательских виджетов с использованием фреймворка Duit и языка Golang DSL.","ar":"مثالي لعمليات وكلاء التطوير Flutter الذين يحتاجون إلى إمكانيات إنشاء أدوات مخصصة مع إطار Duit و لغة Golang DSL."},"recommendation":{"en":"Empowers agents to create custom Flutter widgets using the Duit Framework, leveraging Golang DSL for attributes structure, widget type addition, and code generation with ''make gogen'' command, while utilizing ''pkg/duit_attributes/'' and ''pkg/duit_core/'' directories.","zh":"赋予代理使用Duit Framework创建自定义Flutter小部件的能力，利用Golang DSL进行属性结构、小部件类型添加和代码生成，使用''make gogen''命令，同时利用''pkg/duit_attributes/''和''pkg/duit_core/''目录。","ja":"Duit Frameworkを使用してカスタムFlutterウィジェットを作成し、Golang DSLを使用して属性構造、ウィジェットタイプの追加、コード生成を行うことができるようにします。''make gogen''コマンドを使用し、''pkg/duit_attributes/''と''pkg/duit_core/''ディレクトリを利用します。","ko":"Duit Framework를 사용하여 사용자 지정 Flutter 위젯을 생성하고, Golang DSL을 사용하여 속성 구조, 위젯 유형 추가 및 코드 생성을 수행할 수 있도록 합니다. ''make gogen'' 명령을 사용하고, ''pkg/duit_attributes/'' 및 ''pkg/duit_core/'' 디렉토리를 활용합니다.","es":"Habilita a los agentes a crear widgets Flutter personalizados utilizando el marco Duit, aprovechando el DSL Golang para la estructura de atributos, la adición de tipos de widgets y la generación de código con el comando ''make gogen'', mientras utiliza los directorios ''pkg/duit_attributes/'' y ''pkg/duit_core/''.","fr":"Permet aux agents de créer des widgets Flutter personnalisés en utilisant le framework Duit, en exploitant le DSL Golang pour la structure des attributs, l''ajout de types de widgets et la génération de code avec la commande ''make gogen'', tout en utilisant les répertoires ''pkg/duit_attributes/'' et ''pkg/duit_core/''.","de":"Ermächtigt die Agenten, benutzerdefinierte Flutter-Widgets mit dem Duit-Framework zu erstellen, indem sie das Golang-DSL für die Attributstruktur, die Hinzufügung von Widgettypen und die Codegenerierung mit dem Befehl ''make gogen'' nutzen, während sie die Verzeichnisse ''pkg/duit_attributes/'' und ''pkg/duit_core/'' verwenden.","pt":"Habilita os agentes a criar widgets Flutter personalizados usando o Framework Duit, aproveitando a linguagem Golang DSL para estrutura de atributos, adição de tipo de widget e geração de código com o comando ''make gogen'', enquanto utiliza os diretórios ''pkg/duit_attributes/'' e ''pkg/duit_core/''.","ru":"Наделяет агентов возможностью создавать пользовательские виджеты Flutter, используя фреймворк Duit, с использованием языка Golang DSL для структуры атрибутов, добавления типа виджета и генерации кода с помощью команды ''make gogen'', при этом используя директории ''pkg/duit_attributes/'' и ''pkg/duit_core/''.","ar":"تمكّن الوكلاء من إنشاء أدوات Flutter مخصصة باستخدام إطار Duit، مستفيداً من لغة Golang DSL لSTRUCTURE السلبية، وإضافة نوع الأداة، وإنشاء رمز مع أمر ''make gogen''، بينما يستخدم مجلدات ''pkg/duit_attributes/'' و ''pkg/duit_core/''."},"useCases":{"en":["Implementing new Flutter widgets for the Duit library","Generating custom widget attributes structures in ''pkg/duit_attributes/''","Adding widget functions in ''pkg/duit_widget/''"],"zh":["为Duit库实现新的Flutter小部件","在''pkg/duit_attributes/''中生成自定义小部件属性结构","在''pkg/duit_widget/''中添加小部件函数"],"ja":["Duitライブラリのための新しいFlutterウィジェットを実装する","''pkg/duit_attributes/''でカスタムウィジェット属性構造を生成する","''pkg/duit_widget/''でウィジェット関数を追加する"],"ko":["Duit 라이브러리의 새로운 Flutter 위젯을 구현하는 것","''pkg/duit_attributes/''에서 사용자 지정 위젯 속성 구조를 생성하는 것","''pkg/duit_widget/''에서 위젯 함수를 추가하는 것"],"es":["Implementar nuevos widgets Flutter para la biblioteca Duit","Generar estructuras de atributos de widgets personalizados en ''pkg/duit_attributes/''","Agregar funciones de widget en ''pkg/duit_widget/''"],"fr":["Mettre en œuvre de nouveaux widgets Flutter pour la bibliothèque Duit","Générer des structures d''attributs de widgets personnalisés dans ''pkg/duit_attributes/''","Ajouter des fonctions de widget dans ''pkg/duit_widget/''"],"de":["Implementierung neuer Flutter-Widgets für die Duit-Bibliothek","Erzeugen von benutzerdefinierten Widget-Attributstrukturen in ''pkg/duit_attributes/''","Hinzufügen von Widgetfunktionen in ''pkg/duit_widget/''"],"pt":["Implementar novos widgets Flutter para a biblioteca Duit","Gerar estruturas de atributos de widgets personalizados em ''pkg/duit_attributes/''","Adicionar funções de widget em ''pkg/duit_widget/''"],"ru":["Реализация новых виджетов Flutter для библиотеки Duit","Генерация структур атрибутов пользовательских виджетов в ''pkg/duit_attributes/''","Добавление функций виджета в ''pkg/duit_widget/''"],"ar":["تطبيق أدوات Flutter الجديدة لمكتبة Duit","إنشاء هيكل سلبية الأدوات المخصصة في ''pkg/duit_attributes/''","إضافة دوال الأداة في ''pkg/duit_widget/''"]},"limitations":{"en":["Requires Golang and Flutter setup","Specific to Duit Framework and Flutter development"],"zh":["需要Golang和Flutter设置","特定于Duit Framework和Flutter开发"],"ja":["GolangとFlutterの設定が必要","Duit FrameworkとFlutter開発に特有"],"ko":["Golang 및 Flutter 설정이 필요","Duit Framework 및 Flutter 개발에 특정"],"es":["Requiere configuración de Golang y Flutter","Específico del marco Duit y del desarrollo de Flutter"],"fr":["Nécessite une configuration Golang et Flutter","Spécifique au framework Duit et au développement Flutter"],"de":["Benötigt Golang- und Flutter-Setup","Spezifisch für das Duit-Framework und die Flutter-Entwicklung"],"pt":["Requer configuração do Golang e Flutter","Específico para o Framework Duit e desenvolvimento Flutter"],"ru":["Требует настройки Golang и Flutter","Специфичен для фреймворка Duit и разработки Flutter"],"ar":["يتطلب إعداد Golang و Flutter","محدد لإطار Duit و تطوير Flutter"]},"version":4},"contentHash":"4f45f85c80ccaf6e1aef72d967985a9612d49b7ee5395138b29f1ae6412324a9","qualityScore":36}');
