INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Duit-Foundation/duit_go/duit-maintainer', 'duit-maintainer', 'Duit-Foundation', 'duit_go', 'community', 'duit-maintainer Duit-Foundation duit_go community The duit-maintainer skill provides a Golang DSL for the Duit Framework, enabling developers to create custom Flutter widgets. It benefits developers working with Flutter and Duit. Duit Maintainer 是一个 Golang DSL，为 Duit 框架提供驱动 UI Tookit。它允许开发者快速实现新的 Flutter 小部件 Duit Maintainer は、Duit フレームワーク向けの駆動 UI Tookit を提供する Golang DSL です。開発者が新しい Flutter ウィジェットを迅速に実装できるようにします Duit Maintainer는 Duit 프레임워크용 드라이브 UI 툴킷을 제공하는 Golang DSL입니다. 개발자가 새로운 Flutter 위젯을 빠르게 구현할 수 있도록 합니다 Duit Maintainer es un DSL de Golang para el framework Duit, que permite crear herramientas de UI personalizadas para Flutter Duit Maintainer est un DSL Golang pour le framework Duit, permettant de créer des outils d''interface utilisateur personnalisés pour Flutter Duit Maintainer ist ein Golang-DSL für das Duit-Framework, mit dem benutzerdefinierte UI-Tools für Flutter erstellt werden können O Duit Maintainer é um DSL em Golang para o framework Duit, permitindo a criação de widgets personalizados para Flutter Duit Maintainer - это DSL на Golang для фреймворка Duit, позволяющий создавать кастомные виджеты для Flutter Duit Maintainer هو لغة تشغيلية في Golang لإطار Duit، مما يسمح بإنشاء أدوات تحكم مخصصة لFlutter how to use duit-maintainer duit-maintainer setup guide duit-maintainer alternative Golang DSL for Duit Framework Flutter widget implementation what is duit-maintainer duit-maintainer vs Flutter duit-maintainer install Duit Framework tutorial Duit Maintainer Golang DSL Flutter 小部件 驱动 UI Tookit Duit 框架 代码生成 属性结构 小部件类型 Creates attributes structure in pkg/duit_attributes/ Adds widget type to pkg/duit_core/element_type.go Generates code using the make gogen command Supports writing tests in pkg/duit_widget/ Implements widget functions in pkg/duit_widget/ duit-maintainer is a Golang DSL for the Duit Framework, used for creating and managing Flutter widgets');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jonsdoesch87-ai/craft-beer-wizard/color-consistency-checker', 'community', 'jonsdoesch87-ai', 'craft-beer-wizard', 'jonsdoesch87-ai/craft-beer-wizard', 'color-consistency-checker', 0, 0, 36, '2026-03-08T01:57:15.553Z', '2026-03-08T02:11:33.136Z', '0117afddca370397513a078bbe72094a6ebfa379a4629920204a83f3a4190197', '{"id":"jonsdoesch87-ai/craft-beer-wizard/color-consistency-checker","name":"color-consistency-checker","description":{"en":"The color-consistency-checker skill checks if colors are used consistently with the defined color scheme in Tailwind CSS projects, benefiting developers working with custom UI components.","zh":"颜色一致性检查器是一种工具，用于检查应用程序中的颜色是否与定义在tailwind.config.ts和app/globals.css中的官方色彩方案一致","ja":"色一致性チェッカーは、公式の色彩スキームと一致するアプリケーションの色を確認するツールです","ko":"색상 일관성 체커는 공식 색상 스키마와 일치하는 애플리케이션의 색상을 확인하는 도구입니다","es":"El verificador de coherencia de color es una herramienta que comprueba si los colores se utilizan de manera coherente con el esquema de colores definido","fr":"Le vérificateur de cohérence des couleurs est un outil qui vérifie si les couleurs sont utilisées de manière cohérente avec le schéma de couleurs défini","de":"Der Farb-Konsistenz-Prüfer ist ein Tool, das prüft, ob Farben konsistent mit dem Farbschema verwendet werden","pt":"O Color Consistency Checker é uma ferramenta que verifica a consistência das cores no seu projeto com Tailwind CSS.","ru":"ИИ Агент Color Consistency Checker - это инструмент, который проверяет согласованность цветов в вашем проекте с Tailwind CSS.","ar":"Color Consistency Checker هو أداة تتحقق من اتساق الألوان في مشروعك مع Tailwind CSS."},"seo":{"title":{"en":"color-consistency-checker: Tailwind CSS Color Validation ...","zh":"颜色一致性检查器Setup Guide","ja":"色一致性チェッカー ベストプラクティス","ko":"색상 일관성 체커 사용법","es":"Guía de configuración del verificador de coherencia de color","fr":"Guide de configuration du vérificateur de cohérence des c...","de":"Einrichtungsanleitung für den Farb-Konsistenz-Prüfer","pt":"Guia de Configuração do Color Consistency Checker","ru":"Настройка ИИ Агента Color Consistency Checker","ar":"دليل إعداد Color Consistency Checker"},"description":{"en":"Ensure consistent color usage in your Tailwind CSS projects with the color-consistency-checker skill - learn how to set it up and validate your colors today!","zh":"使用颜色一致性检查器确保您的应用程序中的颜色与官方色彩方案保持一致，提高用户体验","ja":"色一致性チェッカーを使用して、公式の色彩スキームと一致するアプリケーションの色を確認します","ko":"색상 일관성 체커를 사용하여 공식 색상 스키마와 일치하는 애플리케이션의 색상을 확인하세요","es":"Aprende a utilizar el verificador de coherencia de color para garantizar la consistencia de los colores en tu proyecto","fr":"Découvrez comment utiliser le vérificateur de cohérence des couleurs pour assurer la cohérence des couleurs dans votre projet","de":"Erfahren Sie, wie Sie den Farb-Konsistenz-Prüfer verwenden, um die Farbkonsequenz in Ihrem Projekt sicherzustellen","pt":"Aprenda a usar o Color Consistency Checker para garantir a consistência das cores no seu projeto com Tailwind CSS","ru":"Узнайте, как использовать ИИ Агент Color Consistency Checker для обеспечения согласованности цветов в вашем проекте с Tailwind CSS","ar":"تعرف على كيفية استخدام Color Consistency Checker لضمان الاتساق في الألوان في مشروعك مع Tailwind CSS"},"definition":{"en":"color-consistency-checker is a skill that validates color consistency in Tailwind CSS projects based on a predefined color scheme defined in tailwind.config.ts and app/globals.css","zh":"颜色一致性检查器是一种AIエージェント，用于检查应用程序中的颜色一致性","ja":"色一致性チェッカーは、AIエージェントの一種で、アプリケーションの色の一致性を確認する","ko":"색상 일관성 체커는 AI 도구의 일종으로 애플리케이션의 색상 일관성을 확인합니다","es":"Un verificador de coherencia de color es una herramienta que garantiza la consistencia de los colores en un proyecto","fr":"Un vérificateur de cohérence des couleurs est un outil qui assure la cohérence des couleurs dans un projet","de":"Ein Farb-Konsistenz-Prüfer ist ein Tool, das die Farbkonsequenz in einem Projekt sicherstellt","pt":"O que é Color Consistency Checker? É uma ferramenta que garante a consistência das cores no seu projeto.","ru":"Что такое ИИ Агент Color Consistency Checker? Это инструмент, обеспечивающий согласованность цветов в вашем проекте.","ar":"ما هو Color Consistency Checker؟ إنه أداة تضمن الاتساق في الألوان في مشروعك."},"features":{"en":["Checks color consistency against a predefined color scheme in tailwind.config.ts","Validates color usage based on Tailwind CSS classes such as primary, primary-hover, and primary-foreground","References app/globals.css for global CSS definitions","Supports custom color definitions in Hex format","Ensures consistent color usage for accents, buttons, links, and text"],"zh":["支持Tailwind CSS配置","检查颜色与官方色彩方案的一致性","使用Hex和Tailwind类名定义颜色","支持Primary、Primary Hover和Primary Foreground颜色","检查背景颜色和文本颜色的一致性"],"ja":["Tailwind CSSの設定をサポート","色と公式色彩スキームの一致性を確認","HexとTailwindクラス名で色を定義","Primary、Primary Hover、Primary Foreground色をサポート","背景色とテキスト色の一致性を確認"],"ko":["Tailwind CSS 설정 지원","색상과 공식 색상 스키마의 일관성을 확인","Hex와 Tailwind 클래스 이름으로 색상을 정의","Primary, Primary Hover, Primary Foreground 색상 지원","배경색과 텍스트 색상의 일관성을 확인"],"es":["Comprobación de la coherencia de colores con el esquema de colores definido en tailwind.config.ts","Verificación de la utilización de colores primarios y de fondo","Comprobación de la coherencia de colores en estados de hover","Utilización de la clase primary-foreground para textos sobre fondos primarios","Definición de colores personalizados en app/globals.css"],"fr":["Vérification de la cohérence des couleurs avec le schéma de couleurs défini dans tailwind.config.ts","Vérification de l''utilisation des couleurs primaires et de fond","Vérification de la cohérence des couleurs dans les états de hover","Utilisation de la classe primary-foreground pour les textes sur les fonds primaires","Définition de couleurs personnalisées dans app/globals.css"],"de":["Prüfung der Farbkonsequenz mit dem Farbschema in tailwind.config.ts","Prüfung der Verwendung von Primär- und Hintergrundfarben","Prüfung der Farbkonsequenz in Hover-Zuständen","Verwendung der Klasse primary-foreground für Texte auf Primärfarben","Definierung von benutzerdefinierten Farben in app/globals.css"],"pt":["Verifica a consistência das cores com o esquema de cores definido em `tailwind.config.ts`","Suporta a verificação de cores para botões, links e textos","USA a classe `primary` para estilos de botões e links","Verifica a consistência das cores de fundo e de texto","Integração com Tailwind CSS para garantir a consistência das cores"],"ru":["Проверяет согласованность цветов с цветовой схемой, определенной в `tailwind.config.ts`","Поддерживает проверку цветов для кнопок, ссылок и текста","Использует класс `primary` для стилей кнопок и ссылок","Проверяет согласованность цветов фона и текста","Интегрируется с Tailwind CSS для обеспечения согласованности цветов"],"ar":["يتحقق من الاتساق في الألوان مع مخطط الألوان المحدد في `tailwind.config.ts`","يدعم التحقق من الألوان لأزرار وروابط ونصوص","يستخدم الفئة `primary` لأسلوب الأزرار والروابط","يتحقق من الاتساق في الألوان الخلفية والنصية","يتكامل مع Tailwind CSS لضمان الاتساق في الألوان"]},"keywords":{"en":["how to use color-consistency-checker","color-consistency-checker setup guide","tailwind css color validation","color-consistency-checker vs stylelint","install color-consistency-checker","color-consistency-checker alternative","what is color-consistency-checker","color consistency in ui design","tailwind css best practices"],"zh":["颜色一致性检查器","AIエージェント","Tailwind CSS","色彩一致性","Hex颜色","Tailwind类名","Primary颜色","背景颜色"],"ja":["色一致性チェッカー","AIエージェント","Tailwind CSS","色の一致性","Hex色","Tailwindクラス名","Primary色","背景色"],"ko":["색상 일관성 체커","AI 도구","Tailwind CSS","색상 일관성","Hex 색상","Tailwind 클래스 이름","Primary 색상","배경색"],"es":["verificador de coherencia de color","herramientas de desarrollo","esquema de colores","tailwind config","colores personalizados","coherencia de colores","desarrollo web","diseño de interfaz de usuario"],"fr":["vérificateur de cohérence des couleurs","outils de développement","schéma de couleurs","tailwind config","couleurs personnalisées","cohérence des couleurs","développement web","conception d''interface utilisateur"],"de":["Farb-Konsistenz-Prüfer","Entwicklungstools","Farbschema","tailwind config","benutzerdefinierte Farben","Farbkonsequenz","Webentwicklung","Benutzeroberflächendesign"],"pt":["Color Consistency Checker","Tailwind CSS","esquema de cores","consistência de cores","ferramenta de desenvolvimento","desenvolvimento web","otimização de projeto","guias de estilo"],"ru":["ИИ Агент Color Consistency Checker","Tailwind CSS","цветовая схема","согласованность цветов","инструмент разработки","веб-разработка","оптимизация проекта","стиль кода"],"ar":["Color Consistency Checker","Tailwind CSS","مخطط الألوان","اتساق الألوان","أداة التطوير","تطوير الويب","تحسين المشروع","دليل الأسلوب"]}},"owner":"jonsdoesch87-ai","repo":"craft-beer-wizard","repoPath":"jonsdoesch87-ai/craft-beer-wizard","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.553Z","topics":[],"category":"community","skillMd":{"name":"color-consistency-checker","description":"Prüft die Farbkonsistenz im Projekt. Findet hardcoded Hex-Farben die durch Tailwind-Klassen ersetzt werden sollten. Verwende diesen Skill bei Code-Reviews, nach UI-Änderungen, oder wenn der User nach einer Farbprüfung fragt.","bodyPreview":"# Color Consistency Checker\n\nPrüft ob Farben konsistent mit dem Farbschema verwendet werden.\n\n## Offizielles Farbschema\n\nDefiniert in `tailwind.config.ts` und `app/globals.css`:\n\n| Farbe | Hex | Tailwind-Klasse | Verwendung |\n|-------|-----|-----------------|------------|\n| Primary | `#FFBF00` | `primary` | Akzente, Buttons, Links |\n| Primary Hover | `#E5AC00` | `primary/90` | Hover-States |\n| Primary Foreground | `#1a1a1a` | `primary-foreground` | Text auf Primary |\n| Background | `#1a1a1a` | `","body":"# Color Consistency Checker\n\nPrüft ob Farben konsistent mit dem Farbschema verwendet werden.\n\n## Offizielles Farbschema\n\nDefiniert in `tailwind.config.ts` und `app/globals.css`:\n\n| Farbe | Hex | Tailwind-Klasse | Verwendung |\n|-------|-----|-----------------|------------|\n| Primary | `#FFBF00` | `primary` | Akzente, Buttons, Links |\n| Primary Hover | `#E5AC00` | `primary/90` | Hover-States |\n| Primary Foreground | `#1a1a1a` | `primary-foreground` | Text auf Primary |\n| Background | `#1a1a1a` | `background` | Hintergrund |\n| Foreground | `#ededed` | `foreground` | Text |\n| Secondary | `#2a2a2a` | `secondary` | Sekundäre Elemente |\n| Muted | `#2a2a2a` | `muted` | Gedämpfte Bereiche |\n| Muted Foreground | `#a0a0a0` | `muted-foreground` | Gedämpfter Text |\n| Border | `#3a3a3a` | `border` | Rahmen |\n| Destructive | `#ef4444` | `destructive` | Fehler, Löschen |\n| Success | `#4CBB17` | `success` | Erfolg |\n| Ring | `#FFBF00` | `ring` | Focus-Ring |\n\n## Häufige Probleme\n\n### 1. Hardcoded Hex statt Tailwind-Klasse\n\n```tsx\n// ❌ Schlecht - hardcoded\nclassName=\"bg-[#FFBF00] text-black hover:bg-[#E5AC00]\"\nclassName=\"text-[#FFBF00]\"\nclassName=\"border-[#FFBF00]\"\n\n// ✅ Gut - Tailwind-Klassen\nclassName=\"bg-primary text-primary-foreground hover:bg-primary/90\"\nclassName=\"text-primary\"\nclassName=\"border-primary\"\n```\n\n### 2. Inkonsistente Hover-States\n\n```tsx\n// ❌ Verschiedene Hover-Farben\nhover:bg-[#E5AC00]  // manchmal\nhover:bg-[#d4a000]  // manchmal anders\n\n// ✅ Konsistent\nhover:bg-primary/90\n```\n\n### 3. Hardcoded Grautöne\n\n```tsx\n// ❌ Hardcoded\nbg-[#1a1a1a]\ntext-[#ededed]\nborder-[#3a3a3a]\n\n// ✅ Semantic\nbg-background\ntext-foreground\nborder-border\n```\n\n## Prüfungs-Workflow\n\n### Schritt 1: Finde hardcoded Farben\n\n```bash\n# Alle Hex-Farben in TSX/TS Dateien\nrg ''#[0-9A-Fa-f]{6}'' --type ts --type tsx -g ''!*.json''\n\n# Spezifisch Primary-Farbe\nrg ''#FFBF00|#ffbf00'' --type ts --type tsx\n\n# Bracket-Notation (Tailwind arbitrary values)\nrg ''\\[#[0-9A-Fa-f]{6}\\]'' --type ts --type tsx\n```\n\n### Schritt 2: Kategorisiere die Funde\n\n| Kategorie | Aktion |\n|-----------|--------|\n| `#FFBF00` in className | → `primary` |\n| `#E5AC00` in hover | → `primary/90` |\n| `#1a1a1a` Background | → `background` |\n| `#ededed` Text | → `foreground` |\n| `#3a3a3a` Border | → `border` |\n| `#ef4444` Error | → `destructive` |\n| `#4CBB17` Success | → `success` |\n| Andere Hex-Werte | → Prüfen ob notwendig |\n\n### Schritt 3: Ausnahmen identifizieren\n\nDiese hardcoded Farben sind **OK**:\n\n1. **EBC/SRM Bierfarben** in `RecipeCard.tsx`:\n   ```tsx\n   // Diese sind dynamisch berechnet!\n   if (srm < 4) return \"#F8F5D4\"; // Pale Straw\n   if (srm < 7) return \"#F3F993\"; // Gold\n   ```\n\n2. **Print Styles** in `RecipeCard.tsx`:\n   ```tsx\n   // Print braucht andere Farben\n   border-bottom: 2px solid #FFBF00;\n   ```\n\n3. **OG Images** in `app/api/og/`:\n   ```tsx\n   // Generierte Bilder, kein Tailwind\n   ```\n\n## Report-Format\n\n```markdown\n## Farbkonsistenz-Prüfung\n\n### 🔴 Kritisch (hardcoded Primary)\n| Datei | Zeile | Aktuell | Vorschlag |\n|-------|-------|---------|-----------|\n| Navbar.tsx | 42 | `bg-[#FFBF00]` | `bg-primary` |\n\n### 🟡 Empfohlen (andere hardcoded)\n| Datei | Zeile | Aktuell | Vorschlag |\n|-------|-------|---------|-----------|\n| Footer.tsx | 15 | `text-[#a0a0a0]` | `text-muted-foreground` |\n\n### ✅ Ausnahmen (OK)\n- RecipeCard.tsx: EBC Farben (dynamisch berechnet)\n- api/og/route.tsx: OG Image Generation\n```\n\n## Bekannte Dateien mit vielen Hardcoded Farben\n\nDiese Dateien haben besonders viele hardcoded Farben:\n\n- `app/cellar/page.tsx` - 13 Stellen\n- `components/RecipeCard.tsx` - 82 Stellen (viele OK wegen Print/EBC)\n- `components/BrewSession.tsx` - 110 Stellen\n- `components/WizardStep2.tsx` - 6 Stellen\n- `components/Navbar.tsx` - 22 Stellen\n\n## Ersetzungs-Regeln\n\n### Button Primary\n```tsx\n// ❌ Vorher\n<Button className=\"bg-[#FFBF00] text-black hover:bg-[#E5AC00]\">\n\n// ✅ Nachher\n<Button className=\"bg-primary text-primary-foreground hover:bg-primary/90\">\n```\n\n### Text Primary\n```tsx\n// ❌ Vorher\n<span className=\"text-[#FFBF00]\">\n\n// ✅ Nachher\n<span className=\"text-primary\">\n```\n\n### Tab Active State\n```tsx\n// ❌ Vorher\nclassName=\"data-[state=active]:bg-[#FFBF00] data-[state=active]:text-black\"\n\n// ✅ Nachher\nclassName=\"data-[state=active]:bg-primary data-[state=active]:text-primary-foreground\"\n```\n\n### Star/Rating\n```tsx\n// ❌ Vorher\nclassName={rating ? \"text-[#FFBF00] fill-[#FFBF00]\" : \"text-zinc-600\"}\n\n// ✅ Nachher\nclassName={rating ? \"text-primary fill-primary\" : \"text-muted-foreground\"}\n```\n"},"lastSynced":"2026-03-08T02:11:33.136Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents working with Tailwind CSS projects, ensuring color consistency across custom UI components.","zh":"非常适合与 Tailwind CSS 项目合作的前端代理，确保自定义 UI 组件的颜色一致性。","ja":"Tailwind CSS プロジェクトで作業するフロントエンド エージェントに最適で、カスタム UI コンポーネントの色の一貫性を確保します。","ko":"Tailwind CSS 프로젝트와 협력하는 프론트엔드 에이전트에게 적합하며, 사용자 지정 UI 컴포넌트의 색상 일관성을 보장합니다.","es":"Perfecto para Agentes Frontend que trabajan con proyectos Tailwind CSS, garantizando la consistencia del color en los componentes de la interfaz de usuario personalizados.","fr":"Parfait pour les agents Frontend travaillant sur des projets Tailwind CSS, assurant la cohérence des couleurs sur les composants d''interface utilisateur personnalisés.","de":"Perfekt für Frontend-Agents, die an Tailwind-CSS-Projekten arbeiten und so die Farbkonsequenz in benutzerdefinierten Benutzeroberflächenelementen sicherstellen.","pt":"Perfeito para Agentes Frontend que trabalham com projetos Tailwind CSS, garantindo a consistência de cores em componentes de UI personalizados.","ru":"Идеально подходит для агентов Frontend, работающих с проектами Tailwind CSS, обеспечивающих согласованность цвета в пользовательских компонентах интерфейса.","ar":"مثالي للوكلاء الأمامية الذين يعملون مع مشاريع Tailwind CSS، مما يضمن الاتساق في الألوان عبر مكونات الواجهة المستخدمة المخصصة."},"recommendation":{"en":"Empowers agents to enforce a defined color scheme, utilizing Tailwind CSS classes and configuration files like `tailwind.config.ts` and `app/globals.css`, to maintain visual consistency and brand identity.","zh":"赋予代理人执行定义的颜色方案的能力，利用 Tailwind CSS 类和配置文件，如 `tailwind.config.ts` 和 `app/globals.css`，以保持视觉一致性和品牌识别。","ja":"エージェントが定義された色彩スキームを適用する能力を提供し、`tailwind.config.ts` や `app/globals.css` などの Tailwind CSS クラスや設定ファイルを使用して、視覚的一貫性とブランド ID を維持します。","ko":"에이전트가 정의된 색상 스키마를 적용할 수 있는 기능을 제공하며, `tailwind.config.ts` 및 `app/globals.css`와 같은 Tailwind CSS 클래스 및 구성 파일을 사용하여 시각적 일관성 및 브랜드 ID를 유지합니다.","es":"Habilita a los agentes a aplicar un esquema de color definido, utilizando clases y archivos de configuración de Tailwind CSS como `tailwind.config.ts` y `app/globals.css`, para mantener la consistencia visual y la identidad de la marca.","fr":"Permet aux agents d''appliquer un schéma de couleur défini, en utilisant des classes et des fichiers de configuration de Tailwind CSS tels que `tailwind.config.ts` et `app/globals.css`, afin de maintenir la cohérence visuelle et l''identité de la marque.","de":"Ermöglicht es Agenten, ein definiertes Farbschema durchzusetzen, indem sie Tailwind-CSS-Klassen und Konfigurationsdateien wie `tailwind.config.ts` und `app/globals.css` verwenden, um so die visuelle Konsistenz und die Markenidentität aufrechtzuerhalten.","pt":"Habilita os agentes a impor um esquema de cores definido, utilizando classes Tailwind CSS e arquivos de configuração como `tailwind.config.ts` e `app/globals.css`, para manter a consistência visual e a identidade da marca.","ru":"Позволяет агентам реализовывать определенный цветовой схем, используя классы Tailwind CSS и файлы конфигурации, такие как `tailwind.config.ts` и `app/globals.css`, для поддержания визуальной согласованности и идентичности бренда.","ar":"تمكين الوكلاء من فرض مخطط ألوان محدد، باستخدام فئات Tailwind CSS وملفات التهيئة مثل `tailwind.config.ts` و `app/globals.css`، للحفاظ على الاتساق البصري وهوية العلامة التجارية."},"useCases":{"en":["Validating color usage in UI components against the official color scheme","Automating color consistency checks for new feature developments","Debugging inconsistent color applications in existing projects"],"zh":["验证 UI 组件中颜色的使用是否符合官方颜色方案","自动执行新功能开发的颜色一致性检查","调试现有项目中不一致的颜色应用"],"ja":["UI コンポーネントで使用されている色が公式の色彩スキームに準拠していることを検証する","新しい機能開発の色の一貫性チェックを自動化する","既存のプロジェクトで一貫性のない色の適用をデバッグする"],"ko":["UI 컴포넌트에서 색상 사용이 공식 색상 스키마와 일치하는지 확인","새로운 기능 개발의 색상 일관성 점검을 자동화","기존 프로젝트에서 일관되지 않은 색상 적용을 디버깅"],"es":["Validar el uso de colores en componentes de la interfaz de usuario frente al esquema de color oficial","Automatizar las comprobaciones de consistencia de color para nuevos desarrollos de funciones","Depurar aplicaciones de color inconsistentes en proyectos existentes"],"fr":["Valider l''utilisation des couleurs dans les composants d''interface utilisateur par rapport au schéma de couleur officiel","Automatiser les vérifications de cohérence des couleurs pour les nouveaux développements de fonctionnalités","Déboguer les applications de couleur incohérentes dans les projets existants"],"de":["Überprüfen der Farbnutzung in Benutzeroberflächenelementen gegen das offizielle Farbschema","Automatisieren von Farbkonsequenz-Prüfungen für neue Funktionsentwicklungen","Fehlersuche bei inkonsistenten Farbanwendungen in bestehenden Projekten"],"pt":["Validar o uso de cores em componentes de UI contra o esquema de cores oficial","Automatizar verificações de consistência de cores para desenvolvimentos de recursos novos","Depurar aplicações de cores inconsistentes em projetos existentes"],"ru":["Проверять использование цвета в компонентах интерфейса против официального цветового схем","Автоматизировать проверки согласованности цвета для новых разработок функций","Отлаживать несогласованные применения цвета в существующих проектах"],"ar":["التحقق من استخدام الألوان في مكونات الواجهة ضد مخطط الألوان الرسمي","توفير تلقائي لفحوصات الاتساق في الألوان لتحديثات الميزات الجديدة","تصحيح تطبيقات الألوان غير المتسقة في المشاريع الحالية"]},"limitations":{"en":["Requires access to Tailwind CSS project configuration files","Limited to projects using Tailwind CSS framework","Needs predefined color scheme definitions in `tailwind.config.ts` and `app/globals.css`"],"zh":["需要访问 Tailwind CSS 项目配置文件","仅限于使用 Tailwind CSS 框架的项目","需要在 `tailwind.config.ts` 和 `app/globals.css` 中预定义颜色方案"],"ja":["Tailwind CSS プロジェクトの設定ファイルへのアクセスが必要","Tailwind CSS フレームワークを使用するプロジェクトのみ","`tailwind.config.ts` および `app/globals.css` に色彩スキームを事前に定義する必要がある"],"ko":["Tailwind CSS 프로젝트 구성 파일에 접근할 수 있어야 함","Tailwind CSS 프레임워크를 사용하는 프로젝트만 해당","`tailwind.config.ts` 및 `app/globals.css`에 색상 스키마를 미리 정의해야 함"],"es":["Requiere acceso a los archivos de configuración del proyecto Tailwind CSS","Limitado a proyectos que utilizan el framework Tailwind CSS","Necesita definiciones de esquemas de color preestablecidas en `tailwind.config.ts` y `app/globals.css`"],"fr":["Nécessite un accès aux fichiers de configuration du projet Tailwind CSS","Limité aux projets utilisant le framework Tailwind CSS","Nécessite des définitions de schémas de couleur prédéfinies dans `tailwind.config.ts` et `app/globals.css`"],"de":["Erfordert Zugriff auf die Konfigurationsdateien des Tailwind-CSS-Projekts","Begrenzt auf Projekte, die das Tailwind-CSS-Framework verwenden","Benötigt vordefinierte Farbschemadefinitionen in `tailwind.config.ts` und `app/globals.css`"],"pt":["Exige acesso a arquivos de configuração do projeto Tailwind CSS","Limitado a projetos que usam o framework Tailwind CSS","Necessita de definições de esquema de cores predefinidas em `tailwind.config.ts` e `app/globals.css`"],"ru":["Требует доступа к файлам конфигурации проекта Tailwind CSS","Ограничен проектами, использующими фреймворк Tailwind CSS","Требует предопределенных определений цветового схем в `tailwind.config.ts` и `app/globals.css`"],"ar":["يتطلب الوصول إلى ملفات تكوين مشروع Tailwind CSS","محدود بمشاريع التي تستخدم إطار Tailwind CSS","يحتاج إلى تعريفات مخطط الألوان المحددة مسبقا في `tailwind.config.ts` و `app/globals.css`"]},"version":4},"contentHash":"0117afddca370397513a078bbe72094a6ebfa379a4629920204a83f3a4190197","qualityScore":36}');
