INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jonsdoesch87-ai/craft-beer-wizard/color-consistency-checker', 'color-consistency-checker', 'jonsdoesch87-ai', 'craft-beer-wizard', 'community', 'color-consistency-checker jonsdoesch87-ai craft-beer-wizard community The color-consistency-checker skill checks if colors are used consistently with the defined color scheme in Tailwind CSS projects, benefiting developers working with custom UI components. 颜色一致性检查器是一种工具，用于检查应用程序中的颜色是否与定义在tailwind.config.ts和app/globals.css中的官方色彩方案一致 色一致性チェッカーは、公式の色彩スキームと一致するアプリケーションの色を確認するツールです 색상 일관성 체커는 공식 색상 스키마와 일치하는 애플리케이션의 색상을 확인하는 도구입니다 El verificador de coherencia de color es una herramienta que comprueba si los colores se utilizan de manera coherente con el esquema de colores definido Le vérificateur de cohérence des couleurs est un outil qui vérifie si les couleurs sont utilisées de manière cohérente avec le schéma de couleurs défini Der Farb-Konsistenz-Prüfer ist ein Tool, das prüft, ob Farben konsistent mit dem Farbschema verwendet werden O Color Consistency Checker é uma ferramenta que verifica a consistência das cores no seu projeto com Tailwind CSS. ИИ Агент Color Consistency Checker - это инструмент, который проверяет согласованность цветов в вашем проекте с Tailwind CSS. Color Consistency Checker هو أداة تتحقق من اتساق الألوان في مشروعك مع Tailwind CSS. how to use color-consistency-checker color-consistency-checker setup guide tailwind css color validation color-consistency-checker vs stylelint install color-consistency-checker color-consistency-checker alternative what is color-consistency-checker color consistency in ui design tailwind css best practices 颜色一致性检查器 AIエージェント Tailwind CSS 色彩一致性 Hex颜色 Tailwind类名 Primary颜色 背景颜色 Checks color consistency against a predefined color scheme in tailwind.config.ts Validates color usage based on Tailwind CSS classes such as primary, primary-hover, and primary-foreground References app/globals.css for global CSS definitions Supports custom color definitions in Hex format Ensures consistent color usage for accents, buttons, links, and text color-consistency-checker is a skill that validates color consistency in Tailwind CSS projects based on a predefined color scheme defined in tailwind.config.ts and app/globals.css');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bybren-llc/story-systems-template/logline', 'community', 'bybren-llc', 'story-systems-template', 'bybren-llc/story-systems-template', 'logline', 0, 0, 36, '2026-03-08T01:57:15.564Z', '2026-03-08T02:11:39.019Z', 'f5f7c6ddd66ddb52c6183af56bf90a5a44f9919f353266c2e9a6030fb710a429', '{"id":"bybren-llc/story-systems-template/logline","name":"logline","description":{"en":"The logline skill helps developers and creators distill their stories to a one-sentence hook, preparing pitch materials and testing concept clarity. It''s ideal for screenwriters, novelists, and filmmakers.","zh":"logline 是一个用于创建引人入胜的剧情简介的 AI Éージェント，帮助您将故事浓缩成一两句话","ja":"logline は、映画や小説のコンセプトを明確にする AI エージェントで、ストーリーを一兩句话に凝縮する","ko":"logline 은 스크린플레이 및 소설을 위한 AI 에이전트로 스토리를 핵심적인 한두 문장으로 요약합니다","es":"Logline es una plantilla de proyecto creativo para guiones, novelas y producción de películas con capacidades de sincronización multi-AI","fr":"Logline est un modèle de projet créatif pour scénarios, romans et production de films avec des capacités de synchronisation multi-AI","de":"Logline ist eine Vorlage für kreative Projekte für Drehbücher, Romane und Filmproduktion mit Multi-AI-Synchronisierungsfunktionen","pt":"O logline é uma descrição de uma ou duas frases que captura a essência da história, tornando-a atraente para o público. Aprenda a aplicá-lo em seus projetos","ru":"Логлайн - это одно- или двухпредложное описание, которое захватывает суть истории, делая ее привлекательной для зрителей. Узнайте, как применить его в ваших проектах с помощью ИИ Агентов","ar":"لوغلاين هو وصف قصير بطريقة واحدة أو عدة جمل يلخص جوهر القصة بطريقة تجذب الجمهور. تعلم كيفية تطبيقه في مشاريعك"},"seo":{"title":{"en":"Logline: Creative Project Template Setup Guide | AI Agent...","zh":"logline 设置指南：使用 AI Éージェント 为您的剧本创建引人入胜的剧情简介","ja":"logline セットアップガイド：映画や小説のコンセプトを明確にする AI 