INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bybren-llc/story-systems-template/logline', 'logline', 'bybren-llc', 'story-systems-template', 'community', 'logline bybren-llc story-systems-template community The logline skill helps developers and creators distill their stories to a one-sentence hook, preparing pitch materials and testing concept clarity. It''s ideal for screenwriters, novelists, and filmmakers. logline 是一个用于创建引人入胜的剧情简介的 AI Éージェント，帮助您将故事浓缩成一两句话 logline は、映画や小説のコンセプトを明確にする AI エージェントで、ストーリーを一兩句话に凝縮する logline 은 스크린플레이 및 소설을 위한 AI 에이전트로 스토리를 핵심적인 한두 문장으로 요약합니다 Logline es una plantilla de proyecto creativo para guiones, novelas y producción de películas con capacidades de sincronización multi-AI Logline est un modèle de projet créatif pour scénarios, romans et production de films avec des capacités de synchronisation multi-AI Logline ist eine Vorlage für kreative Projekte für Drehbücher, Romane und Filmproduktion mit Multi-AI-Synchronisierungsfunktionen O logline é uma descrição de uma ou duas frases que captura a essência da história, tornando-a atraente para o público. Aprenda a aplicá-lo em seus projetos Логлайн - это одно- или двухпредложное описание, которое захватывает суть истории, делая ее привлекательной для зрителей. Узнайте, как применить его в ваших проектах с помощью ИИ Агентов لوغلاين هو وصف قصير بطريقة واحدة أو عدة جمل يلخص جوهر القصة بطريقة تجذب الجمهور. تعلم كيفية تطبيقه في مشاريعك how to use logline what is logline logline alternative logline vs screenplay summary logline install logline setup guide creative project template screenplay pitch materials story hook generation logline AI Éージェント 剧情简介生成 电影剧本 小说创作 WTFB 方法论 多个 AI 模型 上游同步 实时更新 Applies WTFB methodology for effective hooks Contains four essential components for a compelling logline Supports upstream sync for multi-AI harness Enables testing of concept clarity and marketing of screenplays logline is a one to two sentence description of a movie or story that captures its essence and makes people want to see it');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bravegeek/ai-workshop/hugo-publisher', 'community', 'bravegeek', 'ai-workshop', 'bravegeek/ai-workshop', 'hugo-publisher', 0, 0, 36, '2026-03-08T01:57:15.574Z', '2026-03-08T02:11:48.221Z', '8fd4e76c3cf24b40fab2364e4cd2b31e8afb10330f7b18019eec01ba4ae497b2', '{"id":"bravegeek/ai-workshop/hugo-publisher","name":"hugo-publisher","description":{"en":"The hugo-publisher skill automates the process of publishing articles to Hugo-based websites, handling tasks such as frontmatter metadata generation and content formatting. It benefits developers and content creators working with Hugo static sites.","zh":"Hugo Publisher 是一个帮助用户将文章内容发布到 Hugo 静态网站的工具，支持格式化、元数据和文件结构","ja":"Hugo Publisher は、Hugo 静的サイトに記事の内容を公開するためのツールです。形式、メタデータ、ファイル構造をサポート","ko":"Hugo Publisher는 Hugo 정적 사이트에 기사 내용을 게시하는 도구입니다. 형식, 메타데이터, 파일 구조를 지원합니다","es":"El agente de publicación de Hugo es una herramienta para publicar artículos en sitios web estáticos con formato y metadatos adecuados. Proporciona una estructura de directorios correcta y gestiona referencias de imágenes","fr":"L''agent de publication de Hugo est un outil pour publier des articles sur des sites web statiques avec un format et des métadonnées appropriés. Il fournit une structure de répertoire correcte et gère les références d''images","de":"Der Hugo-Veröffentlichungsagent ist ein Tool zum Veröffentlichen von Artikeln auf statischen Websites mit geeigneten Formatierungen und Metadaten. Es bietet eine korrekte Verzeichnisstruktur und verwaltet Bildreferenzen","pt":"O Hugo Publisher é um agente que ajuda a publicar artigos em sites estáticos com formatação e metadados adequados","ru":"ИИ Агент Hugo Publisher помогает публиковать статьи на статических сайтах с правильной форматировкой и метаданными","ar":"يعمل Hugo Publisher كعامل في نشر المقالات على المواقع الثابتة مع تنسيق وبيانات وصفية مناسبة"},"seo":{"title":{"en":"hugo-publisher: Automated Hugo Site Deployment | AI Agent...","zh":"Hugo Publisher 设置指南：静态网站发布最佳实践","ja":"Hugo Publisher の設定方法：静的サイトへの記事公開のベストプラクティス","ko":"Hugo Publisher 설정 가이드: 정적 사이트에 기사 게시하기","es":"Guía de configuración de Hugo Publisher para sitios web e...","fr":"Guide de mise en place de Hugo Publisher pour les sites w...","de":"Einrichtungsanleitung für Hugo Publisher für statische We...","pt":"Guia de Configuração do Hugo Publisher para Desenvolvedores","ru":"Настройка ИИ Агента Hugo Publisher: Руководство для Разра...","ar":"دليل إعداد Hugo Publisher لمنشئي التطبيقات"},"description":{"en":"Discover how to streamline your Hugo site publishing with the hugo-publisher skill. Learn more and get started with automated frontmatter generation and dire...","zh":"学习如何使用 Hugo Publisher 将文章内容发布到 Hugo 静态网站，包括格式化、元数据和文件结构","ja":"Hugo Publisher を使用して、記事の内容を Hugo 静的サイトに公開する方法を学びます。形式、メタデータ、ファイル構造など","ko":"Hugo Publisher를 사용하여 기사 내용을 Hugo 정적 사이트에 게시하는 방법을 배워보세요. 형식, 메타데이터, 파일 구조 등","es":"Aprende a publicar artículos en sitios web basados en Hugo con el agente de publicación de Hugo, incluyendo metadatos, estructura de directorios y formatos d...","fr":"Découvrez comment publier des articles sur des sites web basés sur Hugo avec l''agent de publication de Hugo, y compris les métadonnées, la structure de réper...","de":"Erfahren Sie, wie Sie Artikel auf Hugo-basierten Websites mit dem Hugo-Veröffentlichungsagenten veröffentlichen, einschließlich Metadaten, Verzeichnisstruktu...","pt":"Aprenda a configurar o Hugo Publisher para publicar artigos em sites estáticos com formatação e metadados adequados","ru":"Узнайте, как настроить ИИ Агент Hugo Publisher для публикации статей на статических сайтах с правильной форматировкой и метаданными","ar":"تعلم كيفية إعداد Hugo Publisher لنشر المقالات على المواقع الثابتة مع تنسيق وبيانات وصفية مناسبة"},"definition":{"en":"hugo-publisher is an AI agent skill responsible for automating the deployment of articles to Hugo static sites, ensuring proper formatting and metadata.","zh":"Hugo Publisher 是一个 AI 工具，帮助用户将文章内容发布到 Hugo 静态网站","ja":"Hugo Publisher は、Hugo 静的サイトに記事の内容を公開するための AI エージェント","ko":"Hugo Publisher는 Hugo 정적 사이트에 기사 내용을 게시하는 AI 도구","es":"El agente de publicación de Hugo es una herramienta de publicación de sitios web estáticos que ayuda a los usuarios a publicar artículos con metadatos, estructura de directorios y formatos de contenido adecuados","fr":"L''agent de publication de Hugo est un outil de publication de sites web statiques qui aide les utilisateurs à publier des articles avec des métadonnées, une structure de répertoire et des formats de contenu appropriés","de":"Der Hugo-Veröffentlichungsagent ist ein Tool für die Veröffentlichung statischer Websites, das Benutzern hilft, Artikel mit Metadaten, Verzeichnisstruktur und Inhaltsformaten zu veröffentlichen","pt":"O que é Hugo Publisher? Um agente que publica artigos em sites estáticos com formatação e metadados","ru":"Что такое ИИ Агент Hugo Publisher? Агент, который публикует статьи на статических сайтах с метаданными","ar":"ما هو Hugo Publisher؟ عامل ينشر المقالات على المواقع الثابتة مع بيانات وصفية"},"features":{"en":["Generates proper Hugo frontmatter metadata","Creates the correct directory structure for Hugo sites","Formats content according to Hugo conventions","Manages image references and prompts for seamless integration","Provides publishing workflow guidance for efficient deployment"],"zh":["生成适合 Hugo 的前置元数据","创建正确的目录结构","使用 Hugo 约定格式化内容","管理图像引用和提示","提供发布工作流指南"],"ja":["Hugo に適したフロントマターのメタデータを生成","正しいディレクトリ構造を作成","Hugo の規約に従ってコンテンツを書式設定","画像参照とプロンプトを管理","公開ワークフローのガイダンスを提供"],"ko":["Hugo에 적합한 프론티어 메타데이터 생성","정확한 디렉토리 구조 생성","Hugo 규약에 따라 콘텐츠 형식화","이미지 참조 및 프롬프트 관리","게시 워크플로우 지침 제공"],"es":["Generación de metadatos de frontmatter de Hugo","Creación de estructura de directorios correcta","Formato de contenido con convenciones de Hugo","Gestión de referencias de imágenes y solicitudes","Guía de flujo de trabajo de publicación"],"fr":["Génération de métadonnées de frontmatter de Hugo","Création de structure de répertoire correcte","Formatage de contenu avec des conventions de Hugo","Gestion des références d''images et des requêtes","Guide de flux de travail de publication"],"de":["Generierung von Hugo-Frontmatter-Metadaten","Erstellung einer korrekten Verzeichnisstruktur","Formatierung von Inhalten mit Hugo-Konventionen","Verwaltung von Bildreferenzen und Anfragen","Leitfaden für den Veröffentlichungsworkflow"],"pt":["Geração de metadados frontmatter do Hugo","Criação da estrutura de diretórios correta","Formatação de conteúdo com convenções do Hugo","Gerenciamento de referências e prompts de imagem","Orientação do fluxo de trabalho de publicação"],"ru":["Генерация метаданных frontmatter для Hugo","Создание правильной структуры директорий","Форматирование контента с использованием конвенций Hugo","Управление ссылками и подсказками изображений","Руководство по рабочему процессу публикации"],"ar":["توليد بيانات وصفية frontmatter لهوجو","إنشاء هيكل دليل صحيح","تنسيق المحتوى باستخدام الاتفاقيات هوجو","إدارة المراجع وملحوظات الصور","توجيه سير عمل النشر"]},"keywords":{"en":["how to use hugo-publisher","hugo-publisher setup guide","hugo static site deployment","hugo frontmatter generation","automated hugo site publishing","hugo-publisher alternative","hugo-publisher vs other deployment tools","hugo-publisher install","hugo-publisher documentation"],"zh":["Hugo Publisher","Hugo 静态网站","文章发布","格式化","元数据","文件结构","AI 工具","静态网站生成"],"ja":["Hugo Publisher","Hugo 静的サイト","記事公開","形式","メタデータ","ファイル構造","AI エージェント","静的サイト生成"],"ko":["Hugo Publisher","Hugo 정적 사이트","기사 게시","형식","메타데이터","파일 구조","AI 도구","정적 사이트 생성"],"es":["hugo publisher","sitios web estáticos","metadatos de frontmatter","estructura de directorios","formato de contenido","gestión de imágenes","flujo de trabajo de publicación","herramientas de publicación de sitios web","agentes de publicación de AI"],"fr":["hugo publisher","sites web statiques","métadonnées de frontmatter","structure de répertoire","formatage de contenu","gestion d''images","flux de travail de publication","outils de publication de sites web","agents de publication d''IA"],"de":["hugo publisher","statische Websites","Frontmatter-Metadaten","Verzeichnisstruktur","Inhaltsformatierung","Bildverwaltung","Veröffentlichungsworkflow","Website-Veröffentlichungstools","KI-Veröffentlichungsagenten"],"pt":["hugo publisher","publicar artigos em sites estáticos","formatação de conteúdo","metadados frontmatter","fluxo de trabalho de publicação","desenvolvedores web","hugo static site"],"ru":["ИИ Агент Hugo Publisher","публикация статей на статических сайтах","форматирование контента","метаданные frontmatter","рабочий процесс публикации","разработчики веб-приложений","hugo статический сайт"],"ar":["هوجو ناشر","نشر المقالات على المواقع الثابتة","تنسيق المحتوى","بيانات وصفية frontmatter","سير عمل النشر","مطورو التطبيقات","موقع هوجو الثابت"]}},"owner":"bravegeek","repo":"ai-workshop","repoPath":"bravegeek/ai-workshop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.574Z","topics":[],"category":"community","skillMd":{"name":"hugo-publisher","description":"Agent for publishing articles to Hugo static sites. Handles metadata generation, directory creation, and Hugo file structure for The Aiglet and other Hugo sites.","bodyPreview":"You are the Hugo Publisher, responsible for taking article content and publishing it to a Hugo static site with proper formatting, metadata, and file structure.\n\n## Your Role\n\nYou help users publish articles to Hugo-based websites by:\n- Generating proper Hugo frontmatter metadata\n- Creating the correct directory structure\n- Formatting content with Hugo conventions\n- Managing image references and prompts\n- Providing publishing workflow guidance\n\n## CRITICAL PROTOCOL - READ BEFORE PROCEEDING\n\n**YO","body":"You are the Hugo Publisher, responsible for taking article content and publishing it to a Hugo static site with proper formatting, metadata, and file structure.\n\n## Your Role\n\nYou help users publish articles to Hugo-based websites by:\n- Generating proper Hugo frontmatter metadata\n- Creating the correct directory structure\n- Formatting content with Hugo conventions\n- Managing image references and prompts\n- Providing publishing workflow guidance\n\n## CRITICAL PROTOCOL - READ BEFORE PROCEEDING\n\n**YOU MUST STOP AND WAIT FOR USER APPROVAL AFTER GENERATING METADATA.**\n\n1. **DO NOT** create any files or directories until the user has explicitly approved the metadata (title, slug, date, tags).\n2. Present the plan (metadata) and ask \"Shall I proceed?\"\n3. Only AFTER the user says \"yes\" or approves should you execute the file creation commands.\n\n## Publishing Workflow\n\n### Phase 1: Gather Information\n\nIf not already provided, ask the user for:\n\n1. **Article content** - The full article text\n2. **Article title** - The headline\n3. **Hugo site path** - Where to publish (default: `/home/greg/dev/theaiglet/content/posts/`)\n4. **Image prompt** (optional) - For img-prompt frontmatter field\n5. **Additional metadata** (optional):\n   - Tags\n   - Description/summary\n   - Custom date/time\n   - Draft status\n\n**Be efficient:** If the user provides article content with an obvious title, don''t ask for the title separately. Extract it from the content.\n\n### Phase 2: Generate Metadata\n\n1. **Generate all required metadata:**\n   - **Date:** Current date/time in format `YYYY-MM-DDTHH:MM:SS-04:00` (Eastern Time)\n   - **Title:** The article headline\n   - **Slug:** URL-friendly version of title (lowercase, hyphens, no special chars)\n   - **Directory name:** `YYYY-MM-DD-slug` (e.g., `2025-11-16-mandatory-fun-policy`)\n   - **Image filename:** Descriptive, URL-friendly (e.g., `article-topic.jpg`)\n   - **Alt text:** Brief description for accessibility\n   - **Tags:** 2-4 relevant tags (auto-generate if not provided)\n   - **Description:** 1-2 sentence summary for SEO/previews (extract from article if not provided)\n\n2. **Offer metadata alternatives:**\n   - Suggest 2-3 alternative headline variations if applicable\n   - Suggest alternative tags or additional tags to consider\n   - Suggest punchier description options for social sharing\n   - Example: \"Alternative slug: ''google-gift-texas-higher-bills''\"\n\n3. **STOP AND ASK FOR APPROVAL:**\n   - Show all metadata and ask: \"Does everything look good, or would you like to use any alternative options?\"\n   - **DO NOT PROCEED** until the user approves.\n\n### Phase 3: Create Hugo Files\n\n1. **Check if directory already exists:**\n   - If exists, inform user and ask how to proceed (overwrite, rename, cancel)\n\n2. **Create directory structure:**\n   ```\n   [hugo-site-path]/YYYY-MM-DD-slug/\n   ```\n\n3. **Create index.md** with proper frontmatter:\n   ```toml\n   +++\n   date = ''YYYY-MM-DDTHH:MM:SS-04:00''\n   type = ''posts''\n   draft = false\n   title = ''Article Title Here''\n   slug = ''article-slug-here''\n   image = ''image-filename.jpg''\n   alt = ''Alt text description''\n   tags = [''tag1'', ''tag2'', ''tag3'']\n   description = \"Brief description here\"\n   img-prompt = \"The full image prompt here (if provided)\"\n   +++\n   ```\n\n4. **Add the article content** below the frontmatter\n\n5. **Handle special formatting:**\n   - Ensure location lines are in ALL CAPS bold (e.g., \"**WASHINGTON, D.C.**\")\n   - Preserve paragraph breaks and formatting\n   - Handle quotes, emphasis, and other markdown properly\n\n### Phase 4: Post-Publishing\n\n1. **Inform user of what was created:**\n   - Full path to the created directory\n   - Full path to index.md\n   - Summary of metadata used\n\n2. **Provide next steps:**\n   - If image prompt provided: \"Generate the image using this prompt and save as `[directory]/[image-filename]`\"\n   - Hugo preview: \"Run `hugo server` or `hugo server -D` to preview\"\n   - Git workflow: \"Don''t forget to commit and push when ready\"\n   - Build/deploy: Mention any build or deployment steps if applicable\n\n3. **Offer workflow tips:**\n   - Mention shortcuts or optimizations\n   - Suggest related tasks (e.g., \"Want to add this to your ideas tracking?\")\n\n## Important Guidelines\n\n- **Be efficient:** Don''t ask for information that can be inferred from context\n- **Be flexible:** Adapt to different Hugo site structures and requirements\n- **Validate paths:** Check that target directories exist before creating files\n- **Handle errors gracefully:** If files exist or something fails, inform user clearly and suggest alternatives\n- **Follow Hugo conventions:** Use proper frontmatter format, file structure, and naming\n- **Preserve formatting:** Maintain the article''s original formatting and style\n- **Be helpful:** Suggest next steps and workflow improvements\n- **Support multiple sites:** Don''t assume The Aiglet - ask for Hugo site path if unclear\n\n## Default Paths\n\n- **Default Hugo site:** `/home/greg/dev/theaiglet/content/posts/`\n- **Default timezone:** Eastern Time (-04:00 or -05:00 depending on DST)\n\n## Frontmatter Fields\n\nThe standard Hugo frontmatter for The Aiglet includes:\n- `date` - Publication date/time (required)\n- `type` - Content type, usually ''posts'' (required)\n- `draft` - Draft status, true/false (required)\n- `title` - Article headline (required)\n- `slug` - URL slug (required)\n- `image` - Image filename (required)\n- `alt` - Image alt text (required)\n- `tags` - Array of tags (required)\n- `description` - SEO/social description (required)\n- `img-prompt` - Image generation prompt (optional)\n\n## Starting the Session\n\nWhen the user invokes this agent:\n1. Check what information they''ve already provided\n2. Ask for any missing required information\n3. Proceed with metadata generation\n4. **STOP** and wait for user approval\n5. Create the Hugo files ONLY after approval\n6. Provide next steps\n\nLet''s get this published!\n\n---\n\n## Communication Style\n\n**Read and apply:** `.gemini/shared/no-flatter-mode.md`\n"},"lastSynced":"2026-03-08T02:11:48.221Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents needing automated Hugo static site publishing capabilities.","zh":"适合需要自动化Hugo静态网站发布功能的内容创建代理。","ja":"Hugo静的サイトの自動公開機能が必要なコンテンツ作成エージェントに適しています。","ko":"Hugo 정적 사이트 자동 공개 기능이 필요한 콘텐츠 생성 에이전트에 적합합니다.","es":"Perfecto para Agentes de Creación de Contenido que necesitan capacidades de publicación automatizada de sitios web estáticos de Hugo.","fr":"Parfait pour les agents de création de contenu nécessitant des capacités de publication automatique de sites web statiques Hugo.","de":"Perfekt für Content Creation Agents, die automatisierte Hugo-Static-Site-Veröffentlichungsfunktionen benötigen.","pt":"Perfeito para Agentes de Criação de Conteúdo que necessitam de capacidades de publicação de sites estáticos Hugo automatizadas.","ru":"Идеально подходит для агентов по созданию контента, которым необходимы автоматические возможности публикации статических сайтов Hugo.","ar":"مثالي للوكلاء الذين يحتاجون إلى قدرات نشر موقع هوغو الثابت آليًا"},"recommendation":{"en":"Empowers agents to generate proper Hugo frontmatter metadata, create correct directory structures, and format content with Hugo conventions, streamlining the publishing workflow with features like image reference management and protocol guidance, all utilizing Hugo-specific file formats and protocols.","zh":"赋予代理生成适当的Hugo前置元数据，创建正确的目录结构，并使用Hugo约定格式化内容，从而通过功能如图像引用管理和协议指南来简化发布工作流程，所有这些都利用Hugo特定的文件格式和协议。","ja":"エージェントに適切なHugoフロントマターのメタデータを生成し、正しいディレクトリ構造を作成し、Hugoの規約に従ってコンテンツをフォーマットすることを可能にし、画像参照の管理やプロトコルのガイダンスなどの機能を使用して公開ワークフローをストリームライン化し、すべてHugo固有的ファイル形式とプロトコルを利用します。","ko":"에이전트가 적절한 Hugo 전면 메타데이터를 생성하고 올바른 디렉토리 구조를 만들고 Hugo 규약에 따라 콘텐츠를 형식화할 수 있도록 하여 이미지 참조 관리 및 프로토콜 가이드와 같은 기능을 사용하여 게시 워크플로를 간소화하고 모든 Hugo 고유의 파일 형식 및 프로토콜을 활용합니다.","es":"Habilita a los agentes a generar metadatos de frontmatter de Hugo adecuados, crear estructuras de directorios correctas y dar formato al contenido con convenciones de Hugo, simplificando el flujo de trabajo de publicación con características como gestión de referencias de imágenes y orientación de protocolo, todo utilizando formatos de archivo y protocolos específicos de Hugo.","fr":"Permet aux agents de générer des métadonnées de frontmatter de Hugo appropriées, de créer des structures de répertoires correctes et de formater le contenu selon les conventions de Hugo, en simplifiant le flux de travail de publication avec des fonctionnalités telles que la gestion des références d''images et l''orientation du protocole, le tout en utilisant des formats de fichiers et des protocoles spécifiques à Hugo.","de":"Ermächtigt Agenten, ordnungsgemäße Hugo-Frontmatter-Metadaten zu generieren, richtige Verzeichnisstrukturen zu erstellen und Inhalte mit Hugo-Konventionen zu formatieren, wodurch der Veröffentlichungsworkflow mit Funktionen wie Bildverweisverwaltung und Protokollführung vereinfacht wird, und zwar unter Verwendung von Hugo-spezifischen Dateiformaten und Protokollen.","pt":"Habilita os agentes a gerar metadados de frontmatter apropriados do Hugo, criar estruturas de diretório corretas e formatar o conteúdo de acordo com as convenções do Hugo, simplificando o fluxo de trabalho de publicação com recursos como gerenciamento de referências de imagens e orientação de protocolo, tudo utilizando formatos de arquivo e protocolos específicos do Hugo.","ru":"Наделяет агентов возможностью генерировать правильные метаданные frontmatter Hugo, создавать правильную структуру директорий и форматировать контент в соответствии с конвенциями Hugo, оптимизируя рабочий процесс публикации с помощью функций, таких как управление ссылками на изображения и руководство по протоколам, все это при помощи форматов файлов и протоколов, специфичных для Hugo.","ar":"تمكّن الوكلاء من توليد بيانات وصفية أمامية مناسبة لهوغو، وخلق هياكل 目錄 صحيحة، وتشكيل المحتوى وفقًا لاتفاقيات هوغو، وبذلك تسهيل سير عمل النشر بميزات مثل إدارة المراجع الصورية وإرشادات البروتوكول، وكل ذلك باستخدام تنسيقات الملفات والبروتوكولات المحددة لهوغو"},"useCases":{"en":["Automating article publishing to Hugo-based websites","Generating frontmatter metadata for Hugo posts","Formatting content according to Hugo conventions"],"zh":["自动将文章发布到基于Hugo的网站","为Hugo帖子生成前置元数据","根据Hugo约定格式化内容"],"ja":["Hugoベースのウェブサイトへの記事の自動公開","Hugo投稿のフロントマターのメタデータを生成する","Hugoの規約に従ってコンテンツをフォーマットする"],"ko":["Hugo 기반 웹사이트에 기사의 자동 게시","Hugo 게시물의 전면 메타데이터 생성","Hugo 규약에 따라 콘텐츠 형식화"],"es":["Automatizar la publicación de artículos en sitios web basados en Hugo","Generar metadatos de frontmatter para publicaciones de Hugo","Dar formato al contenido según las convenciones de Hugo"],"fr":["Automatiser la publication d''articles sur des sites web basés sur Hugo","Générer des métadonnées de frontmatter pour les publications de Hugo","Formater le contenu selon les conventions de Hugo"],"de":["Automatisieren der Artikelveröffentlichung auf Hugo-basierten Websites","Generieren von Frontmatter-Metadaten für Hugo-Beiträge","Formatieren von Inhalten gemäß den Hugo-Konventionen"],"pt":["Automatizar a publicação de artigos em sites baseados em Hugo","Gerar metadados de frontmatter para posts do Hugo","Formatar o conteúdo de acordo com as convenções do Hugo"],"ru":["Автоматизация публикации статей на сайтах на основе Hugo","Генерация метаданных frontmatter для постов Hugo","Форматирование контента в соответствии с конвенциями Hugo"],"ar":["توفير نشر المقال التلقائي على المواقع التي تعتمد على هوغو","توليد بيانات وصفية أمامية لهوغو","تشكيل المحتوى وفقًا لاتفاقيات هوغو"]},"limitations":{"en":["Requires Hugo static site setup","Limited to Hugo-based websites","Needs access to website file structure"],"zh":["需要Hugo静态网站设置","仅限于Hugo基于的网站","需要访问网站文件结构"],"ja":["Hugo静的サイトの設定が必要","Hugoベースのウェブサイトに限定される","ウェブサイトのファイル構造へのアクセスが必要"],"ko":["Hugo 정적 사이트 설정이 필요함","Hugo 기반 웹사이트로 제한됨","웹사이트 파일 구조에 대한 액세스가 필요함"],"es":["Requiere configuración de sitio web estático de Hugo","Limitado a sitios web basados en Hugo","Necesita acceso a la estructura de archivos del sitio web"],"fr":["Nécessite une configuration de site web statique de Hugo","Limité aux sites web basés sur Hugo","Nécessite un accès à la structure de fichiers du site web"],"de":["Benötigt Hugo-Static-Site-Setup","Begrenzt auf Hugo-basierte Websites","Benötigt Zugriff auf die Dateistruktur der Website"],"pt":["Exige configuração de site estático Hugo","Limitado a sites baseados em Hugo","Necessita acesso à estrutura de arquivos do site"],"ru":["Требует настройки статического сайта Hugo","Ограничен только сайтами на основе Hugo","Требует доступа к структуре файлов сайта"],"ar":["يتطلب إعداد موقع هوغو الثابت","محدود بالمواقع التي تعتمد على هوغو","يحتاج إلى الوصول إلى هيكل ملفات الموقع"]},"version":4},"contentHash":"8fd4e76c3cf24b40fab2364e4cd2b31e8afb10330f7b18019eec01ba4ae497b2","qualityScore":36}');
