INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bravegeek/ai-workshop/hugo-publisher', 'hugo-publisher', 'bravegeek', 'ai-workshop', 'community', 'hugo-publisher bravegeek ai-workshop community The hugo-publisher skill automates the process of publishing articles to Hugo-based websites, handling tasks such as frontmatter metadata generation and content formatting. It benefits developers and content creators working with Hugo static sites. Hugo Publisher 是一个帮助用户将文章内容发布到 Hugo 静态网站的工具，支持格式化、元数据和文件结构 Hugo Publisher は、Hugo 静的サイトに記事の内容を公開するためのツールです。形式、メタデータ、ファイル構造をサポート Hugo Publisher는 Hugo 정적 사이트에 기사 내용을 게시하는 도구입니다. 형식, 메타데이터, 파일 구조를 지원합니다 El agente de publicación de Hugo es una herramienta para publicar artículos en sitios web estáticos con formato y metadatos adecuados. Proporciona una estructura de directorios correcta y gestiona referencias de imágenes L''agent de publication de Hugo est un outil pour publier des articles sur des sites web statiques avec un format et des métadonnées appropriés. Il fournit une structure de répertoire correcte et gère les références d''images Der Hugo-Veröffentlichungsagent ist ein Tool zum Veröffentlichen von Artikeln auf statischen Websites mit geeigneten Formatierungen und Metadaten. Es bietet eine korrekte Verzeichnisstruktur und verwaltet Bildreferenzen O Hugo Publisher é um agente que ajuda a publicar artigos em sites estáticos com formatação e metadados adequados ИИ Агент Hugo Publisher помогает публиковать статьи на статических сайтах с правильной форматировкой и метаданными يعمل Hugo Publisher كعامل في نشر المقالات على المواقع الثابتة مع تنسيق وبيانات وصفية مناسبة how to use hugo-publisher hugo-publisher setup guide hugo static site deployment hugo frontmatter generation automated hugo site publishing hugo-publisher alternative hugo-publisher vs other deployment tools hugo-publisher install hugo-publisher documentation Hugo Publisher Hugo 静态网站 文章发布 格式化 元数据 文件结构 AI 工具 静态网站生成 Generates proper Hugo frontmatter metadata Creates the correct directory structure for Hugo sites Formats content according to Hugo conventions Manages image references and prompts for seamless integration Provides publishing workflow guidance for efficient deployment hugo-publisher is an AI agent skill responsible for automating the deployment of articles to Hugo static sites, ensuring proper formatting and metadata.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('muyen/vibe-to-prod/dev-workflow', 'community', 'muyen', 'vibe-to-prod', 'muyen/vibe-to-prod', 'dev-workflow', 0, 0, 36, '2026-03-08T01:57:15.577Z', '2026-03-08T02:11:49.096Z', '80326c36902460a25ca2f96d39fd91f6ff39017a94294a79ab42e4ab58a066a2', '{"id":"muyen/vibe-to-prod/dev-workflow","name":"dev-workflow","description":{"en":"dev-workflow is a production-ready full-stack template that streamlines the software development life cycle (SDLC) for developers. It automates tasks from intake to deployment using AI-native tools.","zh":"dev-workflow是一个生产就绪的全栈模板，包含AI原生开发工作流，帮助开发人员快速完成项目","ja":"dev-workflowは、AIエージェントによるフルスタックテンプレートであり、開発者がプロジェクトを迅速に完了するのに役立ちます","ko":"dev-workflow는 생산 준비가 된 풀스택 템플릿으로 AI 네이티브 개발 워크플로우를 포함하여 개발자가 프로젝트를 빠르게 완료하도록 도와줍니다","es":"dev-workflow es un modelo de desarrollo de aplicaciones que utiliza herramientas de AI para agilizar el flujo de trabajo","fr":"dev-workflow est un modèle de développement d''applications qui utilise des outils d''IA pour accélérer le flux de travail","de":"dev-workflow ist ein Entwicklungsmodell für Anwendungen, das KI-Tools verwendet, um den Arbeitsfluss zu beschleunigen","pt":"O dev-workflow é um modelo de fluxo de trabalho de desenvolvimento AI-nativo que acelera o desenvolvimento de software. Ele inclui ferramentas como mcp__linear__get_issue e mcp__notion__notion-search","ru":"Dev-workflow - это модель потока разработки с ИИ Агентами, которая ускоряет разработку программного обеспечения. Он включает инструменты seperti mcp__linear__get_issue и mcp__notion__notion-search","ar":"dev-workflow هو نموذج تدفق عمل التطوير ذو العقل الاصطناعي الذي يسرع تطوير البرمجيات. يتضمن أدوات مثل mcp__linear__get_issue و mcp__notion__notion-search"},"seo":{"title":{"en":"dev-workflow: Streamlined SDLC Setup Guide | AI Agent Skill","zh":"dev-workflow Setup Guide: AI原生开发工作流","ja":"d