INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('muyen/vibe-to-prod/dev-workflow', 'dev-workflow', 'muyen', 'vibe-to-prod', 'community', 'dev-workflow muyen vibe-to-prod community dev-workflow is a production-ready full-stack template that streamlines the software development life cycle (SDLC) for developers. It automates tasks from intake to deployment using AI-native tools. dev-workflow是一个生产就绪的全栈模板，包含AI原生开发工作流，帮助开发人员快速完成项目 dev-workflowは、AIエージェントによるフルスタックテンプレートであり、開発者がプロジェクトを迅速に完了するのに役立ちます dev-workflow는 생산 준비가 된 풀스택 템플릿으로 AI 네이티브 개발 워크플로우를 포함하여 개발자가 프로젝트를 빠르게 완료하도록 도와줍니다 dev-workflow es un modelo de desarrollo de aplicaciones que utiliza herramientas de AI para agilizar el flujo de trabajo dev-workflow est un modèle de développement d''applications qui utilise des outils d''IA pour accélérer le flux de travail dev-workflow ist ein Entwicklungsmodell für Anwendungen, das KI-Tools verwendet, um den Arbeitsfluss zu beschleunigen O dev-workflow é um modelo de fluxo de trabalho de desenvolvimento AI-nativo que acelera o desenvolvimento de software. Ele inclui ferramentas como mcp__linear__get_issue e mcp__notion__notion-search Dev-workflow - это модель потока разработки с ИИ Агентами, которая ускоряет разработку программного обеспечения. Он включает инструменты seperti mcp__linear__get_issue и mcp__notion__notion-search dev-workflow هو نموذج تدفق عمل التطوير ذو العقل الاصطناعي الذي يسرع تطوير البرمجيات. يتضمن أدوات مثل mcp__linear__get_issue و mcp__notion__notion-search how to use dev-workflow dev-workflow setup guide dev-workflow alternative dev-workflow vs linear what is dev-workflow dev-workflow install SDLC template with AI-native tools mcp tools for development AI-powered software development life cycle dev-workflow AI原生开发工作流 软件开发加速 SDLC MCP工具 GitHub集成 Notion集成 代码开发 测试和部署 Utilizes MCP tools such as mcp__linear__get_issue for intake phase Employs mcp__memory__search_nodes for exploration and planning Supports code generation and editing with mcp__context7__query-docs Integrates with Notion for notion-search and notion-create-pages Facilitates GitHub integration for search_code, create_branch, and more Streamlines testing and review with automated workflows dev-workflow is a software development life cycle (SDLC) template that integrates AI-native tools to accelerate development from intake to deployment');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bigs/treebot/docs-maintainer', 'community', 'bigs', 'treebot', 'bigs/treebot', 'docs-maintainer', 0, 0, 36, '2026-03-08T01:57:15.587Z', '2026-03-08T02:11:57.859Z', '708546ebc5e30b892abb18c7fe71447ac126014f3c95511d7102e4fb52a92320', '{"id":"bigs/treebot/docs-maintainer","name":"docs-maintainer","description":{"en":"The docs-maintainer skill helps developers keep their documentation accurate by updating, adding, or removing docs after code changes. It benefits developers working on AI agents by ensuring their docs/ folder remains accurate.","zh":"docs-maintainer 是一种保持文档准确性的工具，通过更新、添加或删除文档以匹配代码更改","ja":"docs-maintainer はドキュメントを最新に保つためのツールで、コード変更後のドキュメントを更新、追加、または削除します","ko":"docs-maintainer는 문서를 최신 상태로 유지하는 도구로 코드 변경 후 문서를 업데이트, 추가 또는 삭제합니다","es":"Docs-maintainer es una herramienta que ayuda a mantener la documentación actualizada después de cambios significativos en el código","fr":"Docs-maintainer est un outil qui aide à maintenir la documentation à jour après des changements importants dans le code","de":"Docs-maintainer ist ein Tool, das hilft, die Dokumentation auf dem neuesten Stand zu halten, nachdem der Code wesentlich geändert wurde","pt":"O Docs Maintainer ajuda a manter a documentação precisa após alterações significativas de código, atualizando e removendo documentação de forma eficaz.","ru":"Docs Maintainer помогает поддерживать актуальность документации после значительных изменений кода, обновляя и удаляя документацию по мере необходимости.","ar":"يحافظ Docs Maintainer على دقة التوثيق بعد التغييرات الكبيرة في الكود، من خلال تحديث وازالة الوثائق بفعالية"},"seo":{"title":{"en":"docs-maintainer: Automated Documentation Updates for AI A...","zh":"docs-maintainer 文档维护设置指南","ja":"docs-maintainer ドキュメントメンテナンスベストプラクティス","ko":"docs-maintainer 문서 유지 보수 가이드","es":"Guía de configuración de docs-maintainer para actualizar ...","fr":"Configurer docs-maintainer pour maintenir une documentati...","de":"Einrichten von docs-maintainer für aktuelle Dokumentation","pt":"Guia de Configuração do Docs Maintainer: Melhores Práticas","ru":"Настройка Docs Maintainer: Руководство по обновлению доку...","ar":"دليل إعداد Docs Maintainer: تحديث الدокументات بفعالية مع..."},"description":{"en":"Learn how to keep your docs/ folder up-to-date with docs-maintainer. Discover how to automate documentation updates after substantial code changes and improv...","zh":"使用 docs-maintainer 保持文档准确性，通过更新、添加或删除文档以匹配代码更改","ja":"docs-maintainer を使用してドキュメントを最新に保ち、コード変更後のドキュメントを更新、追加、または削除します","ko":"docs-maintainer를 사용하여 문서를 최신 상태로 유지하고 코드 변경 후 문서를 업데이트, 추가 또는 삭제합니다","es":"Aprende a mantener tu documentación actualizada con docs-maintainer, la herramienta de AI para desarrolladores","fr":"Découvrez comment maintenir votre documentation à jour avec docs-maintainer, l''outil d''agent IA pour les développeurs","de":"Erfahren Sie, wie Sie Ihre Dokumentation mit docs-maintainer, dem AI-Tool für Entwickler, auf dem neuesten Stand halten","pt":"Aprenda a manter a documentação atualizada após alterações significativas de código com o Docs Maintainer. Veja como atualizar e remover documentação de form...","ru":"Обновляйте документацию после значительных изменений кода с помощью Docs Maintainer. Узнайте, как использовать ИИ Агенты для поддержки актуальности документа...","ar":"تعلم كيفية الحفاظ على توثيق دقيق بعد التغييرات الكبيرة في الكود باستخدام Docs Maintainer. إطلع على كيفية تحديث وازالة الوثائق بفعالية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"docs-maintainer is a skill that automates documentation updates by identifying behavior changes and updating the docs/ folder accordingly.","zh":"docs-maintainer 是一种自动化工具，用于维护文档的准确性","ja":"docs-maintainer はドキュメントの正確性を保つための自動化ツールです","ko":"docs-maintainer는 문서의 정확성을 유지하기 위한 자동화 도구입니다","es":"Docs-maintainer es un agente de AI que actualiza la documentación en respuesta a cambios en el código","fr":"Docs-maintainer est un agent d''IA qui met à jour la documentation en réponse aux changements de code","de":"Docs-maintainer ist ein AI-Agent, der die Dokumentation in Reaktion auf Codeänderungen aktualisiert","pt":"O Docs Maintainer é uma ferramenta que ajuda a manter a documentação precisa após alterações de código.","ru":"Docs Maintainer - это инструмент, помогающий поддерживать актуальность документации после изменений кода.","ar":"Docs Maintainer هو أداة تساعد في الحفاظ على دقة التوثيق بعد التغييرات في الكود"},"features":{"en":["Updates documentation to match new behavior after substantial code changes","Uses rg command for searching impacted material in the docs/ folder","Adds new module files when a new user-facing feature is introduced","Removes outdated documentation to keep the docs/ folder accurate","Supports follow-up commits to ensure documentation consistency"],"zh":["自动更新文档以匹配代码更改","支持使用 rg 命令搜索文档","可以添加新模块文件","可以更新文档以匹配新行为","支持 CLI 命令行界面"],"ja":["コード変更に応じてドキュメントを自動更新","rg コマンドを使用してドキュメントを検索","新しいモジュールファイルを追加","新しい動作に合わせてドキュメントを更新","CLI コマンドラインインターフェイスをサポート"],"ko":["코드 변경에 따라 문서를 자동으로 업데이트","rg 명령을 사용하여 문서를 검색","새로운 모듈 파일을 추가","새로운 동작에 따라 문서를 업데이트","CLI 명령줄 인터페이스를 지원"],"es":["Actualiza la documentación después de cambios significativos en el código","Identifica los cambios de comportamiento introducidos por los commits","Busca material impactado en la documentación utilizando rg","Agrega nuevos archivos de módulos cuando se agrega un nuevo comportamiento","Mantiene la documentación actualizada con commits separados"],"fr":["Met à jour la documentation après des changements importants dans le code","Identifie les changements de comportement introduits par les commits","Recherche le matériel impacté dans la documentation en utilisant rg","Ajoute de nouveaux fichiers de modules lorsque de nouveaux comportements sont ajoutés","Maintient la documentation à jour avec des commits séparés"],"de":["Aktualisiert die Dokumentation nach wesentlichen Änderungen im Code","Identifiziert die Änderungen des Verhaltens, die durch Commits eingeführt werden","Sucht betroffenes Material in der Dokumentation mithilfe von rg","Fügt neue Moduldateien hinzu, wenn ein neues Verhalten hinzugefügt wird","Hält die Dokumentation auf dem neuesten Stand mit separaten Commits"],"pt":["Atualização de documentação após alterações significativas de código","Remoção de documentação desnecessária","Adição de novos arquivos de módulos","Utilização de comandos como ''rg'' para busca de palavras-chave","Integração com fluxos de trabalho de desenvolvimento"],"ru":["Обновление документации после значительных изменений кода","Удаление ненужной документации","Добавление новых модульных файлов","Использование команд như ''rg'' для поиска ключевых слов","Интеграция с рабочими процессами разработки"],"ar":["تحديث التوثيق بعد التغييرات الكبيرة في الكود","ازالة التوثيق غير الضروري","إضافة ملفات وحدات جديدة","استخدام أوامر مثل ''rg'' للبحث عن الكلمات الرئيسية","التكامل مع سير عمل التطوير"]},"keywords":{"en":["how to use docs-maintainer","docs-maintainer setup guide","automated documentation updates","docs-maintainer alternative","docs-maintainer vs manual documentation","rg command for documentation search","docs/ folder management","AI agent documentation best practices"],"zh":["docs-maintainer","文档维护","代码更改","自动化工具","rg 命令","CLI 命令行界面","AIエージェント","文档更新"],"ja":["docs-maintainer","ドキュメントメンテナンス","コード変更","自動化ツール","rg コマンド","CLI コマンドラインインターフェイス","AIエージェント","ドキュメント更新"],"ko":["docs-maintainer","문서 유지 보수","코드 변경","자동화 도구","rg 명령","CLI 명령줄 인터페이스","AI 에이전트","문서 업데이트"],"es":["docs-maintainer","herramientas de AI para desarrolladores","actualización de documentación","cambios en el código","commits de características","rg para búsqueda en documentación","documentación de módulos","desarrollo de software"],"fr":["docs-maintainer","outils d''agent IA pour les développeurs","mise à jour de la documentation","changements de code","commits de fonctionnalités","rg pour la recherche dans la documentation","documentation de modules","développement de logiciels"],"de":["docs-maintainer","AI-Tools für Entwickler","Dokumentenaktualisierung","Codeänderungen","Funktionscommits","rg für die Suche in der Dokumentation","Moduldokumentation","Softwareentwicklung"],"pt":["Docs Maintainer","manutenção de documentação","atualização de código","ferramentas de desenvolvimento","otimização de documentação","melhores práticas de documentação","desenvolvimento de software"],"ru":["Docs Maintainer","поддержка документации","обновление кода","инструменты разработки","оптимизация документации","лучшие практики документации","разработка программного обеспечения","ИИ Агенты"],"ar":["Docs Maintainer","صيانة التوثيق","تحديث الكود","أدوات التطوير","تحسين التوثيق","أفضل الممارسات لتوثيق","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"bigs","repo":"treebot","repoPath":"bigs/treebot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.587Z","topics":[],"category":"community","skillMd":{"name":"docs-maintainer","description":"Maintain and update project documentation in docs/ after application changes. Use when a new feature is added, a feature is deleted, or expected behavior changes and the code work has been completed with a commit; perform a follow-up documentation update in a new commit.","bodyPreview":"# Docs Maintainer\n\n## Overview\n\nKeep `docs/` accurate after substantial code changes by updating, adding, or removing documentation in a separate, follow-up commit.\n\n## Workflow (run after the feature commit)\n\n1. Identify the behavior changes introduced by the feature commit (new behavior, removed behavior, or changed behavior).\n2. Search `docs/` for impacted material (use `rg -n \"<keyword>\" docs`).\n3. Update documentation to match the new behavior:\n   - Add new module files when a new user-faci","body":"# Docs Maintainer\n\n## Overview\n\nKeep `docs/` accurate after substantial code changes by updating, adding, or removing documentation in a separate, follow-up commit.\n\n## Workflow (run after the feature commit)\n\n1. Identify the behavior changes introduced by the feature commit (new behavior, removed behavior, or changed behavior).\n2. Search `docs/` for impacted material (use `rg -n \"<keyword>\" docs`).\n3. Update documentation to match the new behavior:\n   - Add new module files when a new user-facing feature, API route, or data model is added.\n   - Update existing module sections when behavior, data shape, or flows change.\n   - Delete docs for removed features and remove links from the index.\n4. Update the index and navigation:\n   - `docs/README.md` must link to any new docs and remove links to deleted docs.\n   - Update `docs/architecture/site-map.md` for route changes.\n   - Update `docs/api/routes.md` for API route changes.\n   - Update `docs/data/data-models.md` for schema changes.\n5. Validate internal links in `docs/`:\n\n```bash\npython3 - <<''PY''\nimport os, re\nroot = \"docs\"\nmissing = []\nif not os.path.isdir(root):\n    raise SystemExit(''docs directory not found. Run from repo root.'')\nlink_re = re.compile(r\"\\[[^\\]]*\\]\\(([^)]+)\\)\")\nfor dirpath, _, filenames in os.walk(root):\n    for fn in filenames:\n        if not fn.endswith(\".md\"):\n            continue\n        path = os.path.join(dirpath, fn)\n        with open(path, \"r\", encoding=\"utf-8\") as f:\n            text = f.read()\n        for link in link_re.findall(text):\n            if link.startswith((\"http://\", \"https://\", \"mailto:\")):\n                continue\n            if link.startswith(\"#\"):\n                continue\n            link_path = link.split(\"#\", 1)[0]\n            if not link_path:\n                continue\n            target = os.path.normpath(os.path.join(dirpath, link_path))\n            if not os.path.exists(target):\n                missing.append((path, link, target))\nif missing:\n    print(\"Missing links:\")\n    for m in missing:\n        print(m)\n    raise SystemExit(1)\nprint(\"All internal links resolved.\")\nPY\n```\n\n6. Commit the documentation changes separately (after the feature commit). Use a clear message like `docs: update for <feature>`.\n\n## Scope reminders\n\n- Focus on user-facing behavior, APIs, data model changes, and onboarding/admin flows.\n- If a change does not affect any documented behavior or assumptions, no docs update is required.\n"},"lastSynced":"2026-03-08T02:11:57.859Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Maintenance Agents needing automated documentation updates after substantial code changes.","zh":"适合需要在大量代码更改后自动更新文档的代码维护代理。","ja":"コードメンテナンスエージェントが大量なコード変更後の自動ドキュメント更新を必要とする場合に最適です。","ko":"코드 유지보수 에이전트가大量 코드 변경 후 자동 문서 업데이트가 필요한 경우에 적합합니다.","es":"Perfecto para agentes de mantenimiento de código que necesitan actualizaciones automatizadas de documentación después de cambios de código sustanciales.","fr":"Parfait pour les agents de maintenance de code ayant besoin de mises à jour automatiques de documentation après des modifications de code substantielles.","de":"Perfekt für Code-Wartungsagenten, die automatisierte Dokumentenaktualisierungen nach umfangreichen Codeänderungen benötigen.","pt":"Perfeito para Agentes de Manutenção de Código que necessitam de atualizações automatizadas de documentação após alterações substanciais no código.","ru":"Идеально подходит для агентов по обслуживанию кода, которым требуются автоматические обновления документации после существенных изменений кода.","ar":"مثالي لعمليات维护 الكود التي تحتاج إلى تحديثات توثيقية آلية بعد تغييرات كبيرة في الكود."},"recommendation":{"en":"Empowers agents to maintain accurate documentation by updating, adding, or removing docs in a separate commit, ensuring the docs/ folder remains synchronized with the codebase using tools like rg for searching impacted material.","zh":"赋予代理维护准确文档的能力，通过在单独的提交中更新、添加或删除文档，确保docs/文件夹与代码库保持同步，使用诸如rg的工具来搜索受影响的材料。","ja":"エージェントがコードベースと同期された状態でドキュメントを保持することを可能にし、ツール seperti rg を使用して影響を受ける資料を検索し、別のコミットでドキュメントを更新、追加、または削除します。","ko":"에이전트가 코드베이스와 동기화된 상태에서 문서를 유지할 수 있도록 하며, 도구 seperti rg를 사용하여 영향을 받는 자료를 검색하고, 별도의 커밋에서 문서를 업데이트하거나 추가 또는 삭제합니다.","es":"Habilita a los agentes a mantener documentación precisa actualizando, agregando o eliminando documentos en un compromiso separado, asegurando que la carpeta docs/ permanece sincronizada con el código base utilizando herramientas como rg para buscar material afectado.","fr":"Permet aux agents de maintenir une documentation précise en mettant à jour, en ajoutant ou en supprimant des documents dans un commit séparé, en veillant à ce que le dossier docs/ reste synchronisé avec le code base en utilisant des outils comme rg pour rechercher le matériel affecté.","de":"Ermächtigt die Agenten, eine genaue Dokumentation zu erhalten, indem sie Dokumente in einem separaten Commit aktualisieren, hinzufügen oder entfernen, und sicherstellen, dass der Ordner docs/ mit dem Codebase synchronisiert bleibt, indem Tools wie rg zum Suchen des betroffenen Materials verwendet werden.","pt":"Habilita os agentes a manter a documentação precisa atualizando, adicionando ou removendo docs em um commit separado, garantindo que a pasta docs/ permaneça sincronizada com o código-fonte usando ferramentas como rg para buscar material impactado.","ru":"Наделяет агентов возможностью поддерживать точную документацию, обновляя, добавляя или удаляя документы в отдельном коммите, обеспечивая синхронизацию папки docs/ с кодовой базой с помощью инструментов seperti rg для поиска затронутого материала.","ar":"يتمكن العميل من الحفاظ على توثيق دقيق من خلال تحديث أو إضافة أو إزالة الوثائق في Commit منفصل، مع ضمان بقاء مجلد الوثائق docs/ متزامن مع قاعدة الشفرة باستخدام أدوات مثل rg للبحث عن المواد المتأثرة."},"useCases":{"en":["Updating documentation to reflect new behavior introduced by feature commits","Automating the removal of outdated documentation after code refactoring","Generating new module files for added functionality"],"zh":["更新文档以反映功能提交引入的新行为","自动删除代码重构后过时的文档","为添加的功能生成新模块文件"],"ja":["機能コミットによって導入された新しい動作を反映するためにドキュメントを更新する","コードリファクタリング後に古くなったドキュメントを自動的に削除する","追加された機能用に新しいモジュールファイルを生成する"],"ko":["기능 커밋에 의해導入された 새로운 동작을 반영하기 위해 문서를 업데이트 하는 것","코드 리팩토링 이후로 구식이 된 문서를 자동으로 제거하는 것","추가된 기능을 위한 새로운 모듈 파일을 생성하는 것"],"es":["Actualización de la documentación para reflejar el nuevo comportamiento introducido por los compromisos de características","Automatización de la eliminación de documentación obsoleta después de la refactorización del código","Generación de nuevos archivos de módulos para funcionalidades agregadas"],"fr":["Mise à jour de la documentation pour refléter le nouveau comportement introduit par les commits de fonctionnalités","Automatisation de la suppression de la documentation obsolète après la réorganisation du code","Génération de nouveaux fichiers de modules pour les fonctionnalités ajoutées"],"de":["Aktualisierung der Dokumentation, um das neue Verhalten zu widerspiegeln, das durch Funktionscommits eingeführt wird","Automatisierung der Entfernung veralteter Dokumentation nach dem Refactoring des Codes","Generierung neuer Moduldateien für hinzugefügte Funktionalitäten"],"pt":["Atualizar a documentação para refletir o novo comportamento introduzido por commits de funcionalidades","Automatizar a remoção de documentação desatualizada após refatoração de código","Gerar novos arquivos de módulo para funcionalidades adicionadas"],"ru":["Обновление документации для отражения нового поведения, введенного коммитами функций","Автоматизация удаления устаревшей документации после рефакторинга кода","Генерация новых файлов модулей для добавленных функций"],"ar":["تحديث الوثائق لتعكس السلوك الجديد الذي قدمتهCommits الميزات","التحكم الآلي في إزالة الوثائق القديمة بعد إعادة هيكلة الكود","генерация ملفات وحدة جديدة للمزايا المضافّة"]},"limitations":{"en":["Requires access to the code repository and docs/ folder","Limited to updating documentation in a separate, follow-up commit"],"zh":["需要访问代码仓库和docs/文件夹","仅限在单独的后续提交中更新文档"],"ja":["コードリポジトリとdocs/フォルダへのアクセスが必要","別の後続コミットでのみドキュメントを更新できる"],"ko":["코드 저장소와 docs/ 폴더에 대한 액세스가 필요함","별도의 후속 커밋에서만 문서를 업데이트할 수 있음"],"es":["Requiere acceso al repositorio de código y a la carpeta docs/","Limitado a la actualización de la documentación en un compromiso separado, posterior"],"fr":["Nécessite un accès au référentiel de code et au dossier docs/","Limité à la mise à jour de la documentation dans un commit séparé, ultérieur"],"de":["Erfordert Zugriff auf das Code-Repository und den Ordner docs/","Begrenzt auf die Aktualisierung der Dokumentation in einem separaten, nachfolgenden Commit"],"pt":["Exige acesso ao repositório de código e à pasta docs/","Limitado à atualização da documentação em um commit separado, de acompanhamento"],"ru":["Требует доступа к репозиторию кода и папке docs/","Ограничен обновлением документации в отдельном, последующем коммите"],"ar":["يتطلب الوصول إلى مستودع الشفرة ومجلد الوثائق docs/","محدود بتحديث الوثائق في Commit منفصل، متبوع"]},"version":4},"contentHash":"708546ebc5e30b892abb18c7fe71447ac126014f3c95511d7102e4fb52a92320","qualityScore":36}');
