INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bigs/treebot/docs-maintainer', 'docs-maintainer', 'bigs', 'treebot', 'community', 'docs-maintainer bigs treebot community The docs-maintainer skill helps developers keep their documentation accurate by updating, adding, or removing docs after code changes. It benefits developers working on AI agents by ensuring their docs/ folder remains accurate. docs-maintainer 是一种保持文档准确性的工具，通过更新、添加或删除文档以匹配代码更改 docs-maintainer はドキュメントを最新に保つためのツールで、コード変更後のドキュメントを更新、追加、または削除します docs-maintainer는 문서를 최신 상태로 유지하는 도구로 코드 변경 후 문서를 업데이트, 추가 또는 삭제합니다 Docs-maintainer es una herramienta que ayuda a mantener la documentación actualizada después de cambios significativos en el código Docs-maintainer est un outil qui aide à maintenir la documentation à jour après des changements importants dans le code Docs-maintainer ist ein Tool, das hilft, die Dokumentation auf dem neuesten Stand zu halten, nachdem der Code wesentlich geändert wurde O Docs Maintainer ajuda a manter a documentação precisa após alterações significativas de código, atualizando e removendo documentação de forma eficaz. Docs Maintainer помогает поддерживать актуальность документации после значительных изменений кода, обновляя и удаляя документацию по мере необходимости. يحافظ Docs Maintainer على دقة التوثيق بعد التغييرات الكبيرة في الكود، من خلال تحديث وازالة الوثائق بفعالية how to use docs-maintainer docs-maintainer setup guide automated documentation updates docs-maintainer alternative docs-maintainer vs manual documentation rg command for documentation search docs/ folder management AI agent documentation best practices docs-maintainer 文档维护 代码更改 自动化工具 rg 命令 CLI 命令行界面 AIエージェント 文档更新 Updates documentation to match new behavior after substantial code changes Uses rg command for searching impacted material in the docs/ folder Adds new module files when a new user-facing feature is introduced Removes outdated documentation to keep the docs/ folder accurate Supports follow-up commits to ensure documentation consistency docs-maintainer is a skill that automates documentation updates by identifying behavior changes and updating the docs/ folder accordingly.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ghimirerohan/erpnextCCDis/vue-webapp-creation', 'community', 'ghimirerohan', 'erpnextCCDis', 'ghimirerohan/erpnextCCDis', 'vue-webapp-creation', 0, 0, 36, '2026-03-08T01:57:15.589Z', '2026-03-08T02:12:01.158Z', 'd8a8581153e6eb0fb3e683e4b6dc4cf052e122d682e027a9a7efa1f7408b7d94', '{"id":"ghimirerohan/erpnextCCDis/vue-webapp-creation","name":"vue-webapp-creation","description":{"en":"The vue-webapp-creation skill guides developers through creating a new Vue web application within the custom_erp Frappe app. It covers initial setup to production deployment for a seamless experience.","zh":"本指南介绍如何在自定义 ERP 中创建新的 Vue Web 应用，从设置到生产部署","ja":"このガイドでは、カスタム ERP 内で新しい Vue Web アプリケーションを作成する方法を、設定から生産へのデプロイまでを説明します","ko":"이 가이드는 커스텀 ERP에서 새로운 Vue 웹 애플리케이션을 생성하는 방법을 설정에서 생산 배포까지 설명합니다","es":"Vue WebApp Creation es una habilidad que te guía a través de la creación de una nueva aplicación web Vue dentro de la aplicación personalizada de ERP Next.","fr":"Vue WebApp Creation est une compétence qui vous guide à travers la création d''une nouvelle application web Vue au sein de l''application personnalisée ERP Next.","de":"Vue WebApp Creation ist eine Fähigkeit, die Sie durch die Erstellung einer neuen Vue-Webanwendung innerhalb der benutzerdefinierten ERP-Next-Anwendung führt.","pt":"O skill vue-webapp-creation ajuda a criar aplicativos web Vue personalizados no Custom ERP, desde a configuração inicial até a implantação em produção.","ru":"Навык vue-webapp-creation помогает создать настраиваемые веб-приложения Vue в Custom ERP, от初альной настройки до развертывания в производство.","ar":"المهارة vue-webapp-creation تساعد على إنشاء تطبيقات ويب Vue المخصصة في Custom ERP، من الإعداد الأولي إلى النشر في الإنتاج."},"seo":{"title":{"en":"vue-webapp-creation: Vue WebApp Setup Guide | AI Agent Skill","zh":"Vue WebApp Creation Setup Guide - AIエージェント","ja":"Vue WebApp Creation ベストプラクティス - AIエージェント","ko":"Vue WebApp Creation 시작하기 - AI 에이전트","es":"Guía de configuración de Vue WebApp Creation","fr":"Guide de création d''applications Web Vue","de":"Vue WebApp Creation-Setup-Anleitung","pt":"Crie Aplicativos Web Vue: Guia de Configuração","ru":"Создание веб-приложений Vue: Руководство по настройке ИИ ...","ar":"إنشاء تطبيقات ويب Vue: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create a new Vue web application within custom_erp Frappe app. Learn setup to production deployment and get started with vue-webapp-creation ...","zh":"了解如何使用 Vue.js 创建自定义 ERP Web 应用，包括设置和生产部署","ja":"Vue.js を使用してカスタム ERP Web アプリケーションを作成する方法を学びます","ko":"Vue.js를 사용하여 커스텀 ERP 웹 애플리케이션을 생성하고 설정하는 방법을 알아보세요","es":"Crea aplicaciones web personalizadas con Vue y ERP Next. Aprende a configurar y desplegar tu aplicación de forma efectiva.","fr":"Créez des applications web personnalisées avec Vue et ERP Next. Découvrez comment configurer et déployer votre application de manière efficace.","de":"Erstellen Sie benutzerdefinierte Webanwendungen mit Vue und ERP Next. Erfahren Sie, wie Sie Ihre Anwendung effektiv konfigurieren und bereitstellen.","pt":"Aprenda a criar aplicativos web Vue personalizados no Custom ERP com nosso guia passo a passo","ru":"Узнайте, как создать настраиваемые веб-приложения Vue в Custom ERP с нашей пошаговой инструкцией ИИ Агентов","ar":"تعلم كيفية إنشاء تطبيقات ويب Vue المخصصة في Custom ERP باستخدام دليلنا خطوة بخطوة لأدوات الذكاء الاصطناعي"},"definition":{"en":"vue-webapp-creation is a skill that enables developers to create new Vue web applications within the custom_erp Frappe app, streamlining the development process.","zh":"Vue WebApp Creation 是一种创建自定义 ERP Web 应用的方法，使用 Vue.js 框架","ja":"Vue WebApp Creation は、Vue.js フレームワークを使用してカスタム ERP Web アプリケーションを作成する方法です","ko":"Vue WebApp Creation은 Vue.js 프레임워크를 사용하여 커스텀 ERP 웹 애플리케이션을 생성하는 방법입니다","es":"Vue WebApp Creation es una habilidad que permite crear aplicaciones web personalizadas con Vue y ERP Next.","fr":"Vue WebApp Creation est une compétence qui permet de créer des applications web personnalisées avec Vue et ERP Next.","de":"Vue WebApp Creation ist eine Fähigkeit, die die Erstellung benutzerdefinierter Webanwendungen mit Vue und ERP Next ermöglicht.","pt":"O que é vue-webapp-creation? É um skill que permite criar aplicativos web Vue personalizados no Custom ERP.","ru":"Что такое vue-webapp-creation? Это навык, который позволяет создать настраиваемые веб-приложения Vue в Custom ERP.","ar":"ما هي vue-webapp-creation؟ هي مهارة تتيح إنشاء تطبيقات ويب Vue المخصصة في Custom ERP."},"features":{"en":["Creates a new Vue web application at a specified route, such as /my-app","Initializes the Vue app with a main.js file in the src directory","Sets up the root component with PWA configuration in App.vue","Organizes the source directory with index.html and src folders","Supports production deployment for the created Vue web application"],"zh":["使用 Vue.js 框架创建自定义 ERP Web 应用","设置和配置 Vue 应用初始化","创建根组件并设置 PWA","生产部署和优化","使用 Frappe 应用创建自定义 ERP 解决方案"],"ja":["Vue.js フレームワークを使用してカスタム ERP Web アプリケーションを作成","Vue アプリの初期化と設定","ルートコンポーネントの作成と PWA の設定","生産へのデプロイと最適化","Frappe アプリを使用してカスタム ERP ソリューションを作成"],"ko":["Vue.js 프레임워크를 사용하여 커스텀 ERP 웹 애플리케이션을 생성","Vue 애플리케이션 초기화 및 설정","루트 컴포넌트 생성 및 PWA 설정","생산 배포 및 최적화","Frappe 애플리케이션을 사용하여 커스텀 ERP 솔루션 생성"],"es":["Configuración de la aplicación web Vue","Creación de componentes personalizados con Vue","Despliegue de la aplicación en producción","Integración con la aplicación personalizada de ERP Next","Uso de PWA para mejorar la experiencia del usuario"],"fr":["Configuration de l''application web Vue","Création de composants personnalisés avec Vue","Déploiement de l''application en production","Intégration avec l''application personnalisée ERP Next","Utilisation de PWA pour améliorer l''expérience utilisateur"],"de":["Konfiguration der Vue-Webanwendung","Erstellung benutzerdefinierter Komponenten mit Vue","Bereitstellung der Anwendung in der Produktion","Integration mit der benutzerdefinierten ERP-Next-Anwendung","Verwendung von PWA zur Verbesserung der Benutzererfahrung"],"pt":["Criação de aplicativos web Vue personalizados","Configuração inicial e implantação em produção","Uso do arquivo main.js para inicialização do aplicativo Vue","Uso do componente App.vue para configuração do PWA","Criação de diretórios e arquivos para o aplicativo web"],"ru":["Создание настраиваемых веб-приложений Vue","Первоначальная настройка и развертывание в производство","Использование файла main.js для инициализации приложения Vue","Использование компонента App.vue для настройки PWA","Создание директорий и файлов для веб-приложения"],"ar":["إنشاء تطبيقات ويب Vue المخصصة","الإعداد الأولي والنشر في الإنتاج","استخدام الملف main.js لتشغيل التطبيق Vue","استخدام المكون App.vue لإعداد PWA","إنشاء الدلائل والملفات للتطبيق الويب"]},"keywords":{"en":["how to use vue-webapp-creation","vue-webapp-creation setup guide","vue-webapp-creation alternative","vue-webapp-creation vs custom_erp","vue-webapp-creation install","what is vue-webapp-creation","vue-webapp-creation tutorial","vue-webapp-creation frappe app integration"],"zh":["Vue WebApp Creation","自定义 ERP","Vue.js","Frappe","PWA","生产部署","AI エージェント","Web 应用创建"],"ja":["Vue WebApp Creation","カスタム ERP","Vue.js","Frappe","PWA","生産へのデプロイ","AI エージェント","Web アプリケーション作成"],"ko":["Vue WebApp Creation","커스텀 ERP","Vue.js","Frappe","PWA","생산 배포","AI 에이전트","웹 애플리케이션 생성"],"es":["Vue WebApp Creation","ERP Next","aplicaciones web personalizadas","desarrollo web","PWA","configuración de aplicaciones web","creación de componentes Vue","despliegue de aplicaciones en producción"],"fr":["Vue WebApp Creation","ERP Next","applications web personnalisées","développement web","PWA","configuration d''applications web","création de composants Vue","déploiement d''applications en production"],"de":["Vue WebApp Creation","ERP Next","benutzerdefinierte Webanwendungen","Webentwicklung","PWA","Konfiguration von Webanwendungen","Erstellung von Vue-Komponenten","Bereitstellung von Anwendungen in der Produktion"],"pt":["vue-webapp-creation","criar aplicativos web Vue","Custom ERP","configuração inicial","implantação em produção","main.js","App.vue","PWA"],"ru":["vue-webapp-creation","создать веб-приложения Vue","Custom ERP","первоначальная настройка","развертывание в производство","main.js","App.vue","PWA","ИИ Агенты"],"ar":["vue-webapp-creation","إنشاء تطبيقات ويب Vue","Custom ERP","الإعداد الأولي","النشر في الإنتاج","main.js","App.vue","PWA","أدوات الذكاء الاصطناعي"]}},"owner":"ghimirerohan","repo":"erpnextCCDis","repoPath":"ghimirerohan/erpnextCCDis","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.589Z","topics":[],"category":"community","skillMd":{"name":"vue-webapp-creation","description":"Create new Vue web applications within the custom_erp Frappe app. Use when the user wants to create a new Vue app, add a new frontend app, create a new PWA, or asks about adding apps like qrpay, pay-dashboard. Covers directory structure, routing, Vite config, Frappe www files, PWA manifest, and deployment.","bodyPreview":"# Vue WebApp Creation in Custom_ERP\n\nThis skill guides you through creating a new Vue web application within the custom_erp Frappe app, from initial setup to production deployment.\n\n## Quick Reference\n\nFor a new app called `my-app` at route `/my-app`, you need:\n\n| File/Directory | Purpose |\n|----------------|---------|\n| `my-app/` | Source directory with `index.html` and `src/` |\n| `my-app/src/main.js` | Vue app initialization |\n| `my-app/src/App.vue` | Root component with PWA setup |\n| `my-app/","body":"# Vue WebApp Creation in Custom_ERP\n\nThis skill guides you through creating a new Vue web application within the custom_erp Frappe app, from initial setup to production deployment.\n\n## Quick Reference\n\nFor a new app called `my-app` at route `/my-app`, you need:\n\n| File/Directory | Purpose |\n|----------------|---------|\n| `my-app/` | Source directory with `index.html` and `src/` |\n| `my-app/src/main.js` | Vue app initialization |\n| `my-app/src/App.vue` | Root component with PWA setup |\n| `my-app/src/router.js` | Vue Router with auth guards |\n| `my-app/src/MyApp.vue` | Main page component |\n| `custom_erp/www/my-app.html` | Frappe production entry (hyphenated) |\n| `custom_erp/www/my_app.py` | Frappe context (underscored) |\n| `public/manifest-my-app.json` | PWA manifest |\n| `public/icons/my-app/icon-512x512.png` | App icon |\n| `vite.config.js` | Add to apps array |\n| `build-apps.js` | Add to apps array + theme config |\n\n## Naming Convention\n\n**CRITICAL**: Follow this naming pattern exactly:\n\n| Location | Format | Example |\n|----------|--------|---------|\n| Directory & URL | hyphenated | `my-app`, `/my-app` |\n| www/*.html | hyphenated | `my-app.html` |\n| www/*.py | underscored | `my_app.py` |\n| vite.config.js | hyphenated | `''my-app''` |\n| build-apps.js | hyphenated | `''my-app''` |\n| manifest | hyphenated | `manifest-my-app.json` |\n| Router base | hyphenated | `/my-app` |\n\n---\n\n## Step-by-Step Creation Process\n\n### Step 1: Create Directory Structure\n\n```bash\ncd frappe-bench/apps/custom_erp\nmkdir -p my-app/src\n```\n\n### Step 2: Create Source Files\n\nCreate all files in this order. See [templates.md](templates.md) for complete file contents.\n\n1. `my-app/index.html` - Dev entry point\n2. `my-app/src/main.js` - Vue initialization\n3. `my-app/src/App.vue` - Root component\n4. `my-app/src/router.js` - Router with auth\n5. `my-app/src/MyApp.vue` - Main component\n\n### Step 3: Update Build Configurations\n\n**vite.config.js** - Add to apps array:\n```javascript\nconst apps = [\n  ''qrpay'',\n  ''my-app'',  // ADD HERE\n  // ... other apps\n]\n```\n\n**build-apps.js** - Add to apps array AND appThemes:\n```javascript\nconst apps = [\n  ''qrpay'',\n  ''my-app'',  // ADD HERE\n  // ...\n]\n\nconst appThemes = {\n  // ...\n  ''my-app'': { \n    theme: ''#3b82f6'',      // Primary color (hex)\n    bg: ''#ffffff'',          // Background color\n    name: ''My App'',         // Display name\n    desc: ''App description'' // PWA description\n  },\n}\n```\n\n### Step 4: Create Frappe WWW Files\n\n**custom_erp/www/my-app.html** (placeholder - build will update):\n```html\n<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <link rel=\"icon\" href=\"/assets/custom_erp/frontend/my-app/favicon.png\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\" />\n    <title>My App - Description</title>\n    <meta name=\"theme-color\" content=\"#3b82f6\" />\n    <meta name=\"mobile-web-app-capable\" content=\"yes\" />\n    <link rel=\"manifest\" href=\"/api/method/custom_erp.api.pwa.get_manifest?app_name=my-app\" />\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script>\n        {% for key in boot %}\n        window[\"{{ key }}\"] = {{ boot[key] | tojson }};\n        {% endfor %}\n    </script>\n  </body>\n</html>\n```\n\n**custom_erp/www/my_app.py** (NOTE: underscored filename):\n```python\nimport frappe\n\ndef get_context(context):\n    \"\"\"Context for my-app\"\"\"\n    context.no_cache = 1\n    return context\n```\n\n### Step 5: Create PWA Manifest\n\n**public/manifest-my-app.json**:\n```json\n{\n  \"id\": \"/my-app/\",\n  \"name\": \"My App\",\n  \"short_name\": \"MyApp\",\n  \"description\": \"App description\",\n  \"start_url\": \"/my-app/\",\n  \"scope\": \"/my-app/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait-primary\",\n  \"background_color\": \"#ffffff\",\n  \"theme_color\": \"#3b82f6\",\n  \"icons\": [\n    {\n      \"src\": \"/assets/custom_erp/icons/my-app/icon-512x512.png\",\n      \"sizes\": \"512x512\",\n      \"type\": \"image/png\",\n      \"purpose\": \"any maskable\"\n    }\n  ],\n  \"categories\": [\"business\", \"finance\"],\n  \"prefer_related_applications\": false\n}\n```\n\n### Step 6: Add App Icon\n\n```bash\nmkdir -p public/icons/my-app\ncp public/icons/qrpay/icon-512x512.png public/icons/my-app/\n```\n\nOr create a custom 512x512 PNG icon.\n\n---\n\n## Testing & Deployment\n\n### Local Development\n```bash\ncd frappe-bench/apps/custom_erp\nyarn dev\n# Access at http://localhost:8080/my-app\n```\n\n### Build for Production\n```bash\ncd frappe-bench/apps/custom_erp\nnode build-apps.js\n```\n\n### Commit & Push\n```bash\ngit add -A\ngit commit -m \"feat: add my-app Vue web application\"\ngit push origin main\n```\n\n### Deploy to Server\n```bash\n# On production server:\ncd ~/frappe-bench/apps/custom_erp\ngit pull origin main\nnode build-apps.js\ncd ~/frappe-bench\nbench build --app custom_erp\nbench restart\n```\n\n---\n\n## Checklist\n\nCopy this checklist when creating a new app:\n\n```\nNew Vue App: [APP_NAME]\n\nDirectory & Source Files:\n- [ ] Created [app-name]/ directory\n- [ ] Created [app-name]/index.html\n- [ ] Created [app-name]/src/main.js\n- [ ] Created [app-name]/src/App.vue\n- [ ] Created [app-name]/src/router.js (base path: /[app-name])\n- [ ] Created [app-name]/src/[AppName].vue\n\nBuild Configuration:\n- [ ] Added to vite.config.js apps array\n- [ ] Added to build-apps.js apps array\n- [ ] Added theme config to build-apps.js appThemes\n\nFrappe Files:\n- [ ] Created custom_erp/www/[app-name].html\n- [ ] Created custom_erp/www/[app_name].py (underscored!)\n\nPWA Assets:\n- [ ] Created public/manifest-[app-name].json\n- [ ] Added icon to public/icons/[app-name]/icon-512x512.png\n\nTesting:\n- [ ] Tested locally with yarn dev\n- [ ] Built with node build-apps.js\n- [ ] Verified at /[app-name] route\n\nDeployment:\n- [ ] Committed and pushed\n- [ ] Pulled on server\n- [ ] Ran node build-apps.js on server\n- [ ] Ran bench build --app custom_erp\n- [ ] Ran bench restart\n```\n\n---\n\n## Common Issues & Solutions\n\n### 404 Errors for Assets\n**Cause**: Build output doesn''t exist or wrong paths\n**Fix**: Run `node build-apps.js` - it generates correct asset hashes\n\n### PWA Manifest 404\n**Cause**: App not in build-apps.js or manifest not generated\n**Fix**: Add to build-apps.js apps array and rebuild\n\n### Login Redirect Loop\n**Cause**: Wrong router base path\n**Fix**: Ensure `createWebHistory(\"/my-app\")` matches your URL\n\n### Python File Not Found\n**Cause**: Wrong filename format\n**Fix**: WWW Python files use underscores: `my_app.py` (not `my-app.py`)\n\n---\n\n## Additional Resources\n\n- See [templates.md](templates.md) for complete file templates\n- See [examples.md](examples.md) for real app examples\n- Reference existing apps: `qrpay/`, `pay-dashboard/`, `qrpay-horlicks/`\n"},"lastSynced":"2026-03-08T02:12:01.158Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined Vue web application development and deployment within custom ERP systems like Frappe.","zh":"非常适合需要在自定义ERP系统（如Frappe）中进行流畅的Vue网页应用开发和部署的前端代理。","ja":"FrappeのようなカスタムERPシステム内でスムーズなVue Webアプリケーションの開発とデプロイを必要とするフロントエンドエージェントに最適です。","ko":"Frappe와 같은 커스텀 ERP 시스템 내에서 원활한 Vue 웹 애플리케이션 개발 및 배포가 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan un desarrollo y despliegue de aplicaciones web Vue optimizados dentro de sistemas ERP personalizados como Frappe.","fr":"Parfait pour les agents Frontend qui ont besoin d''un développement et d''un déploiement d''applications web Vue rationalisés au sein de systèmes ERP personnalisés comme Frappe.","de":"Perfekt für Frontend-Agents, die eine optimierte Entwicklung und Bereitstellung von Vue-Webanwendungen innerhalb von benutzerdefinierten ERP-Systemen wie Frappe benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de desenvolvimento e implantação de aplicações web Vue de forma eficiente dentro de sistemas ERP personalizados como o Frappe.","ru":"Идеально для агентов Frontend, которым необходим упрощенный разработка и развертывание веб-приложений Vue внутри пользовательских систем ERP, таких как Frappe.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى تطوير وتحديث تطبيقات ويب Vue بشكل متدفق داخل أنظمة إدارة الموارد الخاصة مثل Frappe."},"recommendation":{"en":"Empowers agents to create and deploy Vue web applications from initial setup to production, leveraging Vue app initialization, PWA setup, and seamless integration with custom_erp Frappe app, utilizing files like `main.js` and `App.vue`.","zh":"赋予代理创建和部署Vue网页应用的能力，从初始设置到生产，利用Vue应用初始化、PWA设置和与自定义ERP系统Frappe应用的无缝集成，使用诸如`main.js`和`App.vue`的文件。","ja":"エージェントがVue Webアプリケーションを作成してデプロイする機能を提供し、初期設定から生産まで、Vueアプリの初期化、PWA設定、およびカスタムERPシステムのFrappeアプリとのシームレスな統合を利用し、`main.js`や`App.vue`のようなファイルを使用します。","ko":"에이전트가 Vue 웹 애플리케이션을 생성하고 배포할 수 있는 기능을 제공하여 초기 설정에서 생산까지 Vue 애플리케이션 초기화, PWA 설정 및 커스텀 ERP 시스템의 Frappe 애플리케이션과 통일된 통합을 활용하며, `main.js` 및 `App.vue`와 같은 파일을 사용합니다.","es":"Habilita a los agentes a crear y desplegar aplicaciones web Vue desde la configuración inicial hasta la producción, aprovechando la inicialización de la aplicación Vue, la configuración de PWA y la integración sin problemas con la aplicación Frappe de custom_erp, utilizando archivos como `main.js` y `App.vue`.","fr":"Permet aux agents de créer et de déployer des applications web Vue depuis la configuration initiale jusqu''à la production, en exploitant l''initialisation de l''application Vue, la configuration de PWA et l''intégration transparente avec l''application Frappe de custom_erp, en utilisant des fichiers comme `main.js` et `App.vue`.","de":"Ermöglicht es Agents, Vue-Webanwendungen von der initialen Einrichtung bis zur Produktion zu erstellen und bereitzustellen, indem es die Initialisierung der Vue-Anwendung, die PWA-Konfiguration und die nahtlose Integration mit der Frappe-App von custom_erp nutzt, unter Verwendung von Dateien wie `main.js` und `App.vue`.","pt":"Permite que os agentes criem e implantem aplicações web Vue desde a configuração inicial até a produção, aproveitando a inicialização do aplicativo Vue, a configuração do PWA e a integração sem problemas com o aplicativo custom_erp Frappe, utilizando arquivos como `main.js` e `App.vue`.","ru":"Наделяет агентов возможностью создавать и развертывать веб-приложения Vue от начальной настройки до производства, используя инициализацию приложения Vue, настройку PWA и бесшовную интеграцию с пользовательским приложением custom_erp Frappe, используя файлы seperti `main.js` и `App.vue`.","ar":"يمنح الوكلاء القدرة على إنشاء وتحديث تطبيقات ويب Vue من الإعداد الأولي إلى الإنتاج، مستفيدًا من inicialização التطبيق Vue وتكوين PWA والتكامل السلس مع تطبيق custom_erp Frappe، باستخدام ملفات مثل `main.js` و `App.vue`."},"useCases":{"en":["Creating new Vue web applications within custom_erp Frappe app","Configuring PWA setup for enhanced user experience","Deploying Vue web applications to production environments"],"zh":["在自定义ERP系统Frappe应用中创建新的Vue网页应用","配置PWA设置以增强用户体验","将Vue网页应用部署到生产环境"],"ja":["カスタムERPシステムのFrappeアプリ内で新しいVue Webアプリケーションを作成する","PWA設定を構成してユーザーエクスペリエンスを強化する","Vue Webアプリケーションを生产環境にデプロイする"],"ko":["커스텀 ERP 시스템의 Frappe 애플리케이션 내에서 새로운 Vue 웹 애플리케이션을 생성하는 것","PWA 설정을 구성하여 사용자 경험을 향상시키는 것","Vue 웹 애플리케이션을 생산 환경에 배포하는 것"],"es":["Crear nuevas aplicaciones web Vue dentro de la aplicación Frappe de custom_erp","Configurar la configuración de PWA para una experiencia de usuario mejorada","Desplegar aplicaciones web Vue en entornos de producción"],"fr":["Créer de nouvelles applications web Vue au sein de l''application Frappe de custom_erp","Configurer la configuration de PWA pour une expérience utilisateur améliorée","Déployer des applications web Vue dans des environnements de production"],"de":["Erstellen von neuen Vue-Webanwendungen innerhalb der Frappe-App von custom_erp","Konfigurieren der PWA-Einstellungen für eine verbesserte Benutzeroberfläche","Bereitstellen von Vue-Webanwendungen in Produktionsumgebungen"],"pt":["Criar novas aplicações web Vue dentro do aplicativo custom_erp Frappe","Configurar a configuração do PWA para uma experiência de usuário aprimorada","Implantar aplicações web Vue em ambientes de produção"],"ru":["Создание новых веб-приложений Vue внутри приложения custom_erp Frappe","Настройка конфигурации PWA для улучшения пользовательского опыта","Развертывание веб-приложений Vue в производственных средах"],"ar":["إنشاء تطبيقات ويب Vue جديدة داخل تطبيق custom_erp Frappe","تكوين إعدادات PWA لتحسين تجربة المستخدم","نشر تطبيقات ويب Vue في بيئات الإنتاج"]},"limitations":{"en":["Requires custom_erp Frappe app setup","Specific to Vue web application development","Needs understanding of Vue app initialization and PWA setup"],"zh":["需要自定义ERP系统Frappe应用设置","特定于Vue网页应用开发","需要了解Vue应用初始化和PWA设置"],"ja":["カスタムERPシステムのFrappeアプリの設定が必要","Vue Webアプリケーションの開発に特化している","Vueアプリの初期化とPWA設定の理解が必要"],"ko":["커스텀 ERP 시스템의 Frappe 애플리케이션 설정이 필요","Vue 웹 애플리케이션 개발에 특정","Vue 애플리케이션 초기화 및 PWA 설정에 대한 이해가 필요"],"es":["Requiere configuración de la aplicación Frappe de custom_erp","Específico para el desarrollo de aplicaciones web Vue","Necesita comprensión de la inicialización de la aplicación Vue y la configuración de PWA"],"fr":["Nécessite une configuration de l''application Frappe de custom_erp","Spécifique au développement d''applications web Vue","Nécessite une compréhension de l''initialisation de l''application Vue et de la configuration de PWA"],"de":["Benötigt die Konfiguration der Frappe-App von custom_erp","Spezifisch für die Entwicklung von Vue-Webanwendungen","Benötigt das Verständnis der Initialisierung der Vue-Anwendung und der PWA-Konfiguration"],"pt":["Requer configuração do aplicativo custom_erp Frappe","Específico para o desenvolvimento de aplicações web Vue","Necessita de compreensão da inicialização do aplicativo Vue e da configuração do PWA"],"ru":["Требует настройки приложения custom_erp Frappe","Относится конкретно к разработке веб-приложений Vue","Требует понимания инициализации приложения Vue и настройки PWA"],"ar":["يتطلب إعداد تطبيق custom_erp Frappe","محدد لتطوير تطبيقات ويب Vue","يحتاج إلى فهم inicialização التطبيق Vue وإعدادات PWA"]},"version":4},"contentHash":"d8a8581153e6eb0fb3e683e4b6dc4cf052e122d682e027a9a7efa1f7408b7d94","qualityScore":36}');
