INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ghimirerohan/erpnextCCDis/vue-webapp-creation', 'vue-webapp-creation', 'ghimirerohan', 'erpnextCCDis', 'community', 'vue-webapp-creation ghimirerohan erpnextCCDis community The vue-webapp-creation skill guides developers through creating a new Vue web application within the custom_erp Frappe app. It covers initial setup to production deployment for a seamless experience. 本指南介绍如何在自定义 ERP 中创建新的 Vue Web 应用，从设置到生产部署 このガイドでは、カスタム ERP 内で新しい Vue Web アプリケーションを作成する方法を、設定から生産へのデプロイまでを説明します 이 가이드는 커스텀 ERP에서 새로운 Vue 웹 애플리케이션을 생성하는 방법을 설정에서 생산 배포까지 설명합니다 Vue WebApp Creation es una habilidad que te guía a través de la creación de una nueva aplicación web Vue dentro de la aplicación personalizada de ERP Next. Vue WebApp Creation est une compétence qui vous guide à travers la création d''une nouvelle application web Vue au sein de l''application personnalisée ERP Next. Vue WebApp Creation ist eine Fähigkeit, die Sie durch die Erstellung einer neuen Vue-Webanwendung innerhalb der benutzerdefinierten ERP-Next-Anwendung führt. O skill vue-webapp-creation ajuda a criar aplicativos web Vue personalizados no Custom ERP, desde a configuração inicial até a implantação em produção. Навык vue-webapp-creation помогает создать настраиваемые веб-приложения Vue в Custom ERP, от初альной настройки до развертывания в производство. المهارة vue-webapp-creation تساعد على إنشاء تطبيقات ويب Vue المخصصة في Custom ERP، من الإعداد الأولي إلى النشر في الإنتاج. how to use vue-webapp-creation vue-webapp-creation setup guide vue-webapp-creation alternative vue-webapp-creation vs custom_erp vue-webapp-creation install what is vue-webapp-creation vue-webapp-creation tutorial vue-webapp-creation frappe app integration Vue WebApp Creation 自定义 ERP Vue.js Frappe PWA 生产部署 AI エージェント Web 应用创建 Creates a new Vue web application at a specified route, such as /my-app Initializes the Vue app with a main.js file in the src directory Sets up the root component with PWA configuration in App.vue Organizes the source directory with index.html and src folders Supports production deployment for the created Vue web application vue-webapp-creation is a skill that enables developers to create new Vue web applications within the custom_erp Frappe app, streamlining the development process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SeoulMomentTech/seoul-moment-fe/figma-to-code', 'community', 'SeoulMomentTech', 'seoul-moment-fe', 'SeoulMomentTech/seoul-moment-fe', 'figma-to-code', 0, 0, 36, '2026-03-08T01:57:15.602Z', '2026-03-08T02:13:05.534Z', 'abf6f191a84df4a9c6c73dd994f613c0de8ae060c607bff30b600e4a79f17125', '{"id":"SeoulMomentTech/seoul-moment-fe/figma-to-code","name":"figma-to-code","description":{"en":"The Figma-to-Code skill analyzes Figma designs and generates React code compatible with Seoul Moment''s standard tech stack, including Next.js, Tailwind CSS, and Zustand. This skill benefits developers working on React projects","zh":"Figma 到代码转换功能支持 Next.js 和 React 代码生成，集成了 Tailwind CSS v4 和 Zustand","ja":"Figma の設計を分析して、Next.js と React のコードを生成します","ko":"피그마 설계를 분석하여 Seoul Moment 프로젝트의 표준 기술 스택과 컨벤션에 맞는 React 코드로 변환","es":"El skill Figma a código convierte diseños de Figma en código React con Next.js y Tailwind CSS. Utiliza tecnologías como Zustand y TanStack Query","fr":"Le skill Figma vers code convertit les designs Figma en code React avec Next.js et Tailwind CSS. Il utilise des technologies comme Zustand et TanStack Query","de":"Das Skill Figma zu Code wandelt Figma-Designs in React-Code mit Next.js und Tailwind CSS um. Es verwendet Technologien wie Zustand und TanStack Query","pt":"O skill Figma-to-Code é uma ferramenta que converte designs do Figma em código React, utilizando o framework Next.js e bibliotecas como Tailwind CSS e Zustand.","ru":"Навык Figma-to-Code является инструментом, который преобразует дизайн Figma в код React, используя фреймворк Next.js и библиотеки как Tailwind CSS и Zustand.","ar":"مهارة Figma-to-Code هي أداة تحويل التصاميم من Figma إلى كود React، باستخدام إطار Next.js و المكتبات مثل Tailwind CSS و Zustand"},"seo":{"title":{"en":"Figma-to-Code: Next.js and React Code Generation Setup Gu...","zh":"Figma 到代码转换 Setup Guide","ja":"Figma からコードへの変換ベストプラクティス - AIエージェント","ko":"피그마 설계를 코드로 변환하는 가이드 - Figma to Code Skill","es":"Guía de configuración de Figma a código con React y Next.js","fr":"Guide de mise en place de Figma vers code avec React et N...","de":"Einrichtungsleitfaden für Figma zu Code mit React und Nex...","pt":"Guia de Configuração Figma para Código com Next.js e React","ru":"ИИ Агент Figma-to-Code: Руководство по Настройке для Разр...","ar":"دليل إعداد أداة تحويل التصميم إلى كود مع React و Next.js"},"description":{"en":"Unlock efficient design-to-code workflows with Figma-to-Code. Get started with our setup guide and discover how to generate React code with Next.js and Tailw...","zh":"使用 Figma 到代码转换功能，快速生成 Next.js 和 React 代码，支持 Tailwind CSS v4 和 Zustand","ja":"Figma の設計を分析して、Next.js と React のコードを生成します - AIエージェントの Figma からコードへの変換","ko":"피그마 설계를 분석하여 Seoul Moment 프로젝트의 표준 기술 스택과 컨벤션에 맞는 React 코드로 변환하는 가이드","es":"Convierta diseños de Figma en código React con nuestra guía de configuración. Aprenda a utilizar Next.js, Tailwind CSS y más","fr":"Convertissez vos designs Figma en code React avec notre guide de configuration. Découvrez comment utiliser Next.js, Tailwind CSS et plus","de":"Wandeln Sie Figma-Designs in React-Code um mit unserer Einrichtungsanleitung. Erfahren Sie, wie Sie Next.js, Tailwind CSS und mehr verwenden","pt":"Aprenda a converter designs do Figma em código React com o framework Next.js e bibliotecas como Tailwind CSS e Zustand","ru":"Откройте для себя, как преобразовать дизайн Figma в код React с помощью фреймворка Next.js и библиотек như Tailwind CSS и Zustand","ar":"تعرف على كيفية تحويل التصاميم من Figma إلى كود React باستخدام إطار Next.js و المكتبات مثل Tailwind CSS و Zustand"},"definition":{"en":"Figma-to-code is a skill that converts Figma designs into React code, utilizing technologies like Next.js, Vite, and Tailwind CSS to ensure compatibility with Seoul Moment''s project standards","zh":"Figma 到代码转换是一种将 Figma 设计转换为 Next.js 和 React 代码的功能","ja":"Figma からコードへの変換は、Figma の設計を Next.js と React のコードに変換する機能です","ko":"피그마 설계를 코드로 변환하는 기능은 Figma 설계를 Seoul Moment 프로젝트의 표준 기술 스택과 컨벤션에 맞는 React 코드로 변환","es":"El skill Figma a código es una herramienta que convierte diseños de Figma en código React","fr":"Le skill Figma vers code est un outil qui convertit les designs Figma en code React","de":"Das Skill Figma zu Code ist ein Tool, das Figma-Designs in React-Code umwandelt","pt":"O que é Figma-to-Code? É uma ferramenta que analisa designs do Figma e gera código React com base em tecnologias como Next.js e Tailwind CSS","ru":"Что такое Figma-to-Code? Это инструмент, который анализирует дизайн Figma и генерирует код React на основе технологий как Next.js и Tailwind CSS","ar":"ما هي أداة Figma-to-Code؟ هي أداة تحليل التصاميم من Figma وتوليد كود React بالاعتماد على تقنيات مثل Next.js و Tailwind CSS"},"features":{"en":["Generates React code with Next.js (App Router) and Vite support","Utilizes Tailwind CSS v4 for styling and layout management","Integrates with @seoul-moment/ui for internal component library management","Supports Lucide React icons and custom SVG icons","Employs Zustand for state management and TanStack Query for data fetching"],"zh":["支持 Next.js 和 React 代码生成","集成了 Tailwind CSS v4","支持 Zustand 状态管理","使用 Lucide React 图标","支持 TanStack Query 数据获取"],"ja":["Next.js と React のコードを生成します","Tailwind CSS v4 をサポート","Zustand 状態管理をサポート","Lucide React アイコンを使用","TanStack Query データ取得をサポート"],"ko":["Next.js 와 React 코드를生成","Tailwind CSS v4 지원","Zustand 상태 관리 지원","Lucide React 아이콘 사용","TanStack Query 데이터 가져오기 지원"],"es":["Conversión de diseños de Figma en código React","Utiliza Next.js y Tailwind CSS","Integración con Zustand y TanStack Query","Compatibilidad con Lucide React y SVG","Utiliza la biblioteca de componentes @seoul-moment/ui"],"fr":["Conversion de designs Figma en code React","Utilise Next.js et Tailwind CSS","Intégration avec Zustand et TanStack Query","Compatibilité avec Lucide React et SVG","Utilise la bibliothèque de composants @seoul-moment/ui"],"de":["Umwandlung von Figma-Designs in React-Code","Verwendung von Next.js und Tailwind CSS","Integration mit Zustand und TanStack Query","Kompatibilität mit Lucide React und SVG","Verwendung der Komponentenbibliothek @seoul-moment/ui"],"pt":["Conversão de designs do Figma em código React","Utilização do framework Next.js e Vite","Integração com bibliotecas como Tailwind CSS e Zustand","Suporte a ícones com Lucide React","Gestão de estado com Zustand","Recuperação de dados com TanStack Query"],"ru":["Преобразование дизайна Figma в код React","Использование фреймворка Next.js и Vite","Интеграция с библиотеками как Tailwind CSS и Zustand","Поддержка иконок с Lucide React","Управление состоянием с Zustand","Получение данных с TanStack Query"],"ar":["تحويل التصاميم من Figma إلى كود React","استخدام إطار Next.js و Vite","التكامل مع المكتبات مثل Tailwind CSS و Zustand","دعم الأيقونات مع Lucide React","إدارة الحالة مع Zustand","استرجاع البيانات مع TanStack Query"]},"keywords":{"en":["how to use Figma-to-Code","Figma-to-Code setup guide","Figma-to-Code alternative","Figma-to-Code vs Sketch-to-Code","Figma-to-Code install","React code generation with Next.js","Tailwind CSS integration with Figma-to-Code","Seoul Moment project standards"],"zh":["Figma 到代码转换","Next.js 代码生成","React 代码生成","Tailwind CSS v4","Zustand 状态管理","Lucide React 图标","TanStack Query 数据获取"],"ja":["Figma からコードへの変換","Next.js コード生成","React コード生成","Tailwind CSS v4","Zustand 状態管理","Lucide React アイコン","TanStack Query データ取得"],"ko":["피그마 설계를 코드로 변환","Next.js 코드 생성","React 코드 생성","Tailwind CSS v4","Zustand 상태 관리","Lucide React 아이콘","TanStack Query 데이터 가져오기"],"es":["Figma a código","React","Next.js","Tailwind CSS","Zustand","TanStack Query","Lucide React","SVG","desarrollo web","herramientas de diseño"],"fr":["Figma vers code","React","Next.js","Tailwind CSS","Zustand","TanStack Query","Lucide React","SVG","développement web","outils de design"],"de":["Figma zu Code","React","Next.js","Tailwind CSS","Zustand","TanStack Query","Lucide React","SVG","Webentwicklung","Design-tools"],"pt":["Figma para código","Next.js","React","Tailwind CSS","Zustand","TanStack Query","Desenvolvimento web","Ferramentas de desenvolvimento","Conversão de designs"],"ru":["Figma в код","Next.js","React","Tailwind CSS","Zustand","TanStack Query","Веб-разработка","Инструменты разработки","Преобразование дизайна"],"ar":["Figma إلى كود","Next.js","React","Tailwind CSS","Zustand","TanStack Query","تطوير الويب","أدوات التطوير","تحويل التصاميم"]}},"owner":"SeoulMomentTech","repo":"seoul-moment-fe","repoPath":"SeoulMomentTech/seoul-moment-fe","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.602Z","topics":[],"category":"community","skillMd":{"name":"figma-to-code","description":"피그마 설계를 분석하여 프로젝트의 Tailwind v4 기반 기술 스택 및 컨벤션에 맞춰 코드로 변환합니다. UI 컴포넌트 라이브러리(@seoul-moment/ui)를 우선적으로 활용합니다.","bodyPreview":"# Figma to Code Skill\n\n이 스킬은 피그마 설계를 분석하여 Seoul Moment 프로젝트의 표준 기술 스택과 컨벤션에 맞는 React 코드로 변환하는 가이드를 제공합니다.\n\n## 프로젝트 표준 기술 스택\n\n- **Framework**: Next.js (App Router) 또는 Vite (React)\n- **Styling**: Tailwind CSS v4\n- **UI Library**: `@seoul-moment/ui` (내부 컴포넌트 라이브러리)\n- **Icons**: Lucide React (또는 프로젝트 내 SVG)\n- **State Management**: Zustand\n- **Data Fetching**: TanStack Query (React Query)\n\n## 워크플로우\n\n1. **디자인 분석 (`get_design_context`)**: 피그마 URL 또는 Node ID를 사용하여 디자인 메타데이터와 코드를 추출합니다.\n2. **컴포넌트 매핑**: 디","body":"# Figma to Code Skill\n\n이 스킬은 피그마 설계를 분석하여 Seoul Moment 프로젝트의 표준 기술 스택과 컨벤션에 맞는 React 코드로 변환하는 가이드를 제공합니다.\n\n## 프로젝트 표준 기술 스택\n\n- **Framework**: Next.js (App Router) 또는 Vite (React)\n- **Styling**: Tailwind CSS v4\n- **UI Library**: `@seoul-moment/ui` (내부 컴포넌트 라이브러리)\n- **Icons**: Lucide React (또는 프로젝트 내 SVG)\n- **State Management**: Zustand\n- **Data Fetching**: TanStack Query (React Query)\n\n## 워크플로우\n\n1. **디자인 분석 (`get_design_context`)**: 피그마 URL 또는 Node ID를 사용하여 디자인 메타데이터와 코드를 추출합니다.\n2. **컴포넌트 매핑**: 디자인의 각 요소를 `@seoul-moment/ui` 컴포넌트로 매핑합니다.\n3. **레이아웃 구조화**: `VStack`, `HStack`, `Flex` 컴포넌트를 사용하여 레이아웃을 구성합니다.\n4. **스타일링 적용**: Tailwind v4 유틸리티 클래스를 사용하여 세부 스타일을 조정합니다.\n5. **인터랙션 및 상태 추가**: 필요한 경우 클릭 핸들러, 로딩 상태, Zustand 스토어 연결 등을 추가합니다.\n\n## 코드 변환 원칙\n\n### 1. @seoul-moment/ui 우선 사용\n디자인 요소가 UI 라이브러리에 존재하는 경우, 직접 구현하는 대신 라이브러리 컴포넌트를 사용합니다.\n- `Button`, `Input`, `Badge`, `Card`, `Dialog`, `Tabs` 등\n- 레이아웃: `VStack` (세로), `HStack` (가로), `Flex` (유연한 레이아웃)\n\n### 2. 레이아웃 컨벤션\n- 마진(Margin) 대신 **Gap** 사용을 권장합니다 (`VStack`, `HStack`의 `gap` 속성 활용).\n- 패딩(Padding)은 컨테이너 컴포넌트에서 Tailwind 클래스로 처리합니다 (`p-4`, `px-6` 등).\n\n### 3. 스타일링 (Tailwind v4)\n- 하드코딩된 색상값 대신 Tailwind 테마 변수를 사용합니다.\n- 폰트 크기, 간격 등은 테마 시스템에 정의된 값을 따릅니다.\n\n### 4. 코드 구조\n- **Client Component**: 인터랙션이 필요한 경우 파일 상단에 `''use client'';`를 명시합니다.\n- **Props**: 컴포넌트의 Props 타입을 명확히 정의합니다.\n\n## 예시: 변환 패턴\n\n### 가로 배치 (Header/Action Bar)\n```tsx\nimport { HStack, Button } from \"@seoul-moment/ui\";\n\nexport function Header() {\n  return (\n    <HStack justify=\"between\" align=\"center\" className=\"w-full py-4 px-6 border-b border-neutral-100\">\n      <h1 className=\"text-xl font-bold\">제목</h1>\n      <HStack gap={8}>\n        <Button variant=\"outline\">취소</Button>\n        <Button>저장</Button>\n      </HStack>\n    </HStack>\n  );\n}\n```\n\n### 세로 배치 (Card List)\n```tsx\nimport { VStack, Card } from \"@seoul-moment/ui\";\n\nexport function ProfileCard() {\n  return (\n    <Card className=\"p-6\">\n      <VStack gap={16} align=\"center\">\n        <div className=\"w-20 h-20 rounded-full bg-neutral-200\" />\n        <VStack gap={4} align=\"center\">\n          <span className=\"text-lg font-semibold\">사용자 이름</span>\n          <span className=\"text-sm text-neutral-500\">user@example.com</span>\n        </VStack>\n      </VStack>\n    </Card>\n  );\n}\n```\n\n## 참고 사항\n- 디자인의 복잡도가 높은 경우, 작은 단위의 컴포넌트로 분할하여 구현합니다.\n- 이미지 자산은 `public/` 디렉토리에 배치하고 Next.js `Image` 컴포넌트를 사용합니다."},"lastSynced":"2026-03-08T02:13:05.534Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing automated React code generation from Figma designs.","zh":"非常适合需要从Figma设计中自动生成React代码的前端代理。","ja":"Figmaデザインから自動的にReactコードを生成する必要があるフロントエンドエージェントに最適です。","ko":"Figma 디자인에서 자동으로 React 코드를 생성해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes frontend que necesitan generación automática de código React desde diseños de Figma.","fr":"Parfait pour les agents frontend ayant besoin de génération automatique de code React à partir de conceptions Figma.","de":"Perfekt für Frontend-Agents, die automatische React-Code-Generierung aus Figma-Entwürfen benötigen.","pt":"Perfeito para Agentes Frontend que precisam de geração automática de código React a partir de designs do Figma.","ru":"Идеально подходит для агентов Frontend, которым требуется автоматическая генерация кода React из дизайнов Figma.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى توليد تلقائي للكود React من تصاميم Figma."},"recommendation":{"en":"Empowers agents to generate compatible React code using Next.js, Tailwind CSS, and Zustand, streamlining development workflows with standardized tech stacks and UI libraries like @seoul-moment/ui and Lucide React.","zh":"赋予代理生成兼容的React代码，使用Next.js、Tailwind CSS和Zustand，通过标准化的技术栈和UI库（如@seoul-moment/ui和Lucide React）简化开发工作流。","ja":"エージェントに、Next.js、Tailwind CSS、およびZustandを使用して互換性のあるReactコードを生成する能力を付与し、標準化されたテクノロジースタックとUIライブラリ（@seoul-moment/uiとLucide Reactなど）で開発ワークフローを簡素化します。","ko":"에이전트가 Next.js, Tailwind CSS 및 Zustand를 사용하여 호환되는 React 코드를 생성할 수 있도록 하여, 표준화된 기술 스택 및 UI 라이브러리(@seoul-moment/ui 및 Lucide React 등)를 통해 개발 워크플ロー를 간소화합니다.","es":"Habilita a los agentes a generar código React compatible utilizando Next.js, Tailwind CSS y Zustand, simplificando los flujos de trabajo de desarrollo con pilas tecnológicas estandarizadas y bibliotecas de UI como @seoul-moment/ui y Lucide React.","fr":"Permet aux agents de générer du code React compatible en utilisant Next.js, Tailwind CSS et Zustand, rationalisant les flux de travail de développement avec des piles technologiques standardisées et des bibliothèques d''interface utilisateur comme @seoul-moment/ui et Lucide React.","de":"Ermächtigt Agenten, kompatiblen React-Code mit Next.js, Tailwind CSS und Zustand zu generieren, indem Entwicklungsworkflows mit standardisierten Technologiestacks und Benutzeroberflächenbibliotheken wie @seoul-moment/ui und Lucide React rationalisiert werden.","pt":"Habilita os agentes a gerar código React compatível usando Next.js, Tailwind CSS e Zustand, otimizando fluxos de trabalho de desenvolvimento com pilhas de tecnologia e bibliotecas de UI padronizadas como @seoul-moment/ui e Lucide React.","ru":"Наделяет агентов возможностью генерировать совместимый код React с использованием Next.js, Tailwind CSS и Zustand, оптимизируя рабочие процессы разработки с помощью стандартизированных технологических стеков и библиотек UI, таких как @seoul-moment/ui и Lucide React.","ar":"YTEمكن الوكلاء من توليد كود React متوافق باستخدام Next.js و Tailwind CSS و Zustand، وتحسين سير عمل التطوير باستخدام سلاسل تقنية ومكتبات واجهة المستخدم المعيارية مثل @seoul-moment/ui و Lucide React."},"useCases":{"en":["Automating React component generation from Figma designs","Generating compatible code for Next.js and Vite frameworks","Streamlining UI development with standardized Tailwind CSS styling"],"zh":["从Figma设计中自动生成React组件","为Next.js和Vite框架生成兼容代码","使用标准化的Tailwind CSS样式简化UI开发"],"ja":["FigmaデザインからReactコンポーネントを自動生成する","Next.jsとViteフレームワークの互換性のあるコードを生成する","標準化されたTailwind CSSスタイルでUI開発を簡素化する"],"ko":["Figma 디자인에서 React 컴포넌트를 자동으로 생성하는 것","Next.js 및 Vite 프레임워크에 대한 호환되는 코드를 생성하는 것","표준화된 Tailwind CSS 스타일을 사용하여 UI 개발을 간소화하는 것"],"es":["Automatización de la generación de componentes React desde diseños de Figma","Generación de código compatible para los frameworks Next.js y Vite","Racionalización del desarrollo de UI con estilos estandarizados de Tailwind CSS"],"fr":["Automatisation de la génération de composants React à partir de conceptions Figma","Génération de code compatible pour les frameworks Next.js et Vite","Rationalisation du développement d''interface utilisateur avec des styles standardisés de Tailwind CSS"],"de":["Automatisierung der React-Komponenten-Generierung aus Figma-Entwürfen","Generierung von kompatiblen Code für die Frameworks Next.js und Vite","Rationalisierung der Benutzeroberflächen-Entwicklung mit standardisierten Tailwind CSS-Stilen"],"pt":["Automatizar a geração de componentes React a partir de designs do Figma","Gerar código compatível para os frameworks Next.js e Vite","Otimizar o desenvolvimento de UI com estilização Tailwind CSS padronizada"],"ru":["Автоматизировать генерацию компонентов React из дизайнов Figma","Генерировать совместимый код для фреймворков Next.js и Vite","Оптимизировать разработку UI с помощью стандартизированной стилевой обработки Tailwind CSS"],"ar":["توليد تلقائي لمكونات React من تصاميم Figma","توليد كود متوافق لأطر العمل Next.js و Vite","تحسين تطوير واجهة المستخدم باستخدام تنسيق Tailwind CSS المعياري"]},"limitations":{"en":["Requires Figma design files or Node IDs","Limited to React projects with specific tech stacks (Next.js, Tailwind CSS, Zustand)","Dependent on @seoul-moment/ui and Lucide React libraries"],"zh":["需要Figma设计文件或节点ID","仅限于具有特定技术栈（Next.js、Tailwind CSS、Zustand）的React项目","依赖于@seoul-moment/ui和Lucide React库"],"ja":["FigmaデザインファイルまたはノードIDが必要","特定のテクノロジースタック（Next.js、Tailwind CSS、Zustand）を持つReactプロジェクトのみ","@seoul-moment/uiとLucide Reactライブラリに依存する"],"ko":["Figma 디자인 파일 또는 노드 ID가 필요함","특정 기술 스택(Next.js, Tailwind CSS, Zustand)을 갖춘 React 프로젝트만 해당함","@seoul-moment/ui 및 Lucide React 라이브러리에 의존함"],"es":["Requiere archivos de diseño de Figma o IDs de nodo","Limitado a proyectos React con pilas tecnológicas específicas (Next.js, Tailwind CSS, Zustand)","Dependiente de las bibliotecas @seoul-moment/ui y Lucide React"],"fr":["Nécessite des fichiers de conception Figma ou des ID de nœud","Limité aux projets React avec des piles technologiques spécifiques (Next.js, Tailwind CSS, Zustand)","Dépendant des bibliothèques @seoul-moment/ui et Lucide React"],"de":["Benötigt Figma-Entwurfsdateien oder Knoten-IDs","Begrenzt auf React-Projekte mit bestimmten Technologiestacks (Next.js, Tailwind CSS, Zustand)","Abhängig von den Bibliotheken @seoul-moment/ui und Lucide React"],"pt":["Exige arquivos de design do Figma ou IDs de nó","Limitado a projetos React com pilhas de tecnologia específicas (Next.js, Tailwind CSS, Zustand)","Dependente das bibliotecas @seoul-moment/ui e Lucide React"],"ru":["Требует файлов дизайна Figma или идентификаторов узлов","Ограничен проектами React с конкретными технологическими стеками (Next.js, Tailwind CSS, Zustand)","Зависит от библиотек @seoul-moment/ui и Lucide React"],"ar":["يتطلب ملفات تصميم Figma أو معرّفات العقد","محدود بمشاريع React ذات السلاسل التقنية المحددة (Next.js و Tailwind CSS و Zustand)","يعتمد على مكتبات @seoul-moment/ui و Lucide React"]},"version":4},"contentHash":"abf6f191a84df4a9c6c73dd994f613c0de8ae060c607bff30b600e4a79f17125","qualityScore":36}');
