INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SeoulMomentTech/seoul-moment-fe/figma-to-code', 'figma-to-code', 'SeoulMomentTech', 'seoul-moment-fe', 'community', 'figma-to-code SeoulMomentTech seoul-moment-fe community The Figma-to-Code skill analyzes Figma designs and generates React code compatible with Seoul Moment''s standard tech stack, including Next.js, Tailwind CSS, and Zustand. This skill benefits developers working on React projects Figma 到代码转换功能支持 Next.js 和 React 代码生成，集成了 Tailwind CSS v4 和 Zustand Figma の設計を分析して、Next.js と React のコードを生成します 피그마 설계를 분석하여 Seoul Moment 프로젝트의 표준 기술 스택과 컨벤션에 맞는 React 코드로 변환 El skill Figma a código convierte diseños de Figma en código React con Next.js y Tailwind CSS. Utiliza tecnologías como Zustand y TanStack Query Le skill Figma vers code convertit les designs Figma en code React avec Next.js et Tailwind CSS. Il utilise des technologies comme Zustand et TanStack Query Das Skill Figma zu Code wandelt Figma-Designs in React-Code mit Next.js und Tailwind CSS um. Es verwendet Technologien wie Zustand und TanStack Query O skill Figma-to-Code é uma ferramenta que converte designs do Figma em código React, utilizando o framework Next.js e bibliotecas como Tailwind CSS e Zustand. Навык Figma-to-Code является инструментом, который преобразует дизайн Figma в код React, используя фреймворк Next.js и библиотеки как Tailwind CSS и Zustand. مهارة Figma-to-Code هي أداة تحويل التصاميم من Figma إلى كود React، باستخدام إطار Next.js و المكتبات مثل Tailwind CSS و Zustand how to use Figma-to-Code Figma-to-Code setup guide Figma-to-Code alternative Figma-to-Code vs Sketch-to-Code Figma-to-Code install React code generation with Next.js Tailwind CSS integration with Figma-to-Code Seoul Moment project standards Figma 到代码转换 Next.js 代码生成 React 代码生成 Tailwind CSS v4 Zustand 状态管理 Lucide React 图标 TanStack Query 数据获取 Generates React code with Next.js (App Router) and Vite support Utilizes Tailwind CSS v4 for styling and layout management Integrates with @seoul-moment/ui for internal component library management Supports Lucide React icons and custom SVG icons Employs Zustand for state management and TanStack Query for data fetching Figma-to-code is a skill that converts Figma designs into React code, utilizing technologies like Next.js, Vite, and Tailwind CSS to ensure compatibility with Seoul Moment''s project standards');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LongIV999/Openclawd/discord', 'community', 'LongIV999', 'Openclawd', 'LongIV999/Openclawd', 'discord', 0, 0, 36, '2026-03-08T01:57:15.616Z', '2026-03-08T02:13:21.965Z', '9b53327307b414cc0abecbd911bcd906c24e9b4ce5e30b103ad4cebdb5fe4eb2', '{"id":"LongIV999/Openclawd/discord","name":"discord","description":{"en":"The Discord skill enables AI agents to interact with Discord channels and users. It supports sending messages, respecting gating, and using explicit IDs for guilds, channels, and users.","zh":"使用message工具与Discord集成，实现多种功能，如发送消息和管理频道","ja":"messageツールを使用してDiscordと連携し、メッセージの送信やチャンネルの管理などを行います","ko":"message 도구를 사용하여 Discord와 연동하여 메시지 전송 및 채널 관리 등을 수행합니다","es":"La integración de Discord permite a los agentes de IA interactuar con canales y usuarios a través de la herramienta de mensaje. Configura tu agente para enviar y recibir mensajes en Discord.","fr":"L''intégration de Discord permet aux outils d''IA d''interagir avec les canaux et les utilisateurs via l''outil de message. Configurez votre outil pour envoyer et recevoir des messages sur Discord.","de":"Die Integration von Discord ermöglicht es KI-Agents, mit Kanälen und Benutzern über das Message-Tool zu interagieren. Konfigurieren Sie Ihren Agenten, um Nachrichten in Discord zu senden und zu empfangen.","pt":"O Discord é uma plataforma de comunicação que pode ser configurada para desenvolvedores. Aprenda a usar o message tool e respeitar o gating.","ru":"Discord - это платформа коммуникации, которую можно настроить для ИИ Агентов. Узнайте, как использовать message tool и уважать gating.","ar":"الديسكورد هو منصة اتصال يمكن تنظیمها لمنصات الإي الأي الجديدة. تعلم كيفية استخدام أداة الرسالة واحترام الحجز."},"seo":{"title":{"en":"Discord: Setup Guide for AI Agents | AI Agent Skill","zh":"Discord集成指南：使用message工具","ja":"Discord連携ガイド：messageツールの使い方","ko":"Discord 연동 가이드: message 도구 사용법","es":"Guía de configuración de Discord para agentes de IA","fr":"Guide de configuration de Discord pour les outils d''IA","de":"Discord-Setup-Leitfaden für KI-Agents","pt":"Guia de Configuração do Discord para Desenvolvedores","ru":"Настройка Discord для ИИ Агентов: Руководство","ar":"دليل إعداد الديسكورد لمنصات الإي الأي الجديدة"},"description":{"en":"Unlock the power of Discord with our AI agent skill. Learn how to send messages, respect gating, and prefer explicit IDs. Get started with our setup guide to...","zh":"了解如何使用message工具与Discord集成，包括设置和最佳实践","ja":"Discordと連携するためのmessageツールの設定方法とベストプラクティスを学びましょう","ko":"message 도구를 사용하여 Discord와 연동하는 방법에 대해 알아보세요","es":"Aprende a configurar Discord para agentes de IA con nuestra guía paso a paso. Descubre cómo utilizar la herramienta de mensaje para interactuar con canales y...","fr":"Découvrez comment configurer Discord pour les outils d''IA avec notre guide étape par étape. Apprenez à utiliser l''outil de message pour interagir avec les ca...","de":"Erfahren Sie, wie Sie Discord für KI-Agents konfigurieren, mit unserer Schritt-für-Schritt-Anleitung. Entdecken Sie, wie Sie das Message-Tool verwenden, um m...","pt":"Aprenda a configurar o Discord para desenvolvedores com nossa guia passo a passo. Descubra como usar o message tool e respeitar o gating.","ru":"Узнайте, как настроить Discord для ИИ Агентов с нашей пошаговой инструкцией. Откройте для себя, как использовать message tool и уважать gating.","ar":"تعلم كيفية تنظیم الديسكورد لمنصات الإي الأي الجديدة مع دليلنا الخطوة خطوة. اكتشف كيفية استخدام أداة الرسالة واحترام الحجز."},"definition":{"en":"Discord is a communication platform that allows AI agents to send messages and interact with users via the message tool, with features like channel and user targeting.","zh":"Discord集成是指使用message工具与Discord平台进行交互","ja":"Discord連携とは、messageツールを使用してDiscordプラットフォームと交互することです","ko":"Discord 연동은 message 도구를 사용하여 Discord 플랫폼과 상호 작용하는 것을 의미합니다","es":"La integración de Discord es una función que permite a los agentes de IA interactuar con la plataforma de comunicación en línea Discord.","fr":"L''intégration de Discord est une fonctionnalité qui permet aux outils d''IA d''interagir avec la plateforme de communication en ligne Discord.","de":"Die Integration von Discord ist eine Funktion, die es KI-Agents ermöglicht, mit der Online-Kommunikationsplattform Discord zu interagieren.","pt":"O Discord é uma plataforma de comunicação que permite aos desenvolvedores usar o message tool para enviar e receber mensagens.","ru":"Discord - это платформа коммуникации, которая позволяет ИИ Агентам использовать message tool для отправки и получения сообщений.","ar":"الديسكورد هو منصة اتصال تتيح لمنصات الإي الأي الجديدة استخدام أداة الرسالة لإرسال واستلام الرسائل."},"features":{"en":["Sends messages to Discord channels and users via the message tool","Respects gating for actions like roles, moderation, presence, and channels","Supports explicit IDs for guilds, channels, and users","Allows multi-account support with optional accountId","Targets specific channels and users with to: channel:<id> or to: user:<id> syntax"],"zh":["使用channel属性指定Discord频道","支持发送消息和管理频道","可选的accountId参数用于多账户支持","使用guildId、channelId、messageId和userId进行显式ID指定"],"ja":["channel属性を使用してDiscordチャンネルを指定","メッセージの送信とチャンネルの管理をサポート","オプションのaccountIdパラメータを使用してマルチアカウントをサポート","guildId、channelId、messageId、userIdを使用して明示的なIDを指定"],"ko":["channel 속성을 사용하여 Discord 채널을 지정","메시지 전송 및 채널 관리를 지원","옵션의 accountId 매개 변수를 사용하여 다중 계정 지원","guildId, channelId, messageId, userId를 사용하여 명시적인 ID를 지정"],"es":["Envío de mensajes a canales y usuarios de Discord","Recepción de mensajes de Discord mediante la herramienta de mensaje","Compatibilidad con varias cuentas mediante el parámetro accountId","Respeto de las restricciones de gating para acciones en Discord","Uso de IDs de canal, mensaje y usuario para interactuar con Discord"],"fr":["Envoi de messages aux canaux et utilisateurs de Discord","Réception de messages de Discord via l''outil de message","Compatibilité avec plusieurs comptes via le paramètre accountId","Respect des restrictions de gating pour les actions sur Discord","Utilisation des IDs de canal, de message et d''utilisateur pour interagir avec Discord"],"de":["Senden von Nachrichten an Discord-Kanäle und -Benutzer","Empfangen von Discord-Nachrichten über das Message-Tool","Unterstützung mehrerer Konten über den Parameter accountId","Einhalten der Gating-Beschränkungen für Aktionen in Discord","Verwendung von Kanal-, Nachrichten- und Benutzer-IDs zur Interaktion mit Discord"],"pt":["Uso do message tool para enviar e receber mensagens","Respeito ao gating para controlar as ações do Discord","Preferência por ids explícitos para guildId, channelId, messageId e userId","Opção de multi-conta com accountId","Ações de envio de mensagens para canais e usuários específicos"],"ru":["Использование message tool для отправки и получения сообщений","Уважение к gating для контроля действий Discord","Преференция явных идентификаторов для guildId, channelId, messageId и userId","Возможность многоконтурности с accountId","Действия отправки сообщений для конкретных каналов и пользователей"],"ar":["استخدام أداة الرسالة لإرسال واستلام الرسائل","احترام الحجز للسيطرة على إجراءات الديسكورد","التفضيل للهويات الصريحة لguildId، channelId، messageId وuserId","خيار متعدد الحسابات مع accountId","إجراءات إرسال الرسائل إلى القنوات والمستخدمين المحددين"]},"keywords":{"en":["how to use discord with AI agents","discord setup guide for AI","what is discord in AI","discord vs slack for AI integration","discord install for AI agents","discord API for AI development","discord bot setup for AI","discord messaging for AI agents","discord integration with AI platforms"],"zh":["Discord集成","message工具","Discord API","Discord开发","AIエージェント","Discord自动化","消息工具","Discord平台"],"ja":["Discord連携","messageツール","Discord API","Discord開発","AIエージェント","Discord自動化","メッセージツール","Discordプラットフォーム"],"ko":["Discord 연동","message 도구","Discord API","Discord 개발","AI 에이전트","Discord 자동화","메시지 도구","Discord 플랫폼"],"es":["Discord para agentes de IA","Integración de Discord","Herramienta de mensaje de Discord","Configuración de Discord para IA","Agentes de IA en Discord","Desarrollo de chatbots para Discord"],"fr":["Discord pour les outils d''IA","Intégration de Discord","Outil de message de Discord","Configuration de Discord pour l''IA","Outils d''IA sur Discord","Développement de chatbots pour Discord"],"de":["Discord für KI-Agents","Discord-Integration","Discord-Message-Tool","Discord-Konfiguration für KI","KI-Agents auf Discord","Entwicklung von Chatbots für Discord"],"pt":["discord para desenvolvedores","configurar discord","message tool","gating discord","ids explícitos discord","multi-conta discord","ações de envio de mensagens discord"],"ru":["discord для ИИ Агентов","настройка discord","message tool","gating discord","явные идентификаторы discord","многоконтурность discord","действия отправки сообщений discord"],"ar":["الديسكورد لمنصات الإي الأي الجديدة","تنظیم الديسكورد","أداة الرسالة","الحجز الديسكورد","الهويات الصريحة الديسكورد","خيار متعدد الحسابات الديسكورد","إجراءات إرسال الرسائل الديسكورد"]}},"owner":"LongIV999","repo":"Openclawd","repoPath":"LongIV999/Openclawd","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.616Z","topics":[],"category":"community","skillMd":{"name":"discord","description":"Discord ops via the message tool (channel=discord).","bodyPreview":"# Discord (Via `message`)\n\nUse the `message` tool. No provider-specific `discord` tool exposed to the agent.\n\n## Musts\n\n- Always: `channel: \"discord\"`.\n- Respect gating: `channels.discord.actions.*` (some default off: `roles`, `moderation`, `presence`, `channels`).\n- Prefer explicit ids: `guildId`, `channelId`, `messageId`, `userId`.\n- Multi-account: optional `accountId`.\n\n## Targets\n\n- Send-like actions: `to: \"channel:<id>\"` or `to: \"user:<id>\"`.\n- Message-specific actions: `channelId: \"<id>\"`","body":"# Discord (Via `message`)\n\nUse the `message` tool. No provider-specific `discord` tool exposed to the agent.\n\n## Musts\n\n- Always: `channel: \"discord\"`.\n- Respect gating: `channels.discord.actions.*` (some default off: `roles`, `moderation`, `presence`, `channels`).\n- Prefer explicit ids: `guildId`, `channelId`, `messageId`, `userId`.\n- Multi-account: optional `accountId`.\n\n## Targets\n\n- Send-like actions: `to: \"channel:<id>\"` or `to: \"user:<id>\"`.\n- Message-specific actions: `channelId: \"<id>\"` (or `to`) + `messageId: \"<id>\"`.\n\n## Common Actions (Examples)\n\nSend message:\n\n```json\n{\n  \"action\": \"send\",\n  \"channel\": \"discord\",\n  \"to\": \"channel:123\",\n  \"message\": \"hello\",\n  \"silent\": true\n}\n```\n\nSend with media:\n\n```json\n{\n  \"action\": \"send\",\n  \"channel\": \"discord\",\n  \"to\": \"channel:123\",\n  \"message\": \"see attachment\",\n  \"media\": \"file:///tmp/example.png\"\n}\n```\n\nReact:\n\n```json\n{\n  \"action\": \"react\",\n  \"channel\": \"discord\",\n  \"channelId\": \"123\",\n  \"messageId\": \"456\",\n  \"emoji\": \"✅\"\n}\n```\n\nRead:\n\n```json\n{\n  \"action\": \"read\",\n  \"channel\": \"discord\",\n  \"to\": \"channel:123\",\n  \"limit\": 20\n}\n```\n\nEdit / delete:\n\n```json\n{\n  \"action\": \"edit\",\n  \"channel\": \"discord\",\n  \"channelId\": \"123\",\n  \"messageId\": \"456\",\n  \"message\": \"fixed typo\"\n}\n```\n\n```json\n{\n  \"action\": \"delete\",\n  \"channel\": \"discord\",\n  \"channelId\": \"123\",\n  \"messageId\": \"456\"\n}\n```\n\nPoll:\n\n```json\n{\n  \"action\": \"poll\",\n  \"channel\": \"discord\",\n  \"to\": \"channel:123\",\n  \"pollQuestion\": \"Lunch?\",\n  \"pollOption\": [\"Pizza\", \"Sushi\", \"Salad\"],\n  \"pollMulti\": false,\n  \"pollDurationHours\": 24\n}\n```\n\nPins:\n\n```json\n{\n  \"action\": \"pin\",\n  \"channel\": \"discord\",\n  \"channelId\": \"123\",\n  \"messageId\": \"456\"\n}\n```\n\nThreads:\n\n```json\n{\n  \"action\": \"thread-create\",\n  \"channel\": \"discord\",\n  \"channelId\": \"123\",\n  \"messageId\": \"456\",\n  \"threadName\": \"bug triage\"\n}\n```\n\nSearch:\n\n```json\n{\n  \"action\": \"search\",\n  \"channel\": \"discord\",\n  \"guildId\": \"999\",\n  \"query\": \"release notes\",\n  \"channelIds\": [\"123\", \"456\"],\n  \"limit\": 10\n}\n```\n\nPresence (often gated):\n\n```json\n{\n  \"action\": \"set-presence\",\n  \"channel\": \"discord\",\n  \"activityType\": \"playing\",\n  \"activityName\": \"with fire\",\n  \"status\": \"online\"\n}\n```\n\n## Writing Style (Discord)\n\n- Short, conversational, low ceremony.\n- No markdown tables.\n- Prefer multiple small replies over one wall of text.\n"},"lastSynced":"2026-03-08T02:13:21.965Z","agentAnalysis":{"suitability":{"en":"Ideal for Social Media Agents requiring seamless Discord channel integration and user interaction capabilities.","zh":"适合需要无缝Discord频道集成和用户交互能力的社交媒体代理。","ja":"Discordチャンネルのシームレスな統合とユーザーとのやり取り機能を必要とするソーシャルメディアエージェントに最適です。","ko":"시ーム리스 Discord 채널 통합 및 사용자 상호 작용 기능을 요구하는 소셜 미디어 에이전트에 적합합니다.","es":"Ideal para agentes de redes sociales que requieren una integración de canal de Discord sin problemas y capacidades de interacción con el usuario.","fr":"Idéal pour les agents de médias sociaux nécessitant une intégration de canal Discord transparente et des capacités d''interaction avec l''utilisateur.","de":"Ideal für Social-Media-Agents, die eine nahtlose Discord-Kanalintegration und Benutzerinteraktionsfunktionen erfordern.","pt":"Ideal para Agentes de Mídia Social que exigem integração perfeita de canais do Discord e capacidades de interação do usuário.","ru":"Идеально подходит для Социальных Медиа Агентов, требующих бесперебойной интеграции каналов Discord и возможностей взаимодействия с пользователями.","ar":"مثالي لعميل وسائل الإعلام الاجتماعية الذي يتطلب دمجًا سلسًا لقنوات ديسكورد وقدرات التفاعل مع المستخدم."},"recommendation":{"en":"Empowers agents to send targeted messages via Discord, utilizing explicit IDs for guilds, channels, and users, while respecting gating protocols such as roles, moderation, and presence, all through the `message` tool.","zh":"赋予代理发送目标消息的能力，通过Discord使用公会、频道和用户的显式ID，同时尊重角色、审查和状态等网关协议，所有这些都通过`message`工具实现。","ja":"エージェントに、Discordを介してターゲットメッセージを送信する機能を付与します。ギルド、チャンネル、ユーザーの明示的なIDを使用し、役割、モデレーション、存在などのゲートウェイプロトコルを尊重します。これらはすべて、`message`ツールを通じて実現されます。","ko":"대리인에게 Discord를 통해 대상 메시지를 보내는 기능을 부여합니다. 길드, 채널, 사용자의 명시적 ID를 사용하며, 역할, 모더레이션, 존재와 같은 게이트웨이 프로토콜을尊重합니다. 모두 `message` 도구를 통해 구현됩니다.","es":"Permite a los agentes enviar mensajes dirigidos a través de Discord, utilizando IDs explícitas para servidores, canales y usuarios, respetando protocolos de control como roles, moderación y presencia, todo a través de la herramienta `message`.","fr":"Permet aux agents d''envoyer des messages ciblés via Discord, en utilisant des ID explicites pour les serveurs, les canaux et les utilisateurs, en respectant les protocoles de contrôle tels que les rôles, la modération et la présence, le tout via l''outil `message`.","de":"Ermächtigt Agenten, gezielte Nachrichten über Discord zu senden, indem explizite IDs für Server, Kanäle und Benutzer verwendet werden, wobei Protokolle wie Rollen, Moderation und Anwesenheit respektiert werden, und all dies über das `message`-Tool.","pt":"Habilita os agentes a enviar mensagens direcionadas via Discord, utilizando IDs explícitas para servidores, canais e usuários, respeitando protocolos de controle, como papéis, moderação e presença, tudo por meio da ferramenta `message`.","ru":"Наделяет агентов возможностью отправлять целевые сообщения через Discord, используя явные идентификаторы для гильдий, каналов и пользователей, при этом уважая протоколы шлюзования, такие как роли, модерация и присутствие, все через инструмент `message`.","ar":"يتمكّن الوكيل من إرسال رسائل مستهدفة عبر ديسكورد، باستخدام معرّفات 明确 للخادم، والقنوات، والمستخدمين، مع احترام بروتوكولات التموضع، مثل الأدوار، والتعديل، والحضور، كل ذلك من خلال أداة `message`."},"useCases":{"en":["Sending automated notifications to specific Discord channels","Implementing Discord-based user support systems with targeted messaging","Managing Discord communities through automated moderation actions"],"zh":["向特定Discord频道发送自动通知","使用目标消息实现基于Discord的用户支持系统","通过自动化的管理操作来管理Discord社区"],"ja":["特定のDiscordチャンネルに自動通知を送信する","ターゲットメッセージを使用してDiscordベースのユーザーサポートシステムを実装する","自動化されたモデレーションアクションを通じてDiscordコミュニティを管理する"],"ko":["특정 Discord 채널에 자동 알림을 보내는 것","대상 메시지를 사용하여 Discord 기반 사용자 지원 시스템 구현","자동화 된 모더레이션 동작을 통해 Discord 커뮤니티 관리"],"es":["Enviar notificaciones automatizadas a canales de Discord específicos","Implementar sistemas de soporte de usuario basados en Discord con mensajería dirigida","Administrar comunidades de Discord a través de acciones de moderación automatizadas"],"fr":["Envoyer des notifications automatiques à des canaux Discord spécifiques","Mettre en œuvre des systèmes de support utilisateur basés sur Discord avec une messagerie ciblée","Gérer des communautés Discord via des actions de modération automatisées"],"de":["Automatisierte Benachrichtigungen an bestimmte Discord-Kanäle senden","Discord-basierte Benutzersupportsysteme mit gezielter Messaging implementieren","Discord-Communities durch automatisierte Moderationsaktionen verwalten"],"pt":["Envio de notificações automatizadas para canais específicos do Discord","Implementação de sistemas de suporte ao usuário baseados no Discord com mensagens direcionadas","Gerenciamento de comunidades do Discord por meio de ações de moderação automatizadas"],"ru":["Отправка автоматических уведомлений в определенные каналы Discord","Реализация систем поддержки пользователей на основе Discord с целевым сообщением","Управление сообществами Discord с помощью автоматических действий модерации"],"ar":["إرسال إشعارات آلية إلى قنوات ديسكورد محددة","تنفيذ أنظمة دعم المستخدم القائمة على ديسكورد مع رسائل مستهدفة","إدارة مجتمعات ديسكورد من خلال إجراءات تعديل آلية"]},"limitations":{"en":["Requires explicit IDs for guilds, channels, and users","Respects gating, with some actions defaulting to off (e.g., roles, moderation, presence)","Multi-account support is optional and requires `accountId` specification"],"zh":["需要公会、频道和用户的显式ID","尊重网关，某些操作默认关闭（例如，角色、审查、状态）","多账户支持是可选的，需要`accountId`指定"],"ja":["ギルド、チャンネル、ユーザーの明示的なIDが必要","ゲートウェイを尊重し、特定のアクションはデフォルトでオフになります（例：役割、モデレーション、存在）","マルチアカウントのサポートはオプションであり、`accountId`の指定が必要"],"ko":["길드, 채널, 사용자의 명시적 ID가 필요합니다.","게이트웨이를尊重하며, 특정 동작은 기본적으로 꺼져 있습니다. (예: 역할, 모더레이션, 존재)","멀티 어카운트 지원은 선택 사항이며, `accountId`지정이 필요합니다."],"es":["Requiere IDs explícitas para servidores, canales y usuarios","Respetar el control, con algunas acciones que se desactivan de forma predeterminada (por ejemplo, roles, moderación, presencia)","El soporte multi-cuenta es opcional y requiere la especificación de `accountId`"],"fr":["Nécessite des ID explicites pour les serveurs, les canaux et les utilisateurs","Respecte le contrôle, avec certaines actions qui sont désactivées par défaut (par exemple, les rôles, la modération, la présence)","La prise en charge multi-compte est facultative et nécessite la spécification de `accountId`"],"de":["Erfordert explizite IDs für Server, Kanäle und Benutzer","Respektiert die Kontrolle, wobei einige Aktionen standardmäßig deaktiviert sind (z. B. Rollen, Moderation, Anwesenheit)","Die Unterstützung für mehrere Konten ist optional und erfordert die Angabe von `accountId`"],"pt":["Exige IDs explícitas para servidores, canais e usuários","Respeita o controle de acesso, com algumas ações desativadas por padrão (por exemplo, papéis, moderação, presença)","Suporte a multi-conta é opcional e exige especificação de `accountId`"],"ru":["Требует явных идентификаторов для гильдий, каналов и пользователей","Уважает протоколы шлюзования, при этом некоторые действия по умолчанию выключены (например, роли, модерация, присутствие)","Поддержка нескольких аккаунтов является опциональной и требует указания `accountId`"],"ar":["يتطلب معرّفات明确 للخادم، والقنوات، والمستخدمين","يهتم ببروتوكولات التموضع، مع بعض الإجراءات المعطلة افتراضيًا (على سبيل المثال، الأدوار، والتعديل، والحضور)","دعم حسابات متعددة هو اختياري ويتطلب تحديد `accountId`"]},"version":4},"contentHash":"9b53327307b414cc0abecbd911bcd906c24e9b4ce5e30b103ad4cebdb5fe4eb2","qualityScore":36}');
