INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LongIV999/Openclawd/discord', 'discord', 'LongIV999', 'Openclawd', 'community', 'discord LongIV999 Openclawd community The Discord skill enables AI agents to interact with Discord channels and users. It supports sending messages, respecting gating, and using explicit IDs for guilds, channels, and users. 使用message工具与Discord集成，实现多种功能，如发送消息和管理频道 messageツールを使用してDiscordと連携し、メッセージの送信やチャンネルの管理などを行います message 도구를 사용하여 Discord와 연동하여 메시지 전송 및 채널 관리 등을 수행합니다 La integración de Discord permite a los agentes de IA interactuar con canales y usuarios a través de la herramienta de mensaje. Configura tu agente para enviar y recibir mensajes en Discord. L''intégration de Discord permet aux outils d''IA d''interagir avec les canaux et les utilisateurs via l''outil de message. Configurez votre outil pour envoyer et recevoir des messages sur Discord. Die Integration von Discord ermöglicht es KI-Agents, mit Kanälen und Benutzern über das Message-Tool zu interagieren. Konfigurieren Sie Ihren Agenten, um Nachrichten in Discord zu senden und zu empfangen. O Discord é uma plataforma de comunicação que pode ser configurada para desenvolvedores. Aprenda a usar o message tool e respeitar o gating. Discord - это платформа коммуникации, которую можно настроить для ИИ Агентов. Узнайте, как использовать message tool и уважать gating. الديسكورد هو منصة اتصال يمكن تنظیمها لمنصات الإي الأي الجديدة. تعلم كيفية استخدام أداة الرسالة واحترام الحجز. how to use discord with AI agents discord setup guide for AI what is discord in AI discord vs slack for AI integration discord install for AI agents discord API for AI development discord bot setup for AI discord messaging for AI agents discord integration with AI platforms Discord集成 message工具 Discord API Discord开发 AIエージェント Discord自动化 消息工具 Discord平台 Sends messages to Discord channels and users via the message tool Respects gating for actions like roles, moderation, presence, and channels Supports explicit IDs for guilds, channels, and users Allows multi-account support with optional accountId Targets specific channels and users with to: channel:<id> or to: user:<id> syntax Discord is a communication platform that allows AI agents to send messages and interact with users via the message tool, with features like channel and user targeting.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jinbangyi/k8s-agent/mermaid-fix', 'community', 'jinbangyi', 'k8s-agent', 'jinbangyi/k8s-agent', 'mermaid-fix', 0, 0, 36, '2026-03-08T01:57:15.620Z', '2026-03-08T02:13:28.451Z', 'af3accc18432605fd04444df45d8cd99af8303ae68808fcddac5c3cf410e5260', '{"id":"jinbangyi/k8s-agent/mermaid-fix","name":"mermaid-fix","description":{"en":"mermaid-fix is a Kubernetes environment management tool that uses AI to fix Mermaid diagram parsing errors, benefiting developers and DevOps teams. It automates the process of loading existing rules, extracting diagrams, and validating syntax using mermaid-cli and mmdc.","zh":"Mermaid Fix 是一个使用 AI 代理管理 k8s 环境的工具，通过 mermaid-cli 解析 Mermaid 图表并修复错误。它可以自动发现新规则并更新现有规则","ja":"Mermaid Fix は、AI エージェントを使用して k8s 環境を管理するツールで、mermaid-cli を使用して Mermaid 図を解析してエラーを修正します。新しいルールを自動的に発見して既存のルールを更新することもできます","ko":"Mermaid Fix는 AI 에이전트를 사용하여 k8s 환경을 관리하는 도구로, mermaid-cli를 사용하여 Mermaid 다이어그램을 파싱하고 오류를 수정합니다. 또한 새로운 규칙을 자동으로 발견하고 기존 규칙을 업데이트할 수 있습니다","es":"mermaid-fix es una herramienta de gestión de entornos k8s que utiliza mermaid-cli para validar y corregir errores de parsing en diagramas Mermaid","fr":"mermaid-fix est un outil de gestion d''environnements k8s qui utilise mermaid-cli pour valider et corriger les erreurs de parsing dans les diagrammes Mermaid","de":"mermaid-fix ist ein Tool zur Verwaltung von k8s-Umgebungen, das mermaid-cli verwendet, um Parsing-Fehler in Mermaid-Diagrammen zu überprüfen und zu korrigieren","pt":"mermaid-fix é uma ferramenta de gerenciamento de ambiente k8s baseada em AI que corrige erros de diagrama Mermaid. Ela utiliza mermaid-cli para validar e corrigir os erros.","ru":"mermaid-fix — это инструмент управления окружением k8s на основе ИИ Агентов, который исправляет ошибки диаграмм Mermaid. Он использует mermaid-cli для проверки и исправления ошибок.","ar":"mermaid-fix هي أداة إدارة بيئة k8s قائمة على أدوات الذكاء الاصطناعي التي تصحح أخطاء الرسوم البيانية Mermaid. إنها تستخدم mermaid-cli للتحقق وتصحيح الأخطاء."},"seo":{"title":{"en":"mermaid-fix: Kubernetes Env Management Setup Guide | AI A...","zh":"Mermaid Fix 设置指南：AI 环境管理工具","ja":"Mermaid Fix のベストプラクティス：AI エージェントによる k8s 環境管理","ko":"Mermaid Fix 설치 가이드: AI 에이전트를 이용한 k8s 환경 관리","es":"Guía de configuración de mermaid-fix para gestión de ento...","fr":"Guide de mise en place de mermaid-fix pour la gestion des...","de":"Einrichtungsleitfaden für mermaid-fix zur Verwaltung von ...","pt":"mermaid-fix: Guia de Configuração para Erros de Diagrama ...","ru":"mermaid-fix: Руководство по настройке для исправления оши...","ar":"mermaid-fix: دليل الإعداد لتصحيح أخطاء الرسوم البيانية Me..."},"description":{"en":"Discover how mermaid-fix simplifies Kubernetes environment management with AI-driven Mermaid diagram parsing and error fixing - get started now!","zh":"Mermaid Fix 是一个使用 AI 代理管理 k8s 环境的工具，通过 mermaid-cli 解析 Mermaid 图表并修复错误","ja":"Mermaid Fix は、AI エージェントを使用して k8s 環境を管理するツールで、mermaid-cli を使用して Mermaid 図を解析してエラーを修正します","ko":"Mermaid Fix는 AI 에이전트를 사용하여 k8s 환경을 관리하는 도구로, mermaid-cli를 사용하여 Mermaid 다이어그램을 파싱하고 오류를 수정합니다","es":"Descubre cómo mermaid-fix utiliza mermaid-cli y reglas de parsing para gestionar entornos k8s de manera efectiva","fr":"Découvrez comment mermaid-fix utilise mermaid-cli et des règles de parsing pour gérer les environnements k8s de manière efficace","de":"Erfahren Sie, wie mermaid-fix mit mermaid-cli und Parsing-Regeln k8s-Umgebungen effizient verwaltet","pt":"Aprenda a configurar mermaid-fix para resolver erros de diagrama Mermaid em ambientes k8s com esta ferramenta de gerenciamento de ambiente baseada em AI","ru":"Узнайте, как настроить mermaid-fix для исправления ошибок диаграмм Mermaid в средах k8s с помощью этого инструмента управления окружением на основе ИИ Агентов","ar":"تعلم كيفية配置 mermaid-fix لتصحيح أخطاء الرسوم البيانية Mermaid في بيئات k8s باستخدام أداة إدارة البيئة هذه القائمة على أدوات الذكاء الاصطناعي"},"definition":{"en":"mermaid-fix is an AI-powered tool for managing Kubernetes environments by automatically fixing Mermaid diagram parsing errors and discovering new rules.","zh":"Mermaid Fix 是一个使用 AI 代理管理 k8s 环境的工具，用于解析 Mermaid 图表并修复错误","ja":"Mermaid Fix は、AI エージェントを使用して k8s 環境を管理するツールで、Mermaid 図を解析してエラーを修正するために使用されます","ko":"Mermaid Fix는 AI 에이전트를 사용하여 k8s 환경을 관리하는 도구로, Mermaid 다이어그램을 파싱하고 오류를 수정하는 데 사용됩니다","es":"mermaid-fix es un agente de inteligencia artificial (IA) que gestiona entornos k8s mediante la corrección de errores de parsing en diagramas Mermaid","fr":"mermaid-fix est un agent d''intelligence artificielle (IA) qui gère les environnements k8s en corrigeant les erreurs de parsing dans les diagrammes Mermaid","de":"mermaid-fix ist ein KI-Agent, der k8s-Umgebungen durch die Korrektur von Parsing-Fehlern in Mermaid-Diagrammen verwaltet","pt":"mermaid-fix é uma ferramenta de gerenciamento de ambiente que utiliza AI para corrigir erros de diagrama Mermaid em ambientes k8s","ru":"mermaid-fix — это инструмент управления окружением, который использует ИИ Агентов для исправления ошибок диаграмм Mermaid в средах k8s","ar":"mermaid-fix هي أداة إدارة بيئة تستخدم أدوات الذكاء الاصطناعي لتصحيح أخطاء الرسوم البيانية Mermaid في بيئات k8s"},"features":{"en":["Loads existing rules from .claude/rules/mermaid.md for known patterns","Extracts Mermaid code blocks from target files using mermaid-cli","Validates syntax using mmdc command with temporary file input","Applies fixes based on mmdc error output for seamless diagram rendering","Updates mermaid.md with newly discovered error patterns for continuous improvement"],"zh":["使用 mermaid-cli 解析 Mermaid 图表","自动发现新规则并更新现有规则","支持 k8s 环境管理","通过 mmdc 进行语法验证","修复 Mermaid 图表解析错误"],"ja":["mermaid-cli を使用して Mermaid 図を解析する","新しいルールを自動的に発見して既存のルールを更新する","k8s 環境管理をサポートする","mmdc を使用して構文を検証する","Mermaid 図の解析エラーを修正する"],"ko":["mermaid-cli를 사용하여 Mermaid 다이어그램을 파싱","새로운 규칙을 자동으로 발견하고 기존 규칙을 업데이트","k8s 환경 관리를 지원","mmdc를 사용하여 구문을 검증","Mermaid 다이어그램의 파싱 오류를 수정"],"es":["Validación de diagramas Mermaid con mermaid-cli","Corrección de errores de parsing en diagramas Mermaid","Descubrimiento de nuevas reglas de parsing","Actualización de reglas de parsing en mermaid.md","Integración con entornos k8s"],"fr":["Validation des diagrammes Mermaid avec mermaid-cli","Correction des erreurs de parsing dans les diagrammes Mermaid","Découverte de nouvelles règles de parsing","Mise à jour des règles de parsing dans mermaid.md","Intégration avec les environnements k8s"],"de":["Validierung von Mermaid-Diagrammen mit mermaid-cli","Korrektur von Parsing-Fehlern in Mermaid-Diagrammen","Entdeckung neuer Parsing-Regeln","Aktualisierung von Parsing-Regeln in mermaid.md","Integration mit k8s-Umgebungen"],"pt":["Validação de diagramas Mermaid com mermaid-cli","Correção automática de erros de sintaxe","Descoberta de novos padrões de erro","Atualização de regras de validação","Integração com ambientes k8s"],"ru":["Проверка диаграмм Mermaid с помощью mermaid-cli","Автоматическое исправление ошибок синтаксиса","Обнаружение новых моделей ошибок","Обновление правил проверки","Интеграция с окружениями k8s"],"ar":["التحقق من الرسوم البيانية Mermaid باستخدام mermaid-cli","تصحيح آلي لأخطاء الصياغة","اكتشاف أنماط جديدة للأخطاء","تحديث قواعد التحقق","التكامل مع بيئات k8s"]},"keywords":{"en":["how to use mermaid-fix","mermaid-fix setup guide","mermaid-fix alternative","mermaid-fix vs k8s management tools","mermaid-fix install","what is mermaid-fix","mermaid-fix for Kubernetes","mermaid-fix error fixing","mermaid-fix and mmdc","mermaid-fix AI agent"],"zh":["Mermaid Fix","AI 环境管理","k8s 环境管理","mermaid-cli","Mermaid 图表解析","AI 代理","环境管理工具"],"ja":["Mermaid Fix","AI エージェント","k8s 環境管理","mermaid-cli","Mermaid 図解析","AI ツール","環境管理ツール"],"ko":["Mermaid Fix","AI 에이전트","k8s 환경 관리","mermaid-cli","Mermaid 다이어그램 파싱","AI 도구","환경 관리 도구"],"es":["mermaid-fix","gestión de entornos k8s","mermaid-cli","Parsing de diagramas Mermaid","corrección de errores de parsing","descubrimiento de reglas de parsing","integración con k8s","herramientas de inteligencia artificial para k8s","agentes de IA para k8s"],"fr":["mermaid-fix","gestion d''environnements k8s","mermaid-cli","Parsing de diagrammes Mermaid","correction des erreurs de parsing","découverte de règles de parsing","intégration avec k8s","outils d''intelligence artificielle pour k8s","agents d''IA pour k8s"],"de":["mermaid-fix","Verwaltung von k8s-Umgebungen","mermaid-cli","Parsing von Mermaid-Diagrammen","Korrektur von Parsing-Fehlern","Entdeckung von Parsing-Regeln","Integration mit k8s","KI-Tools für k8s","KI-Agenten für k8s"],"pt":["mermaid-fix","gerenciamento de ambiente k8s","correção de erros de diagrama Mermaid","ferramenta de gerenciamento de ambiente baseada em AI","mermaid-cli","validação de diagramas Mermaid","k8s","AI","ambientes de desenvolvimento"],"ru":["mermaid-fix","управление окружением k8s","исправление ошибок диаграмм Mermaid","инструмент управления окружением на основе ИИ Агентов","mermaid-cli","проверка диаграмм Mermaid","k8s","ИИ Агенты","окружения разработки"],"ar":["mermaid-fix","إدارة بيئة k8s","تصحيح أخطاء الرسوم البيانية Mermaid","أداة إدارة بيئة قائمة على أدوات الذكاء الاصطناعي","mermaid-cli","التحقق من الرسوم البيانية Mermaid","k8s","أدوات الذكاء الاصطناعي","بيئات التطوير"]}},"owner":"jinbangyi","repo":"k8s-agent","repoPath":"jinbangyi/k8s-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.620Z","topics":[],"category":"community","skillMd":{"name":"mermaid-fix","description":"Fix and validate Mermaid diagrams using mermaid-cli (mmdc). Use when Claude needs to fix parsing errors in Mermaid diagrams, validate diagrams, or when encountering Mermaid syntax issues. This skill reads rules from .claude/rules/mermaid.md and updates it with newly discovered patterns.","bodyPreview":"# Mermaid Fix\n\nFixes Mermaid diagram parsing errors using mermaid-cli and discovers new rules.\n\n## Quick Start\n\n1. **Read existing rules**: Load `.claude/rules/mermaid.md` for known patterns\n2. **Extract diagrams**: Find all Mermaid code blocks in the target file(s)\n3. **Validate with mmdc**: Run `mmdc -i <temp_file> -o /dev/null` to check syntax\n4. **Fix errors**: Apply fixes based on mmdc error output\n5. **Update rules**: Add newly discovered error patterns to mermaid.md\n\n## Validation Command","body":"# Mermaid Fix\n\nFixes Mermaid diagram parsing errors using mermaid-cli and discovers new rules.\n\n## Quick Start\n\n1. **Read existing rules**: Load `.claude/rules/mermaid.md` for known patterns\n2. **Extract diagrams**: Find all Mermaid code blocks in the target file(s)\n3. **Validate with mmdc**: Run `mmdc -i <temp_file> -o /dev/null` to check syntax\n4. **Fix errors**: Apply fixes based on mmdc error output\n5. **Update rules**: Add newly discovered error patterns to mermaid.md\n\n## Validation Command\n\n```bash\n# Create temp file, validate, check exit code\nmmdc -t neutral -i diagram.mmd -o /dev/null\n# Exit code 0 = valid, non-zero = error\n```\n\n## Common Fixes\n\nBased on existing rules in `mermaid.md`:\n\n| Error Pattern | Fix |\n|--------------|-----|\n| `Graph TD` | Change to lowercase: `graph TD` |\n| `<br/>`, `<b>`, `<i>` in labels | Remove HTML tags, use plain text |\n| `dmzSubnet` style naming | Use hyphens: `dmz-subnet` |\n| Missing `graph` direction | Add `LR`, `TD`, `RL`, or `BT` |\n\n## Discovering New Rules\n\nWhen you encounter a new error pattern:\n\n1. **Document the error**: Capture the error message from mmdc\n2. **Identify the fix**: What change resolved the error?\n3. **Update mermaid.md**: Add a new rule entry with:\n   - Rule number (next sequential)\n   - Category name\n   - Pattern description\n   - Fix/avoidance guidance\n\nExample new rule format:\n\n```markdown\n**N. Category Name**\n- Error pattern: `<what causes the error>`\n- Fix: `<how to resolve>`\n- Example: `<before -> after>`\n```\n\n## Workflow Steps\n\n### Quick Mode (Markdown Files with Multiple Diagrams)\n\nFor markdown files containing multiple Mermaid diagrams, use concurrent validation:\n\n```bash\n# Validate all diagrams in a markdown file concurrently (4 workers by default)\npython3 .claude/skills/mermaid-fix/scripts/validate_markdown_mermaid.py <path/to/file.md>\n\n# Specify number of parallel workers\npython3 .claude/skills/mermaid-fix/scripts/validate_markdown_mermaid.py <path/to/file.md> --workers 8\n```\n\n### Step-by-Step Mode\n\n1. Read the target file(s) containing Mermaid diagrams\n2. For each diagram:\n   - Extract the Mermaid code block\n   - Write to a temporary `.mmd` file\n   - Run `mmdc` to validate\n   - If error: fix based on error message and known rules\n   - If new pattern: document for mermaid.md update\n3. Replace fixed diagrams in source file(s)\n4. If new patterns were discovered, update `.claude/rules/mermaid.md`\n\n## Constraints\n\n- Preserve the diagram''s semantic meaning\n- Only fix syntax/structure issues\n- Do not \"optimize\" or \"improve\" the visual design (use `/optimize-mermaid` for that)\n- Test each fix with mmdc before applying\n"},"lastSynced":"2026-03-08T02:13:28.451Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing automated Mermaid diagram parsing error fixes in Kubernetes environments.","zh":"非常适合需要在Kubernetes环境中自动修复Mermaid图解析错误的DevOps代理。","ja":"Kubernetes環境でMermaid図のパースエラーを自動修復する必要があるDevOpsエージェントに最適です。","ko":"Kubernetes 환경에서 Mermaid 다이어그램 파싱 오류를 자동으로 수정해야 하는 DevOps 에이전트에 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan correcciones automáticas de errores de análisis de diagramas Mermaid en entornos de Kubernetes.","fr":"Parfait pour les agents DevOps ayant besoin de corrections automatiques d''erreurs d''analyse de diagrammes Mermaid dans des environnements Kubernetes.","de":"Perfekt für DevOps-Agents, die automatische Fehlerkorrekturen für Mermaid-Diagramm-Analyse in Kubernetes-Umgebungen benötigen.","pt":"Perfeito para Agentes DevOps que necessitam de correção automática de erros de parsing de diagramas Mermaid em ambientes Kubernetes.","ru":"Идеально подходит для агентов DevOps, которым необходима автоматическая исправление ошибок парсинга диаграмм Mermaid в средах Kubernetes.","ar":"مثالي لعميل DevOps الذين يحتاجون إلى تصحيح آلي لخطأ تحليل الرسم البياني Mermaid في بيئات Kubernetes."},"recommendation":{"en":"Empowers agents to automate Mermaid diagram validation using mermaid-cli and mmdc, ensuring syntax accuracy and discovering new rules for enhanced environment management, leveraging .claude/rules/mermaid.md for known patterns and updating them with newly discovered error patterns.","zh":"赋予代理自动验证Mermaid图的能力，使用mermaid-cli和mmdc，确保语法准确性，并发现新的规则以增强环境管理，利用.claude/rules/mermaid.md中的已知模式，并用新发现的错误模式更新它们。","ja":"エージェントにMermaid図の検証を自動化する能力を与え、mermaid-cliとmmdcを使用して、構文の正確性を確保し、新しい規則を発見して環境管理を強化する。.claude/rules/mermaid.mdの既知のパターンを利用し、新しく発見されたエラーパターンで更新します。","ko":"에이전트가 Mermaid 다이어그램의 유효성을 자동으로 확인할 수 있도록 해줍니다. mermaid-cli와 mmdc를 사용하여 구문 정확성을 보장하고 새로운 규칙을 발견하여 환경 관리를 강화합니다. .claude/rules/mermaid.md에 있는 알려진 패턴을 활용하고 새로 발견된 오류 패턴으로 업데이트합니다.","es":"Habilita a los agentes a automatizar la validación de diagramas Mermaid utilizando mermaid-cli y mmdc, garantizando la precisión de la sintaxis y descubriendo nuevas reglas para una mejor gestión del entorno, aprovechando .claude/rules/mermaid.md para patrones conocidos y actualizándolos con patrones de errores recién descubiertos.","fr":"Permet aux agents d''automatiser la validation des diagrammes Mermaid en utilisant mermaid-cli et mmdc, garantissant l''exactitude de la syntaxe et découvrant de nouvelles règles pour une meilleure gestion de l''environnement, en exploitant .claude/rules/mermaid.md pour les modèles connus et en les mettant à jour avec les nouveaux modèles d''erreurs découverts.","de":"Ermöglicht es den Agenten, die Validierung von Mermaid-Diagrammen mithilfe von mermaid-cli und mmdc zu automatisieren, wodurch die Syntakgenauigkeit gewährleistet und neue Regeln für eine verbesserte Umgebungsverwaltung entdeckt werden, indem .claude/rules/mermaid.md für bekannte Muster genutzt und mit neu entdeckten Fehlern aktualisiert wird.","pt":"Habilita os agentes a automatizar a validação de diagramas Mermaid usando mermaid-cli e mmdc, garantindo a precisão da sintaxe e descobrindo novas regras para uma gestão de ambiente melhorada, utilizando .claude/rules/mermaid.md para padrões conhecidos e atualizando-os com padrões de erros recém-descobertos.","ru":"Наделяет агентов возможностью автоматизировать проверку диаграмм Mermaid с помощью mermaid-cli и mmdc, обеспечивая точность синтаксиса и открывая новые правила для улучшенного управления средой, используя .claude/rules/mermaid.md для известных шаблонов и обновляя их новыми обнаруженными шаблонами ошибок.","ar":"يُمكّن الوكيل من تسهيل التحقق من صحة الرسم البياني Mermaid باستخدام mermaid-cli و mmdc، وضمان دقة الصياغة واكتشاف قواعد جديدة لتحسين إدارة البيئة، واستخدام .claude/rules/mermaid.md للنماذج المعروفة وتحديثها بنماذج الأخطاء المكتشفة حديثًا."},"useCases":{"en":["Automating Mermaid diagram parsing error fixes","Validating Mermaid syntax with mmdc","Discovering and updating new rules for Mermaid diagrams"],"zh":["自动修复Mermaid图解析错误","使用mmdc验证Mermaid语法","发现和更新Mermaid图的新规则"],"ja":["Mermaid図のパースエラーを自動修復する","mmdcを使用してMermaidの構文を検証する","Mermaid図の新しい規則を発見して更新する"],"ko":["Mermaid 다이어그램 파싱 오류를 자동으로 수정하기","mmdc를 사용하여 Mermaid 구문을 검증하기","Mermaid 다이어그램의 새로운 규칙을 발견하고 업데이트하기"],"es":["Automatizar correcciones de errores de análisis de diagramas Mermaid","Validar la sintaxis Mermaid con mmdc","Descubrir y actualizar nuevas reglas para diagramas Mermaid"],"fr":["Automatiser les corrections d''erreurs d''analyse de diagrammes Mermaid","Valider la syntaxe Mermaid avec mmdc","Découvrir et mettre à jour de nouvelles règles pour les diagrammes Mermaid"],"de":["Automatisierung von Fehlerkorrekturen für Mermaid-Diagramm-Analyse","Validierung der Mermaid-Syntax mit mmdc","Entdecken und Aktualisieren neuer Regeln für Mermaid-Diagramme"],"pt":["Automatizar a correção de erros de parsing de diagramas Mermaid","Validar a sintaxe Mermaid com mmdc","Descobrir e atualizar novas regras para diagramas Mermaid"],"ru":["Автоматизировать исправление ошибок парсинга диаграмм Mermaid","Проверять синтаксис Mermaid с помощью mmdc","Обнаруживать и обновлять новые правила для диаграмм Mermaid"],"ar":["آليّة تصحيح أخطاء تحليل الرسم البياني Mermaid","التحقق من صحة بناء الجملة Mermaid باستخدام mmdc","اكتشاف قواعد جديدة لرسوم بيانية Mermaid وتحديثها"]},"limitations":{"en":["Requires mermaid-cli and mmdc installation","Kubernetes environment necessary","Dependent on .claude/rules/mermaid.md for existing rules"],"zh":["需要安装mermaid-cli和mmdc","需要Kubernetes环境","依赖.claude/rules/mermaid.md中的现有规则"],"ja":["mermaid-cliとmmdcのインストールが必要","Kubernetes環境が必要",".claude/rules/mermaid.mdの既存の規則に依存する"],"ko":["mermaid-cli와 mmdc 설치가 필요합니다","Kubernetes 환경이 필요합니다",".claude/rules/mermaid.md의 기존 규칙에 종속됩니다"],"es":["Requiere la instalación de mermaid-cli y mmdc","Entorno de Kubernetes necesario","Dependiente de .claude/rules/mermaid.md para reglas existentes"],"fr":["Nécessite l''installation de mermaid-cli et mmdc","Environnement Kubernetes nécessaire","Dépendant de .claude/rules/mermaid.md pour les règles existantes"],"de":["Benötigt die Installation von mermaid-cli und mmdc","Kubernetes-Umgebung erforderlich","Abhängig von .claude/rules/mermaid.md für bestehende Regeln"],"pt":["Exige a instalação do mermaid-cli e mmdc","Ambiente Kubernetes necessário","Dependente de .claude/rules/mermaid.md para regras existentes"],"ru":["Требует установки mermaid-cli и mmdc","Необходима среда Kubernetes","Зависит от .claude/rules/mermaid.md для существующих правил"],"ar":["يتطلب تثبيت mermaid-cli و mmdc","بيئة Kubernetes ضرورية","يعتمد على .claude/rules/mermaid.md للقواعد الحالية"]},"version":4},"contentHash":"af3accc18432605fd04444df45d8cd99af8303ae68808fcddac5c3cf410e5260","qualityScore":36}');
