INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jinbangyi/k8s-agent/mermaid-fix', 'mermaid-fix', 'jinbangyi', 'k8s-agent', 'community', 'mermaid-fix jinbangyi k8s-agent community mermaid-fix is a Kubernetes environment management tool that uses AI to fix Mermaid diagram parsing errors, benefiting developers and DevOps teams. It automates the process of loading existing rules, extracting diagrams, and validating syntax using mermaid-cli and mmdc. Mermaid Fix 是一个使用 AI 代理管理 k8s 环境的工具，通过 mermaid-cli 解析 Mermaid 图表并修复错误。它可以自动发现新规则并更新现有规则 Mermaid Fix は、AI エージェントを使用して k8s 環境を管理するツールで、mermaid-cli を使用して Mermaid 図を解析してエラーを修正します。新しいルールを自動的に発見して既存のルールを更新することもできます Mermaid Fix는 AI 에이전트를 사용하여 k8s 환경을 관리하는 도구로, mermaid-cli를 사용하여 Mermaid 다이어그램을 파싱하고 오류를 수정합니다. 또한 새로운 규칙을 자동으로 발견하고 기존 규칙을 업데이트할 수 있습니다 mermaid-fix es una herramienta de gestión de entornos k8s que utiliza mermaid-cli para validar y corregir errores de parsing en diagramas Mermaid mermaid-fix est un outil de gestion d''environnements k8s qui utilise mermaid-cli pour valider et corriger les erreurs de parsing dans les diagrammes Mermaid mermaid-fix ist ein Tool zur Verwaltung von k8s-Umgebungen, das mermaid-cli verwendet, um Parsing-Fehler in Mermaid-Diagrammen zu überprüfen und zu korrigieren mermaid-fix é uma ferramenta de gerenciamento de ambiente k8s baseada em AI que corrige erros de diagrama Mermaid. Ela utiliza mermaid-cli para validar e corrigir os erros. mermaid-fix — это инструмент управления окружением k8s на основе ИИ Агентов, который исправляет ошибки диаграмм Mermaid. Он использует mermaid-cli для проверки и исправления ошибок. mermaid-fix هي أداة إدارة بيئة k8s قائمة على أدوات الذكاء الاصطناعي التي تصحح أخطاء الرسوم البيانية Mermaid. إنها تستخدم mermaid-cli للتحقق وتصحيح الأخطاء. how to use mermaid-fix mermaid-fix setup guide mermaid-fix alternative mermaid-fix vs k8s management tools mermaid-fix install what is mermaid-fix mermaid-fix for Kubernetes mermaid-fix error fixing mermaid-fix and mmdc mermaid-fix AI agent Mermaid Fix AI 环境管理 k8s 环境管理 mermaid-cli Mermaid 图表解析 AI 代理 环境管理工具 Loads existing rules from .claude/rules/mermaid.md for known patterns Extracts Mermaid code blocks from target files using mermaid-cli Validates syntax using mmdc command with temporary file input Applies fixes based on mmdc error output for seamless diagram rendering Updates mermaid.md with newly discovered error patterns for continuous improvement mermaid-fix is an AI-powered tool for managing Kubernetes environments by automatically fixing Mermaid diagram parsing errors and discovering new rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eserlan/Codex-Cryptica/cytoscape', 'community', 'eserlan', 'Codex-Cryptica', 'eserlan/Codex-Cryptica', 'cytoscape', 0, 0, 36, '2026-03-08T01:57:15.597Z', '2026-03-08T02:13:30.563Z', 'ec44230c7efa1472a3eba645714871970a11ef88a43011db4f2e60c84298ec1c', '{"id":"eserlan/Codex-Cryptica/cytoscape","name":"cytoscape","description":{"en":"Cytoscape is a node-based RPG campaign manager that utilizes Cytoscape.js for high-performance network visualizations, benefiting developers and gamers alike.","zh":"Cytoscape 是一个用于创建高性能网络可视化的工具，具有 Svelte 5 集成和 Codex Arcana 科幻美学","ja":"Cytoscape は、高パフォーマンスのネットワーク可視化を作成するためのツールです。Svelte 5 統合と Codex Arcana サイエンスフィクション美学を備えています - AIエージェント","ko":"Cytoscape는 고성능 네트워크 시각화를 생성하기 위한 도구로서 Svelte 5 통합 및 Codex Arcana 과학 픽션 미학을 갖추고 있습니다 - AI 도구","es":"Cytoscape es un gestor de campañas de RPG basado en nodos que utiliza Cytoscape.js y Svelte 5 para crear visualizaciones de redes","fr":"Cytoscape est un gestionnaire de campagnes de RPG basé sur des nœuds qui utilise Cytoscape.js et Svelte 5 pour créer des visualisations de réseaux","de":"Cytoscape ist ein nodebasierter RPG-Kampagnen-Manager, der Cytoscape.js und Svelte 5 für die Erstellung von Netzwerkvisualisierungen verwendet","pt":"Cytoscape é uma ferramenta de gerenciamento de campanhas de RPG baseada em nós, que utiliza Cytoscape.js e Svelte 5 para criar visualizações de rede de alta performance.","ru":"Cytoscape - это инструмент управления кампаниями RPG на основе узлов, который использует Cytoscape.js и Svelte 5 для создания высокопроизводительных визуализаций сетей для ИИ Агентов.","ar":"Cytoscape هو أداة لإدارة حملات RPG القائمة على العقد، التي تستخدم Cytoscape.js و Svelte 5 لإنشاء تصورات شبكة عالية الأداء"},"seo":{"title":{"en":"Cytoscape: Svelte 5 Integration Setup Guide | AI Agent Skill","zh":"Cytoscape 网络可视化设置指南","ja":"Cytoscape ネットワーク可視化ベストプラクティス - AIエージェント","ko":"Cytoscape 네트워크 시각화 설정 가이드 - AI 도구","es":"Guía de configuración de Cytoscape para visualización de ...","fr":"Guide de mise en place de Cytoscape pour la visualisation...","de":"Cytoscape-Setup-Anleitung für Graphvisualisierung","pt":"Guia de Configuração do Cytoscape para Desenvolvedores","ru":"Настройка Cytoscape: Руководство для Разработчиков ИИ Аге...","ar":"دليل إعداد Cytoscape لمنشئي التطبيقات"},"description":{"en":"Unlock the full potential of Cytoscape.js with Svelte 5 integration and discover how to create stunning network visualizations with ease - get started now!","zh":"使用 Cytoscape.js 和 Svelte 5 创建高性能、视觉惊人的网络可视化。了解 Cytoscape 生命周期和反应性管理","ja":"Cytoscape.js と Svelte 5 を使用して、高パフォーマンスで美しいネットワーク可視化を作成します。Cytoscape ライフサイクルとリアクティブ性の管理について学びます - AIエージェント","ko":"Cytoscape.js와 Svelte 5를 사용하여 고성능, 시각적으로惊人的 네트워크 시각화를 생성합니다. Cytoscape 라이프사이클 및 반응성 관리에 대해 알아보기 - AI 도구","es":"Aprende a crear visualizaciones de redes de alto rendimiento con Cytoscape.js y Svelte 5","fr":"Découvrez comment créer des visualisations de réseaux haute performance avec Cytoscape.js et Svelte 5","de":"Erfahren Sie, wie Sie mit Cytoscape.js und Svelte 5 hochleistungsstarke Netzwerkvisualisierungen erstellen","pt":"Aprenda a criar visualizações de rede de alta performance com Cytoscape.js e integração com Svelte 5","ru":"Мастерство создания высокопроизводительных визуализаций сетей с помощью Cytoscape.js и интеграции с Svelte 5 для ИИ Агентов","ar":"تعلم كيفية إنشاء تصورات شبكة عالية الأداء باستخدام Cytoscape.js ودمجها مع Svelte 5"},"definition":{"en":"Cytoscape is a graph visualization tool that uses Cytoscape.js to create aesthetically striking network visualizations with a focus on Svelte 5 integration.","zh":"Cytoscape 是一个用于创建网络可视化的 JavaScript 库，具有高性能和可定制的布局","ja":"Cytoscape は、ネットワーク可視化を作成するための JavaScript ライブラリです。高パフォーマンスとカスタマイズ可能なレイアウトを備えています","ko":"Cytoscape는 네트워크 시각화를 생성하기 위한 JavaScript 라이브러리로서 고성능 및 사용자 정의 레이아웃을 제공합니다","es":"Cytoscape es una herramienta de visualización de grafos que utiliza Cytoscape.js y Svelte 5","fr":"Cytoscape est un outil de visualisation de graphes qui utilise Cytoscape.js et Svelte 5","de":"Cytoscape ist ein Tool für die Visualisierung von Graphen, das Cytoscape.js und Svelte 5 verwendet","pt":"Cytoscape é uma biblioteca JavaScript para criar visualizações de rede de alta performance","ru":"Cytoscape - это библиотека JavaScript для создания высокопроизводительных визуализаций сетей","ar":"Cytoscape هي مكتبة JavaScript لإنشاء تصورات شبكة عالية الأداء"},"features":{"en":["Manages Cytoscape lifecycle and reactivity using Svelte 5 `$effect` and `onMount`","Utilizes Cytoscape.js for high-performance network visualizations","Integrates with Svelte 5 for seamless component management","Supports the ''Codex Arcana'' sci-fi aesthetic for unique visualizations","Employs `onDestroy` for proper component cleanup","Leverages TypeScript for robust code management"],"zh":["Svelte 5 集成","Cytoscape 生命周期管理","高性能网络可视化","Codex Arcana 科幻美学","使用 $effect 和 onMount 管理反应性"],"ja":["Svelte 5 統合","Cytoscape ライフサイクル管理","高パフォーマンスのネットワーク可視化","Codex Arcana サイエンスフィクション美学","$effect と onMount を使用したリアクティブ性管理"],"ko":["Svelte 5 통합","Cytoscape 라이프사이클 관리","고성능 네트워크 시각화","Codex Arcana 과학 픽션 미학","$effect 및 onMount를 사용한 반응성 관리"],"es":["Integración con Svelte 5","Uso de Cytoscape.js para la visualización de grafos","Gestión del ciclo de vida y la reactividad con `$effect` y `onMount`","Compatibilidad con el estilo \"Codex Arcana\" de ciencia ficción","Creación de visualizaciones de redes de alto rendimiento"],"fr":["Intégration avec Svelte 5","Utilisation de Cytoscape.js pour la visualisation de graphes","Gestion du cycle de vie et de la réactivité avec `$effect` et `onMount`","Compatibilité avec le style \"Codex Arcana\" de science-fiction","Création de visualisations de réseaux haute performance"],"de":["Integration mit Svelte 5","Verwendung von Cytoscape.js für die Visualisierung von Graphen","Verwaltung des Lebenszyklus und der Reaktivität mit `$effect` und `onMount`","Kompatibilität mit dem Stil \"Codex Arcana\" der Science-Fiction","Erstellung von hochleistungsstarken Netzwerkvisualisierungen"],"pt":["Integração com Svelte 5","Uso de Cytoscape.js para visualizações de rede","Gerenciamento de ciclo de vida e reatividade com `$effect` e `onMount`","Suporte a estilos personalizados com \"Codex Arcana\""],"ru":["Интеграция с Svelte 5","Использование Cytoscape.js для визуализаций сетей","Управление циклом жизни и реактивностью с `$effect` и `onMount`","Поддержка пользовательских стилей с \"Codex Arcana\""],"ar":["دمج مع Svelte 5","استخدام Cytoscape.js لتصورات الشبكة","إدارة دورة الحياة والتفاعل مع `$effect` و `onMount`","دعم أنماط مخصصة مع \"Codex Arcana\""]},"keywords":{"en":["how to use cytoscape with Svelte 5","cytoscape alternative to other graph visualization tools","cytoscape vs sigma js","cytoscape install guide","cytoscape setup tutorial for AI agents","what is cytoscape used for in RPG campaign management"],"zh":["Cytoscape","Svelte 5","网络可视化","高性能","Codex Arcana","JavaScript 库","Cytoscape 生命周期管理","反应性管理"],"ja":["Cytoscape","Svelte 5","ネットワーク可視化","高パフォーマンス","Codex Arcana","JavaScript ライブラリ","Cytoscape ライフサイクル管理","リアクティブ性管理","AIエージェント"],"ko":["Cytoscape","Svelte 5","네트워크 시각화","고성능","Codex Arcana","JavaScript 라이브러리","Cytoscape 라이프사이클 관리","반응성 관리","AI 도구"],"es":["Cytoscape","Svelte 5","Cytoscape.js","visualización de grafos","gestor de campañas de RPG","herramienta de visualización de grafos","desarrollo de aplicaciones con Svelte","visualización de redes","estilo Codex Arcana"],"fr":["Cytoscape","Svelte 5","Cytoscape.js","visualisation de graphes","gestionnaire de campagnes de RPG","outil de visualisation de graphes","développement d''applications avec Svelte","visualisation de réseaux","style Codex Arcana"],"de":["Cytoscape","Svelte 5","Cytoscape.js","Visualisierung von Graphen","RPG-Kampagnen-Manager","Tool für die Visualisierung von Graphen","Entwicklung von Anwendungen mit Svelte","Netzwerkvisualisierung","Stil Codex Arcana"],"pt":["Cytoscape","Svelte 5","Cytoscape.js","visualização de rede","gerenciamento de campanhas de RPG","desenvolvimento de aplicativos","bibliotecas JavaScript"],"ru":["Cytoscape","Svelte 5","Cytoscape.js","визуализация сетей","управление кампаниями RPG","разработка приложений","библиотеки JavaScript","ИИ Агенты"],"ar":["Cytoscape","Svelte 5","Cytoscape.js","تصوير الشبكة","إدارة حملات RPG","تنمية التطبيقات","مكتبات JavaScript","أدوات الذكاء الاصطناعي"]}},"owner":"eserlan","repo":"Codex-Cryptica","repoPath":"eserlan/Codex-Cryptica","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.597Z","topics":[],"category":"community","skillMd":{"name":"cytoscape","description":"Master Cytoscape.js for graph visualization, including Svelte 5 integration, sci-fi styling, custom layouts, and interaction patterns. Use when building relationship maps, node-link diagrams, or interactive network visualizations.","bodyPreview":"# Cytoscape Graph Visualization\n\nMaster the art of creating high-performance, aesthetically striking network visualizations using Cytoscape.js, with a focus on Svelte 5 integration and the \"Codex Arcana\" sci-fi aesthetic.\n\n## Core Patterns\n\n### 1. Svelte 5 Integration\n\nManage Cytoscape lifecycle and reactivity using Svelte 5 `$effect` and `onMount`.\n\n```svelte\n<script lang=\"ts\">\n  import { onMount, onDestroy } from \"svelte\";\n  import cytoscape, { type Core } from \"cytoscape\";\n\n  let container: H","body":"# Cytoscape Graph Visualization\n\nMaster the art of creating high-performance, aesthetically striking network visualizations using Cytoscape.js, with a focus on Svelte 5 integration and the \"Codex Arcana\" sci-fi aesthetic.\n\n## Core Patterns\n\n### 1. Svelte 5 Integration\n\nManage Cytoscape lifecycle and reactivity using Svelte 5 `$effect` and `onMount`.\n\n```svelte\n<script lang=\"ts\">\n  import { onMount, onDestroy } from \"svelte\";\n  import cytoscape, { type Core } from \"cytoscape\";\n\n  let container: HTMLElement;\n  let cy: Core | undefined = $state();\n  let { elements } = $props();\n\n  onMount(() => {\n    cy = cytoscape({\n      container,\n      elements,\n      style: [\n        /* styles */\n      ],\n      layout: { name: \"cose\" },\n    });\n  });\n\n  onDestroy(() => {\n    cy?.destroy();\n  });\n\n  // Reactive updates\n  $effect(() => {\n    if (cy && elements) {\n      cy.elements().remove();\n      cy.add(elements);\n      cy.layout({ name: \"cose\", animate: true }).run();\n    }\n  });\n</script>\n\n<div bind:this={container} class=\"w-full h-full\"></div>\n```\n\n### 2. Sci-Fi \"Terminal\" Styling\n\nEmbrace a high-contrast, glowing aesthetic. Use dark backgrounds with vibrant green or amber accents.\n\n| Feature        | Pattern                                                                  |\n| -------------- | ------------------------------------------------------------------------ |\n| **Node Shape** | `round-rectangle` or `diamond` for sci-fi feel.                          |\n| **Node Label** | Use `text-valign: bottom` and `text-margin-y` for a data-readout look.   |\n| **Edge Style** | `bezier` curves with `triangle` arrows. Keep lines thin and subtle.      |\n| **Overlays**   | Use `overlay-color` and `overlay-opacity` for glowing selection effects. |\n\n**Example Sci-Fi Style:**\n\n```ts\nconst SCIFI_STYLE = [\n  {\n    selector: \"node\",\n    style: {\n      \"background-color\": \"#022c22\",\n      \"border-width\": 1,\n      \"border-color\": \"#15803d\",\n      label: \"data(label)\",\n      color: \"#86efac\",\n      \"font-family\": \"Inter, monospace\",\n      \"font-size\": 10,\n      \"text-transform\": \"uppercase\",\n    },\n  },\n  {\n    selector: \"edge\",\n    style: {\n      \"line-color\": \"#14532d\",\n      \"target-arrow-shape\": \"triangle\",\n      \"curve-style\": \"bezier\",\n      opacity: 0.6,\n    },\n  },\n];\n```\n\n### 3. Layout Strategies\n\n- **Cose**: Good for organic, balanced layouts.\n- **Circle/GridLayout**: Use for structured overviews or specific groupings.\n- **Fcose/Cola**: Advanced force-directed layouts for complex networks (require plugins).\n- **Manual**: Use `metadata.coordinates` if entities have fixed positions.\n\n## Interaction Patterns\n\n### Selection & Focus\n\nAnimate the view when a node is selected to provide feedback.\n\n```ts\ncy.on(\"tap\", \"node\", (evt) => {\n  const node = evt.target;\n  cy.animate({\n    center: { eles: node },\n    zoom: 1.5,\n    duration: 500,\n    easing: \"ease-out-cubic\",\n  });\n});\n```\n\n### Connection Management\n\nImplement a \"Connect Mode\" to allow users to link nodes visually.\n\n- Tap Source -> Tap Target -> Save relationship.\n- Visual feedback via classes (e.g., `.selected-source`).\n\n## Performance Guidelines\n\n1. **Batch Updates**: Use `cy.batch()` when performing many operations.\n2. **Selective Layouts**: Only run layouts when elements change significantly, not on every prop update.\n3. **Hardware Acceleration**: Cytoscape uses Canvas, which is generally performant, but keep texture usage low.\n\n## Best Practices\n\n1. **Lifecycle Management**: Always `destroy()` the instance in `onDestroy`.\n2. **Viewport Handling**: Use `cy.fit()` and `cy.resize()` to ensure the graph looks good on all screens.\n3. **Data Transformation**: Use a separate `Transformer` utility to map domain objects (Entities) to Cytoscape elements.\n4. **Overlay Elements**: Use HTML/CSS overlays for UI (zoom controls, legends) instead of rendering them in the Canvas.\n"},"lastSynced":"2026-03-08T02:13:30.563Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Visualization Agents needing high-performance network visualizations with Cytoscape.js integration.","zh":"非常适合需要高性能网络可视化的数据可视化代理，特别是与Cytoscape.js集成的代理。","ja":"Cytoscape.jsを使用した高性能ネットワーク可視化を必要とするデータビジュアライゼーションエージェントに最適です。","ko":"Cytoscape.js 통합을 통해 고성능 네트워크 시각화를 필요한 데이터 시각화 에이전트에게 적합합니다.","es":"Perfecto para agentes de visualización de datos que necesitan visualizaciones de red de alto rendimiento con integración de Cytoscape.js.","fr":"Parfait pour les agents de visualisation de données nécessitant des visualisations de réseau haute performance avec une intégration de Cytoscape.js.","de":"Perfekt für Data-Visualisierungs-Agents, die hochleistungsstarke Netzwerkvisualisierungen mit Cytoscape.js-Integration benötigen.","pt":"Perfeito para Agentes de Visualização de Dados que necessitam de visualizações de rede de alto desempenho com integração do Cytoscape.js.","ru":"Идеально подходит для агентов визуализации данных, требующих высокопроизводительных сетевых визуализаций с интеграцией Cytoscape.js.","ar":"مثالي للوكلاء المرئيين للبيانات الذين يحتاجون إلى تصورات شبكية عالية الأداء مع إدماج Cytoscape.js."},"recommendation":{"en":"Empowers agents to create aesthetically striking network visualizations using Cytoscape.js, with seamless Svelte 5 integration and support for the ''Codex Arcana'' sci-fi aesthetic, leveraging `$effect` and `onMount` for efficient lifecycle management.","zh":"赋予代理使用Cytoscape.js创建视觉上令人惊艳的网络可视化的能力，具有无缝的Svelte 5集成和对''Codex Arcana''科幻美学的支持，利用`$effect`和`onMount`进行高效的生命周期管理。","ja":"Cytoscape.jsを使用して、視覚的に驚くほど美しいネットワーク可視化を作成するエージェントの能力を与え、Svelte 5とのシームレスな統合と''Codex Arcana''のSF的な美学をサポートし、`$effect`と`onMount`を使用して効率的なライフサイクル管理を行う。","ko":"Cytoscape.js를 사용하여 시각적으로 놀랍도록 아름다운 네트워크 시각화를 생성하는 에이전트의 능력을 부여하며, Svelte 5와의无缝 통합 및 ''Codex Arcana''의 SF적인 미학을 지원하며, `$effect`와 `onMount`를 사용하여 효율적인 라이프사이클 관리를 수행한다.","es":"Habilita a los agentes a crear visualizaciones de red visualmente impresionantes utilizando Cytoscape.js, con una integración sin problemas de Svelte 5 y soporte para el estilo de ciencia ficción ''Codex Arcana'', aprovechando `$effect` y `onMount` para una gestión de ciclo de vida eficiente.","fr":"Permet aux agents de créer des visualisations de réseau visuellement frappantes en utilisant Cytoscape.js, avec une intégration transparente de Svelte 5 et un support pour l''esthétique de science-fiction ''Codex Arcana'', en exploitant `$effect` et `onMount` pour une gestion du cycle de vie efficace.","de":"Ermächtigt Agents, visuell ansprechende Netzwerkvisualisierungen mit Cytoscape.js zu erstellen, mit einer nahtlosen Svelte 5-Integration und Unterstützung für das Sci-Fi-Ästhetik ''Codex Arcana'', indem `$effect` und `onMount` für eine effiziente Lebenszyklusverwaltung genutzt werden.","pt":"Habilita os agentes a criar visualizações de rede esteticamente impressionantes usando Cytoscape.js, com integração perfeita do Svelte 5 e suporte ao estético de ficção científica ''Codex Arcana'', aproveitando `$effect` e `onMount` para gestão eficiente do ciclo de vida.","ru":"Наделяет агентов возможностью создавать визуально впечатляющие сетевые визуализации, используя Cytoscape.js, с бесшовной интеграцией Svelte 5 и поддержкой научно-фантастического эстетического оформления ''Codex Arcana'', используя `$effect` и `onMount` для эффективного управления жизненным циклом.","ar":"يمنح الوكلاء القدرة على إنشاء تصورات شبكية متأثرة جماليًا باستخدام Cytoscape.js، مع دمج متكامل من Svelte 5 ودعم التأثيرات العلمية الخيالية ''Codex Arcana''، واستخدام `$effect` و `onMount` للإدارة الفعالة لدورة الحياة."},"useCases":{"en":["Visualizing complex node-based RPG campaign networks","Generating high-performance network visualizations for data analysis","Integrating Cytoscape.js with Svelte 5 for reactive and efficient graph rendering"],"zh":["可视化复杂的基于节点的RPG战役网络","生成高性能的网络可视化用于数据分析","将Cytoscape.js与Svelte 5集成用于反应性和高效的图形渲染"],"ja":["ノードベースのRPGキャンペーンネットワークの可視化","データ分析のための高性能ネットワーク可視化の生成","Cytoscape.jsとSvelte 5の統合によるリアクティブかつ効率的なグラフレンダリング"],"ko":["노드 기반 RPG 캠페인 네트워크 시각화","데이터 분석을 위한 고성능 네트워크 시각화 생성","Cytoscape.js와 Svelte 5의 통합을 통한 반응성 및 효율적인 그래프 렌더링"],"es":["Visualizar redes de campaña de RPG basadas en nodos complejos","Generar visualizaciones de red de alto rendimiento para análisis de datos","Integrar Cytoscape.js con Svelte 5 para renderizado de gráficos reactivo y eficiente"],"fr":["Visualiser des réseaux de campagne de RPG basés sur des nœuds complexes","Générer des visualisations de réseau haute performance pour l''analyse de données","Intégrer Cytoscape.js avec Svelte 5 pour un rendu de graphique réactif et efficace"],"de":["Visualisieren komplexer, knotenbasierter RPG-Kampagnennetze","Erzeugen hochleistungsstarker Netzwerkvisualisierungen für Datenanalyse","Integrieren von Cytoscape.js mit Svelte 5 für reaktives und effizientes Graph-Rendering"],"pt":["Visualizar redes de campanha de RPG baseadas em nós complexos","Gerar visualizações de rede de alto desempenho para análise de dados","Integrar Cytoscape.js com Svelte 5 para renderização reativa e eficiente de gráficos"],"ru":["Визуализация сложных сетей кампаний RPG на основе узлов","Генерация высокопроизводительных сетевых визуализаций для анализа данных","Интеграция Cytoscape.js с Svelte 5 для реактивной и эффективной отрисовки графов"],"ar":["تصوير شبكات حملة RPG المعقدة المعتمدة على العقد","إنتاج تصورات شبكية عالية الأداء لتحليل البيانات","إدماج Cytoscape.js مع Svelte 5 لتحديث الرسومات التفاعلي والفعال"]},"limitations":{"en":["Requires Cytoscape.js and Svelte 5 integration","Limited to network visualization use cases","Dependent on Svelte 5 `$effect` and `onMount` for lifecycle management"],"zh":["需要Cytoscape.js和Svelte 5的集成","仅限于网络可视化的使用场景","依赖于Svelte 5的`$effect`和`onMount`进行生命周期管理"],"ja":["Cytoscape.jsとSvelte 5の統合が必要","ネットワーク可視化の使用ケースのみ","Svelte 5の`$effect`と`onMount`に依存してライフサイクル管理を行う"],"ko":["Cytoscape.js와 Svelte 5의 통합이 필요","네트워크 시각화 사용 사례에만 제한","Svelte 5의 `$effect`와 `onMount`에 의존하여 라이프사이클 관리를 수행"],"es":["Requiere integración de Cytoscape.js y Svelte 5","Limitado a casos de uso de visualización de red","Dependiente de Svelte 5 `$effect` y `onMount` para la gestión del ciclo de vida"],"fr":["Nécessite une intégration de Cytoscape.js et Svelte 5","Limité aux cas d''utilisation de visualisation de réseau","Dépendant de Svelte 5 `$effect` et `onMount` pour la gestion du cycle de vie"],"de":["Benötigt Cytoscape.js- und Svelte 5-Integration","Begrenzt auf Netzwerkvisualisierungs-Anwendungsfälle","Abhängig von Svelte 5 `$effect` und `onMount` für die Lebenszyklusverwaltung"],"pt":["Requer integração do Cytoscape.js e Svelte 5","Limitado a casos de uso de visualização de rede","Dependente do Svelte 5 `$effect` e `onMount` para gestão do ciclo de vida"],"ru":["Требует интеграции Cytoscape.js и Svelte 5","Ограничен для случаев использования сетевой визуализации","Зависит от Svelte 5 `$effect` и `onMount` для управления жизненным циклом"],"ar":["يتطلب إدماج Cytoscape.js و Svelte 5","محدود لاستخدامات تصور الشبكة","يعتمد على Svelte 5 `$effect` و `onMount` لإدارة دورة الحياة"]},"version":4},"contentHash":"ec44230c7efa1472a3eba645714871970a11ef88a43011db4f2e60c84298ec1c","qualityScore":36}');
