INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eserlan/Codex-Cryptica/cytoscape', 'cytoscape', 'eserlan', 'Codex-Cryptica', 'community', 'cytoscape eserlan Codex-Cryptica community Cytoscape is a node-based RPG campaign manager that utilizes Cytoscape.js for high-performance network visualizations, benefiting developers and gamers alike. Cytoscape 是一个用于创建高性能网络可视化的工具，具有 Svelte 5 集成和 Codex Arcana 科幻美学 Cytoscape は、高パフォーマンスのネットワーク可視化を作成するためのツールです。Svelte 5 統合と Codex Arcana サイエンスフィクション美学を備えています - AIエージェント Cytoscape는 고성능 네트워크 시각화를 생성하기 위한 도구로서 Svelte 5 통합 및 Codex Arcana 과학 픽션 미학을 갖추고 있습니다 - AI 도구 Cytoscape es un gestor de campañas de RPG basado en nodos que utiliza Cytoscape.js y Svelte 5 para crear visualizaciones de redes Cytoscape est un gestionnaire de campagnes de RPG basé sur des nœuds qui utilise Cytoscape.js et Svelte 5 pour créer des visualisations de réseaux Cytoscape ist ein nodebasierter RPG-Kampagnen-Manager, der Cytoscape.js und Svelte 5 für die Erstellung von Netzwerkvisualisierungen verwendet Cytoscape é uma ferramenta de gerenciamento de campanhas de RPG baseada em nós, que utiliza Cytoscape.js e Svelte 5 para criar visualizações de rede de alta performance. Cytoscape - это инструмент управления кампаниями RPG на основе узлов, который использует Cytoscape.js и Svelte 5 для создания высокопроизводительных визуализаций сетей для ИИ Агентов. Cytoscape هو أداة لإدارة حملات RPG القائمة على العقد، التي تستخدم Cytoscape.js و Svelte 5 لإنشاء تصورات شبكة عالية الأداء how to use cytoscape with Svelte 5 cytoscape alternative to other graph visualization tools cytoscape vs sigma js cytoscape install guide cytoscape setup tutorial for AI agents what is cytoscape used for in RPG campaign management Cytoscape Svelte 5 网络可视化 高性能 Codex Arcana JavaScript 库 Cytoscape 生命周期管理 反应性管理 Manages Cytoscape lifecycle and reactivity using Svelte 5 `$effect` and `onMount` Utilizes Cytoscape.js for high-performance network visualizations Integrates with Svelte 5 for seamless component management Supports the ''Codex Arcana'' sci-fi aesthetic for unique visualizations Employs `onDestroy` for proper component cleanup Leverages TypeScript for robust code management Cytoscape is a graph visualization tool that uses Cytoscape.js to create aesthetically striking network visualizations with a focus on Svelte 5 integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ignacioedlp/speed-pdf/react-pdf', 'community', 'ignacioedlp', 'speed-pdf', 'ignacioedlp/speed-pdf', 'react-pdf', 0, 0, 36, '2026-03-08T01:57:15.621Z', '2026-03-08T02:13:30.766Z', 'f35f53ab74c5098e8f631768639840cb680294e6aff84dcb1e23425b8f1409f6', '{"id":"ignacioedlp/speed-pdf/react-pdf","name":"react-pdf","description":{"en":"The react-pdf skill generates PDFs with React, requiring local font files and async code wrapping. It benefits developers creating custom PDF documents.","zh":"React-PDF是用于生成PDF的流行库。了解其关键要求和最佳实践，可以提高开发效率","ja":"React-PDFはPDF生成のための人気ライブラリです。重要な要件とベストプラクティスを理解することで、開発効率を向上できます","ko":"React-PDF는 PDF 생성을 위한 인기 있는 라이브러리입니다. 중요한 요구 사항과最佳实践을 이해하면 개발 효율을 향상할 수 있습니다","es":"react-pdf es una biblioteca para generar PDFs en aplicaciones React. Requiere fonts locales y un manejo cuidadoso del código asíncrono","fr":"react-pdf est une bibliothèque pour générer des PDF dans les applications React. Elle nécessite des polices locales et une gestion soigneuse du code asynchrone","de":"react-pdf ist eine Bibliothek zur Erstellung von PDFs in React-Anwendungen. Sie erfordert lokale Schriftarten und eine sorgfältige Handhabung des asynchronen Codes","pt":"O React-PDF é uma biblioteca para geração de PDFs em aplicativos React. Aprenda a configurá-lo corretamente.","ru":"React-PDF — это библиотека для генерации PDF в приложениях React. Узнайте, как ее настроить правильно для ИИ Агентов.","ar":"React-PDF هو مكتبة لإنشاء PDFs في تطبيقات React. تعلم كيفية إعدادها بشكل صحيح لآدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"react-pdf: PDF Generation Setup Guide | AI Agent Skill","zh":"React-PDF Setup Guide: 生成PDF的最佳实践","ja":"React-PDF設定ガイド: PDF生成のベストプラクティス","ko":"React-PDF 설정 가이드: PDF 생성을 위한 전문가의 팁","es":"react-pdf: Guía de configuración para desarrolladores","fr":"react-pdf: Guide de mise en place pour les développeurs","de":"react-pdf: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do React-PDF: Melhores Práticas","ru":"Настройка React-PDF: Руководство по Лучшим Практикам для ...","ar":"دليل إعداد React-PDF: أفضل الممارسات لآدوات الذكاء الاصطناعي"},"description":{"en":"Master react-pdf with our expert guide! Learn critical requirements, disable hyphenation, and generate PDFs with custom fonts. Get started now!","zh":"了解React-PDF的关键要求和最佳实践，包括字体、异步代码和断字处理","ja":"React-PDFの重要な要件とベストプラクティスを学びましょう。フォント、非同期コード、ハイフネーションなど","ko":"React-PDF의 중요한 요구 사항과最佳实践을 알아보세요. 폰트, 비동기 코드, 단어 분리 처리 등","es":"Aprende a generar PDFs con react-pdf. Descubre los requisitos críticos y las mejores prácticas para una implementación exitosa","fr":"Apprenez à générer des PDF avec react-pdf. Découvrez les exigences critiques et les meilleures pratiques pour une mise en œuvre réussie","de":"Erfahren Sie, wie Sie PDFs mit react-pdf erstellen. Entdecken Sie die kritischen Anforderungen und die besten Praktiken für eine erfolgreiche Implementierung","pt":"Aprenda a configurar o React-PDF com nossas dicas e truques. Desenvolva aplicativos web com geração de PDFs personalizados.","ru":"Узнайте, как настроить React-PDF с нашими советами и хитростями. Разрабатывайте веб-приложения с индивидуальной генерацией PDF для ИИ Агентов.","ar":"تعلم كيفية إعداد React-PDF باستخدام نصائحنا وأفكارنا. قم بتطوير تطبيقات الويب مع إنشاء PDFs مخصصة لآدوات الذكاء الاصطناعي."},"definition":{"en":"react-pdf is a library for generating PDFs with React, supporting custom fonts and layouts.","zh":"React-PDF是用于生成PDF的JavaScript库，需要遵循特定的要求和最佳实践","ja":"React-PDFはPDF生成のためのJavaScriptライブラリです。特定の要件とベストプラクティスに従う必要があります","ko":"React-PDF는 PDF 생성을 위한 JavaScript 라이브러리로서 특定的 要求 사항과最佳实践을 따르なければ 합니다","es":"react-pdf es una herramienta de código abierto para generar PDFs en aplicaciones web","fr":"react-pdf est un outil de code ouvert pour générer des PDF dans les applications web","de":"react-pdf ist ein Open-Source-Tool zur Erstellung von PDFs in Webanwendungen","pt":"O React-PDF é uma biblioteca JavaScript para geração de PDFs em aplicativos web React.","ru":"React-PDF — это библиотека JavaScript для генерации PDF в веб-приложениях React для ИИ Агентов.","ar":"React-PDF هو مكتبة جافاسكريبت لإنشاء PDFs في تطبيقات الويب React لآدوات الذكاء الاصطناعي."},"features":{"en":["Generates PDFs with custom fonts by registering local font files","Supports async code execution using IIFE (Immediately Invoked Function Expression) pattern","Disables hyphenation for custom fonts to prevent crashes or incorrect word breaks","Registers hyphenation callbacks using Font.registerHyphenationCallback()","Requires local font files, rejecting remote font URLs (http/https)"],"zh":["必须使用本地字体文件","异步代码需要包裹在IIFE中","自定义字体需要禁用断字处理","支持字体注册和断字回调","可以生成复杂的PDF布局"],"ja":["ローカルフォントファイルを使用する必要があります","非同期コードはIIFEで囲む必要があります","カスタムフォントではハイフネーションを無効にする必要があります","フォント登録とハイフネーションコールバックをサポート","複雑なPDFレイアウトを生成できます"],"ko":["로컬 폰트 파일을 사용해야 합니다","비동기 코드는 IIFE로 감싸야 합니다","커스텀 폰트에서는 단어 분리 처리를 비활성화해야 합니다","폰트 등록과 단어 분리 콜백을 지원","복잡한 PDF 레이아웃을 생성할 수 있습니다"],"es":["Uso de fuentes locales para evitar errores","Implementación de código asíncrono con IIFE","Deshabilitación de la división de palabras para fuentes personalizadas","Compatibilidad con aplicaciones React","Generación de PDFs personalizados"],"fr":["Utilisation de polices locales pour éviter les erreurs","Mise en œuvre de code asynchrone avec IIFE","Désactivation de la division de mots pour les polices personnalisées","Compatibilité avec les applications React","Génération de PDF personnalisés"],"de":["Verwendung lokaler Schriftarten zur Fehlervermeidung","Implementierung asynchronen Codes mit IIFE","Deaktivierung der Silbentrennung für benutzerdefinierte Schriftarten","Kompatibilität mit React-Anwendungen","Erstellung von benutzerdefinierten PDFs"],"pt":["Geração de PDFs personalizados em aplicativos React","Requisitos críticos: fontes locais, código assíncrono em IIFE e desativação de hifenização para fontes personalizadas","Suporte a fontes locais para geração de PDFs","Uso de padrão (async () => { ... })() para código assíncrono","Desativação de hifenização para fontes personalizadas com Font.registerHyphenationCallback"],"ru":["Генерация индивидуальных PDF в приложениях React для ИИ Агентов","Критические требования: локальные шрифты, асинхронный код в IIFE и отключение переноса слов для индивидуальных шрифтов","Поддержка локальных шрифтов для генерации PDF","Использование шаблона (async () => { ... })() для асинхронного кода","Отключение переноса слов для индивидуальных шрифтов с Font.registerHyphenationCallback"],"ar":["إنشاء PDFs مخصصة في تطبيقات React لآدوات الذكاء الاصطناعي","المتطلبات الحرجة: ملفات الخطوط المحلية، رمز غير متزامن في IIFE وإيقاف تشغيل تحويل الكلمات لخطوط مخصصة","دعم ملفات الخطوط المحلية لإنشاء PDFs","استخدام نمط (async () => { ... })() لرقم غير متزامن","إيقاف تحويل الكلمات لخطوط مخصصة مع Font.registerHyphenationCallback"]},"keywords":{"en":["how to use react-pdf","react-pdf setup guide","react-pdf vs jsPDF","react-pdf install","react-pdf custom fonts","generating pdfs with react","react-pdf alternative","react-pdf tutorial"],"zh":["React-PDF","生成PDF","JavaScript库","本地字体文件","异步代码","断字处理","AIエージェント","React开发"],"ja":["React-PDF","PDF生成","JavaScriptライブラリ","ローカルフォントファイル","非同期コード","ハイフネーション","AIエージェント","React開発"],"ko":["React-PDF","PDF 생성","JavaScript 라이브러리","로컬 폰트 파일","비동기 코드","단어 분리 처리","AI 에이전트","React 개발"],"es":["react-pdf","generar pdf","aplicaciones react","fuentes locales","código asíncrono","deshabilitar división de palabras","herramientas de desarrollo","bibliotecas de react"],"fr":["react-pdf","générer pdf","applications react","polices locales","code asynchrone","désactiver division de mots","outils de développement","bibliothèques react"],"de":["react-pdf","pdf erstellen","react-anwendungen","lokale schriftarten","asynchroner code","silbentrennung deaktivieren","entwicklungstools","react-bibliotheken"],"pt":["react-pdf","geração de pdf","aplicativos react","fontes locais","código assíncrono","iife","desativação de hifenização","font.registerhyphenationcallback"],"ru":["react-pdf","генерация pdf","приложения react","локальные шрифты","асинхронный код","iife","отключение переноса слов","font.registerhyphenationcallback","ии агенты"],"ar":["react-pdf","إنشاء pdf","تطبيقات react","ملفات الخطوط المحلية","رقم غير متزامن","iife","إيقاف تحويل الكلمات","font.registerhyphenationcallback","آدوات الذكاء الاصطناعي"]}},"owner":"ignacioedlp","repo":"speed-pdf","repoPath":"ignacioedlp/speed-pdf","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.621Z","topics":[],"category":"community","skillMd":{"name":"react-pdf","description":"","bodyPreview":"# Generating PDFs with React-PDF\n\n## CRITICAL REQUIREMENTS\n\n1. **Fonts MUST be local files** - Remote font URLs (http/https) do NOT work. Always download fonts\n   to local files before using them.\n2. **Wrap async code in IIFE** - Top-level await causes errors. Always use `(async () => { ... })()`\n   pattern.\n3. **Disable hyphenation for custom fonts** - Custom fonts lack hyphenation dictionaries and may\n   crash or break words incorrectly. Always call\n   `Font.registerHyphenationCallback((word)","body":"# Generating PDFs with React-PDF\n\n## CRITICAL REQUIREMENTS\n\n1. **Fonts MUST be local files** - Remote font URLs (http/https) do NOT work. Always download fonts\n   to local files before using them.\n2. **Wrap async code in IIFE** - Top-level await causes errors. Always use `(async () => { ... })()`\n   pattern.\n3. **Disable hyphenation for custom fonts** - Custom fonts lack hyphenation dictionaries and may\n   crash or break words incorrectly. Always call\n   `Font.registerHyphenationCallback((word) => [word]);` after registering custom fonts.\n\n## Files\n\n- `references/google-fonts.txt` - Metadata for ~65 popular Google Fonts with TrueType URLs. Each\n  line is a font variant in tab-separated format: `font name`, `style`, `category`, `weight`, `url`.\n- `references/components.md` - Full component API reference and supported CSS properties\n- `assets/example-template.tsx` - Minimal working example demonstrating fixed footers, page numbers,\n  and unbreakable content. Read this before starting to understand the basic patterns. Note: not all\n  APIs are shown here — always refer to the docs and `references/components.md` for the full API.\n\n## Prerequisites\n\n```bash\nnpm install react @react-pdf/renderer\nnpm install -D tsx @types/react\n```\n\n`tsx` runs TypeScript + JSX files directly via Node with no config — no `tsconfig.json` needed. It\nuses esbuild under the hood and handles JSX transformation automatically.\n\n## Core Components\n\n- **Document**: Root component (metadata, settings)\n- **Page**: Individual pages (A4, Letter, or custom dimensions)\n- **View**: Container component (similar to div)\n- **Text**: Text content, supports nesting for inline styling\n- **Image**: Embed images (JPG, PNG, base64)\n- **Link**: Clickable hyperlinks (external or internal)\n- **Note**: Annotation notes\n- **Canvas**: Freeform drawing with pdfkit methods\n- **Svg**: Vector graphics (Circle, Rect, Path, Line, Polygon, etc.)\n- **StyleSheet**: Create reusable styles\n\nFor full component props and CSS properties, see\n[references/components.md](references/components.md).\n\n## Basic Example\n\n```tsx\nimport React from \"react\";\nimport { Document, Page, Text, View, StyleSheet, renderToFile } from \"@react-pdf/renderer\";\n\nconst styles = StyleSheet.create({\n  page: { flexDirection: \"column\", backgroundColor: \"#ffffff\", padding: 40 },\n  title: { fontSize: 24, marginBottom: 20, fontWeight: \"bold\" },\n  text: { fontSize: 12, lineHeight: 1.5 },\n});\n\nconst MyDocument = () => (\n  <Document>\n    <Page size=\"A4\" style={styles.page}>\n      <View style={{ margin: 10, padding: 20 }}>\n        <Text style={styles.title}>Document Title</Text>\n        <Text style={styles.text}>Your content here</Text>\n      </View>\n    </Page>\n  </Document>\n);\n\n(async () => {\n  await renderToFile(<MyDocument />, \"./output.pdf\");\n  console.log(\"PDF saved!\");\n})();\n```\n\n## Running Scripts\n\nPDF generation scripts use JSX, which Node cannot run directly. Use `tsx` to execute them:\n\n```bash\nnpx tsx my-document.tsx\n```\n\n`npx tsx` works without installing tsx globally — it downloads on demand. If tsx is installed as a\ndev dependency (`npm install -D tsx`), it runs instantly without the npx download step.\n\nAlways wrap rendering in async IIFE:\n\n```tsx\n// Good\n(async () => {\n  await renderToFile(<MyDocument />, \"./output.pdf\");\n})();\n\n// Bad - top-level await may fail\nawait renderToFile(<MyDocument />, \"./output.pdf\");\n```\n\n## Previewing PDFs\n\nTo visually inspect generated PDFs, convert pages to images. Try `pdftoppm` first (often\npre-installed), fall back to Python''s PyMuPDF if unavailable.\n\n**Option 1: pdftoppm (poppler-utils)** — preferred, no install needed in many environments:\n\n```bash\npdftoppm -png -r 200 document.pdf preview\n# → preview-1.png, preview-2.png, ...\n```\n\n**Option 2: PyMuPDF (Python)** — fallback if pdftoppm is not available:\n\n```bash\npip install pymupdf\n```\n\n```python\nimport fitz\n\ndoc = fitz.open(\"document.pdf\")\nfor i, page in enumerate(doc):\n    pix = page.get_pixmap(dpi=200)\n    pix.save(f\"page-{i+1}.png\")\n```\n\n## Rendering Methods\n\n```tsx\nimport { renderToFile, renderToBuffer } from \"@react-pdf/renderer\";\n\n// To file\n(async () => {\n  await renderToFile(<MyDocument />, \"./document.pdf\");\n})();\n\n// To buffer\n(async () => {\n  const buffer = await renderToBuffer(<MyDocument />);\n})();\n```\n\n## Styling\n\nThree methods: `StyleSheet.create()`, inline objects, or mixed arrays.\n\n```tsx\nconst styles = StyleSheet.create({ container: { padding: 20 } });\n\n<View style={styles.container} />\n<View style={{ padding: 20 }} />\n<View style={[styles.container, { marginTop: 10 }]} />\n```\n\n### Supported Units\n\n`pt` (default, 72 DPI), `in`, `mm`, `cm`, `%`, `vw`, `vh`\n\n### Common Style Properties\n\n```tsx\n{\n  // Flexbox\n  flexDirection: \"row\", justifyContent: \"space-between\", alignItems: \"center\",\n  flexWrap: \"wrap\", gap: 10,\n\n  // Box model\n  margin: 10, padding: 20, width: \"100%\", height: 200,\n\n  // Borders\n  borderWidth: 1, borderColor: \"#333\", borderRadius: 5, borderStyle: \"solid\",\n\n  // Colors\n  backgroundColor: \"#f0f0f0\", color: \"#000\", opacity: 0.8,\n\n  // Typography\n  fontSize: 12, fontWeight: \"bold\", fontFamily: \"Helvetica\", fontStyle: \"italic\",\n  lineHeight: 1.5, textAlign: \"center\", textDecoration: \"underline\",\n  textTransform: \"uppercase\", letterSpacing: 1,\n\n  // Position\n  position: \"absolute\", top: 0, left: 0, right: 0, bottom: 0, zIndex: 10,\n\n  // Transforms\n  transform: \"rotate(45deg)\", transformOrigin: \"center\",\n}\n```\n\n## Images\n\nLocal files are most reliable. Remote URLs may fail due to network/CORS issues.\n\n```tsx\nimport { Image } from ''@react-pdf/renderer'';\n\n<Image src=\"./images/photo.jpg\" style={{ width: 200, height: 150 }} />\n<Image src={{ data: buffer, format: ''png'' }} />\n```\n\n**SVG files cannot be used as Image sources.** Read the SVG source and recreate using react-pdf Svg\ncomponents.\n\n## SVG Graphics\n\n```tsx\nimport { Svg, Circle, Rect, Path, Line, G, Defs, LinearGradient, Stop } from \"@react-pdf/renderer\";\n\n<Svg width=\"200\" height=\"200\" viewBox=\"0 0 200 200\">\n  <Defs>\n    <LinearGradient id=\"grad1\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <Stop offset=\"0%\" stopColor=\"#3498db\" />\n      <Stop offset=\"100%\" stopColor=\"#9b59b6\" />\n    </LinearGradient>\n  </Defs>\n  <Circle cx=\"100\" cy=\"100\" r=\"50\" fill=\"url(#grad1)\" />\n  <Rect x=\"10\" y=\"10\" width=\"50\" height=\"50\" fill=\"#e74c3c\" />\n  <Path d=\"M10,50 Q50,10 90,50\" stroke=\"#2ecc71\" strokeWidth=\"2\" fill=\"none\" />\n</Svg>;\n```\n\n## Using Icons\n\nRead SVG source from icon libraries and convert to react-pdf Svg components:\n\n```bash\nnpm install lucide-static\n```\n\n```tsx\nimport { Svg, Path, Rect } from \"@react-pdf/renderer\";\n\n// Converted from lucide-static/icons/mail.svg\nconst MailIcon = ({ size = 12, color = \"#888\" }) => (\n  <Svg width={size} height={size} viewBox=\"0 0 24 24\">\n    <Path d=\"m22 7-8.991 5.727a2 2 0 0 1-2.009 0L2 7\" stroke={color} strokeWidth={2} fill=\"none\" />\n    <Rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\" stroke={color} strokeWidth={2} fill=\"none\" />\n  </Svg>\n);\n```\n\n## Links and Navigation\n\n```tsx\n<Link src=\"https://example.com\"><Text>Visit website</Text></Link>\n\n<View id=\"section-1\"><Text>Target</Text></View>\n<Link src=\"#section-1\"><Text>Jump to Section 1</Text></Link>\n```\n\n## Dynamic Content and Page Numbers\n\n```tsx\n<Text render={({ pageNumber, totalPages }) => `Page ${pageNumber} of ${totalPages}`} />\n```\n\n## Fixed Headers/Footers\n\n```tsx\n<Page size=\"A4\">\n  <View fixed style={{ position: \"absolute\", top: 20, left: 30, right: 30 }}>\n    <Text>Header</Text>\n  </View>\n  <View style={{ marginTop: 60, marginBottom: 60 }}>\n    <Text>Content</Text>\n  </View>\n  <Text\n    fixed\n    style={{ position: \"absolute\", bottom: 20, left: 30, right: 30, textAlign: \"center\" }}\n    render={({ pageNumber, totalPages }) => `Page ${pageNumber} of ${totalPages}`}\n  />\n</Page>\n```\n\n## Page Breaks and Wrapping\n\n```tsx\n<View break />                              // Force page break\n<View wrap={false}><Text>Keep together</Text></View>  // Prevent breaking inside\n<Text orphans={2} widows={2}>Long text...</Text>       // Orphan/widow control\n<View minPresenceAhead={100}><Text>Content</Text></View>  // Min space before break\n```\n\n## Custom Fonts\n\n**CRITICAL: All font sources MUST be local file paths.** Remote URLs do not work.\n\n```tsx\nimport { Font } from \"@react-pdf/renderer\";\n\nFont.register({\n  family: \"Roboto\",\n  fonts: [\n    { src: \"./fonts/Roboto-Regular.ttf\", fontWeight: \"normal\" },\n    { src: \"./fonts/Roboto-Bold.ttf\", fontWeight: \"bold\" },\n    { src: \"./fonts/Roboto-Italic.ttf\", fontStyle: \"italic\" },\n  ],\n});\n\n// Always disable hyphenation when using custom fonts\nFont.registerHyphenationCallback((word) => [word]);\n```\n\n**Built-in fonts**: Courier, Helvetica, Times-Roman (each with Bold, Italic/Oblique variants)\n\n**Font weight values**: thin (100), ultralight (200), light (300), normal (400), medium (500),\nsemibold (600), bold (700), ultrabold (800), heavy (900)\n\n## Google Fonts\n\nUse `references/google-fonts.txt` to find font URLs, then download locally:\n\n```bash\n# Find the font URL\ngrep \"^Roboto\" skills/react-pdf/references/google-fonts.txt | grep \"700\" | grep \"normal\"\n\n# Download\nmkdir -p fonts\ncurl -sL \"<url-from-grep>\" -o fonts/Roboto-Bold.ttf\n\n# Verify - must show \"TrueType Font data\"\nfile fonts/Roboto-Bold.ttf\n```\n\nIf `file` shows \"HTML document\" or \"ASCII text\", the download failed. Try a different URL or search\nGitHub for the font''s official repo with TTF files.\n\n## Emoji\n\nEmoji won''t render in PDFs unless you register an emoji source. Install `twemoji-emojis` to get\nlocal Twemoji PNG assets — no internet needed at render time.\n\n```bash\nnpm install twemoji-emojis\n```\n\n```tsx\nimport { Font } from \"@react-pdf/renderer\";\n\nFont.registerEmojiSource({\n  format: \"png\",\n  url: \"node_modules/twemoji-emojis/vendor/72x72/\",\n});\n```\n\nThen use emoji directly in Text: `<Text>Hello 🚀🎉</Text>`\n\n## Other Features\n\n```tsx\n// Canvas drawing\n<Canvas style={{ width: 200, height: 200 }}\n  paint={(painter, w, h) => { painter.circle(w/2, h/2, 50).fill(\"#3498db\"); }} />\n\n// Annotation notes\n<Note style={{ color: \"yellow\" }}>Annotation text</Note>\n\n// Hyphenation\nFont.registerHyphenationCallback((word) => [word]); // disable\n\n// Debug mode - visualize boundaries\n<View debug><Text debug>Debug text</Text></View>\n\n// Document metadata\n<Document title=\"My Doc\" author=\"Author\" subject=\"Report\" language=\"en-US\" pdfVersion=\"1.5\" />\n```\n\n## Best Practices\n\n1. Use `StyleSheet.create()` — define styles once and reuse\n2. Compress images before embedding, use `cache={true}` for remote images\n3. Test page breaks — content may flow differently than expected\n4. Prefer flexbox over absolute positioning\n5. Use `fixed` prop for headers/footers on every page\n6. Use `debug={true}` to visualize element boundaries\n7. Wrap rendering in try-catch blocks\n\n## Common Issues\n\n**Text overflow**: `<Text style={{ width: 200, maxLines: 3, textOverflow: \"ellipsis\" }}>...</Text>`\n\n**Missing fonts**: Download locally and register with local file paths. Remote URLs will NOT work.\n\n**Unexpected page breaks**: Use `wrap={false}` to keep content together, or `<View break />` to\nforce breaks.\n"},"lastSynced":"2026-03-08T02:13:30.766Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing dynamic PDF generation with custom fonts and layouts.","zh":"非常适合需要动态PDF生成、自定义字体和布局的前端代理。","ja":"フロントエンドエージェントが動的なPDF生成、カスタムフォント、レイアウトを必要とする場合に最適です。","ko":"동적 PDF 생성, 사용자 지정 글꼴 및 레이아웃이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan generación de PDF dinámica con fuentes y diseños personalizados.","fr":"Idéal pour les agents Frontend ayant besoin de génération de PDF dynamique avec des polices et des mises en page personnalisées.","de":"Perfekt für Frontend-Agents, die dynamische PDF-Generierung mit benutzerdefinierten Schriftarten und Layouts benötigen.","pt":"Perfeito para Agentes Frontend que precisam de geração dinâmica de PDF com fontes personalizadas e layouts.","ru":"Идеально подходит для агентов Фронтенда, которым необходима динамическая генерация PDF с пользовательскими шрифтами и макетами.","ar":"مثالي لعميل واجهة المستخدم التي تحتاج إلى توليد ديناميكي لملفات PDF مع خطوط مخصصة وتصاميم."},"recommendation":{"en":"Empowers agents to generate custom PDF documents using React, leveraging local font files and async code wrapping with IIFE patterns, while disabling hyphenation for custom fonts to prevent crashes.","zh":"赋予代理生成使用React的自定义PDF文档的能力，利用本地字体文件和异步代码包装IIFE模式，同时禁用自定义字体的连字功能以防止崩溃。","ja":"Reactを利用して、ローカルフォントファイルとasyncコードをIIFEパターンでラッピングしながら、カスタムフォントのハイフネーションを無効にしてクラッシュを防ぐことで、カスタムPDFドキュメントを生成できるエージェントをEmpowerします。","ko":"React를 사용하여 커스텀 PDF 문서를 생성할 수 있는 에이전트를 강화합니다. 로컬 폰트 파일과 async 코드를 IIFE 패턴으로 감싸고 사용자 지정 폰트의 단어 분리 기능을 비활성화하여 충돌을 방지합니다.","es":"Habilita a los agentes a generar documentos PDF personalizados utilizando React, aprovechando archivos de fuentes locales y código asíncrono con patrones de envoltura IIFE, mientras se deshabilita la división silábica para fuentes personalizadas para prevenir bloqueos.","fr":"Permet aux agents de générer des documents PDF personnalisés en utilisant React, en exploitant les fichiers de polices locaux et le code asynchrone avec des modèles d''encapsulation IIFE, tout en désactivant la césure pour les polices personnalisées pour éviter les plantages.","de":"Ermöglicht es Agents, benutzerdefinierte PDF-Dokumente mit React zu generieren, indem lokale Schriftartendateien und asynchrone Code mit IIFE-Mustern genutzt werden, während die Silbentrennung für benutzerdefinierte Schriftarten deaktiviert wird, um Abstürze zu vermeiden.","pt":"Habilita os agentes a gerar documentos PDF personalizados usando React, aproveitando arquivos de fontes locais e envoltório de código assíncrono com padrões IIFE, enquanto desabilita a hifenização para fontes personalizadas para prevenir falhas.","ru":"Наделяет агентов возможностью генерировать пользовательские документы PDF, используя React, с использованием локальных файлов шрифтов и асинхронного кода, завернутого в шаблоны IIFE, а также отключает перенос слов для пользовательских шрифтов, чтобы предотвратить сбои.","ar":"يمنح الوكلاء القدرة على إنتاج مستندات PDF مخصصة باستخدام React، واستخدام ملفات الخطوط المحلية والرمز المتزامن الملتف بالأنماط IIFE، مع تعطيل تحويل الكلمات لخطوط مخصصة لمنع الأعطال."},"useCases":{"en":["Generating custom PDF reports with embedded fonts","Creating dynamic invoices with async data loading","Debugging PDF rendering issues with custom font hyphenation"],"zh":["生成带有嵌入字体的自定义PDF报告","创建带有异步数据加载的动态发票","调试带有自定义字体连字的PDF渲染问题"],"ja":["埋め込みフォントを持つカスタムPDFレポートを生成する","asyncデータロードを持つ動的な請求書を作成する","カスタムフォントのハイフネーションを持つPDFレンダリングの問題をデバッグする"],"ko":["埋입된 글꼴을 포함하는 사용자 지정 PDF 보고서 생성","비동기 데이터 로드를 포함하는 동적 인보이스 생성","사용자 지정 글꼴의 단어 분리와 함께 PDF 렌더링 문제 디버깅"],"es":["Generar informes PDF personalizados con fuentes incrustadas","Crear facturas dinámicas con carga de datos asíncrona","Depurar problemas de representación de PDF con silbación de fuentes personalizadas"],"fr":["Générer des rapports PDF personnalisés avec des polices intégrées","Créer des factures dynamiques avec chargement de données asynchrone","Déboguer les problèmes de rendu de PDF avec césure de polices personnalisées"],"de":["Erzeugen von benutzerdefinierten PDF-Berichten mit eingebetteten Schriftarten","Erstellen von dynamischen Rechnungen mit asynchroner Datenladung","Beheben von PDF-Renderproblemen mit Silbentrennung benutzerdefinierter Schriftarten"],"pt":["Gerar relatórios PDF personalizados com fontes incorporadas","Criar faturas dinâmicas com carregamento de dados assíncrono","Depurar problemas de renderização de PDF com hifenização de fontes personalizadas"],"ru":["Генерировать пользовательские отчеты PDF с встроенными шрифтами","Создавать динамические счета-фактуры с асинхронной загрузкой данных","Отлаживать проблемы с отрисовкой PDF с помощью пользовательской шрифтовой переноса"],"ar":["توليد تقارير PDF مخصصة مع خطوط مدمجة","إنشاء فواتير ديناميكية مع تحميل بيانات متزامن","تصحيح مشاكل عرض ملفات PDF مع تحويل كلمات الخطوط المخصصة"]},"limitations":{"en":["Requires local font files, remote font URLs are not supported","Top-level await is not supported, async code must be wrapped in IIFE","Custom fonts require hyphenation to be disabled to prevent rendering issues"],"zh":["需要本地字体文件，远程字体URL不支持","顶级等待不支持，异步代码必须包装在IIFE中","自定义字体需要禁用连字以防止渲染问题"],"ja":["ローカルフォントファイルが必要、リモートフォントURLはサポートされていない","トップレベル待機はサポートされていない、asyncコードはIIFEで囲む必要がある","カスタムフォントではハイフネーションを無効にする必要があるため、レンダリングの問題を防ぐ"],"ko":["로컬 폰트 파일이 필요하며, 원격 폰트 URL은 지원되지 않음","최상위 대기是不支持的, 비동기 코드는 IIFE로 감싸야 함","사용자 지정 폰트의 경우 단어 분리를 비활성화해야 렌더링 문제가 발생하지 않음"],"es":["Requiere archivos de fuentes locales, no se admiten URLs de fuentes remotas","No se admite la espera superior, el código asíncrono debe estar envuelto en IIFE","Las fuentes personalizadas requieren que se deshabilite la silbación para evitar problemas de representación"],"fr":["Nécessite des fichiers de polices locaux, les URL de polices distantes ne sont pas prises en charge","La espera de niveau supérieur n''est pas prise en charge, le code asynchrone doit être encapsulé dans IIFE","Les polices personnalisées nécessitent de désactiver la césure pour éviter les problèmes de rendu"],"de":["Erfordert lokale Schriftartendateien, Remote-Schriftart-URLs werden nicht unterstützt","Top-Level-Warten wird nicht unterstützt, asynchrone Code muss in IIFE eingeschlossen werden","Benutzerdefinierte Schriftarten erfordern, dass die Silbentrennung deaktiviert wird, um Renderprobleme zu vermeiden"],"pt":["Requer arquivos de fontes locais, URLs de fontes remotos não são suportados","Aguarde no nível superior não é suportado, código assíncrono deve ser envolto em IIFE","Fontes personalizadas requerem hifenização desabilitada para prevenir problemas de renderização"],"ru":["Требует локальных файлов шрифтов, удаленные URL-адреса шрифтов не поддерживаются","Верхний уровень ожидания не поддерживается, асинхронный код должен быть завернут в шаблоны IIFE","Пользовательские шрифты требуют отключения переноса слов, чтобы предотвратить проблемы с отрисовкой"],"ar":["يتطلب ملفات خطوط محلية، لا يدعم عناوين URL للخطوط البعيدة","الانتظار في المستوى الأعلى غير مدعوم، يجب حزم الرمز المتزامن في أنماط IIFE","تتطلب الخطوط المخصصة تعطيل تحويل الكلمات لمنع مشاكل العرض"]},"version":4},"contentHash":"f35f53ab74c5098e8f631768639840cb680294e6aff84dcb1e23425b8f1409f6","qualityScore":36}');
