INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ignacioedlp/speed-pdf/react-pdf', 'react-pdf', 'ignacioedlp', 'speed-pdf', 'community', 'react-pdf ignacioedlp speed-pdf community The react-pdf skill generates PDFs with React, requiring local font files and async code wrapping. It benefits developers creating custom PDF documents. React-PDF是用于生成PDF的流行库。了解其关键要求和最佳实践，可以提高开发效率 React-PDFはPDF生成のための人気ライブラリです。重要な要件とベストプラクティスを理解することで、開発効率を向上できます React-PDF는 PDF 생성을 위한 인기 있는 라이브러리입니다. 중요한 요구 사항과最佳实践을 이해하면 개발 효율을 향상할 수 있습니다 react-pdf es una biblioteca para generar PDFs en aplicaciones React. Requiere fonts locales y un manejo cuidadoso del código asíncrono react-pdf est une bibliothèque pour générer des PDF dans les applications React. Elle nécessite des polices locales et une gestion soigneuse du code asynchrone react-pdf ist eine Bibliothek zur Erstellung von PDFs in React-Anwendungen. Sie erfordert lokale Schriftarten und eine sorgfältige Handhabung des asynchronen Codes O React-PDF é uma biblioteca para geração de PDFs em aplicativos React. Aprenda a configurá-lo corretamente. React-PDF — это библиотека для генерации PDF в приложениях React. Узнайте, как ее настроить правильно для ИИ Агентов. React-PDF هو مكتبة لإنشاء PDFs في تطبيقات React. تعلم كيفية إعدادها بشكل صحيح لآدوات الذكاء الاصطناعي. how to use react-pdf react-pdf setup guide react-pdf vs jsPDF react-pdf install react-pdf custom fonts generating pdfs with react react-pdf alternative react-pdf tutorial React-PDF 生成PDF JavaScript库 本地字体文件 异步代码 断字处理 AIエージェント React开发 Generates PDFs with custom fonts by registering local font files Supports async code execution using IIFE (Immediately Invoked Function Expression) pattern Disables hyphenation for custom fonts to prevent crashes or incorrect word breaks Registers hyphenation callbacks using Font.registerHyphenationCallback() Requires local font files, rejecting remote font URLs (http/https) react-pdf is a library for generating PDFs with React, supporting custom fonts and layouts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lance-format/lance-context/ci-pr-helper', 'community', 'lance-format', 'lance-context', 'lance-format/lance-context', 'ci-pr-helper', 0, 0, 36, '2026-03-08T01:57:15.623Z', '2026-03-08T02:13:31.514Z', '7a83548716dd9cf598fa9f7a8230f997d3fb09abe498deafcb2036910b05a926', '{"id":"lance-format/lance-context/ci-pr-helper","name":"ci-pr-helper","description":{"en":"The ci-pr-helper skill manages multimodal agentic context lifecycle with Lance, benefiting developers by automating project checks and PR preparation. It runs local checks via scripts and drafts PR titles and bodies.","zh":"CI PR Helper 是一个自动化代码检查和 PR 创建的工具，帮助开发者提高效率。它支持运行本地检查、创建 PR 标题和正文，并自动打开 PR","ja":"CI PR Helper はコードチェックと PR 作成を自動化するツールで、開発者の効率を向上させます。ローカルチェックの実行、PR タイトルと本文の作成、PR の自動開設をサポートします","ko":"CI PR Helper는 코드 검사와 PR 생성을 자동화하는 도구로 개발자의 효율성을 높여줍니다. 로컬 체크 실행, PR 제목 및 본문 생성, PR 자동 열기를 지원합니다","es":"El agente ci-pr-helper gestiona el ciclo de vida del contexto de agente multimodal con Lance, ejecutando comprobaciones de proyecto locales y preparando solicitudes de extracción","fr":"L''agent ci-pr-helper gère le cycle de vie du contexte d''agent multimodal avec Lance, en exécutant des vérifications de projet locales et en préparant des demandes d''extraction","de":"Der Agent ci-pr-helper verwaltet den Lebenszyklus des multimodalen Agentenkontexts mit Lance, indem er Projektprüfungen lokal ausführt und Pull-Requests vorbereitet","pt":"O CI PR Helper é uma ferramenta que ajuda a gerenciar o ciclo de vida do contexto de agente multimodal com Lance","ru":"CI PR Helper - это инструмент, помогающий управлять жизненным циклом контекста многомодального агента с помощью Lance для ИИ Агентов","ar":"CI PR Helper هو أداة تساعد في إدارة دورة حياة سياق العامل المتعدد الوسائط مع Lance"},"seo":{"title":{"en":"ci-pr-helper: Automated PR Setup Guide | AI Agent Skill","zh":"CI PR Helper 设置指南 - 自动化代码检查和 PR 创建","ja":"CI PR Helper 導入ガイド - コードチェックと PR 作成の自動化","ko":"CI PR Helper 설정 가이드 - 자동 코드 검사 및 PR 생성","es":"Configuración de ci-pr-helper: Guía de implementación de ...","fr":"Mise en place de ci-pr-helper : Guide d''installation des ...","de":"Einrichtung von ci-pr-helper: Leitfaden für die Implement...","pt":"Guia de Configuração do CI PR Helper para Desenvolvedores","ru":"Настройка CI PR Helper: Руководство для Разработчиков ИИ ...","ar":"دليل إعداد CI PR Helper لمنصة Lance للculate"},"description":{"en":"Streamline your development workflow with ci-pr-helper, a skill that automates local checks and PR creation - learn how to get started today!","zh":"使用 CI PR Helper 自动化代码检查和 PR 创建，提高开发效率。了解如何设置和使用此工具","ja":"CI PR Helper を使用してコードチェックと PR 作成を自動化し、開発効率を向上させる。設定方法と使い方を学ぶ","ko":"CI PR Helper를 사용하여 코드 검사와 PR 생성을 자동화하고 개발 효율을 높여보세요. 설정 방법과 사용법을 알아보세요","es":"Aprende a configurar ci-pr-helper para ejecutar verificaciones de proyecto de forma local y crear solicitudes de extracción con títulos y resúmenes claros","fr":"Découvrez comment configurer ci-pr-helper pour exécuter des vérifications de projet en local et créer des demandes d''extraction avec des titres et des résumé...","de":"Erfahren Sie, wie Sie ci-pr-helper einrichten, um Projektprüfungen lokal auszuführen und Pull-Requests mit klaren Titeln und Zusammenfassungen zu erstellen","pt":"Aprenda a configurar o CI PR Helper para automatizar verificações de projeto e criar PRs com títulos e resumos claros","ru":"Узнайте, как настроить CI PR Helper для автоматизации проверок проекта и создания PR с ясными заголовками и описаниями для ИИ Агентов","ar":"تعلم كيفية إعداد CI PR Helper للتحقق التلقائي من مشروع وإنشاء طلبات سحب مع عناوين وملخصات واضحة"},"definition":{"en":"ci-pr-helper is a skill that automates the process of running local checks, drafting PR titles and bodies, and creating pull requests using the gh command.","zh":"CI PR Helper 是一个用于自动化代码检查和 PR 创建的 AI 工具","ja":"CI PR Helper はコードチェックと PR 作成を自動化する AI エージェントです","ko":"CI PR Helper는 코드 검사와 PR 생성을 자동화하는 AI 도구입니다","es":"ci-pr-helper es una herramienta de AI que gestiona el ciclo de vida del contexto de agente multimodal con Lance","fr":"ci-pr-helper est un outil d''IA qui gère le cycle de vie du contexte d''agent multimodal avec Lance","de":"ci-pr-helper ist ein AI-Tool, das den Lebenszyklus des multimodalen Agentenkontexts mit Lance verwaltet","pt":"O que é CI PR Helper? É uma ferramenta que automatiza verificações de projeto e cria PRs com títulos e resumos claros","ru":"Что такое CI PR Helper? Это инструмент, автоматизирующий проверки проекта и создающий PR с ясными заголовками и описаниями для ИИ Агентов","ar":"ما هو CI PR Helper؟ هو أداة تلقائية للتحقق من مشروع وإنشاء طلبات سحب مع عناوين وملخصات واضحة"},"features":{"en":["Runs local checks via the script in scripts/","Drafts PR title and body using a predefined template","Creates pull requests using the gh pr create command","Surfaces the exact command for manual execution if gh is not available","Ensures feature branch checks before PR creation"],"zh":["运行本地检查","创建 PR 标题和正文","自动打开 PR","支持 gh 命令行工具","提供脚本运行检查"],"ja":["ローカルチェックの実行","PR タイトルと本文の作成","PR の自動開設","gh コマンドラインツールのサポート","スクリプト実行によるチェック"],"ko":["로컬 체크 실행","PR 제목 및 본문 생성","PR 자동 열기","gh 명령줄 도구 지원","스크립트 실행을 통한 체크"],"es":["Ejecuta comprobaciones de proyecto locales mediante scripts","Crea solicitudes de extracción con títulos y resúmenes claros","Utiliza gh para crear solicitudes de extracción de forma automática","Permite la autenticación con gh para una integración sin problemas","Soporta la ejecución de comprobaciones de proyecto en ramas de características"],"fr":["Exécute des vérifications de projet locales via des scripts","Crée des demandes d''extraction avec des titres et des résumés clairs","Utilise gh pour créer des demandes d''extraction de manière automatisée","Permet l''authentification avec gh pour une intégration sans problèmes","Prend en charge l''exécution de vérifications de projet sur des branches de fonctionnalités"],"de":["Führt Projektprüfungen lokal mittels Skripten aus","Erstellt Pull-Requests mit klaren Titeln und Zusammenfassungen","Verwendet gh, um Pull-Requests automatisch zu erstellen","Ermöglicht die Authentifizierung mit gh für eine reibungslose Integration","Unterstützt die Ausführung von Projektprüfungen auf Feature-Branches"],"pt":["Executa verificações de projeto locais via script em `scripts/`","Cria PRs com títulos e resumos claros usando modelo de template","Suporta autenticação com `gh` para criar PRs automaticamente","Fornece comando exato para o usuário executar manualmente se `gh` não estiver disponível","Integração com Lance para gerenciar ciclo de vida do contexto de agente multimodal"],"ru":["Выполняет локальные проверки проекта через скрипт в `scripts/`","Создаёт PR с ясными заголовками и описаниями, используя шаблон","Поддерживает аутентификацию с `gh` для автоматического создания PR","Предоставляет точную команду для ручного выполнения пользователем, если `gh` недоступен","Интегрируется с Lance для управления жизненным циклом контекста многомодального агента для ИИ Агентов"],"ar":["ينفذ التحقق التلقائي من مشروع عبر سكريبت في `scripts/`","ينشئ طلبات سحب مع عناوين وملخصات واضحة باستخدام نموذج قالب","يدعم المصادقة مع `gh` لإنشاء طلبات سحب تلقائية","يقدم الأمر الدقيق للتنفيذ اليدوي إذا لم يكن `gh` متاحًا","يتكامل مع Lance لإدارة دورة حياة سياق العامل المتعدد الوسائط"]},"keywords":{"en":["how to use ci-pr-helper","ci-pr-helper setup guide","what is ci-pr-helper","ci-pr-helper alternative","ci-pr-helper vs github actions","ci-pr-helper install","automated pr creation","lance agentic context lifecycle"],"zh":["CI PR Helper","代码检查","PR 创建","自动化","AI 工具","代码review","github pr","自动化测试"],"ja":["CI PR Helper","コードチェック","PR 作成","自動化","AI エージェント","コードレビュー","github pr","自動テスト"],"ko":["CI PR Helper","코드 검사","PR 생성","자동화","AI 도구","코드 리뷰","github pr","자동 테스트"],"es":["ci-pr-helper","herramientas de AI","gestión de contexto de agente multimodal","verificaciones de proyecto locales","solicitudes de extracción","gh","autenticación","integración","ramas de características"],"fr":["ci-pr-helper","outils d''IA","gestion du contexte d''agent multimodal","vérifications de projet locales","demandes d''extraction","gh","authentification","intégration","branches de fonctionnalités"],"de":["ci-pr-helper","AI-Tools","Verwaltung des multimodalen Agentenkontexts","Projektprüfungen lokal","Pull-Requests","gh","Authentifizierung","Integration","Feature-Branches"],"pt":["CI PR Helper","Lance","Agente Multimodal","Verificação de Projeto","Criação de PR","Automação de Desenvolvimento","Ferramentas de Desenvolvimento","Desenvolvimento de Software"],"ru":["CI PR Helper","Lance","Многомодальный Агент","Проверка Проекта","Создание PR","Автоматизация Разработки","Инструменты Разработки","Разработка Программного Обеспечения","ИИ Агенты"],"ar":["CI PR Helper","Lance","عامل متعدد الوسائط","التحقق من مشروع","إنشاء طلب سحب","التحكم الآلي في التطوير","أدوات التطوير","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"lance-format","repo":"lance-context","repoPath":"lance-format/lance-context","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.623Z","topics":[],"category":"community","skillMd":{"name":"ci-pr-helper","description":"Run local test/style checks and open GitHub PRs for lance-context. Use when asked to run CI-equivalent checks (uv pytest, ruff/pyright, cargo fmt/clippy/test) and then create a PR with a proper title/body.","bodyPreview":"# CI PR Helper\n\n## Overview\nRun project checks locally, then prepare and open a PR with a clear title and summary.\n\n## Workflow\n\n1. Ensure you are on a feature branch (not `main`).\n2. Run local checks via the script in `scripts/`.\n3. Draft a PR title/body using the template below.\n4. If `gh` is available and authenticated, run `gh pr create` yourself; otherwise, surface the exact command for the user to execute manually.\n\n## Local checks\n\nRun:\n\n```bash\n./.codex/skills/ci-pr-helper/scripts/run_ci","body":"# CI PR Helper\n\n## Overview\nRun project checks locally, then prepare and open a PR with a clear title and summary.\n\n## Workflow\n\n1. Ensure you are on a feature branch (not `main`).\n2. Run local checks via the script in `scripts/`.\n3. Draft a PR title/body using the template below.\n4. If `gh` is available and authenticated, run `gh pr create` yourself; otherwise, surface the exact command for the user to execute manually.\n\n## Local checks\n\nRun:\n\n```bash\n./.codex/skills/ci-pr-helper/scripts/run_ci_checks.sh\n```\n\nIf it fails due to missing tools, install `uv`, `cargo`, or Python deps, then rerun.\n\n## PR creation\n\nDraft a conventional title (e.g., `feat:`/`fix:`/`ci:`) and use:\n\n```\n## Summary\n- ...\n\n## Testing\n- uv run pytest\n- cargo test --manifest-path rust/lance-context/Cargo.toml\n- cargo fmt --manifest-path rust/lance-context/Cargo.toml -- --check\n- cargo clippy --manifest-path rust/lance-context/Cargo.toml --all-targets -- -D warnings\n- ruff format --check python/\n- ruff check python/\n- pyright\n```\n\nIf you need to check auth status, you may still run:\n\n```bash\ngh auth status\n```\n\nWhen ready:\n\n- If `gh` is ready to use, execute:\n\n```bash\ngh pr create --title \"<title>\" --body \"<body>\"\n```\n\n- Some environments emit a spurious `Unsupported subcommand ''pr''` warning before running\n  `gh`; ignore that message and continue with the command.\n\n- If `gh` is missing or fails, print the command instead so the user can run it locally.\n"},"lastSynced":"2026-03-08T02:13:31.514Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated project checks and PR preparation via GitHub CLI and local scripts.","zh":"非常适合需要通过 GitHub CLI 和本地脚本进行自动化项目检查和 PR 准备的开发代理。","ja":"GitHub CLI とローカルスクリプトを使用した自動化されたプロジェクトチェックと PR 准備が必要な開発エージェントに最適です。","ko":"GitHub CLI와 로컬 스크립트를 통해 자동화된 프로젝트 검사 및 PR 준비가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan comprobaciones de proyecto automatizadas y preparación de PR a través de GitHub CLI y scripts locales.","fr":"Parfait pour les Agents de Développement ayant besoin de vérifications de projet automatisées et de préparation de PR via GitHub CLI et scripts locaux.","de":"Perfekt für Entwicklungsmittel, die automatisierte Projektprüfungen und PR-Vorbereitung über GitHub CLI und lokale Skripte benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de verificações de projeto automatizadas e preparação de PR via GitHub CLI e scripts locais.","ru":"Идеально для агентов разработки, которым необходимы автоматические проверки проекта и подготовка PR через GitHub CLI и локальные скрипты.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى فحص المشروع التلقائي وإعداد طلبات السحب عبر واجهة سطر أوامر جيت هاب والسكريبتات المحلية."},"recommendation":{"en":"Empowers agents to automate project checks via local scripts, draft PR titles and bodies, and create PRs using the GitHub CLI, streamlining the development workflow with features like `gh pr create` and script execution from `scripts/`.","zh":"赋予代理人通过本地脚本自动化项目检查、草拟 PR 标题和正文，并使用 GitHub CLI 创建 PR 的能力，通过诸如 `gh pr create` 和从 `scripts/` 执行脚本等功能来简化开发工作流程。","ja":"ローカルスクリプトを使用したプロジェクトの自動化チェック、事前定義されたテンプレートを使用した PR タイトルと本文の作成、GitHub CLI を使用した PR の作成など、`gh pr create` や `scripts/` からのスクリプトの実行などの機能で開発ワークフローを簡素化するエージェントの能力を付与します。","ko":"로컬 스크립트를 사용한 프로젝트 자동화 검사, 미리 정의된 템플릿을 사용한 PR 제목 및 본문 작성, GitHub CLI를 사용한 PR 생성 등 `gh pr create` 및 `scripts/`에서 스크립트 실행과 같은 기능을 통해 개발 워크플로우를 간소화하는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a automatizar las comprobaciones de proyecto a través de scripts locales, a redactar títulos y cuerpos de PR y a crear PR utilizando GitHub CLI, optimizando el flujo de trabajo de desarrollo con características como `gh pr create` y la ejecución de scripts desde `scripts/`.","fr":"Permet aux agents d''automatiser les vérifications de projet via des scripts locaux, de rédiger des titres et des corps de PR et de créer des PR en utilisant GitHub CLI, en rationalisant le flux de travail de développement avec des fonctionnalités comme `gh pr create` et l''exécution de scripts depuis `scripts/`.","de":"Ermöglicht es Agenten, Projektprüfungen über lokale Skripte zu automatisieren, PR-Titel und -Inhalte mit vordefinierten Vorlagen zu entwerfen und PRs mit klaren Zusammenfassungen über GitHub CLI zu erstellen, wodurch der Entwicklungsworkflow mit Funktionen wie `gh pr create` und Skriptausführung aus `scripts/` optimiert wird.","pt":"Habilita os agentes a automatizar as verificações de projeto por meio de scripts locais, redigir títulos e corpos de PR e criar PRs usando o GitHub CLI, otimizando o fluxo de trabalho de desenvolvimento com recursos como `gh pr create` e execução de script a partir de `scripts/`.","ru":"Позволяет агентам автоматизировать проверки проекта с помощью локальных скриптов, создавать заголовки и описания PR, а также создавать PR с помощью GitHub CLI, оптимизируя процесс разработки с помощью функций như `gh pr create` и выполнение скриптов из `scripts/`.","ar":"يمكن للوكلاء من خلاله تلقين فحص المشروع بواسطة السكريبتات المحلية، وكتابة أسماء وشرح طلبات السحب، وخلق طلبات السحب باستخدام واجهة سطر أوامر جيت هاب، وبتصميم تدفق العمل التنموي باستخدام ميزات مثل `gh pr create` وتنفيذ السكريبتات من `scripts/`."},"useCases":{"en":["Automating project checks on feature branches","Drafting PR titles and bodies using predefined templates","Creating PRs with clear summaries using GitHub CLI"],"zh":["在功能分支上自动化项目检查","使用预定义模板草拟 PR 标题和正文","使用 GitHub CLI 创建具有清晰摘要的 PR"],"ja":["機能ブランチ上でのプロジェクトの自動化チェック","事前定義されたテンプレートを使用した PR タイトルと本文の作成","GitHub CLI を使用した明確なサマリーを持つ PR の作成"],"ko":["기능 분기에서 프로젝트 자동화 검사","미리 정의된 템플릿을 사용한 PR 제목 및 본문 작성","GitHub CLI를 사용한 명확한 요약을 가진 PR 생성"],"es":["Automatización de comprobaciones de proyecto en ramas de características","Redacción de títulos y cuerpos de PR utilizando plantillas predefinidas","Creación de PR con resúmenes claros utilizando GitHub CLI"],"fr":["Automatisation des vérifications de projet sur des branches de fonctionnalités","Rédaction de titres et de corps de PR en utilisant des modèles préétablis","Création de PR avec des résumés clairs en utilisant GitHub CLI"],"de":["Automatisierung von Projektprüfungen auf Funktionszweigen","Entwurf von PR-Titeln und -Inhalten unter Verwendung von vordefinierten Vorlagen","Erstellung von PR mit klaren Zusammenfassungen über GitHub CLI"],"pt":["Automatizar verificações de projeto em branches de recurso","Redigir títulos e corpos de PR usando modelos predefinidos","Criar PRs com resumos claros usando o GitHub CLI"],"ru":["Автоматизация проверок проекта на фиче-бранчах","Создание заголовков и описаний PR с помощью заранее определенных шаблонов","Создание PR с четкими сводками с помощью GitHub CLI"],"ar":["تلقين فحص المشروع على فروع الميزة","كتابة أسماء وشرح طلبات السحب باستخدام قوالب محددة مسبقا","خلق طلبات السحب مع ملخصات واضحة باستخدام واجهة سطر أوامر جيت هاب"]},"limitations":{"en":["Requires GitHub CLI availability and authentication","Needs execution on a feature branch (not main)"],"zh":["需要 GitHub CLI 的可用性和身份验证","需要在功能分支（而不是主分支）上执行"],"ja":["GitHub CLI の可用性と認証が必要","機能ブランチ（メインブランチではない）上での実行が必要"],"ko":["GitHub CLI의 가용성 및 인증이 필요","기능 분기(메인 분기가 아님)에서 실행이 필요"],"es":["Requiere disponibilidad y autenticación de GitHub CLI","Requiere ejecución en una rama de características (no en la rama principal)"],"fr":["Nécessite la disponibilité et l''authentification de GitHub CLI","Nécessite l''exécution sur une branche de fonctionnalités (et non sur la branche principale)"],"de":["Benötigt die Verfügbarkeit und Authentifizierung von GitHub CLI","Benötigt die Ausführung auf einem Funktionszweig (nicht auf dem Hauptzweig)"],"pt":["Exige a disponibilidade e autenticação do GitHub CLI","Necessita de execução em uma branch de recurso (não main)"],"ru":["Требует наличия и аутентификации GitHub CLI","Требует выполнения на фиче-бранче (не на основном)"],"ar":["يتطلب توافر وتحقق واجهة سطر أوامر جيت هاب","يحتاج إلى التنفيذ على فرع الميزة (ليس الرئيسي)"]},"version":4},"contentHash":"7a83548716dd9cf598fa9f7a8230f997d3fb09abe498deafcb2036910b05a926","qualityScore":36}');
