INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lance-format/lance-context/ci-pr-helper', 'ci-pr-helper', 'lance-format', 'lance-context', 'community', 'ci-pr-helper lance-format lance-context community The ci-pr-helper skill manages multimodal agentic context lifecycle with Lance, benefiting developers by automating project checks and PR preparation. It runs local checks via scripts and drafts PR titles and bodies. CI PR Helper 是一个自动化代码检查和 PR 创建的工具，帮助开发者提高效率。它支持运行本地检查、创建 PR 标题和正文，并自动打开 PR CI PR Helper はコードチェックと PR 作成を自動化するツールで、開発者の効率を向上させます。ローカルチェックの実行、PR タイトルと本文の作成、PR の自動開設をサポートします CI PR Helper는 코드 검사와 PR 생성을 자동화하는 도구로 개발자의 효율성을 높여줍니다. 로컬 체크 실행, PR 제목 및 본문 생성, PR 자동 열기를 지원합니다 El agente ci-pr-helper gestiona el ciclo de vida del contexto de agente multimodal con Lance, ejecutando comprobaciones de proyecto locales y preparando solicitudes de extracción L''agent ci-pr-helper gère le cycle de vie du contexte d''agent multimodal avec Lance, en exécutant des vérifications de projet locales et en préparant des demandes d''extraction Der Agent ci-pr-helper verwaltet den Lebenszyklus des multimodalen Agentenkontexts mit Lance, indem er Projektprüfungen lokal ausführt und Pull-Requests vorbereitet O CI PR Helper é uma ferramenta que ajuda a gerenciar o ciclo de vida do contexto de agente multimodal com Lance CI PR Helper - это инструмент, помогающий управлять жизненным циклом контекста многомодального агента с помощью Lance для ИИ Агентов CI PR Helper هو أداة تساعد في إدارة دورة حياة سياق العامل المتعدد الوسائط مع Lance how to use ci-pr-helper ci-pr-helper setup guide what is ci-pr-helper ci-pr-helper alternative ci-pr-helper vs github actions ci-pr-helper install automated pr creation lance agentic context lifecycle CI PR Helper 代码检查 PR 创建 自动化 AI 工具 代码review github pr 自动化测试 Runs local checks via the script in scripts/ Drafts PR title and body using a predefined template Creates pull requests using the gh pr create command Surfaces the exact command for manual execution if gh is not available Ensures feature branch checks before PR creation ci-pr-helper is a skill that automates the process of running local checks, drafting PR titles and bodies, and creating pull requests using the gh command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nikolay-Shirokov/cc-1c-skills/role-compile', 'community', 'Nikolay-Shirokov', 'cc-1c-skills', 'Nikolay-Shirokov/cc-1c-skills', 'role-compile', 0, 0, 36, '2026-03-08T01:57:15.635Z', '2026-03-08T02:13:37.273Z', 'd93afdee75ae25a05d76f4f5850a8ba6dac621d804f8ab8a5d39a4f945cd80ce', '{"id":"Nikolay-Shirokov/cc-1c-skills/role-compile","name":"role-compile","description":{"en":"The role-compile skill generates 1C:Enterprise roles from JSON definitions, creating Roles/Имя.xml and Roles/Имя/Ext/Rights.xml files with automated UUIDs, benefiting 1C:Enterprise developers.","zh":"role-compile技能用于生成1C企业开发的角色元数据和权限，通过JSON DSL定义角色","ja":"role-compileスキルは、JSON DSLでロールを定義して、1C Enterprise開発のロールメタデータと権限を生成するために使用されます。","ko":"role-compile 스킬은 JSON DSL로 역할을 정의하여 1C 엔터프라이즈 개발의 역할 메타데이터와 권한을 생성하는 데 사용됩니다.","es":"Role-compile es una habilidad de Claude Code que genera roles en 1C:Enterprise a partir de definiciones JSON","fr":"Role-compile est une compétence de Claude Code qui génère des rôles dans 1C:Enterprise à partir de définitions JSON","de":"Role-compile ist eine Fähigkeit von Claude Code, die Rollen in 1C:Enterprise aus JSON-Definitionen generiert","pt":"O role-compile é uma habilidade do Claude Code que gera metadados e direitos para desenvolvimento 1C:Enterprise a partir de JSON DSL.","ru":"Role-compile — это навык Claude Code, который генерирует метаданные и права для разработки 1С:Предприятие из JSON DSL с ИИ Агентами.","ar":"role-compile هو مهارة من Claude Code التي تولد البيانات الوصفية والصلاحيات لتنمية 1C:Enterprise من JSON DSL مع أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"role-compile: Automated 1C:Enterprise Role Generation | A...","zh":"role-compile_SETUP GUIDE：1C企业开发JSON DSL生成","ja":"role-compile セットアップガイド: 1C Enterprise開発用JSON DSL生成","ko":"role-compile 설정 가이드: 1C 엔터프라이즈 개발을 위한 JSON DSL 생성","es":"Guía de configuración de role-compile para 1C:Enterprise","fr":"Guide de démarrage de role-compile pour 1C:Enterprise","de":"Einrichtungsleitfaden für role-compile in 1C:Enterprise","pt":"role-compile: Guia de Configuração para Desenvolvimento 1...","ru":"role-compile: Руководство по настройке для разработки 1С:...","ar":"role-compile: دليل الإعداد لتنمية 1C:Enterprise مع أدوات ..."},"description":{"en":"Discover how role-compile streamlines 1C:Enterprise development with automated role generation from JSON DSL. Learn more and get started today!","zh":"使用role-compile技能生成1C企业开发的角色元数据和权限，自动创建UUID","ja":"role-compileスキルを使用して、1C Enterprise開発のロールメタデータと権限を生成します。UUIDは自動的に作成されます。","ko":"role-compile 스킬을 사용하여 1C 엔터프라이즈 개발의 역할 메타데이터와 권한을 생성하고 UUID를 자동으로 생성합니다.","es":"Aprende a utilizar role-compile para generar roles en 1C:Enterprise desde definiciones JSON","fr":"Découvrez comment utiliser role-compile pour générer des rôles dans 1C:Enterprise à partir de définitions JSON","de":"Erfahren Sie, wie Sie role-compile verwenden, um Rollen in 1C:Enterprise aus JSON-Definitionen zu generieren","pt":"Aprenda a configurar o role-compile para desenvolvimento 1C:Enterprise com JSON DSL e geração de metadados","ru":"Узнайте, как настроить role-compile для разработки 1С:Предприятие с помощью JSON DSL и генерации метаданных с ИИ Агентами","ar":"تعلم كيفية تكوين role-compile لتنمية 1C:Enterprise مع JSON DSL وإنشاء البيانات الوصفية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"role-compile is a Claude Code skill for automated generation of 1C:Enterprise roles from JSON DSL definitions.","zh":"role-compile是1C企业开发的AI工具，用于生成角色元数据和权限","ja":"role-compileは、1C Enterprise開発のAIエージェントであり、ロールメタデータと権限を生成するために使用されます。","ko":"role-compile은 1C 엔터프라이즈 개발의 AI 에이전트로서 역할 메타데이터와 권한을 생성하는 데 사용됩니다.","es":"Role-compile es una herramienta de inteligencia artificial que genera roles en 1C:Enterprise","fr":"Role-compile est un outil d''intelligence artificielle qui génère des rôles dans 1C:Enterprise","de":"Role-compile ist ein KI-Tool, das Rollen in 1C:Enterprise generiert","pt":"O que é role-compile? É uma habilidade que gera metadados e direitos para desenvolvimento 1C:Enterprise.","ru":"Что такое role-compile? Это навык, который генерирует метаданные и права для разработки 1С:Предприятие.","ar":"ما هو role-compile? هو مهارة تولد البيانات الوصفية والصلاحيات لتنمية 1C:Enterprise."},"features":{"en":["Generates Roles/Имя.xml metadata files from JSON definitions","Creates Roles/Имя/Ext/Rights.xml files for role permissions","Automatically assigns UUIDs to generated roles","Accepts JSONPath and RolesDir parameters for customization","Utilizes PowerShell scripting for role compilation"],"zh":["生成1C企业开发的角色元数据","生成角色权限","自动创建UUID","支持JSON DSL定义角色","使用PowerShell脚本执行"],"ja":["1C Enterprise開発のロールメタデータを生成","ロール権限を生成","UUIDを自動的に作成","JSON DSLでロールを定義","PowerShellスクリプトを使用して実行"],"ko":["1C 엔터프라이즈 개발의 역할 메타데이터 생성","역할 권한 생성","UUID 자동 생성","JSON DSL로 역할 정의","PowerShell 스크립트를 사용하여 실행"],"es":["Generación de roles en 1C:Enterprise a partir de definiciones JSON","Compatibilidad con PowerShell para ejecución de scripts","Generación automática de UUID","Soporte para metadatos y derechos de acceso","Integración con la configuración de 1C:Enterprise"],"fr":["Génération de rôles dans 1C:Enterprise à partir de définitions JSON","Compatibilité avec PowerShell pour l''exécution de scripts","Génération automatique d''UUID","Prise en charge des métadonnées et des droits d''accès","Intégration avec la configuration de 1C:Enterprise"],"de":["Generierung von Rollen in 1C:Enterprise aus JSON-Definitionen","Kompatibilität mit PowerShell für die Ausführung von Skripten","Automatische Generierung von UUID","Unterstützung für Metadaten und Zugriffsrechte","Integration mit der Konfiguration von 1C:Enterprise"],"pt":["Geração de metadados a partir de JSON DSL","Criação de direitos para desenvolvimento 1C:Enterprise","Suporte a UUID automático","Integração com PowerShell para execução de scripts","Geração de arquivos `Roles/Имя.xml` e `Roles/Имя/Ext/Rights.xml`"],"ru":["Генерация метаданных из JSON DSL","Создание прав для разработки 1С:Предприятие","Поддержка автоматического UUID","Интеграция с PowerShell для выполнения скриптов","Генерация файлов `Roles/Имя.xml` и `Roles/Имя/Ext/Rights.xml` с ИИ Агентами"],"ar":["генерация البيانات الوصفية من JSON DSL","إنشاء الصلاحيات لتنمية 1C:Enterprise","دعم UUID التلقائي","التكامل مع PowerShell لتنفيذ البرامج النصية","генерация الملفات `Roles/Имя.xml` و `Roles/Имя/Ext/Rights.xml` مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use role-compile","role-compile setup guide","1C:Enterprise role generation","JSON DSL role definition","role-compile alternative","role-compile vs manual role creation","automated role generation","role-compile install","Claude Code skills for 1C:Enterprise"],"zh":["role-compile","1C企业开发","JSON DSL","角色元数据","权限生成","AI工具","PowerShell脚本"],"ja":["role-compile","1C Enterprise開発","JSON DSL","ロールメタデータ","権限生成","AIエージェント","PowerShellスクリプト"],"ko":["role-compile","1C 엔터프라이즈 개발","JSON DSL","역할 메타데이터","권한 생성","AI 에이전트","PowerShell 스크립트"],"es":["role-compile","1C:Enterprise","generación de roles","definiciones JSON","PowerShell","UUID","metadatos","derechos de acceso","herramientas de inteligencia artificial"],"fr":["role-compile","1C:Enterprise","génération de rôles","définitions JSON","PowerShell","UUID","métadonnées","droits d''accès","outils d''intelligence artificielle"],"de":["role-compile","1C:Enterprise","Rollen generierung","JSON-Definitionen","PowerShell","UUID","Metadaten","Zugriffsrechte","KI-Tools"],"pt":["role-compile","desenvolvimento 1C:Enterprise","JSON DSL","metadados","direitos","UUID automático","PowerShell","Claude Code"],"ru":["role-compile","разработка 1С:Предприятие","JSON DSL","метаданные","права","автоматический UUID","PowerShell","ИИ Агенты","Claude Code"],"ar":["role-compile","تنمية 1C:Enterprise","JSON DSL","البيانات الوصفية","الصلاحيات","UUID التلقائي","PowerShell","أدوات الذكاء الاصطناعي","Claude Code"]}},"owner":"Nikolay-Shirokov","repo":"cc-1c-skills","repoPath":"Nikolay-Shirokov/cc-1c-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.635Z","topics":[],"category":"community","skillMd":{"name":"role-compile","description":"Создание роли 1С из описания прав. Используй когда нужно создать новую роль с набором прав на объекты","bodyPreview":"# /role-compile — генерация роли 1С из JSON DSL\r\n\r\nПринимает JSON-определение роли → генерирует `Roles/Имя.xml` (метаданные) и `Roles/Имя/Ext/Rights.xml` (права). UUID автоматически.\r\n\r\n## Параметры и команда\r\n\r\n| Параметр | Описание |\r\n|----------|----------|\r\n| `JsonPath` | Путь к JSON-определению роли |\r\n| `RolesDir` | Каталог `Roles/` в исходниках конфигурации |\r\n\r\n```powershell\r\npowershell.exe -NoProfile -File .claude/skills/role-compile/scripts/role-compile.ps1 -JsonPath \"<json>\" -OutputDi","body":"# /role-compile — генерация роли 1С из JSON DSL\r\n\r\nПринимает JSON-определение роли → генерирует `Roles/Имя.xml` (метаданные) и `Roles/Имя/Ext/Rights.xml` (права). UUID автоматически.\r\n\r\n## Параметры и команда\r\n\r\n| Параметр | Описание |\r\n|----------|----------|\r\n| `JsonPath` | Путь к JSON-определению роли |\r\n| `RolesDir` | Каталог `Roles/` в исходниках конфигурации |\r\n\r\n```powershell\r\npowershell.exe -NoProfile -File .claude/skills/role-compile/scripts/role-compile.ps1 -JsonPath \"<json>\" -OutputDir \"<RolesDir>\"\r\n```\r\n\r\n`<Role>ИмяРоли</Role>` автоматически добавляется в `<ChildObjects>` файла `Configuration.xml` (ожидается в parent от `RolesDir`).\r\n\r\n## JSON DSL\r\n\r\n### Структура\r\n\r\n```json\r\n{ \"name\": \"ИмяРоли\", \"synonym\": \"Отображаемое имя\", \"objects\": [...], \"templates\": [...] }\r\n```\r\n\r\nНеобязательные: `comment` (\"\"), `setForNewObjects` (false), `setForAttributesByDefault` (true), `independentRightsOfChildObjects` (false).\r\n\r\n### Shorthand-строки и объектная форма\r\n\r\n```json\r\n\"objects\": [\r\n  \"Catalog.Номенклатура: @view\",\r\n  \"Document.Реализация: @edit\",\r\n  \"DataProcessor.Загрузка: @view\",\r\n  \"InformationRegister.Цены: Read, Update\",\r\n  { \"name\": \"Document.Продажа\", \"preset\": \"view\", \"rights\": {\"Delete\": false}, \"rls\": {\"Read\": \"#Шаблон(\\\"\\\")\"} }\r\n]\r\n```\r\n\r\n- Shorthand: `\"Тип.Имя: @пресет\"` или `\"Тип.Имя: Право1, Право2\"`\r\n- Объектная форма: `preset` + `rights` (переопределения) + `rls` (ограничения)\r\n\r\n### Пресеты\r\n\r\n| Пресет | Действие |\r\n|--------|----------|\r\n| `@view` | Просмотр — Read, View (+InputByString для справочников/документов; Use+View для обработок/отчётов) |\r\n| `@edit` | Полное редактирование — CRUD + Interactive* + Posting (документы) |\r\n\r\n`@` обязателен в shorthand. В объектной форме — `\"preset\": \"view\"` без `@`.\r\n\r\nДля сервисов (WebService, HTTPService, IntegrationService) пресеты не определены — используй явные права: `\"WebService.Имя: Use\"`.\r\n\r\n### Русские синонимы\r\n\r\nПоддерживаются русские типы (`Справочник`→Catalog, `Документ`→Document) и права (`Чтение`→Read, `Просмотр`→View). Смешивание допустимо: `\"Справочник.Контрагенты: Чтение, View\"`.\r\n\r\n### Шаблоны RLS\r\n\r\n```json\r\n\"templates\": [{\"name\": \"ДляОбъекта(Мод)\", \"condition\": \"ГДЕ Организация = &ТекОрг\"}]\r\n```\r\n\r\nСсылка в `rls`: `\"#ДляОбъекта(\\\"\\\")\"`. Символ `&` автоматически экранируется в XML.\r\n\r\n## Примеры\r\n\r\n### Простая роль\r\n\r\n```json\r\n{\r\n  \"name\": \"ЧтениеНоменклатуры\", \"synonym\": \"Чтение номенклатуры\",\r\n  \"objects\": [\"Catalog.Номенклатура: @view\", \"Catalog.Контрагенты: @view\", \"DataProcessor.Загрузка: @view\"]\r\n}\r\n```\r\n\r\n### Роль с RLS\r\n\r\n```json\r\n{\r\n  \"name\": \"ЧтениеДокументовПоОрганизации\",\r\n  \"synonym\": \"Чтение документов (ограничение по организации)\",\r\n  \"objects\": [\r\n    \"Catalog.Организации: @view\",\r\n    {\"name\": \"Document.РеализацияТоваровУслуг\", \"preset\": \"view\", \"rls\": {\"Read\": \"#ДляОбъекта(\\\"\\\")\"}}\r\n  ],\r\n  \"templates\": [{\"name\": \"ДляОбъекта(Модификатор)\", \"condition\": \"ГДЕ Организация = &ТекущаяОрганизация\"}]\r\n}\r\n```\r\n\r\nПодробные таблицы пресетов, русских синонимов и дополнительные примеры — в `dsl-reference.md`.\r\n\r\n## Верификация\r\n\r\n```\r\n/role-validate <RightsPath> [MetadataPath]  — проверка корректности XML, прав, RLS\r\n/role-info <RightsPath>                     — визуальная сводка структуры\r\n```\r\n"},"lastSynced":"2026-03-08T02:13:37.273Z","agentAnalysis":{"suitability":{"en":"Perfect for 1C:Enterprise Development Agents needing automated role generation from JSON definitions.","zh":"非常适合需要从JSON定义自动生成角色的一体化企业开发代理。","ja":"1C:Enterprise Development AgentsがJSON定義から自動的にロールを生成する必要がある場合は、こちらが最適です。","ko":"JSON 정의에서 자동으로 역할을 생성해야 하는 1C:Enterprise 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de 1C:Enterprise que necesitan generación de roles automatizada a partir de definiciones JSON.","fr":"Parfait pour les agents de développement 1C:Enterprise nécessitant une génération de rôles automatisée à partir de définitions JSON.","de":"Perfekt für 1C:Enterprise-Entwicklungsagenten, die eine automatisierte Rollenerzeugung aus JSON-Definitionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento 1C:Enterprise que necessitam de geração automática de funções a partir de definições JSON.","ru":"Идеально подходит для агентов разработки 1C:Enterprise, которым требуется автоматическая генерация ролей из JSON-определений.","ar":"مثالي لعمليات تطوير 1C:Enterprise التي تحتاج إلى توليد دور تلقائي من التعريفات JSON."},"recommendation":{"en":"Empowers agents to generate 1C:Enterprise roles from JSON DSL, creating Roles/Имя.xml and Roles/Имя/Ext/Rights.xml files with automated UUIDs, utilizing PowerShell scripting for seamless integration.","zh":"赋予代理从JSON DSL生成一体化企业角色，创建Roles/Имя.xml和Roles/Имя/Ext/Rights.xml文件，自动生成UUID，利用PowerShell脚本实现无缝集成。","ja":"エージェントがJSON DSLから1C:Enterpriseロールを生成できるようにし、Roles/Имя.xmlおよびRoles/Имя/Ext/Rights.xmlファイルを作成し、自動でUUIDを生成し、PowerShellスクリプティングを使用してシームレスに統合します。","ko":"에이전트가 JSON DSL에서 1C:Enterprise 역할을 생성할 수 있도록 하여 Roles/Имя.xml 및 Roles/Имя/Ext/Rights.xml 파일을 생성하고 UUID를 자동으로 생성하며 PowerShell 스크립팅을 사용하여 무중단 통합을 구현합니다.","es":"Habilita a los agentes para generar roles de 1C:Enterprise a partir de JSON DSL, creando archivos Roles/Имя.xml y Roles/Имя/Ext/Rights.xml con UUIDs automatizados, utilizando scripting de PowerShell para una integración sin problemas.","fr":"Permet aux agents de générer des rôles 1C:Enterprise à partir de JSON DSL, en créant des fichiers Roles/Имя.xml et Roles/Имя/Ext/Rights.xml avec des UUID automatiques, en utilisant un scripting PowerShell pour une intégration transparente.","de":"Ermöglicht es Agenten, 1C:Enterprise-Rollen aus JSON-DSL zu generieren, indem Dateien wie Roles/Имя.xml und Roles/Имя/Ext/Rights.xml mit automatisierten UUIDs erstellt werden, wobei PowerShell-Skripting für eine nahtlose Integration verwendet wird.","pt":"Habilita os agentes a gerar funções 1C:Enterprise a partir de JSON DSL, criando arquivos Roles/Имя.xml e Roles/Имя/Ext/Rights.xml com UUIDs automatizados, utilizando script PowerShell para integração sem interrupções.","ru":"Наделяет агентов возможностью генерировать роли 1C:Enterprise из JSON DSL, создавая файлы Roles/Имя.xml и Roles/Имя/Ext/Rights.xml с автоматическими UUID, используя скрипты PowerShell для бесшовной интеграции.","ar":"يسمح للعميل بتوليد أدوار 1C:Enterprise من JSON DSL، بخلق ملفات Roles/Имя.xml و Roles/Имя/Ext/Rights.xml مع UUIDs آلية، باستخدام سكربتات PowerShell لتكامل دون انقطاع."},"useCases":{"en":["Automating role creation for 1C:Enterprise developers","Generating Roles/Имя.xml and Roles/Имя/Ext/Rights.xml files from JSON definitions","Streamlining 1C:Enterprise configuration setup with automated UUID generation"],"zh":["为1C:Enterprise开发者自动创建角色","从JSON定义生成Roles/Имя.xml和Roles/Имя/Ext/Rights.xml文件","使用自动UUID生成简化1C:Enterprise配置设置"],"ja":["1C:Enterprise開発者のロール自動作成","JSON定義からRoles/Имя.xmlおよびRoles/Имя/Ext/Rights.xmlファイルを生成","自動UUID生成を使用した1C:Enterprise構成設定の簡素化"],"ko":["1C:Enterprise 개발자를 위한 자동 역할 생성","JSON 정의에서 Roles/Имя.xml 및 Roles/Имя/Ext/Rights.xml 파일 생성","자동 UUID 생성을 사용한 1C:Enterprise 구성 설정 단순화"],"es":["Automatización de la creación de roles para desarrolladores de 1C:Enterprise","Generación de archivos Roles/Имя.xml y Roles/Имя/Ext/Rights.xml a partir de definiciones JSON","Optimización de la configuración de 1C:Enterprise con generación automática de UUID"],"fr":["Automatisation de la création de rôles pour les développeurs 1C:Enterprise","Génération de fichiers Roles/Имя.xml et Roles/Имя/Ext/Rights.xml à partir de définitions JSON","Optimisation de la configuration 1C:Enterprise avec génération automatique d''UUID"],"de":["Automatisierung der Rollenerstellung für 1C:Enterprise-Entwickler","Erstellung von Dateien wie Roles/Имя.xml und Roles/Имя/Ext/Rights.xml aus JSON-Definitionen","Optimierung der 1C:Enterprise-Konfiguration mit automatisierter UUID-Generierung"],"pt":["Automatizar a criação de funções para desenvolvedores 1C:Enterprise","Gerar arquivos Roles/Имя.xml e Roles/Имя/Ext/Rights.xml a partir de definições JSON","Simplificar a configuração do 1C:Enterprise com geração automática de UUID"],"ru":["Автоматизировать создание ролей для разработчиков 1C:Enterprise","Генерировать файлы Roles/Имя.xml и Roles/Имя/Ext/Rights.xml из JSON-определений","Упростить настройку 1C:Enterprise с автоматической генерацией UUID"],"ar":["تأتمتة إنشاء الأدوار لمطوري 1C:Enterprise","توليد ملفات Roles/Имя.xml و Roles/Имя/Ext/Rights.xml من التعريفات JSON","تبسيط إعداد 1C:Enterprise بتوليد UUID آلي"]},"limitations":{"en":["Requires PowerShell execution environment","1C:Enterprise specific","JSON definition file required"],"zh":["需要PowerShell执行环境","特定于1C:Enterprise","需要JSON定义文件"],"ja":["PowerShell実行環境が必要","1C:Enterprise専用","JSON定義ファイルが必要"],"ko":["PowerShell 실행 환경 필요","1C:Enterprise 전용","JSON 정의 파일 필요"],"es":["Requiere un entorno de ejecución de PowerShell","Específico de 1C:Enterprise","Se requiere un archivo de definición JSON"],"fr":["Nécessite un environnement d''exécution PowerShell","Spécifique à 1C:Enterprise","Un fichier de définition JSON est requis"],"de":["Benötigt eine PowerShell-Ausführungsumgebung","Spezifisch für 1C:Enterprise","Ein JSON-Definitionsdatei ist erforderlich"],"pt":["Requer ambiente de execução PowerShell","Específico do 1C:Enterprise","Arquivo de definição JSON necessário"],"ru":["Требуется среда выполнения PowerShell","Специфичный для 1C:Enterprise","Требуется файл определения JSON"],"ar":["يتطلب بيئة تشغيل PowerShell","محدد لعمليات 1C:Enterprise","مطلوب ملف تعريف JSON"]},"version":4},"contentHash":"d93afdee75ae25a05d76f4f5850a8ba6dac621d804f8ab8a5d39a4f945cd80ce","qualityScore":36}');
