INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nikolay-Shirokov/cc-1c-skills/role-compile', 'role-compile', 'Nikolay-Shirokov', 'cc-1c-skills', 'community', 'role-compile Nikolay-Shirokov cc-1c-skills community The role-compile skill generates 1C:Enterprise roles from JSON definitions, creating Roles/Имя.xml and Roles/Имя/Ext/Rights.xml files with automated UUIDs, benefiting 1C:Enterprise developers. role-compile技能用于生成1C企业开发的角色元数据和权限，通过JSON DSL定义角色 role-compileスキルは、JSON DSLでロールを定義して、1C Enterprise開発のロールメタデータと権限を生成するために使用されます。 role-compile 스킬은 JSON DSL로 역할을 정의하여 1C 엔터프라이즈 개발의 역할 메타데이터와 권한을 생성하는 데 사용됩니다. Role-compile es una habilidad de Claude Code que genera roles en 1C:Enterprise a partir de definiciones JSON Role-compile est une compétence de Claude Code qui génère des rôles dans 1C:Enterprise à partir de définitions JSON Role-compile ist eine Fähigkeit von Claude Code, die Rollen in 1C:Enterprise aus JSON-Definitionen generiert O role-compile é uma habilidade do Claude Code que gera metadados e direitos para desenvolvimento 1C:Enterprise a partir de JSON DSL. Role-compile — это навык Claude Code, который генерирует метаданные и права для разработки 1С:Предприятие из JSON DSL с ИИ Агентами. role-compile هو مهارة من Claude Code التي تولد البيانات الوصفية والصلاحيات لتنمية 1C:Enterprise من JSON DSL مع أدوات الذكاء الاصطناعي. how to use role-compile role-compile setup guide 1C:Enterprise role generation JSON DSL role definition role-compile alternative role-compile vs manual role creation automated role generation role-compile install Claude Code skills for 1C:Enterprise role-compile 1C企业开发 JSON DSL 角色元数据 权限生成 AI工具 PowerShell脚本 Generates Roles/Имя.xml metadata files from JSON definitions Creates Roles/Имя/Ext/Rights.xml files for role permissions Automatically assigns UUIDs to generated roles Accepts JSONPath and RolesDir parameters for customization Utilizes PowerShell scripting for role compilation role-compile is a Claude Code skill for automated generation of 1C:Enterprise roles from JSON DSL definitions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aehrc/pathling/fhir-api', 'community', 'aehrc', 'pathling', 'aehrc/pathling', 'fhir-api', 0, 0, 36, '2026-03-08T01:57:15.638Z', '2026-03-08T02:13:39.490Z', '5ec4f887506c74dc0dad984343747526ed812bc07567c061037c408dbaef5dda', '{"id":"aehrc/pathling/fhir-api","name":"fhir-api","description":{"en":"The fhir-api skill provides guidance for implementing FHIR RESTful APIs according to the HL7 FHIR specification, benefiting developers and data analysts in the healthcare industry.","zh":"FHIR API 是一个基于 Apache Spark 的工具，用于简化数据分析中的 FHIR 和临床术语使用。它提供了 FHIR RESTful API 的实现指导","ja":"FHIR API は、データ分析における FHIR と臨床用語の使用を簡素化する Apache Spark ベースのツールです。FHIR RESTful API の実装ガイドを提供します","ko":"FHIR API는 데이터 분석에서 FHIR 및 임상 용어 사용을 단순화하는 Apache Spark 기반 도구입니다. FHIR RESTful API 구현 가이드를 제공합니다","es":"La habilidad FHIR API proporciona herramientas para utilizar FHIR y terminología clínica en análisis de datos con Apache Spark","fr":"La compétence FHIR API fournit des outils pour utiliser FHIR et la terminologie clinique dans l''analyse de données avec Apache Spark","de":"Die FHIR-API-Fähigkeit bietet Tools, um FHIR und klinische Terminologie in Data Analytics mit Apache Spark zu verwenden","pt":"A FHIR API é uma ferramenta para análise de dados clínicos com Apache Spark. Fornece implementação de API RESTful de acordo com a especificação HL7 FHIR.","ru":"FHIR API - это инструмент для анализа клинических данных с помощью Apache Spark. Он предоставляет реализацию RESTful API в соответствии со спецификацией HL7 FHIR.","ar":"واجهة برمجة تطبيقات FHIR هي أداة لتحليل البيانات السريرية مع Apache Spark. توفر تنفيذ واجهة برمجة تطبيقات RESTful وفقًا لمواصفات HL7 FHIR."},"seo":{"title":{"en":"fhir-api: FHIR REST API Implementation Guide | AI Agent S...","zh":"FHIR API 设置指南：Apache Spark 集成","ja":"FHIR API 導入ガイド：Apache Spark を使用した実装","ko":"FHIR API 설정 가이드: Apache Spark 통합","es":"Guía de configuración de FHIR API para análisis de datos","fr":"Guide de mise en œuvre de FHIR API pour l''analyse de données","de":"Einrichtungsleitfaden für FHIR API in Data Analytics","pt":"Guia de Implementação FHIR API para Desenvolvedores","ru":"Настройка FHIR API: Руководство для ИИ Агентов","ar":"دليل تنفيذ واجهة برمجة تطبيقات FHIR للاستفادة من أدوات ال..."},"description":{"en":"Unlock efficient healthcare data analytics with fhir-api. Learn how to implement FHIR RESTful APIs and leverage Apache Spark for seamless clinical terminolog...","zh":"了解如何使用 FHIR API 和 Apache Spark 进行数据分析，并发现关键功能和技术细节","ja":"FHIR API と Apache Spark を使用したデータ分析の実装方法を学び、重要な機能と技術的詳細を発見","ko":"FHIR API와 Apache Spark를 사용한 데이터 분석 구현 방법을学习하고 주요 기능 및 기술 세부 사항을 발견","es":"Aprende a implementar FHIR API con Apache Spark para análisis de datos clínicos","fr":"Découvrez comment mettre en œuvre FHIR API avec Apache Spark pour l''analyse de données cliniques","de":"Erfahren Sie, wie Sie FHIR API mit Apache Spark für die Datenanalyse im Gesundheitswesen implementieren","pt":"Aprenda a implementar a FHIR API com Apache Spark para análise de dados clínicos. Consulte nossa documentação técnica para desenvolvedores.","ru":"Узнайте, как реализовать FHIR API с помощью Apache Spark для анализа клинических данных. Читайте нашу техническую документацию для ИИ Агентов.","ar":"تعرف على كيفية تنفيذ واجهة برمجة تطبيقات FHIR باستخدام Apache Spark لتحليل البيانات السريرية. استشر وثائقنا الفنية للمطورين."},"definition":{"en":"fhir-api is a toolset built on Apache Spark that simplifies the use of FHIR and clinical terminology within data analytics.","zh":"FHIR API 是一种基于 HL7 FHIR 规范的 RESTful API 实现，用于简化数据分析","ja":"FHIR API は、HL7 FHIR 規格に基づく RESTful API の実装であり、データ分析を簡素化するために使用されます","ko":"FHIR API는 데이터 분석을 단순화하기 위해 사용되는 HL7 FHIR 규격 기반의 RESTful API 구현입니다","es":"FHIR API es un conjunto de herramientas para implementar APIs RESTful de FHIR según la especificación HL7 FHIR","fr":"FHIR API est un ensemble d''outils pour mettre en œuvre des API RESTful FHIR selon la spécification HL7 FHIR","de":"FHIR API ist eine Sammlung von Tools zur Implementierung von FHIR-REST-APIs gemäß der HL7-FHIR-Spezifikation","pt":"FHIR API é uma aplicação que facilita o uso de FHIR e terminologia clínica em análise de dados.","ru":"FHIR API - это приложение, которое упрощает использование FHIR и клинической терминологии в анализе данных.","ar":"واجهة برمجة تطبيقات FHIR هي تطبيق يسهل استخدام FHIR والمنهجية السريرية في تحليل البيانات."},"features":{"en":["Implements FHIR RESTful APIs according to the HL7 FHIR specification (R4/R5)","Follows URL structure pattern: [base]/[type]/[id] with UTF-8 encoding","Supports core operations such as read, search, and create via HTTP requests","Utilizes Apache Spark for efficient data processing and analysis","Enables seamless integration of clinical terminology within data analytics"],"zh":["FHIR RESTful API 实现","Apache Spark 集成","HL7 FHIR 规范（R4/R5）支持","URL 结构：[base]/[type]/[id]","核心操作：读取、创建、更新、删除"],"ja":["FHIR RESTful API の実装","Apache Spark の統合","HL7 FHIR 規格（R4/R5）への対応","URL 構造：[base]/[type]/[id]","コア操作：読み取り、作成、更新、削除"],"ko":["FHIR RESTful API 구현","Apache Spark 통합","HL7 FHIR 규격（R4/R5） 지원","URL 구조：[base]/[type]/[id]","코어 작동：읽기, 생성, 업데이트, 삭제"],"es":["Implementación de FHIR REST API según la especificación HL7 FHIR (R4/R5)","Estructura de URL según el patrón [base]/[type]/[id]","Operaciones básicas como lectura y escritura de recursos","Compatibilidad con Apache Spark para análisis de datos","Soporte para UTF-8 y URLs sensibles a mayúsculas y minúsculas"],"fr":["Mise en œuvre de FHIR REST API selon la spécification HL7 FHIR (R4/R5)","Structure d''URL selon le modèle [base]/[type]/[id]","Opérations de base comme la lecture et l''écriture de ressources","Compatibilité avec Apache Spark pour l''analyse de données","Prise en charge de UTF-8 et d''URL sensibles à la casse"],"de":["Implementierung von FHIR-REST-APIs gemäß der HL7-FHIR-Spezifikation (R4/R5)","URL-Struktur nach dem Muster [base]/[type]/[id]","Grundlegende Operationen wie Lesen und Schreiben von Ressourcen","Kompatibilität mit Apache Spark für Data Analytics","Unterstützung für UTF-8 und Groß-/Kleinschreibungssensitive URLs"],"pt":["Implementação de API RESTful de acordo com a especificação HL7 FHIR","Estrutura de URL personalizável com base, tipo e ID de recurso","Suporte a operações core como leitura, criação, atualização e exclusão de recursos","Uso de Apache Spark para análise de dados clínicos","Compatibilidade com FHIR R4 e R5"],"ru":["Реализация RESTful API в соответствии со спецификацией HL7 FHIR","Настраиваемая структура URL с базой, типом и идентификатором ресурса","Поддержка основных операций, таких как чтение, создание, обновление и удаление ресурсов","Использование Apache Spark для анализа клинических данных","Совместимость с FHIR R4 и R5"],"ar":["تنفيذ واجهة برمجة تطبيقات RESTful وفقًا لمواصفات HL7 FHIR","هيكل URL قابل للتخصيص مع القاعدة ونوع والمعرف الفريد للموارد","دعم العمليات الأساسية مثل قراءة وإنشاء وتحديث وحذف الموارد","استخدام Apache Spark لتحليل البيانات السريرية","التوافق مع FHIR R4 و R5"]},"keywords":{"en":["how to use fhir-api","fhir-api setup guide","fhir-api alternative","fhir-api vs hapi","what is fhir-api","fhir-api install","hl7 fhir specification","apache spark integration","fhir rest api implementation"],"zh":["FHIR API","Apache Spark","HL7 FHIR","RESTful API","数据分析","AIエージェント","FHIR API 设置","FHIR API 实现"],"ja":["FHIR API","Apache Spark","HL7 FHIR","RESTful API","データ分析","AIエージェント","FHIR API 導入","FHIR API 実装"],"ko":["FHIR API","Apache Spark","HL7 FHIR","RESTful API","데이터 분석","AI 에이전트","FHIR API 설정","FHIR API 구현"],"es":["FHIR API","análisis de datos clínicos","Apache Spark","HL7 FHIR","API RESTful","terminología clínica","implementación de FHIR","Herramientas de análisis de datos"],"fr":["FHIR API","analyse de données cliniques","Apache Spark","HL7 FHIR","API RESTful","terminologie clinique","mise en œuvre de FHIR","Outils d''analyse de données"],"de":["FHIR API","Datenanalyse im Gesundheitswesen","Apache Spark","HL7 FHIR","REST-API","klinische Terminologie","Implementierung von FHIR","Data-Analytics-Tools"],"pt":["FHIR API","Apache Spark","análise de dados clínicos","HL7 FHIR","RESTful API","desenvolvimento de software","análise de dados","terminologia clínica","FHIR R4","FHIR R5"],"ru":["FHIR API","Apache Spark","анализ клинических данных","HL7 FHIR","RESTful API","разработка программного обеспечения","анализ данных","клиническая терминология","FHIR R4","FHIR R5"],"ar":["واجهة برمجة تطبيقات FHIR","Apache Spark","تحليل البيانات السريرية","HL7 FHIR","واجهة برمجة تطبيقات RESTful","تطوير البرمجيات","تحليل البيانات","المنهجية السريرية","FHIR R4","FHIR R5"]}},"owner":"aehrc","repo":"pathling","repoPath":"aehrc/pathling","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.638Z","topics":[],"category":"community","skillMd":{"name":"fhir-api","description":"Expert guidance for implementing FHIR RESTful API servers and clients following the HL7 FHIR specification. Use this skill when implementing a FHIR server with REST endpoints, building a FHIR client, designing FHIR API routes and handlers, implementing FHIR operations (read, create, update, delete, search, history), working with FHIR bundles, batch requests, or transactions, handling FHIR content negotiation, headers, and versioning, or implementing conditional operations. Trigger keywords include FHIR REST, FHIR API, FHIR server, FHIR client, FHIR endpoint, FHIR operations, RESTful FHIR, implement FHIR.","bodyPreview":"# FHIR REST API implementation\n\nThis skill provides guidance for implementing FHIR RESTful APIs according to the HL7 FHIR specification (R4/R5).\n\n## URL structure\n\nAll FHIR REST URLs follow the pattern:\n\n```\n[base]/[type]/[id]\n```\n\n- `[base]`: Service base URL (e.g., `https://fhir.example.org/r4`)\n- `[type]`: Resource type (e.g., `Patient`, `Observation`)\n- `[id]`: Logical resource ID\n\nURLs are case-sensitive and use UTF-8 encoding.\n\n## Core operations\n\n| Operation         | HTTP     | URL Patte","body":"# FHIR REST API implementation\n\nThis skill provides guidance for implementing FHIR RESTful APIs according to the HL7 FHIR specification (R4/R5).\n\n## URL structure\n\nAll FHIR REST URLs follow the pattern:\n\n```\n[base]/[type]/[id]\n```\n\n- `[base]`: Service base URL (e.g., `https://fhir.example.org/r4`)\n- `[type]`: Resource type (e.g., `Patient`, `Observation`)\n- `[id]`: Logical resource ID\n\nURLs are case-sensitive and use UTF-8 encoding.\n\n## Core operations\n\n| Operation         | HTTP     | URL Pattern                         | Success |\n| ----------------- | -------- | ----------------------------------- | ------- |\n| Read              | GET      | `[base]/[type]/[id]`                | 200     |\n| VRead             | GET      | `[base]/[type]/[id]/_history/[vid]` | 200     |\n| Create            | POST     | `[base]/[type]`                     | 201     |\n| Update            | PUT      | `[base]/[type]/[id]`                | 200/201 |\n| Patch             | PATCH    | `[base]/[type]/[id]`                | 200     |\n| Delete            | DELETE   | `[base]/[type]/[id]`                | 200/204 |\n| Search            | GET/POST | `[base]/[type]?params`              | 200     |\n| History           | GET      | `[base]/[type]/[id]/_history`       | 200     |\n| Capabilities      | GET      | `[base]/metadata`                   | 200     |\n| Batch/Transaction | POST     | `[base]`                            | 200     |\n\nFor detailed specifications of each operation, see [references/operations.md](references/operations.md).\n\n## Content negotiation\n\n### MIME types\n\n| Format | MIME Type                 |\n| ------ | ------------------------- |\n| JSON   | `application/fhir+json`   |\n| XML    | `application/fhir+xml`    |\n| RDF    | `application/fhir+turtle` |\n\nUse the `Accept` header for response format and `Content-Type` for request body format.\n\nThe `_format` query parameter overrides `Accept` when clients cannot set headers.\n\n### FHIR version\n\nSpecify version via MIME type parameter:\n\n```\nAccept: application/fhir+json; fhirVersion=4.0\n```\n\nVersion mappings: 1.0 (R2), 3.0 (R3), 4.0 (R4), 4.3 (R4B), 5.0 (R5).\n\n## Required headers\n\n### Request headers\n\n| Header        | Purpose             | Example                 |\n| ------------- | ------------------- | ----------------------- |\n| Accept        | Response format     | `application/fhir+json` |\n| Content-Type  | Request body format | `application/fhir+json` |\n| If-Match      | Optimistic locking  | `W/\"123\"`               |\n| If-None-Exist | Conditional create  | `identifier=123`        |\n| Prefer        | Return preference   | `return=representation` |\n\n### Response headers\n\n| Header        | Purpose            | Example                         |\n| ------------- | ------------------ | ------------------------------- |\n| ETag          | Version identifier | `W/\"123\"`                       |\n| Location      | New resource URL   | `[base]/Patient/123/_history/1` |\n| Last-Modified | Modification time  | RFC 7231 date                   |\n\n## Versioning and optimistic locking\n\nFHIR uses weak ETags for version tracking:\n\n1. Server returns `ETag: W/\"[versionId]\"` with responses\n2. Client sends `If-Match: W/\"[versionId]\"` with updates\n3. Server returns `412 Precondition Failed` if version mismatch\n\nImplement version-aware updates when `CapabilityStatement.rest.resource.versioning` is `versioned-update`.\n\n## Error handling\n\nReturn `OperationOutcome` resources for all errors:\n\n```json\n{\n    \"resourceType\": \"OperationOutcome\",\n    \"issue\": [\n        {\n            \"severity\": \"error\",\n            \"code\": \"invalid\",\n            \"diagnostics\": \"Patient.birthDate: Invalid date format\"\n        }\n    ]\n}\n```\n\n### Status codes\n\n| Code | Meaning                                |\n| ---- | -------------------------------------- |\n| 400  | Invalid syntax or validation failure   |\n| 404  | Resource not found                     |\n| 409  | Version conflict                       |\n| 410  | Resource deleted                       |\n| 412  | Precondition failed (version mismatch) |\n| 422  | Business rule violation                |\n\n## Prefer header\n\nControl response content with `Prefer`:\n\n| Value                     | Response body        |\n| ------------------------- | -------------------- |\n| `return=minimal`          | Empty (headers only) |\n| `return=representation`   | Full resource        |\n| `return=OperationOutcome` | Validation outcome   |\n\nFor async operations, use `Prefer: respond-async` to get `202 Accepted` with status polling URL.\n\n## Implementation checklist\n\nServer implementations should:\n\n1. Implement CapabilityStatement at `/metadata`\n2. Support content negotiation (JSON at minimum)\n3. Return proper ETags for versioned resources\n4. Include `Location` header on create/update\n5. Return `OperationOutcome` for all errors\n6. Support `_format` parameter fallback\n7. Honour `Prefer` header for response content\n\n## References\n\n- [operations.md](references/operations.md): Detailed operation specifications\n- [search.md](references/search.md): Search parameter and result handling\n- [batch-transaction.md](references/batch-transaction.md): Batch and transaction processing\n"},"lastSynced":"2026-03-08T02:13:39.490Z","agentAnalysis":{"suitability":{"en":"Perfect for Healthcare Agents needing to implement FHIR RESTful APIs according to the HL7 FHIR specification","zh":"非常适合需要根据HL7 FHIR规范实施FHIR RESTful API的医疗保健代理","ja":"HL7 FHIR仕様に従ってFHIR RESTful APIを実装する必要があるヘルスケアエージェントに最適","ko":"HL7 FHIR 사양에 따라 FHIR RESTful API를 구현해야 하는 헬스케어 에이전트에게 적합","es":"Perfecto para Agentes de Atención Médica que necesitan implementar API RESTful de FHIR según la especificación HL7 FHIR","fr":"Parfait pour les agents de soins de santé ayant besoin de mettre en œuvre des API RESTful FHIR conformément à la spécification HL7 FHIR","de":"Perfekt für Healthcare-Agents, die FHIR-RESTful-APIs gemäß der HL7-FHIR-Spezifikation implementieren müssen","pt":"Perfeito para Agentes de Saúde que precisam implementar APIs RESTful FHIR de acordo com a especificação HL7 FHIR","ru":"Идеально для агентов здравоохранения, которым необходимо реализовать RESTful API FHIR в соответствии со спецификацией HL7 FHIR","ar":"مثالي لوكلاء الرعاية الصحية الذين يحتاجون إلى تنفيذ واجهات برمجة التطبيقات RESTful FHIR وفقًا لمواصفات HL7 FHIR"},"recommendation":{"en":"Empowers agents to interact with FHIR resources using RESTful APIs, providing URL structure guidance and supporting core operations like READ, CREATE, and UPDATE, all based on the HL7 FHIR specification (R4/R5) and utilizing UTF-8 encoding","zh":"赋予代理与FHIR资源交互的能力，使用RESTful API，提供URL结构指导，并支持基于HL7 FHIR规范（R4/R5）的核心操作，如READ、CREATE和UPDATE，使用UTF-8编码","ja":"エージェントがFHIRリソースとやり取りする能力を提供し、RESTful APIを使用して、URL構造に関するガイダンスを提供し、HL7 FHIR仕様（R4/R5）に基づくREAD、CREATE、UPDATEなどの基本操作をサポートし、UTF-8エンコードを使用","ko":"에이전트가 FHIR 리소스와 상호 작용할 수 있는 능력을 제공하며 RESTful API를 사용하여 URL 구조에 대한 지침을 제공하고 HL7 FHIR 사양(R4/R5)에 기반한 READ, CREATE 및 UPDATE와 같은 기본 연산을 지원하며 UTF-8 인코딩을 사용","es":"Habilita a los agentes a interactuar con recursos FHIR utilizando API RESTful, proporcionando orientación sobre la estructura de URL y soportando operaciones básicas como LEER, CREAR y ACTUALIZAR, todo basado en la especificación HL7 FHIR (R4/R5) y utilizando codificación UTF-8","fr":"Permet aux agents d''interagir avec les ressources FHIR en utilisant des API RESTful, en fournissant des conseils sur la structure d''URL et en prenant en charge les opérations de base comme LIRE, CRÉER et METTRE À JOUR, le tout basé sur la spécification HL7 FHIR (R4/R5) et en utilisant le codage UTF-8","de":"Ermächtigt Agenten, mit FHIR-Ressourcen über RESTful-APIs zu interagieren, indem URL-Strukturleitfäden bereitgestellt und Kernoperationen wie LESen, ERSTELLEN und AKTUALISIEREN unterstützt werden, alles basierend auf der HL7-FHIR-Spezifikation (R4/R5) und unter Verwendung von UTF-8-Codierung","pt":"Habilita os agentes a interagir com recursos FHIR usando APIs RESTful, fornecendo orientação sobre a estrutura de URL e suportando operações básicas como LEITURA, CRIAÇÃO e ATUALIZAÇÃO, todas com base na especificação HL7 FHIR (R4/R5) e utilizando codificação UTF-8","ru":"Наделяет агентов возможностью взаимодействовать с ресурсами FHIR с помощью RESTful API, предоставляя руководство по структуре URL и поддержку основных операций, таких как ЧТЕНИЕ, СОЗДАНИЕ и ОБНОВЛЕНИЕ, все на основе спецификации HL7 FHIR (R4/R5) и с использованием кодировки UTF-8","ar":"يُمنح الوكلاء القدرة على التفاعل مع موارد FHIR باستخدام واجهات برمجة التطبيقات RESTful، مع توفير إرشادات حول بنية URL ودعم العمليات الأساسية مثل القراءة والإنشاء والتحديث، وكل ذلك على أساس مواصفات HL7 FHIR (R4/R5) واستخدام ترميز UTF-8"},"useCases":{"en":["Implementing FHIR RESTful APIs for Patient and Observation resources","Generating URLs for FHIR resources following the [base]/[type]/[id] pattern","Debugging FHIR API requests using HTTP methods like GET, POST, and PUT"],"zh":["为患者和观察资源实施FHIR RESTful API","根据[base]/[type]/[id]模式为FHIR资源生成URL","使用HTTP方法（如GET、POST和PUT）调试FHIR API请求"],"ja":["患者と観察リソースのFHIR RESTful APIを実装する","[base]/[type]/[id]パターンに従ってFHIRリソースのURLを生成する","HTTPメソッド（GET、POST、PUTなど）を使用してFHIR APIリクエストをデバッグする"],"ko":["환자 및 관찰 리소스에 대한 FHIR RESTful API 구현","[base]/[type]/[id] 패턴에 따라 FHIR 리소스에 대한 URL 생성","HTTP 메서드(예: GET, POST, PUT)를 사용하여 FHIR API 요청 디버깅"],"es":["Implementar API RESTful de FHIR para recursos de Paciente y Observación","Generar URLs para recursos FHIR siguiendo el patrón [base]/[tipo]/[id]","Depurar solicitudes de API FHIR utilizando métodos HTTP como GET, POST y PUT"],"fr":["Mettre en œuvre des API RESTful FHIR pour les ressources Patient et Observation","Générer des URLs pour les ressources FHIR en suivant le modèle [base]/[type]/[id]","Déboguer les requêtes d''API FHIR en utilisant des méthodes HTTP comme GET, POST et PUT"],"de":["Implementierung von FHIR-RESTful-APIs für Patienten- und Beobachtungsressourcen","Erzeugen von URLs für FHIR-Ressourcen unter Verwendung des Musters [Base]/[Typ]/[ID]","Fehlerbehebung von FHIR-API-Anfragen unter Verwendung von HTTP-Methoden wie GET, POST und PUT"],"pt":["Implementação de APIs RESTful FHIR para recursos de Paciente e Observação","Geração de URLs para recursos FHIR seguindo o padrão [base]/[tipo]/[id]","Depuração de solicitações de API FHIR usando métodos HTTP como GET, POST e PUT"],"ru":["Реализация RESTful API FHIR для ресурсов пациентов и наблюдений","Генерация URL для ресурсов FHIR в соответствии с шаблоном [base]/[type]/[id]","Отладка запросов API FHIR с использованием методов HTTP, таких как GET, POST и PUT"],"ar":["تنفيذ واجهات برمجة التطبيقات RESTful FHIR لموارد المريض والمراقبة","توليد عناوين URL لموارد FHIR اتباعًا لنمط [الأساس]/[النوع]/[المعرف]","تصحيح أخطاء طلبات واجهة برمجة التطبيقات FHIR باستخدام أساليب HTTP مثل GET وPOST وPUT"]},"limitations":{"en":["Requires knowledge of HL7 FHIR specification (R4/R5)","Limited to FHIR RESTful API implementation","Case-sensitive URLs and UTF-8 encoding required"],"zh":["需要HL7 FHIR规范（R4/R5）的知识","仅限FHIR RESTful API实现","需要区分大小写的URL和UTF-8编码"],"ja":["HL7 FHIR仕様（R4/R5）の知識が必要","FHIR RESTful APIの実装に限定","大文字と小文字が区別されるURLとUTF-8エンコードが必要"],"ko":["HL7 FHIR 사양(R4/R5)의 지식이 필요","FHIR RESTful API 구현에만 제한","대/소문자 구분이 가능한 URL 및 UTF-8 인코딩이 필요"],"es":["Requiere conocimiento de la especificación HL7 FHIR (R4/R5)","Limitado a la implementación de API RESTful de FHIR","Se requieren URLs y codificación UTF-8 sensibles a mayúsculas y minúsculas"],"fr":["Nécessite une connaissance de la spécification HL7 FHIR (R4/R5)","Limité à la mise en œuvre de l''API RESTful FHIR","Des URLs et un codage UTF-8 sensibles à la casse sont requis"],"de":["Benötigt Kenntnisse der HL7-FHIR-Spezifikation (R4/R5)","Begrenzt auf die Implementierung von FHIR-RESTful-APIs","Erfordert Groß- und Kleinschreibung von URLs und UTF-8-Codierung"],"pt":["Exige conhecimento da especificação HL7 FHIR (R4/R5)","Limitado à implementação de API RESTful FHIR","URLs sensíveis a maiúsculas e minúsculas e codificação UTF-8 necessárias"],"ru":["Требует знания спецификации HL7 FHIR (R4/R5)","Ограничен реализацией RESTful API FHIR","Требуются чувствительные к регистру URL и кодировка UTF-8"],"ar":["يتطلب معرفة بمواصفات HL7 FHIR (R4/R5)","محدود بتنفيذ واجهة برمجة التطبيقات RESTful FHIR","مطلوبة عناوين URL الحساسة لحالة الأحرف وترميز UTF-8"]},"version":4},"contentHash":"5ec4f887506c74dc0dad984343747526ed812bc07567c061037c408dbaef5dda","qualityScore":36}');
